        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>45. Почему мясо недопустимо [для еды] и почему оно запрещено?</li>
            <li>Почему те, кто рождён в роду мясоедов (ракшасы), [всё же] едят мясо?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>46. Как [миры] подобны луне и солнцу, или напоминают [гору] Меру и
                лотос?</li>
            <li>Поведай мне: почему миры принимают форму льва или [знака]
                Шриватса?<a href="#citation-163" id="ref-163" class="citation-mark"><sup>163</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>47. Как [миры] бывают перевёрнуты вверх дном или подобны сети Индры?</li>
            <li>Как и почему [возникают] миры, состоящие сплошь из драгоценностей?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>48. Как [миры] принимают форму вины или барабана, или подобны разным
                цветам и плодам?</li>
            <li>Как они [сияют] чистотой солнца и луны? Поведай мне!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>49. Кто такие Будды воплощения (<em>nirmāṇika</em>), кто — Будды созревания
                [заслуг] (<em>vipākaja</em>)?</li>
            <li>И как [постигаются] Будды Мудрости Таковости (<em>tathatā-jñāna-buddha</em>)
                — как, через что?<a href="#citation-164" id="ref-164" class="citation-mark"><sup>164</sup></a></li>
            <li>Поведай мне!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>50. Поведай мне: почему Пробуждение не происходит в мире желаний
                (<em>kāma-dhātu</em>)?</li>
            <li>Почему Ты пробуждаешься лишь в [мире] <em>Акаништха</em>, среди тех, кто
                свободен от страстей?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>51. Кто будет поддерживать Учение, когда Сугата уйдёт в
                [окончательное] угасание?</li>
            <li>Как долго будет пребывать Учитель и как долго сохранится Его путь?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>52. Сколько видов высших истин (<em>siddhānta</em>) в Твоем Учении и каковы
                воззрения?<a href="#citation-165" id="ref-165" class="citation-mark"><sup>165</sup></a></li>
            <li>Какова дисциплина (<em>vinaya</em>) и как [обретается] состояние монаха?</li>
            <li>Поведай мне об этом!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>53. Как происходит поворот основы [у бодхисаттв] (<em>parāvṛtti</em>) и</li>
            <li>как [достигается] состояние вне ментальных образов?</li>
            <li>[В чём различие] у пратьекабудд, сыновей Победителей и шраваков?</li>
            <li>Поведай мне!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>54. Откуда берутся мирские сверхзнания (<em>abhijñā</em>) и как обретаются
                сверхзнания запредельные? Каким образом и почему ум [проходит через]
                семь ступеней (<em>bhūmi</em>)?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>55. Сколько видов Сангхи существует и как происходит её раскол?</li>
            <li>Как и почему возникли медицинские науки для [исцеления] существ?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>56. Почему Ты говоришь сыновьям Победителей: «Я был Кашьяпой,
                Кракуччхандой и Канакамуни»? Поведай об этом, о Великий Мудрец!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>57. Почему [существуют] учения о ложном Я и почему — о вечности и
                уничтожении?</li>
            <li>Почему Ты не провозглашаешь повсюду истину о том, что всё есть лишь ум?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>58. Откуда берутся леса из мужчин-и-женщин?<a href="#citation-166" id="ref-166" class="citation-mark"><sup>166</sup></a></li>
            <li>Откуда — леса миробаланов и амлы?</li>
            <li>Как [возникли] гора Кайласа, кольцо гор Чакравала и Алмазная твердыня?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>59. Кто те непоколебимые существа, что пребывают в этих [горах],
                украшенных множеством драгоценностей и наполненных риши и гандхарвами?</li>
            <li>Поведай мне, как и почему это так!</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2. (Будда уточняет вопросы Махамати)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>60. Выслушав всё это, Великий Герой, Будда — лучший из знатоков мира, явил ум, исполненный Махаяны, — сердце и силу Будд.</li>
        </ul>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>61. — Прекрасно, прекрасно, о великомудрый Махамати!</li>
            <li>Внимай же! Я изложу по порядку всё, о чём ты вопрошал.<a href="#citation-167" id="ref-167" class="citation-mark"><sup>167</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>62. Изложу возникновение и не-возникновение,</li>
            <li>Нирвану и шуньяту признаков,</li>
            <li>переход из существования в существование,</li>
            <li>отсутствие собственной природы (<em>niḥsvabhāva</em>),</li>
            <li>природу Будд, Парамиты и сыновей Победителей.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>63. Расскажу о шраваках, сынах Победителей и тиртхиках,</li>
            <li>а также о тех, кто пребывает в бесформенных мирах;</li>
            <li>о горе Меру, океанах, твердынях,</li>
            <li>островах, мирах и земле.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>64. О созвездиях, солнце и луне,</li>
            <li>о тиртхиках, богах и асурах;</li>
            <li>об освобождениях (<em>vimokṣa</em>), власти (<em>vaśitā</em>),</li>
            <li>сверхъестественных способностях (<em>abhijñā</em>), могуществах (<em>bala</em>),</li>
            <li><em>дхьянах</em> и <em>самадхи</em>.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>65. О прекращении (<em>nirodha</em>), основах чудесных сил (<em>ṛddhipāda</em>),</li>
            <li>факторах Пробуждения (<em>bodhyaṅga</em>) и самом Пути (<em>mārga</em>);</li>
            <li>о <em>дхьянах</em>, безмерных состояниях (<em>apramāṇa</em>),</li>
            <li><em>скандхах</em> и круговороте рождений и смертей (<em>gatyāgatāni</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>66. О достижениях самадхи (<em>samāpatti</em>),</li>
            <li>о прекращении и выходе из него (<em>vyutthāna</em>),</li>
            <li>об учении о сознании (<em>citta-deśanā</em>);</li>
            <li>об умe (<em>citta</em>), интеллекте (<em>manas</em>) и различающем сознании (<em>vijñāna</em>);</li>
            <li>об отсутствии «я» (<em>nairātmya</em>) и пяти дхармах.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>67. О собственной природе (<em>svabhāva</em>), воображении (<em>kalpanā</em>) и воображаемом (<em>kalpya</em>);</li>
            <li>о видимом (<em>dṛśya</em>) и о том, как возникают две крайности во взглядах (<em>dṛṣṭi-dvaya</em>);</li>
            <li>о видах Колесниц, родах (<em>gotrāṇi</em>)</li>
            <li>и происхождении золота, драгоценностей и жемчуга.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>68. Об <em>иччхантиках</em>, великих первоэлементах (<em>mahābhūtā</em>), блужданиях (<em>bhramarā</em>)<a href="#citation-168" id="ref-168" class="citation-mark"><sup>168</sup></a></li>
            <li>и о природе единого Будды (<em>ekabuddhatā</em>);</li>
            <li>о знании (<em>jñāna</em>), познаваемом (<em>jñeya</em>), ходе практики (<em>gama</em>), достижении (<em>prāpti</em>),</li>
            <li>а также о бытии и небытии существ (<em>bhavābhava</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>69. Почему и как кони, слоны и олени попадают в ловушки — изложу об этом;</li>
            <li>высшую истину (<em>siddhānta</em>), подтверждённую примерами и доводами (<em>dṛṣṭānta-hetubhiḥ</em>),</li>
            <li>и саму природу изложения Учения (<em>deśanā</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>70. Что есть следствие и причина;</li>
            <li>в чём суть разнообразных заблуждений (<em>nānābhrānti</em>) и методов аргументации (<em>nayam</em>);</li>
            <li>почему всё есть лишь ум и нет внешних объектов;</li>
            <li>и почему на самом деле нет последовательности ступеней.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>71. Ты спрашиваешь Меня о сотне способов поворота к области без ментальных образов?</li>
            <li>Так спроси и об остальном: о медицине, ремёслах, изящных искусствах и преданиях!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>72. Вопрошай же о размерах гор Ачала и Меру, о мерах самой земли!</li>
            <li>Поведай Мне, как ученик: каковы меры океанов, луны и солнца?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>73. Сосчитай: сколько пылинок (<em>rajas</em>) в телах существ — высших, средних и низших?</li>
            <li>Сколько пылинок в каждом мире (<em>kṣetra</em>)?</li>
            <li>Сколько их в каждой мере длины (<em>dhanu</em>)?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>74. Сколько их в локте, в шаге, в кроше, в йоджане и в половине йоджаны?</li>
            <li>Сколько частиц уместится на волоске зайца, в игольном ушке,</li>
            <li>на гниде, на овечьей шерсти, в зерне ячменя?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>75. Сколько ячменных зёрен в мере <em>прастха</em> и сколько в половине <em>прастхи</em>?</li>
            <li>Сколько их в мерах <em>дрона</em> и <em>кхари</em>?</li>
            <li>Сколько там <em>лакх</em>, <em>крор</em> и <em>бимбар</em>?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>76. Сколько атомов (<em>aṇu</em>) в горчичном зерне?</li>
            <li>Сколько горчичных зёрен в бобе <em>маша</em>?</li>
            <li>И сколько таких бобов — в весе <em>дхарана</em>?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>77. Сколько <em>дхаран</em> в весе <em>карша</em>, и сколько <em>карш</em> — в тяжёлом <em>пала</em>?</li>
            <li>Исходя из этих мер веса, сколько <em>пал</em> весит гора Меру?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>78. Именно об этом спрашивай Меня, сын Мой!</li>
            <li>Зачем тебе вопрошать об ином?</li>
            <li>Из скольких атомов состоит тело пратьекабудд,</li>
            <li>шраваков, Будд и сыновей Победителей?</li>
            <li>Почему бы тебе не спросить об этом?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>79. Сколько атомов в языке пламени? Сколько их в порыве ветра?</li>
            <li>Сколько их в каждом органе чувств, в порах кожи, в твоих же бровях?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>80. Как люди становятся владыками богатств, царями и миродержцами?</li>
            <li>Как они стерегут свои царства?</li>
            <li>И как им достичь освобождения?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>81. О прозе и поэзии ты намерился вопрошать Меня?</li>
            <li>Откуда берётся половое соитие, столь славное в этом мире?</li>
            <li>Почему еда и питьё столь разнообразны на вкус?</li>
            <li>И что за «леса из мужчин и женщин» и другие леса?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>82. Почему воздвигнуты Алмазные твердыни и непоколебимые горы?</li>
            <li>Поведай же Мне!</li>
            <li>Почему мир подобен майе и сновидению?</li>
            <li>Почему он кажется маревом в пустыне?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>83. Где собираются облака и откуда приходят времена года?</li>
            <li>В чём секрет «вкусности» самих вкусов?</li>
            <li>И отчего существа делятся на мужчин, женщин и гермафродитов?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>84. Откуда берётся великолепие</li>
            <li>и где рождаются сыны Победителей?</li>
            <li>Спрашивай же об этом, сын Мой!</li>
            <li>Отчего эти горы божественны</li>
            <li>и украшены сонмами риши и гандхарв?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>85. Куда уходит освобождённый?</li>
            <li>Кто здесь связан и кем освобождается?</li>
            <li>Какова сфера пребывания тех, кто погружён в дхьяну?</li>
            <li>Что за творения и учения тиртхиков?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>86. Как возникают «бытие», «небытие» и «не-деяние»?</li>
            <li>Как [ум] внезапно прекращает видеть видимое?</li>
            <li>Как очищается рассудочное мышление</li>
            <li>и откуда оно вообще берётся?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>87. Что приводит в действие деяние?</li>
            <li>Как совершается перемещение существ?</li>
            <li>Как прекращается восприятие (<em>saṃjñā</em>)</li>
            <li>и что именно называют «самадхи»?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>88. Кто этот герой, сокрушающий тройственный мир?</li>
            <li>Каково его тело и где он пребывает?</li>
            <li>Почему Я учу об отсутствии «я»,</li>
            <li>если при этом говорю об относительной истине?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>89. О каких таких «признаках» ты Меня вопрошаешь?</li>
            <li>Что ты ищешь в «отсутствии "я"»?</li>
            <li>И почему ты спрашиваешь Меня</li>
            <li>о Зародыше Татхагат (<em>garbha</em>) и о логиках-найяиках?</li>
            <li>Спрашивай об этом, сын Победителей!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>90. Откуда взялись воззрения о вечности и уничтожении?</li>
            <li>Как успокаивается ум?</li>
            <li>Что есть речь, знание, нравственность и роды (<em>gotra</em>)?</li>
            <li>О сын Победителей! Спрашивай же!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>91. Ты спрашивал Меня о логике и толковании, об учителе и ученике,</li>
            <li>о причинах разнообразия существ;</li>
            <li>о пище и питье, небе и облаках, Марах</li>
            <li>и о том, что всё это — лишь именования (<em>prajñaptimātra</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>92. Ты спрашивал, сын Победителя,</li>
            <li>как и почему растут деревья и лианы;</li>
            <li>о причинах разнообразия земель Будд (<em>kṣetrāṇi</em>),</li>
            <li>и о происхождении риши Диргхатапаса.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>93. Ты спрашивал, сын Победителя,</li>
            <li>о Моём роде (<em>vaṃśa</em>) и Моём учителе (<em>guru</em>);</li>
            <li>о том, почему люди впадают в рабство/зависимость (<em>uhoḍimā</em>),</li>
            <li>и почему Пробуждение не происходит в мире желаний.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>94. Ты спрашивал,</li>
            <li>почему высшая истина (<em>siddhānta</em>) обретается в мирах Акаништха;</li>
            <li>о логике (<em>yukti</em>);</li>
            <li>о происхождении мирских сверхзнаний (<em>laukikābhijñā</em>),</li>
            <li>и о том, как обретается состояние монаха.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>95. Ты спрашивал о Буддах воплощения (<em>nairmāṇika</em>) и Буддах созревания плода (<em>vipāka-sthāna</em>);</li>
            <li>о Буддах Таковости и Знания (<em>tathatā-jñāna-buddha</em>), и о том, как устроена Сангха.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>96. Ты спрашивал о мирах, подобных вине, барабанам и цветам,</li>
            <li>свободных от недостатков обычного мира;</li>
            <li>о том, почему ум проходит через семь ступеней, сын Победителя.</li>
            <li>Обо всём этом и многих других вопросах ты вопрошал Меня, сын Мой!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>97. Я разъясню по порядку — внемли же Мне! —</li>
            <li>каждое [положение], наделённое верными признаками,</li>
            <li>и свободное от изъянов ложных воззрений (<em>dṛṣṭi-doṣa-varjita</em>);</li>
            <li>изложу высшую истину (<em>siddhānta</em>) и само Учение (<em>deśanā</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 3. (108 пар противоположностей)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>98. Я приведу перечень этих положений — слушай же, сын Мой! —</li>
            <li>те сто восемь изречений, что были провозглашены Буддами.</li>
        </ul>
        </blockquote>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Затем бодхисаттва Махамати спросил:</li>
            <li>«Что же это за сто восемь изречений?»</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Благословенный ответил:</li>
            <li>«Это изречения о:</li>
        </ul>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>- возникновении и не-возникновении,</li>
            <li>- вечности и непостоянстве,</li>
            <li>- признаке и беспризнаковости,</li>
            <li>- изменчивости и неизменности,</li>
            <li>- мгновенности и немгновенности,</li>
            <li>- собственной природе и отсутствии собственной природы,</li>
            <li>- шуньяте и ашуньяте,</li>
            <li>- уничтожении и не-уничтожении,</li>
            <li>- уме и не-уме,</li>
            <li>- средине и не-средине,</li>
            <li>- постоянстве и непостоянстве,</li>
            <li>- условиях и отсутствии условий,</li>
            <li>- причине и беспричинности,</li>
            <li>- клешах и отсутствии клеш,</li>
            <li>- жажде и отсутствии жажды,</li>
            <li>- искусных средствах и их отсутствии,</li>
            <li>- мастерстве и отсутствии мастерства,</li>
            <li>- чистоте и нечистоте,</li>
            <li>- логике и отсутствии логики,</li>
            <li>- примере и отсутствии примера,</li>
            <li>- ученике и отсутствии ученика,</li>
            <li>- учителе и отсутствии учителя,</li>
            <li>- родах (<em>gotra</em>) и отсутствии родов,</li>
            <li>- трёх колесницах и их отсутствии,</li>
            <li>- области без ментальных образов и её отсутствии,</li>
            <li>- обетах и отсутствии обетов,</li>
            <li>- трёх кругах (<em>trimaṇḍala</em>) и их отсутствии,</li>
            <li>- знаках и отсутствии знаков,</li>
            <li>- крайностях бытия-небытия,</li>
            <li>- обоих крайностях и их отсутствии,</li>
            <li>- личном знании благородных<a href="#citation-169" id="ref-169" class="citation-mark"><sup>169</sup></a> и его отсутствии,</li>
            <li>- блаженстве в видимом и его отсутствии,</li>
            <li>- мирах и их отсутствии,</li>
            <li>- атомах и их отсутствии,</li>
            <li>- воде и не-воде,</li>
            <li>- пустыне и не-пустыне,</li>
            <li>- первоэлементах и их отсутствии,</li>
            <li>- исчислении и его отсутствии,</li>
            <li>- сверхзнаниях и их отсутствии,</li>
            <li>- усталости и неусталости,</li>
            <li>- тучах и не-тучах,</li>
            <li>- ремёслах, искусствах и науках и их отсутствии,</li>
            <li>- ветре и не-ветре,</li>
            <li>- земле и не-земле,</li>
            <li>- мыслимом и немыслимом,</li>
            <li>- условных именах и их отсутствии,</li>
            <li>- скандхах и не-скандхах,</li>
            <li>- существах и не-существах,</li>
            <li>- разуме и его отсутствии,</li>
            <li>- Нирване и не-Нирване,</li>
            <li>- познаваемом и непознаваемом,</li>
            <li>- тиртхиках и не-тиртхиках,</li>
            <li>- барабанах и их отсутствии,</li>
            <li>- майе и не-майе,</li>
            <li>- сне и не-сне,</li>
            <li>- мареве и не-мареве,</li>
            <li>- отражении и не-отражении,</li>
            <li>- колесе и не-колесе,</li>
            <li>- городе гандхарвов и его отсутствии,</li>
            <li>- богах и не-богах,</li>
            <li>- пище и питье и их отсутствии,</li>
            <li>- соитии и его отсутствии,</li>
            <li>- увиденном и неувиденном,</li>
            <li>- Парамитах и их отсутствии,</li>
            <li>- нравственности и её отсутствии,</li>
            <li>- луне, солнце и звёздах и их отсутствии,</li>
            <li>- истине и не-истине,</li>
            <li>- плодах и отсутствии плодов,</li>
            <li>- прекращении (<em>nirodha</em>) и его отсутствии,</li>
            <li>- выходе из прекращения и его отсутствии,</li>
            <li>- медицине и её отсутствии,</li>
            <li>- признаках и их отсутствии,</li>
            <li>- факторах и их отсутствии,</li>
            <li>- <em>дхьяне</em> и не-<em>дхьяне</em>,</li>
            <li>- заблуждении и отсутствии заблуждения,</li>
            <li>- видимом и невидимом,</li>
            <li>- защите и её отсутствии,</li>
            <li>- роде и преемственности и их отсутствии,</li>
            <li>- риши и не-риши,</li>
            <li>- царстве и не-царстве,</li>
            <li>- захваченности и незахваченности,</li>
            <li>- драгоценностях и их отсутствии,</li>
            <li>- предсказании и его отсутствии,</li>
            <li>- <em>иччхантиках</em> и не-<em>иччхантиках</em>,</li>
            <li>- мужском, женском и среднем и их отсутствии,</li>
            <li>- вкусе и отсутствии вкуса,</li>
            <li>- действии и отсутствии действия,</li>
            <li>- теле и отсутствии тела,</li>
            <li>- рассудочном мышлении (<em>tarka</em>) и его отсутствии,</li>
            <li>- движении и неподвижности,</li>
            <li>- органах чувств и их отсутствии,</li>
            <li>- обусловленном и необусловленном,</li>
            <li>- причине и следствии и их отсутствии,</li>
            <li>- [небе] <em>Акаништха</em> и не-<em>Акаништхе</em>,</li>
            <li>- временах года и их отсутствии,</li>
            <li>- деревьях, лианах и их отсутствии,</li>
            <li>- разнообразии и отсутствии разнообразия,</li>
            <li>- вхождении в учение и не-вхождении,</li>
            <li>- дисциплине и её отсутствии,</li>
            <li>- монашестве и не-монашестве,</li>
            <li>- силе благословения (<em>adhiṣṭhāna</em>) и её отсутствии,</li>
            <li>- буквах (<em>akṣara</em>) и их отсутствии.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Вот те сто восемь изречений, Махамати, что были провозглашены Буддами прошлого».<a href="#citation-170" id="ref-170" class="citation-mark"><sup>170</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 4. (О возникновении, пребывании и прекращении сознаний)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</li>
            <li>— Сколько существует видов возникновения, пребывания и прекращения сознаний?</li>
            <li>Благословенный ответил:</li>
        </ul>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>— Махамати, существует два вида возникновения, пребывания и прекращения сознаний, недоступных пониманию рассудочных логиков (<em>tārkika</em>):</li>
            <li>это — <strong>прекращение потока</strong><a href="#citation-171" id="ref-171" class="citation-mark"><sup>171</sup></a> и <strong>прекращение признака</strong>.<a href="#citation-172" id="ref-172" class="citation-mark"><sup>172</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Существует два вида возникновения сознаний:</li>
            <li>— <strong>возникновение потока</strong><a href="#citation-173" id="ref-173" class="citation-mark"><sup>173</sup></a> и <strong>возникновение признака</strong>.<a href="#citation-174" id="ref-174" class="citation-mark"><sup>174</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Существует два вида пребывания:</li>
            <li>— <strong>пребывание потока</strong><a href="#citation-175" id="ref-175" class="citation-mark"><sup>175</sup></a> и <strong>пребывание признака</strong>.<a href="#citation-176" id="ref-176" class="citation-mark"><sup>176</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, сознание обладает тремя признаками:</li>
            <li>— признаком <strong>деятельности</strong>,<a href="#citation-177" id="ref-177" class="citation-mark"><sup>177</sup></a></li>
            <li>— признаком <strong>действия</strong>,<a href="#citation-178" id="ref-178" class="citation-mark"><sup>178</sup></a></li>
            <li>— и признаком <strong>рождения</strong>.<a href="#citation-179" id="ref-179" class="citation-mark"><sup>179</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кратко говоря, Махамати, всё сознание, обладающее восемью признаками, сводится к двум видам:</li>
            <li>— <strong>сознанию проявления</strong><a href="#citation-180" id="ref-180" class="citation-mark"><sup>180</sup></a></li>
            <li>— и <strong>сознанию различения объектов</strong>.<a href="#citation-181" id="ref-181" class="citation-mark"><sup>181</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как зеркало принимает формы,</li>
            <li>таково и действие сознания проявления.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Эти два вида сознания — нераздельны по своим признакам</li>
            <li>и взаимно обусловливают друг друга.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>При этом, Махамати:</li>
            <li>— причина <strong>сознания проявления</strong> — это <strong>непостижимое преобразование отпечатков</strong>;<a href="#citation-182" id="ref-182" class="citation-mark"><sup>182</sup></a></li>
            <li>— причина же <strong>сознания различения объектов</strong> — это <strong>различение объектов</strong><a href="#citation-183" id="ref-183" class="citation-mark"><sup>183</sup></a> и <strong>отпечатки безначального понятийного многообразия</strong>.<a href="#citation-184" id="ref-184" class="citation-mark"><sup>184</sup></a></li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Так, Махамати, прекращение всех чувственных сознаний означает прекращение
                    разнообразия отпечатков (<em>vāsanā</em>) ложного воображения<a href="#citation-185" id="ref-185" class="citation-mark"><sup>185</sup></a> в <em>Алайя-виджняне</em>.</li>
                <li>Это, Махамати, и есть прекращение признака.<a href="#citation-186" id="ref-186" class="citation-mark"><sup>186</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Прекращение потока<a href="#citation-187" id="ref-187" class="citation-mark"><sup>187</sup></a> же относится к тому, из чего [сознание] возникает.</li>
                <li>«Из чего» — это то, что служит опорой (<em>āśraya</em>) и объектом опоры (<em>ālambana</em>).</li>
                <li>Здесь опора — это пагубные отпечатки безначального понятийного разрастания,<a href="#citation-188" id="ref-188" class="citation-mark"><sup>188</sup></a></li>
                <li>а объект опоры — различения в сфере видимого, которое есть лишь проявление собственного ума.<a href="#citation-189" id="ref-189" class="citation-mark"><sup>189</sup></a></li>
            </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Это подобно тому, Махамати, как ком глины состоит из мельчайших частиц глины,</li>
            <li>не являясь ни отличным от них, ни тождественным им;</li>
            <li>и это подобно золоту и украшению из него.</li>
        </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Если бы, Махамати, ком глины был отличен от частиц, он не мог бы быть ими образован.</li>
                <li>Но поскольку он образован ими, он не отличен от них.</li>
                <li>Если бы он был полностью тождествен им, не было бы различия между комом и частицей.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Точно так же, Махамати,</li>
                <li>если бы активные сознания<a href="#citation-190" id="ref-190" class="citation-mark"><sup>190</sup></a> были отличны от признака рождения<a href="#citation-191" id="ref-191" class="citation-mark"><sup>191</sup></a> <em>Алайя-виджняны</em>,</li>
                <li>они не имели бы <em>Алайю</em> своей причиной.</li>
                <li>Если бы они были тождественны ей,</li>
                <li>то с прекращением активных сознаний прекратилась бы и сама <em>Алайя-виджняна</em>.</li>
                <li>Но её собственный признак рождения<a href="#citation-192" id="ref-192" class="citation-mark"><sup>192</sup></a> не прекращается.</li>
                <li>Посему, Махамати, в сознаниях прекращается не собственный признак рождения,</li>
                <li>а признак действия.<a href="#citation-193" id="ref-193" class="citation-mark"><sup>193</sup></a></li>
                <li>Если бы прекращалась сам признак рождения,</li>
                <li>то прекратилась бы и <em>Алайя-виджняна</em>.</li>
                <li>А если бы прекратилась <em>Алайя-виджняна</em>,</li>
                <li>это учение ничем не отличалось бы от нигилизма (<em>ucchedavāda</em>) тиртхиков.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Учение тиртхиков, Махамати, гласит:</li>
                <li>«С прекращением схватывания объектов прекращается и поток сознания.</li>
                <li>А с прекращением потока сознания обрывается безначальная преемственность».</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Тиртхики, Махамати, описывают движение потока через причинность.</li>
                <li>Они не объясняют возникновение зрительного сознания из встречи формы и света,</li>
                <li>но ищут [причину] в ином — в [метафизических] причинах.</li>
                <li>Причиной же для них являются:</li>
                <li>Первоматерия (<em>pradhāna</em>), Дух (<em>puruṣa</em>), Ишвара, Время или Атомы».<a href="#citation-194" id="ref-194" class="citation-mark"><sup>194</sup></a></li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
        <li><strong>(4. О возникновении, пребывании и прекращении сознаний)</strong></li>
        <li>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</li>
        <li>— Сколько существует видов возникновения, пребывания и прекращения сознаний?</li>
        <li>Благословенный ответил:</li>
    </ul>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>— Махамати, рассудочные логики (<em>tārkika</em>) не понимают, что у сознаний есть два вида возникновения, пребывания и прекращения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Прекращение бывает двух видов: прекращается либо сам <strong>поток</strong><a href="#citation-171" id="ref-171" class="citation-mark"><sup>171</sup></a> сознания, либо его <strong>признаки</strong><a href="#citation-172" id="ref-172" class="citation-mark"><sup>172</sup></a> (характеристики проявления).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Возникновение тоже двух видов: возникает либо <strong>поток</strong><a href="#citation-173" id="ref-173" class="citation-mark"><sup>173</sup></a> сознания, либо его <strong>признаки</strong><a href="#citation-174" id="ref-174" class="citation-mark"><sup>174</sup></a>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Пребывание также двух видов: пребывает либо <strong>поток</strong><a href="#citation-175" id="ref-175" class="citation-mark"><sup>175</sup></a>, либо <strong>признаки</strong><a href="#citation-176" id="ref-176" class="citation-mark"><sup>176</sup></a>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, у каждого сознания три признака: признак <strong>деятельности</strong>,<a href="#citation-177" id="ref-177" class="citation-mark"><sup>177</sup></a> признак <strong>действия</strong><a href="#citation-178" id="ref-178" class="citation-mark"><sup>178</sup></a> и признак <strong>рождения</strong>.<a href="#citation-179" id="ref-179" class="citation-mark"><sup>179</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Если говорить кратко, Махамати, всё сознание, обладающее восемью признаками, сводится к двум видам:</li>
            <li>— <strong>сознанию проявления</strong>,<a href="#citation-180" id="ref-180" class="citation-mark"><sup>180</sup></a> которое просто отражает, как зеркало отражает формы и</li>
            <li>— <strong>сознанию различения объектов.</strong><a href="#citation-181" id="ref-181" class="citation-mark"><sup>181</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Эти два вида нераздельны и порождают друг друга.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что их порождает? Причина <strong>сознания проявления</strong> — это <strong>непостижимое преобразование отпечатков</strong><a href="#citation-182" id="ref-182" class="citation-mark"><sup>182</sup></a> (прошлого опыта).</li>
            <li>Причина же <strong>сознания различения объектов</strong> — это само <strong>различение объектов</strong><a href="#citation-183" id="ref-183" class="citation-mark"><sup>183</sup></a> и <strong>отпечатки безначального понятийного многообразия</strong><a href="#citation-184" id="ref-184" class="citation-mark"><sup>184</sup></a>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Теперь о прекращении. Когда прекращаются все чувственные сознания (зрение, слух и т.д.), это означает, что в <em>Алайя-виджняне</em> прекращается многообразное действие отпечатков (<em>vāsanā</em>) ложного воображения<a href="#citation-185" id="ref-185" class="citation-mark"><sup>185</sup></a>.</li>
            <li>Это и называется <strong>прекращением признака</strong><a href="#citation-186" id="ref-186" class="citation-mark"><sup>186</sup></a> — перестают проявляться характеристики сознания.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li><strong>Прекращение потока</strong><a href="#citation-187" id="ref-187" class="citation-mark"><sup>187</sup></a> — это когда исчезает сама основа, из которой возникает сознание.</li>
            <li>Эта основа двойная: <strong>опора</strong> (<em>āśraya</em>) — накопленные отпечатки безначального понятийного разрастания<a href="#citation-188" id="ref-188" class="citation-mark"><sup>188</sup></a>, и <strong>объект опоры</strong> (<em>ālambana</em>) — различения в сфере видимого, которое есть лишь проявление собственного ума<a href="#citation-189" id="ref-189" class="citation-mark"><sup>189</sup></a>.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Рассмотрим, для примера, ком глины и мельчайшие частицы глины.</li>
            <li>Ком — это не совершенно иное, чем частицы глины, но и не абсолютно то же самое.</li>
            <li>Аналогично золото и украшение из золота.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Если бы ком был полностью отличен от частиц, он не мог бы состоять из них.</li>
            <li>Но поскольку он из них состоит, он не может быть совершенно отличен от них.</li>
            <li>Если бы он был полностью идентичен частицам, не было бы разницы между комом и отдельной частицей.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>То же самое с сознаниями.</li>
            <li>Активные сознания<a href="#citation-190" id="ref-190" class="citation-mark"><sup>190</sup></a> (зрение, слух и т.д.) соотносятся с признаком рождения<a href="#citation-191" id="ref-191" class="citation-mark"><sup>191</sup></a> <em>Алайя-виджняны</em> так же, как ком с частицами.</li>
            <li>Если бы они были полностью отличны от Алайи, она не была бы их причиной.</li>
            <li>Если бы они были тождественны ей, то с прекращением активных сознаний прекращалась бы и сама <em>Алайя-виджняна</em>.</li>
            <li>Но этого не происходит — её признак рождения<a href="#citation-192" id="ref-192" class="citation-mark"><sup>192</sup></a> не прекращается.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поэтому, Махамати, когда сознания прекращаются, прекращается их признак действия,<a href="#citation-193" id="ref-193" class="citation-mark"><sup>193</sup></a> но не признак рождения.</li>
            <li>Если бы прекращался признак рождения, исчезла бы сама <em>Алайя-виджняна</em>.</li>
            <li>А если бы прекратилась Алайя-виджняна, это учение ничем не отличалось бы от нигилизма (<em>ucchedavāda</em>) тиртхиков, которые утверждаеют полное уничтожение.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Учение тиртхиков, Махамати, гласит:</li>
            <li>«С прекращением схватывания объектов прекращается и поток сознания.</li>
            <li>А с прекращением потока сознания обрывается безначальная преемственность».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Тиртхики, Махамати, объясняют поток сознания через внешнюю причинность.</li>
            <li>Они не объясняют, что зрительное сознание возникает просто от встречи формы и света.</li>
            <li>Они ищут метафизическую Первопричину: первоматерию (<em>pradhāna</em>), дух (<em>puruṣa</em>), бога Ишвару, время или атомы.<a href="#citation-194" id="ref-194" class="citation-mark"><sup>194</sup></a></li>
        </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 5. (Семь природ и семь сфер высшей истины)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, существует семь видов природ (<em>svabhāva</em>):<a href="#citation-195" id="ref-195" class="citation-mark"><sup>195</sup></a></li>
            <li>Природа возникновения;<a href="#citation-196" id="ref-196" class="citation-mark"><sup>196</sup></a></li>
            <li>Природа существования;<a href="#citation-197" id="ref-197" class="citation-mark"><sup>197</sup></a></li>
            <li>Природа признака;<a href="#citation-198" id="ref-198" class="citation-mark"><sup>198</sup></a></li>
            <li>Природа великих первоэлементов;<a href="#citation-199" id="ref-199" class="citation-mark"><sup>199</sup></a></li>
            <li>Природа причины;</li>
            <li>Природа условий;<a href="#citation-200" id="ref-200" class="citation-mark"><sup>200</sup></a></li>
            <li>Природа завершённости<a href="#citation-201" id="ref-201" class="citation-mark"><sup>201</sup></a> — седьмая.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, существует семь видов<a href="#citation-202" id="ref-202" class="citation-mark"><sup>202</sup></a> высшей истины (<em>paramārtha</em>):</li>
            <li>1. Сфера ума;<a href="#citation-203" id="ref-203" class="citation-mark"><sup>203</sup></a></li>
            <li>2. Сфера знания;<a href="#citation-204" id="ref-204" class="citation-mark"><sup>204</sup></a></li>
            <li>3. Сфера мудрости;<a href="#citation-205" id="ref-205" class="citation-mark"><sup>205</sup></a></li>
            <li>4. Сфера двух воззрений;<a href="#citation-206" id="ref-206" class="citation-mark"><sup>206</sup></a></li>
            <li>5. Сфера, превосходящая два воззрения;<a href="#citation-207" id="ref-207" class="citation-mark"><sup>207</sup></a></li>
            <li>6. Сфера последовательного прохождения ступеней бодхисаттвы;<a href="#citation-208" id="ref-208" class="citation-mark"><sup>208</sup></a></li>
            <li>7. Сфера личного постижения Татхагаты.<a href="#citation-209" id="ref-209" class="citation-mark"><sup>209</sup></a></li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Это, Махамати, и есть сердце учения о способах бытия и высшей истине, принадлежащее Татхагатам, Архатам и Совершенно Пробуждённым прошлого, будущего и настоящего. Обладая им, Татгахаты с помощью благородного ока мудрости устанавливают мирские и запредельные дхармы в их общих и собственных признаках.</li>
                <li>И устанавливают они их так, чтобы те не имели ничего общего с дурными воззрениями и утверждениями тиртхиков.</li>
                <li>Как же, Махамати, возникают эти сходства с дурными воззрениями тиртхиков?</li>
                <li>Они возникают из-за непонимания того, что сознания суть лишь различения, порождённые объектами собственного ума.</li>
                <li>Махамати, из-за неспособности проникнуть в истину о том, что всё есть лишь воспринимаемое собственным умом, невежды и обычные люди становятся приверженцами двойственного учения о высшей истине, основанного на крайностях бытия и небытия.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2.6 (О преодолении учения об уничтожении и утверждении пути только-ума)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Кроме того, Махамати, Я разъясню</li>
                <li>[путь] прекращения страданий в трёх мирах, порождённых различениями;</li>
                <li>прекращения [влияния] неведения, жажды и кармических условий;</li>
                <li>а также [путь] созерцания объектов как <em>майи</em>,</li>
                <li>что есть лишь воспринимаемое собственным умом (<em>svacitta-dṛśya</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Махамати, те шраманы или брахманы,</li>
                <li>кто полагают, будто [мир] возникает из ничего</li>
                <li>или по воле веры в причины, плоды, субстанции, время и условия,</li>
                <li>и кто желают видеть возникновение и пребывание <em>скандх</em>, <em>дхату</em> и <em>аятан</em>,</li>
                <li>а затем — их исчезновение,</li>
                <li>такие люди, Махамати, становятся приверженцами учения об уничтожении (<em>ucchedavāda</em>).<a href="#citation-210" id="ref-210" class="citation-mark"><sup>210</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Они отрицают преемственность (<em>saṃtati</em>), действие, возникновение и
                    распад,</li>
                <li>бытие, Нирвану, Путь, карму, плод и саму истину.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Почему это так?</li>
                <li>Потому что они лишены прямого восприятия (<em>pratyakṣa</em>)</li>
                <li>и не видят изначальной основы.<a href="#citation-211" id="ref-211" class="citation-mark"><sup>211</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Подобно тому, Махамати, как черепки разбитого кувшина</li>
                <li>не могут исполнять функцию кувшина,</li>
                <li>и сожжённое семя — не может дать ростка,</li>
                <li>так же и <em>скандхи</em>, <em>дхату</em> и <em>аятаны</em>,</li>
                <li>что прекратились, прекращаются или прекратятся,</li>
                <li>не имеют непрерывного потока,<a href="#citation-212" id="ref-212" class="citation-mark"><sup>212</sup></a></li>
                <li>ибо их единственная причина — различения,</li>
                <li>воспринимаемые собственным умом.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Если бы, Махамати, возникновение сознаний происходило из [их изначального] небытия (<em>abhūtvā</em>) через тройное сочетание (<em>trisaṃgati</em>),<a href="#citation-213" id="ref-213" class="citation-mark"><sup>213</sup></a></li>
                <li>тогда, Махамати, и из шерсти черепахи могло бы что-то возникнуть,</li>
                <li>или можно было бы выжать масло из песка.</li>
                <li>Махамати, [в таком случае] их собственные тезисы рушатся,</li>
                <li>и установленный порядок [кармы] нарушается;</li>
                <li>утверждения тех, кто говорит о бытии и небытии</li>
                <li>относительно действия, кармы и деятеля,</li>
                <li>становятся бессмысленными.</li>
                <li>Пребывая на уровне рассудочного мышления (<em>tarka-bhūmi</em>),</li>
                <li>они излагают учения о реальности признаков прошлого, будущего и настоящего,</li>
                <li>основываясь на ложной вере в собственные признаки причины и плода.</li>
                <li>Они наставляют так, будучи ведомы отпечатками (<em>vāsanā</em>)</li>
                <li>пороков своих собственных воззрений.</li>
                <li>Поистине, Махамати, так невежды,</li>
                <li>укушенные змеёй дурных воззрений и обладающие извращённым умом,</li>
                <li>называют «высшим учением» то, что создано такими же невеждами.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Те же шраманы и брахманы, Махамати,</li>
                <li>кто видят [мир] как лишённый собственной природы (<em>niḥsvabhāva</em>),</li>
                <li>подобный огненному колесу, городу гандхарвов, <em>майе</em>, мареву, отражению луны в воде;</li>
                <li>кто осознают, что внешнее воспринимаемое — лишь различения собственного ума,</li>
                <li>обусловленные безначальным многообразием различений;</li>
                <li>кто оставили привязанность к воображаемым именам, признакам и обозначаемым объектам;</li>
                <li>кто созерцают сферу без ментальных образов (<em>nirābhāsa-gocara</em>),</li>
                <li>свободную от двойственности схватываемого и схватывающего,</li>
                <li>вне возникновения, пребывания и распада —</li>
                <li>ту сферу, что есть лишь проявление собственного ума, —</li>
                <li>такие бодхисаттвы-махасаттвы, Махамати,</li>
                <li>в скором времени достигнут равенства сансары и нирваны.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Обладая великим состраданием и искусными средствами,</li>
                <li>действуя без усилий (<em>anābhoga</em>),</li>
                <li>они видят всех существ как магические отражения.</li>
                <li>Свободные от условий, порождающих представление о внешнем,</li>
                <li>они понимают: вне ума ничего не существует.</li>
                <li>Следуя беззнаковому благословению (<em>animitta-adhiṣṭhāna</em>)</li>
                <li>и постепенно проходя ступени и сферы <em>самадхи</em>,</li>
                <li>они осознают три мира как собственный ум</li>
                <li>и обретают самадхи, подобное майе (<em>māyopama-samādhi</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Проникнув в сферу без ментальных образов,</li>
                <li>которая есть лишь их собственный ум,</li>
                <li>они достигают пребывания в Совершенной Мудрости.<a href="#citation-214" id="ref-214" class="citation-mark"><sup>214</sup></a></li>
                <li>Оставив действия, порождающие иллюзии,</li>
                <li>они обретают подобный ваджру образ Татхагаты (<em>vajra-bimba</em>);</li>
                <li>тело, сопровождаемое проявлениями таковости (<em>tathatā-nirmāṇa</em>),</li>
                <li>украшенное <em>силами</em>, <em>сверхзнаниями</em>, <em>властью</em> и состраданием.</li>
                <li>Они проникают во все земли Будд,</li>
                <li>будучи свободными от ума (<em>citta</em>), интеллекта (<em>manas</em>) и различающего сознания (<em>vijñāna</em>).</li>
                <li>Совершив поворот основы (<em>parāvṛtti</em>),</li>
                <li>они обретают Тело Татхагаты.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Посему, Махамати,</li>
                <li>бодхисаттвы-махасаттвы, стремящиеся к обретению Тела Татхагаты,</li>
                <li>должны пребывать,</li>
                <li>свободными от различений возникновения, пребывания и распада,</li>
                <li>от идей о причинах, условиях и <em>скандхах</em>,</li>
                <li>следуя лишь пути только-ума (<em>cittamātra</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Тот, кто видит тройственное бытие</li>
                <li>как порождение отпечатков (<em>vāsanā</em>) различений</li>
                <li>и путы понятийного многообразия,</li>
                <li>тянущегося с безначальных времён, —</li>
                <li>тот, благодаря памятованию о не-возникновении</li>
                <li>и о ступенях Будд, свободных от ментальных образов,</li>
                <li>вступает в сферу личного благородного постижения Дхармы.</li>
                <li>Такой [бодхисаттва] обретает власть над собственным умом</li>
                <li>и входит на путь действия без усилий.<a href="#citation-215" id="ref-215" class="citation-mark"><sup>215</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Подобно драгоценному камню, принимающему все цвета (<em>viśvarūpa-maṇi</em>),</li>
                <li>он проникает в тончайшие движения умов живых существ</li>
                <li>с помощью своих <em>проявлений</em>.</li>
                <li>Утвердившись в понимании того, что всё есть только-ум (<em>cittamātra</em>),</li>
                <li>он ведет [других] по ступеням и путям [самадхи].</li>
                <li>Посему, Махамати, бодхисаттве-махасаттве следует быть искусным</li>
                <li>в собственном высшем учении.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2.7 (О признаках ума, манаса и виджнян)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>И вновь Махамати обратился к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Пусть Благословенный изложит мне</li>
                <li>цикл учения Дхармы (<em>dharmaparyāya</em>) —</li>
                <li>учение о признаках ума (<em>citta</em>), интеллекта (<em>manas</em>) и различающего сознания (<em>vijñāna</em>),</li>
                <li>о пяти <em>дхармах</em> и трёх <em>свабхавах!</em></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Это — путь, по которому следуют Будды и бодхисаттвы;</li>
                <li>это — средство освобождения от уз,</li>
                <li>привязывающих к сфере видимого,</li>
                <li>что есть лишь проявление собственного ума.<a href="#citation-216" id="ref-216" class="citation-mark"><sup>216</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Провозгласи же <strong><em>Сердце всех наставлений Будды</em></strong>,</li>
                <li>разрушающее ложные признаки</li>
                <li>всех словесных выражений и логических доводов!</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Поведай о волнах [активных сознаний], возникающих в океане <em>Алайи</em><a href="#citation-217" id="ref-217" class="citation-mark"><sup>217</sup></a></li>
                <li>и о Теле Дхармы Татхагаты —</li>
                <li>ради бодхисаттв, пребывающих здесь,</li>
                <li>на горе Малая в граде Ланка!</li>
            </ul>
        </blockquote>
        <p>Благословенный так ответил бодхисаттве-махасаттве Махамати:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Махамати, зрительное сознание приходит в движение по четырём причинам.</li>
                <li>Каковы эти четыре? А именно:</li>
                <li>- неведение того, что схватываемое есть лишь проявление собственного ума;<a href="#citation-218" id="ref-218" class="citation-mark"><sup>218</sup></a></li>
                <li>- привязанность к отпечаткам (<em>vāsanā</em>) форм, порождённым пагубным безначальным понятийным многообразием;<a href="#citation-219" id="ref-219" class="citation-mark"><sup>219</sup></a></li>
                <li>- собственная природа сознания как таковая;<a href="#citation-220" id="ref-220" class="citation-mark"><sup>220</sup></a></li>
                <li>- стремление к восприятию разнообразных форм и признаков.<a href="#citation-221" id="ref-221" class="citation-mark"><sup>221</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>В силу этих четырёх причин, Махамати,</li>
                <li>из <em>Алайя-виджняны</em> — подобной внутреннему потоку —</li>
                <li>возникают волны активных сознаний.<a href="#citation-222" id="ref-222" class="citation-mark"><sup>222</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Подобно тому, Махамати, как возникает зрительное сознание,</li>
                <li>так же во всех органах чувств, в атомах и порах кожи</li>
                <li>одновременно или последовательно разворачиваются объекты —</li>
                <li>подобно отражениям в зеркале</li>
                <li>или волнам в океане, когда его возмущает ветер.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Махамати, волны океана ума вздымаются ветром объектов.</li>
                <li>Эти пять групп чувственных сознаний</li>
                <li>непрерывны в своих причинах, действиях и признаках,</li>
                <li>они нераздельны,</li>
                <li>прочно спаяны в своих характеристиках кармы и рождения —</li>
                <li>и существа не осознают их подлинной природы.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Вместе с этими пятью группами сознаний</li>
                <li>развёртывается <em>мановиджняна</em>,</li>
                <li>которая определяет признаки объектов и условий.</li>
                <li>Её тело рождено теми же причинами.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>И ни у пяти сознаний, ни у <em>мановиджняны</em> не возникает мысли:</li>
                <li>«Мы являемся причинами друг друга;</li>
                <li>мы движимы привязанностью к различениям того,</li>
                <li>что есть лишь проявление собственного ума».</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>При этом [сознания] приходят в движение,</li>
                <li>нераздельные в своих признаках,</li>
                <li>когда вовлечены в определение объектов познания.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Их движение таково, что даже у йогина, вошедшего в <em>самадхи</em>,</li>
                <li>тончайшее течение отпечатков (<em>vāsanā</em>) остаётся непознанным.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Йогины думают: «Мы войдём в <em>самадхи</em>, прекратив деятельность сознаний».</li>
                <li>Однако они входят в <em>самадхи</em>, не прекратив деятельность сознаний,</li>
                <li>ибо семена-отпечатки (<em>vāsanā-bīja</em>) не уничтожены.</li>
                <li>Сознания кажутся им прекращёнными</li>
                <li>лишь потому, что отсутствует восприятие развёртывающихся объектов.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Настолько тонок, Махамати, ход и движение <em>Алайя-виджняны</em>,</li>
                <li>что его нелегко постичь кому-либо,</li>
                <li>кроме Татхагат и бодхисаттв, утверждённых на ступенях.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Прочим же — шравакам, пратьекабуддам и йогинам-тиртхикам —</li>
                <li>не под силу постичь его,</li>
                <li>даже обладая силой сосредоточения и мудрости.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Лишь те йогины — высшие, средние или низшие —</li>
                <li>что пребывают в лесных чащах и пещерах,</li>
                <li>свободные от многообразия понятий и различений того,</li>
                <li>что есть лишь проявление собственного ума,</li>
                <li>способны постичь признаки ступеней, мастерство в мудрости и знании,</li>
                <li>накопить бесконечные корни благого,</li>
                <li>и обрести <em>посвящение</em>, <em>власти</em>, <em>силы</em> и <em>самадхи</em></li>
                <li>в бесконечных мирах Победителей.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Только в сопровождении добрых друзей (<em>kalyāṇa-mitra</em>) и Победителей, Махамати,</li>
                <li>возможно пересечь океан бытия —</li>
                <li>этот круговорот различений ума (<em>citta</em>), интеллекта (<em>manas</em>) и сознания (<em>vijñāna</em>),</li>
                <li>порождённый кармой, жаждой и неведением.</li>
                <li>Посему, Махамати, йогин должен усердствовать в йоге</li>
                <li>под руководством добрых друзей и Победителей.</li>
            </ul>
        </blockquote>
            <p>Затем Благословенный провозгласил такие стихи:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>99. Подобно тому как волны океана, гонимые ветром,</li>
                <li>вздымаются в танце, и нет им прекращения, —</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>100. Так и поток <em>Алайи</em>, вечно движимый ветрами объектов (<em>viṣaya</em>),</li>
                <li>разворачивается в танце многообразных</li>
                <li>«волн-сознаний» (<em>taraṃga-vijñāna</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>101. Подобно тому как синева, краснота, солёность,</li>
                <li>белизна раковины, белизна молока, сладость сахара,</li>
                <li>ароматы плодов и цветов, лучи солнца —</li>
                <li>неотделимы от своей основы,</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>102. и как волны океана не считаются</li>
                <li>ни отличными от него, ни тождественными ему,</li>
                <li>так и семь сознаний соединены с Умом.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>103. Изменчивость (<em>pariṇāma</em>) океана</li>
                <li>проявляет многообразие волн;</li>
                <li>точно так же и <em>Алайя</em></li>
                <li>разворачивается в многообразии того,</li>
                <li>что зовётся «сознаниями».</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>104.Ум (<em>citta</em>), <em>манас</em> (<em>manas</em>)</li>
                <li>и сознание (<em>vijñāna</em>)</li>
                <li>различаются лишь ради указания признаков.</li>
                <li>Восемь [сознаний] неразделимы по признакам:</li>
                <li>нет ни определяемого (<em>lakṣya</em>), ни признака (<em>lakṣaṇa</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>105. Как между океаном и волнами</li>
                <li>нет качественного различия,</li>
                <li>так и в Уме не найти</li>
                <li>реального видоизменения (<em>pariṇāma</em>)</li>
                <li>в виде [отдельных] сознаний.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>106. Умом (<em>citta</em>) накапливается карма,</li>
                <li><em>манасом</em> — различается,</li>
                <li>[умственной] виджняной познаётся [объект],</li>
                <li>а пятью [чувственными сознаниями]</li>
                <li>выстраивается воспринимаемое.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>[Махамати спросил:]</li>
                <li>107. — Ум людям видится в цветах —</li>
                <li>то синим, то красным.</li>
                <li>О Великий Мудрец! Почему же Ты говоришь</li>
                <li>о сходстве между волнами и умом?</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>[Благословенный ответил:]</li>
                <li>108. — Воистину, в самих волнах</li>
                <li>нет синевы или красноты!</li>
                <li>Деятельность же ума описывается [через них]</li>
                <li>лишь ради [пояснения] признаков для неразумных.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>109. Сам же ум (<em>svacitta</em>, <em>Alaya</em>) —  без  деятельности (<em>vṛtti</em>),</li>
                <li>ибо оно свободнен от схватываемого (<em>grāhya</em>).</li>
                <li>Если бы было схватываемое,</li>
                <li>тогда возникло бы и схватывающее (<em>grāha</em>) —</li>
                <li>подобно волнам [и океану].</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>110. <em>Виджняна</em> проявляется людям</li>
                <li>как «тело», «объекты восприятия» и «мир-вместилище».<a href="#citation-223" id="ref-223" class="citation-mark"><sup>223</sup></a></li>
                <li>Поэтому его деятельность видится</li>
                <li>подобной волнам [океана].</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>[Махамати спросил:]</li>
                <li>111. — Океан видится танцующим в облике волн.</li>
                <li>Почему же подобная динамика (<em>vṛtti</em>) <em>Алайи</em></li>
                <li>не постигается разумом (<em>buddhi</em>)?</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>[Благословенный ответил:]</li>
                <li>112. — У невежд (<em>bāla</em>) разум слаб.</li>
                <li>Потому сходство <em>Алайи</em> с океаном</li>
                <li>и её динамики с волнами</li>
                <li>разъясняется им через это сравнение.</li>
            </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>[Махамати продолжил:]</li>
                <li>113. — Как солнце восходит над миром,</li>
                <li>светя одинаково низшим и высшим,</li>
                <li>так и Ты, Светоч Мира,</li>
                <li>излагаешь истину (<em>tattva</em>) невеждам.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>114. Но утвердив их в дхармах,</li>
                <li>почему не излагаешь истину?</li>
                <li>Ведь если Ты говоришь истину,</li>
                <li>то истина в уме не обнаруживается.</li>
            </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>[Благословенный ответил:]</li>
                <li>115. — Как волны в океане, отражения в зеркале</li>
                <li>образы во сне видятся одновременно (<em>yugapad</em>),</li>
                <li>так и ум в своей собственной сфере (<em>svagocara</em>)</li>
                <li>проявляется в одно и то же время.</li>
                <li>Но из-за неполноты (отсутствия) (<em>vaikalyāt</em>) объектов [восприятия]</li>
                <li>он разворачивается последовательно.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>116. Виджняна распознаёт, <em>манас</em> мыслит,</li>
                <li>пяти [сознаниям] является воспринимаемое;</li>
                <li>но в сосредоточении (<em>samāhita</em>) нет последовательности.</li>
            </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>117. Как опытный живописец или его ученик</li>
                <li>наносит те или иные краски ради создания картины —</li>
                <li>так и Я излагаю Учение.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>118. [Суть] самой картины не обнаруживается</li>
                <li>ни в красках, ни в холсте, ни в сосуде [с красками];</li>
                <li>но ради привлечения существ</li>
                <li>картина изображается при помощи тех или иных красок.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>119. Проповедь не отклоняется от сути,</li>
                <li>истина (<em>tattva</em>) же — воистину вне знаков.</li>
                <li>Утвердив [учеников] в дхарме,</li>
                <li>Я указываю йогинам истину (<em>tattva</em>).</li>
                <li>Истина (<em>tattva</em>) — лично постигаемая (<em>pratyātmagatikam</em>),</li>
                <li>она свободна от измышляемого (<em>kalpya</em>) и измышления (<em>kalpana</em>).</li>
                <li>для незрелых же учение [дается] иначе.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>120. Подобно тому как многообразная иллюзия (<em>māyā</em>) видима,</li>
                <li>но не обнаруживается,</li>
                <li>так и проповедь [Будды] видится многообразной,</li>
                <li>хотя [в своей сути] не отклоняется [от Таковости].</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>121. Ведь то, что является наставлением для одного,</li>
                <li>не является наставлением для другого.</li>
                <li>Как врач назначает лекарство</li>
                <li>каждому больному сообразно его недугу,</li>
                <li>так и Будды провозглашают существам: «только-ум» (<em>cittamātra</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>122. Это не сфера рассудочных логиков (<em>tārkika</em>)</li>
                <li>и не сфера шраваков.</li>
                <li>То, что излагают Владыки, —</li>
                <li>есть сфера личного постижения (<em>pratyātmagatigocara</em>).</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2.8 (О трёх признаках благородной мудрости)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>И ещё, Махамати, бодхисаттве, желающему полностью постичь ту сферу,</li>
                <li>где различаются «схватываемое» и «схватывающий»,</li>
                <li>которые являются лишь проявлением собственного ума,</li>
                <li>следует избегать шумных сборищ (<em>saṃgaṇikā</em>),</li>
                <li>быть свободным от помехи сна и лености (<em>middha-nivaraṇa</em>),</li>
                <li>неустанно пребывать в йоге бодрствования</li>
                <li>в первую, среднюю и последнюю стражу ночи,</li>
                <li>быть свободным от признаков, присущих учениям ложных философов (<em>kutīrthya</em>),</li>
                <li>мифам и повествованиям, а также путям шраваков и пратьекабудд.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Бодхисаттве-махасаттве следует полностью проникнуть в понимание того,</li>
                <li>как разворачиваются признаки различений видимого собственным умом.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>И ещё, Махамати, бодхисаттве-махасаттве, утвердившись</li>
                <li>в понимании признаков ума, сознания и мудрости (<em>prajñā</em>),</li>
                <li>следует практиковать йогу трёх признаков высшей благородной мудрости (<em>āryajñāna</em>).</li>
                <li>Каковы же эти три признака высшей мудрости? Это:</li>
                <li>признак без ментальных образов,<a href="#citation-224" id="ref-224" class="citation-mark"><sup>224</sup></a></li>
                <li>признак опоры на силу обетов всех Будд;<a href="#citation-225" id="ref-225" class="citation-mark"><sup>225</sup></a></li>
                <li>признак личного благородного постижения.<a href="#citation-226" id="ref-226" class="citation-mark"><sup>226</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Обретя их, йогин оставляет признаки ума, прозрения и знания,</li>
                <li>подобно тому, как отбрасывают хромого осла.<a href="#citation-227" id="ref-227" class="citation-mark"><sup>227</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Достигнув восьмой ступени — уровня Сынов Победителя, —</li>
                <li>он всецело входит в йогу этих трёх высших признаков.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>В отношении этого, Махамати, признак без ментальных образов</li>
                <li>развёртывается благодаря полному ознакомлению с признаками</li>
                <li>всех шраваков, пратьекабудд и тиртхиков и их преодолению.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Признак благословения развёртывается благодаря силе обетов прежних Будд.</li>
                <li>Признак личного благородного постижения развёртывается благодаря:</li>
                <li>- отсутствию привязанности к признакам всех дхарм,</li>
                <li>- обретению тела в самадхи, подобном майе,<a href="#citation-228" id="ref-228" class="citation-mark"><sup>228</sup></a></li>
                <li>- и вхождению в сферу деятельности ступеней Будды.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Это, Махамати, — три признака Благородных.</li>
                <li>Обладая этими тремя признаками,</li>
                <li>Благородные достигают сферы личного благородного постижения.</li>
                <li>Посему, Махамати, следует практиковать йогу трёх признаков благородной мудрости.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2.9 (Исследование основы благородной мудрости)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
                <li>Затем бодхисаттва-махасаттва Махамати,</li>
                <li>постигнув ход мыслей и устремлений того собрания бодхисаттв,</li>
                <li>будучи наделён благословением всех Будд,</li>
                <li>обратился к Благословенному с вопросом о наставлении в Дхарме,</li>
                <li>именуемом «Исследование основы благородной мудрости»:<a href="#citation-229" id="ref-229" class="citation-mark"><sup>229</sup></a></li>
            </ul>
            <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Пусть Благословенный изложит мне</li>
                <li>наставление «Исследование основы благородной мудрости»,</li>
                <li>опирающееся на сто восемь тезисов.</li>
                <li>Опираясь на него, Татхагаты, Архаты, Совершенно Пробуждённые</li>
                <li>разъясняют бодхисаттвам-махасаттвам,</li>
                <li>чьи умы всё ещё воспринимают собственные и общие признаки явлений [как реальные],</li>
                <li>разделение путей воображаемой природы.<a href="#citation-230" id="ref-230" class="citation-mark"><sup>230</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Благодаря ясному различению этих путей воображаемой природы,</li>
                <li>бодхисаттвы</li>
                <li>• полностью очистят своё продвижение в отсутствии «я» личности и дхарм;<a href="#citation-231" id="ref-231" class="citation-mark"><sup>231</sup></a></li>
                <li>• станут искусными в прохождении ступеней;</li>
                <li>• превзойдут блаженство <em>дхьян</em>, <em>самадхи</em> и <em>самапатти</em> всех шраваков, пратьекабудд и тиртхиков;</li>
                <li>• достигнут вхождения в сферу непостижимого удела Татхагат, которая свободна от путей пяти <em>дхарм</em> и трёх <em>свабхав</em>.</li>
                <li>Так они обретут Дхармакаю Татхагат,</li>
                <li>где Учение неразрывно связано с мудростью и знанием (<em>prajñā-jñāna</em>),</li>
                <li>где преодолена сфера <em>майи</em>,</li>
                <li>которая охватывает все земли Будд,</li>
                <li>обитель <em>Тушита</em> и высшее небо <em>Акаништха</em>.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.10 (О бытии и небытии)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Здесь, Махамати, некоторые тиртхики и нетиртхики,</li>
            <li>придерживающиеся воззрения небытия (<em>nāstitva</em>),<a href="#citation-232" id="ref-232" class="citation-mark"><sup>232</sup></a></li>
            <li>вследствие истощения причины различающего рассудка<a href="#citation-233" id="ref-233" class="citation-mark"><sup>233</sup></a></li>
            <li>и из-за отсутствия собственной природы,</li>
            <li>умозрительно полагают: «Рогов у зайца не существует»</li>
            <li>и [заключают]: «Подобно тому, как нет рогов у зайца,</li>
            <li>так и все дхармы [не существуют]».<a href="#citation-234" id="ref-234" class="citation-mark"><sup>234</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Другие же, Махамати,</li>
            <li>видя различия в элементах, качествах, атомах,</li>
            <li>веществах, формах и расположении,</li>
            <li>и будучи привязанными к убеждению, что «рогов у зайца нет»,</li>
            <li>умозрительно утверждают:</li>
            <li>«Но рога у коровы-то есть!»<a href="#citation-235" id="ref-235" class="citation-mark"><sup>235</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Они, Махамати, впали в воззрения двух крайностей,</li>
            <li>ибо их умы не утвердились в понимании только-ума (<em>cittamātra</em>).</li>
            <li>Поддерживая различения, возникающие в сфере собственного ума,</li>
            <li>они тем самым питают эти [воззрения].</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, в том, что касается лишь различения путей</li>
            <li>«тела», «объектов восприятия» и «мира-вместилища»,</li>
            <li>не следует умозрительно утверждать рога зайца</li>
            <li>ни как «существующие», ни как «несуществующие».</li>
            <li>Точно так же, Махамати, не следует воображать</li>
            <li>природы всех явлений (<em>bhāva</em>)</li>
            <li>ни как «существующие», ни как «несуществующие».</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Те же, Махамати, кто свободен от [двойственности] бытия и небытия,</li>
            <li>не воображают: «Рогов у зайца нет».</li>
            <li>Им не следует воображать отсутствие рогов у зайца,</li>
            <li>поскольку [идея] небытия имеет своей причиной опору на [идею] бытия.<a href="#citation-236" id="ref-236" class="citation-mark"><sup>236</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Более того, Махамати, поскольку при тщательном исследовании</li>
            <li>вплоть до мельчайших атомов<a href="#citation-237" id="ref-237" class="citation-mark"><sup>237</sup></a></li>
            <li>никакая реальная основа (<em>vastu</em>) не может быть обнаружена,</li>
            <li>не следует воображать: «Рога у коровы есть»,</li>
            <li>ибо это исключено из сферы благородного прозрения (<em>āryajñāna-gocara</em>).</li>
        </ul>
        </blockquote>
        <p>Тогда бодхисаттва-махасаттва Махамати сказал Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Не так ли, Благословенный:</li>
            <li>видя признак не-развёртывания (<em>apravṛtti</em>) различения,</li>
            <li>мы заключаем, что его небытие (<em>nāstitva</em>)</li>
            <li>обусловлено [соотнесением с] этим самым не-развёртыванием различения?<a href="#citation-238" id="ref-238" class="citation-mark"><sup>238</sup></a></li>
        </ul>
        </blockquote>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Нет, Махамати, его небытие</li>
            <li>не обусловлено не-развёртыванием различения. Почему?</li>
            <li>Потому что само различение является причиной своего развёртывания.</li>
            <li>Ведь различение, Махамати,</li>
            <li>развёртывается, опираясь на [образ] рогов.</li>
            <li>Поскольку оно развёртывается, опираясь на [этот] субстрат,</li>
            <li>то из-за наличия этой причинной опоры</li>
            <li>и из-за того, что оно не является</li>
            <li>ни отличным от неё, ни тождественным ей,</li>
            <li>небытие рогов зайца</li>
            <li>не может быть установлено через соотнесение [с чем-либо].</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Если бы различение было иным, чем рога зайца,</li>
            <li>оно не имело бы рога своей причиной.</li>
            <li>Если же оно было бы тождественным им,</li>
            <li>то из-за их необнаруживаемости</li>
            <li>при анализе вплоть до атомов</li>
            <li>различение, будучи неотличным от них,</li>
            <li>также отсутствовало бы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поскольку же оба этих случая</li>
            <li>(бытие и небытие) невозможны,</li>
            <li>то через соотнесение с чем</li>
            <li>и для кого возникает «небытие»?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Посему, Махамати,</li>
            <li>не следует воображать небытие рогов зайца</li>
            <li>через соотнесение с их бытием.</li>
            <li>Из-за порочности самой причины (<em>viṣama-hetu</em>)<a href="#citation-239" id="ref-239" class="citation-mark"><sup>239</sup></a></li>
            <li>тезис о бытии и небытии</li>
            <li>не может быть доказан сторонниками</li>
            <li>[учения] о бытии и небытии.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Другие же тиртхики, Махамати,</li>
            <li>будучи привязаны к формам, причинам и очертаниям</li>
            <li>и не будучи искусны в различении природы пространства (<em>ākāśa</em>),</li>
            <li>воображают, будто форма отделена от пространства.</li>
            <li>Но само пространство, Махамати, и есть форма.</li>
            <li>Из-за взаимопроникновения первоэлементов и формы,</li>
            <li>сама форма и есть пространство.</li>
            <li>Различие между формой и пространством</li>
            <li>следует понимать лишь как условное разделение</li>
            <li>на «поддерживаемое» (<em>ādheya</em>) и «поддерживающее» (<em>ādhāra</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Элементы, Махамати,</li>
            <li>развёртываются, различаясь своими собственными признаками,</li>
            <li>и [кажутся] не имеющими опоры в пространстве,</li>
            <li>но в них нет ничего, что не было бы пространством.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Точно так же, Махамати,</li>
            <li>рога зайца [кажутся] существующими</li>
            <li>лишь в соотнесении с рогами коровы.</li>
            <li>Но если рога коровы разобрать на атомы,</li>
            <li>а те — на ещё более мелкие частицы,</li>
            <li>то они не сохранят признак «частицы».</li>
            <li>С чем же тогда соотносить «небытие»?</li>
            <li>Если же [соотносить] с иной основой (<em>vastu</em>),</li>
            <li>то и она [при анализе] окажется такой же.<a href="#citation-240" id="ref-240" class="citation-mark"><sup>240</sup></a></li>
        </ul>
        </blockquote>
        <p>Затем Благословенный вновь обратился к бодхисаттве-махасаттве Махамати:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Тебе, Махамати, а также и другим бодхисаттвам</li>
            <li>следует быть свободными</li>
            <li>от различений, основанных на [ложных] воззрениях</li>
            <li>относительно рогов зайца и коровы,</li>
            <li>пространства, формы и прочего.</li>
            <li>Вам следует обладать умом, следующим за пониманием того,</li>
            <li>что всё есть лишь различение воспринимаемого собственным умом.<a href="#citation-241" id="ref-241" class="citation-mark"><sup>241</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Во всех собраниях в полях Сынов Победителя</li>
            <li>тебе надлежит давать наставления</li>
            <li>по этой йоге воспринимаемого собственным умом.<a href="#citation-242" id="ref-242" class="citation-mark"><sup>242</sup></a></li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>123. Воспринимаемого не обнаруживается;</li>
                <li>ум же вводится в заблуждение воспринимаемым.</li>
                <li>То, что предстаёт существам</li>
                <li>как тело, [объекты] наслаждения и обитель,</li>
                <li>именуется <em>Алайей</em>.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>124. Ум (<em>citta</em>), <em>манас</em> (<em>manas</em>) и различающее сознание (<em>vijñāna</em>),</li>
                <li><em>три природы</em>, <em>пять дхарм</em> и двойное отсутствие «я» —</li>
                <li>вот что провозглашают Владыки как чистое [учение].</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>125. Подобно [понятиям] «длинное» и «короткое»,</li>
                <li>всё возникает лишь во взаимной зависимости.</li>
                <li>Нет доказательства бытия самого по себе;</li>
                <li>бытие устанавливается лишь в противоположности небытия.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>126. Если разлагать форму до мельчайших частиц,</li>
                <li>то в конце концов нельзя будет вообразить никакую форму.</li>
                <li>Учение о «только-уме» (<em>cittamātra</em>) не принимается теми,</li>
                <li>кто придерживается ложных воззрений.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>127. То, что Владыки излагают</li>
                <li>как сферу личного постижения (<em>pratyātmagati-gocara</em>),</li>
                <li>не является областью для рассудочных логиков (<em>tārkika</em>)</li>
                <li>и не доступно шравакам.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.11 (Постепенное и мгновенное очищение)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному,</li>
            <li>желая очистить поток того, что есть лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-dhārā</em>):</li>
        </ul>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Как, Благословенный, очищается поток воспринимаемого собственным умом</li>
                <li>постепенно или мгновенно?</li>
            </ul>
        </blockquote>
        <p>Благословенный ответил:</p>
            <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
                <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Постепенно, Махамати, очищается поток воспринимаемого собственным умом, а не мгновенно.</li>
            <li>Подобно тому, как плоды манго созревают постепенно, а не мгновенно,</li>
            <li>так и поток воспринимаемого собственным умом у существ очищается постепенно.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, как гончар изготавливает сосуды постепенно, а не мгновенно,</li>
            <li>так и Татхагата очищает поток воспринимаемого собственным умом у существ постепенно.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, как травы, кусты и деревья вырастают из земли постепенно,</li>
            <li>так и Татхагата очищает этот поток постепенно.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, как мастерство в смехе, игре, пении, музыке,</li>
            <li>рисовании и письме обретается постепенно,</li>
            <li>так и Татхагата очищает поток существ постепенно.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Но также, Махамати, мгновенно Татхагата очищает поток воспринимаемого собственным умом у существ —</li>
            <li>делая его без различений (<em>nirvikalpa</em>)</li>
            <li>и озаряя сферу без ментальных образов (<em>nirābhāsa-gocara</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, как в зеркале мгновенно и без различений проявляются все формы,</li>
            <li>так и Татхагата мгновенно очищает поток существ.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, как диски солнца и луны мгновенно освещают своими лучами все формы,</li>
            <li>так и Татхагата мгновенно открывает сферу непостижимого знания Победителей</li>
            <li>тем существам, кто очистился от пагубных отпечатков.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, как Алайя-виджняна мгновенно проявляет</li>
            <li>тело, обитель и объекты наслаждения,</li>
            <li>так и Будда излияния (благ)<a href="#citation-243" id="ref-243" class="citation-mark"><sup>243</sup></a> мгновенно приводит существ к зрелости</li>
            <li>и дарует йогинам соединение с обителью в небесном дворце Акаништха.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, как Будда Таковости (<em>dharmatābuddha</em>) мгновенно сияет</li>
            <li>лучами [тел] воплощения и излияния,</li>
            <li>так и Он мгновенно сияет</li>
            <li>признаками Дхармы личного благородного постижения,</li>
            <li>преодолевая ложные взгляды о бытии и небытии.</li>
        </ul>
            </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.12 (О трёх Буддах и их учении)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, Будда излияния (благ) (<em>niṣyandabuddha</em>)</li>
            <li>излагает [учение] о том, что все дхармы —</li>
            <li>в их собственных и общих признаках —</li>
            <li>связаны с причинами и признаками отпечатков (<em>vāsanā</em>)</li>
            <li>того, что есть лишь воспринимаемое собственным умом (<em>svacitta-dṛśya</em>).</li>
            <li>Он учит о необнаружении реальной основы (<em>anupalabdhi</em>)</li>
            <li>у привязанности к воображаемой природе (<em>parikalpita-svabhāva</em>),</li>
            <li>которая подобна множеству разнообразных магических фигур на сцене.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Далее, Махамати, проявление воображаемой природы возникает</li>
            <li>из привязанности к зависимой природе (<em>paratantra-svabhāva</em>).</li>
            <li>Это подобно тому, как магическая фигура,</li>
            <li>созданная из соломы, дерева и глины силой заклинаний,</li>
            <li>принимает облик любого существа;</li>
            <li>хотя она кажется телом живого существа, она не является им [по сути].</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Так же, Махамати,</li>
            <li>на основе зависимой природы (взаимообусловленных процессов)</li>
            <li>воображаемая природа являет разнообразие признаков изменчивого ума.</li>
            <li>Привязанность к признакам объектов через силу отпечатков</li>
            <li>порождает признаки воображаемой природы.</li>
            <li>Это, Махамати, — поучение Будды излияния (благ).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Будда Таковости (<em>dharmatābuddha</em>), напротив,</li>
            <li>утверждает состояние личного благородного постижения (<em>pratyātmāryagati</em>),</li>
            <li>свободное от любых признаков собственной природы ума (<em>citta-svabhāva</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Будда воплощения (<em>nirmāṇabuddha</em>), Махамати, разъясняет тонкости практики:</li>
            <li>даяние (<em>dāna</em>), нравственность (<em>śīla</em>), <em>дхьяны</em>,</li>
            <li>[методы] сосредоточения (<em>samādhi</em>) и различные виды мудрости и недвойственного знания (<em>prajñā-jñāna</em>), <em>скандхи</em>, <em>дхату</em>, <em>аятаны</em>, пути освобождения (<em>vimokṣa</em>) и</li>
            <li>признаки путей развёртывания сознаний (<em>vijñāna-gati-lakṣaṇa</em>).</li>
            <li>Он также указывает, как превзойти воззрения тиртхиков.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Будда Таковости, Махамати, — безопорный (<em>nirālamba</em>).</li>
            <li>Он за пределами всех опор, действий, органов чувств, мер и признаков.</li>
            <li>Он недоступен для тех, кто захвачен признаками «я»,</li>
            <li>как это бывает у невежд, шраваков и тиртхиков.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Посему, Махамати, следует усердствовать в йоге</li>
            <li>личного благородного постижения</li>
            <li>и пребывать в видении, свободном от признаков воспринимаемого собственным умом.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.13 (Особенности колесницы шраваков)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, существует два вида признаков в колеснице шраваков:</li>
            <li>признаки личного благородного постижения (<em>pratyātmāryādhigama-lakṣaṇa</em>),</li>
            <li>и признаки привязанности к воображаемой природе явлений.<a href="#citation-244" id="ref-244" class="citation-mark"><sup>244</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Каковы, Махамати, признаки личного благородного постижения у шраваков?</li>
            <li>Через постижение того, что <em>скандхи</em>, <em>дхату</em>, <em>аятаны</em> и внешние объекты —</li>
            <li>пусты, лишены «я», страдательны и непостоянны,</li>
            <li>а также через бесстрастие и умиротворение,</li>
            <li>возникающие при этом видении, их ум входит в сосредоточение.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Достигнув сосредоточения, шраваки обретают</li>
            <li>блаженство пребывания в личном благородном постижении,</li>
            <li>свободном от отпечатков <em>дхьян</em>, освобождений, <em>самадхи</em>,</li>
            <li>путей и плодов, достижений и освобождений,</li>
            <li>а также от непостижимых превращений и переходов.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Однако, Махамати, бодхисаттва-махасаттва, достигнув этого блаженства</li>
            <li>— будь то блаженство прекращения (<em>nirodha</em>) или блаженство <em>самадхи</em> (<em>samāpatti</em>) —</li>
            <li>не должен принимать его за окончательное.</li>
            <li>Из сострадания к существам и в силу своих прежних обетов</li>
            <li>он не должен удовлетворяться этим состоянием.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Какова же, Махамати, привязанность шраваков к воображаемой природе явлений?</li>
            <li>Это их воззрение, когда они видят великие элементы —</li>
            <li>синий, жёлтый, тёплый, текучий, движущийся, твёрдый<a href="#citation-245" id="ref-245" class="citation-mark"><sup>245</sup></a> —</li>
            <li>как обладающие собственными признаками.</li>
            <li>Они прочно связаны с логикой, писаниями и средствами познания,</li>
            <li>считая эти свойства реальными,</li>
            <li>и впадают в различение их собственной природы (<em>svabhāva</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Бодхисаттва, постигнув это, должен отвратиться от такого пути.</li>
            <li>Через вхождение в отсутствие «я» дхарм (<em>dharma-nairātmya</em>)</li>
            <li>он должен устранить воззрение, ограничивающееся лишь отсутствием «я» личности (<em>pudgala-nairātmya</em>),</li>
            <li>и утвердиться на последовательности ступеней.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.14 (Вечное и Непостижимое)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Благословенный, Ты провозглашаешь <strong>Вечное и Непостижимое</strong></li>
            <li>как сферу личного благородного постижения (<em>pratyātmāryagati-gocara</em>)</li>
            <li>и как сферу высшей истины (<em>paramārtha-gocara</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Но разве, Благословенный, тиртхики также не утверждают,</li>
            <li>что их <strong>Первопричина</strong> — <strong>Вечна и Непостижима</strong>?</li>
        </ul>
        </blockquote>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Нет, Махамати, у тиртхиков <strong>причина</strong> не достигает</li>
            <li>подлинной <strong>Вечности и Непостижимости</strong>. И вот почему:</li>
            <li>у тиртхиков <strong>Вечное и Непостижимое</strong></li>
            <li>не наделено признаками причины (<em>hetu-lakṣaṇa</em>) и её собственными признаками (<em>sva-lakṣaṇa</em>).</li>
            <li>Если же нечто лишено признаков причины и собственными признаками,</li>
            <li>как оно может быть названо <strong>«Вечным и Непостижимым»</strong>?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Даже если бы их <strong>Вечное и Непостижимое</strong></li>
            <li>обладало признаками причины и собственными признаками,</li>
            <li>оно стало бы зависимым от них</li>
            <li>и, следовательно, <strong>не было бы ни вечным, ни непостижимым</strong>.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Моё же, Махамати, <strong>Высшее Вечное и Непостижимое</strong></li>
            <li>наделено признаками высшей истины (<em>paramārtha-lakṣaṇa</em>) и</li>
            <li>является основанием для её познания.</li>
            <li>Оно <strong>вне бытия и небытия</strong>,</li>
            <li>ибо есть <strong>признак личного благородного постижения</strong></li>
            <li>и <strong>причина познания высшей истины</strong>.</li>
            <li>Оно <strong>вечно</strong>, потому что <strong>не сотворено</strong>,</li>
            <li>и подобно <strong>пространству</strong>, <strong>нирване</strong> и <strong>прекращению</strong> (<em>nirodha</em>).</li>
            <li>Посему, Махамати, это <strong>не тождественно</strong> учению тиртхиков.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Эта <strong>Вечность и Непостижимость Татхагат</strong> —</li>
            <li>не что иное, как <strong>Таковость</strong> (<em>tathatā</em>),</li>
            <li>обретаемая через <strong>личное благородное постижение</strong>.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Посему, Махамати, бодхисаттве-махасаттве</li>
            <li>следует усердствовать в йоге ради обретения</li>
            <li>этого <strong>Вечного и Непостижимого</strong> — <strong>личного благородного постижения</strong>.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, <strong>Вечность и Непостижимость</strong> тиртхиков</li>
            <li>обосновывается ими как иное по отношению к непостоянному.<a href="#citation-246" id="ref-246" class="citation-mark"><sup>246</sup></a></li>
            <li>Она не является вечной, поскольку</li>
            <li>не возникает как признак их собственного достижения.<a href="#citation-247" id="ref-247" class="citation-mark"><sup>247</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Если же, Махамати, тиртхики утверждают свою <strong>Вечность и Непостижимость</strong></li>
            <li>через рассудочный вывод (<em>anumāna-buddhi</em>),</li>
            <li>видя, что сотворённые вещи непостоянны и исчезают,</li>
            <li>и потому полагая существование вечного,</li>
            <li>то по этой самой причине</li>
            <li>и Моё учение тоже могло бы показаться таким же —</li>
            <li>ведь Я также указываю на вечное,</li>
            <li>видя непостоянство и исчезновение сотворённого.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Если же, Махамати, их вечность и непостижимость</li>
            <li>наделены признаками причины (<em>hetu-lakṣaṇa</em>),</li>
            <li>то из-за отсутствия у тиртхиков</li>
            <li>фактической причины (<em>hetu-bhāva</em>) и собственной природы (<em>sva-lakṣaṇa</em>)</li>
            <li>их <strong>Вечность и Непостижимость</strong>, Махамати,</li>
            <li>подобна рогам зайца.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Их учение, Махамати, сводится лишь к словесным различениям.<a href="#citation-248" id="ref-248" class="citation-mark"><sup>248</sup></a></li>
            <li>Почему это так?</li>
            <li>Потому что рога зайца — это лишь словесные различения,</li>
            <li>поскольку у них нет собственной причины и признаков (<em>sva-hetu-lakṣaṇa</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Моё же, Махамати, <strong>Вечное и Непостижимое</strong> является вечным,</li>
            <li>ибо оно есть признак личного благородного постижения,<a href="#citation-249" id="ref-249" class="citation-mark"><sup>249</sup></a></li>
            <li>ибо оно свободно от двойственности сотворённого и несотворённого.<a href="#citation-250" id="ref-250" class="citation-mark"><sup>250</sup></a></li>
            <li>Оно не является вечным</li>
            <li>из-за вывода, основанного на внешнем непостоянстве.<a href="#citation-251" id="ref-251" class="citation-mark"><sup>251</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Тот же, Махамати, кто утверждает вечность</li>
            <li>лишь на основе логического вывода об отсутствии [непостоянного] во вне,</li>
            <li>тот не знает признака собственной причины этой вечности.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поскольку признаки сферы личного благородного постижения</li>
            <li>лежат вне их понимания,</li>
            <li>с ними, Махамати, не о чем и рассуждать.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.15 (Сансара и Нирвана)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Кроме того, Махамати, есть те, кто, страшась страданий,</li>
                <li>порождённых различениями в сансаре, ищут Нирвану.</li>
                <li>Не зная отсутствия различия между сансарой и Нирваной,</li>
                <li>они воображают Нирвану как полное отсутствие</li>
                <li>различений во всех явлениях и</li>
                <li>и невозвращение объектов к органам чувств.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Они не понимают, что [истинная Нирвана] — это</li>
                <li>поворот основы (<em>parāvṛtti</em>) в <em>Алайя-виджняне</em>,</li>
                <li>достигаемый через личное постижение (<em>pratyātmagati</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Посему, Махамати, эти заблуждающиеся люди</li>
                <li>становятся приверженцами учения о Трёх Колесницах,</li>
                <li>а не учения «только-ума», свободного от ментальных образов (<em>nirābhāsa</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Махамати, они не постигают сферу опыта</li>
                <li>Татхагат прошлого, будущего и настоящего,</li>
                <li>которая есть лишь воспринимаемое собственным умом;<a href="#citation-252" id="ref-252" class="citation-mark"><sup>252</sup></a></li>
                <li>они привязаны к сфере объектов,</li>
                <li>кажущихся существующими вне ума.<a href="#citation-253" id="ref-253" class="citation-mark"><sup>253</sup></a></li>
                <li>Так они, Махамати, продолжают вращаться в колесе сансары.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.16 (Не-возникновение всех дхарм)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, Татхагаты прошлого, будущего и настоящего</li>
            <li>говорят о не-возникновении всех дхарм. Почему это так?</li>
            <li>Потому что, Махамати, все явления —</li>
            <li>лишь воспринимаемы собственным умом (<em>svacitta-dṛśya</em>),</li>
            <li>свободны от бытия и небытия,</li>
            <li>и потому лишены возникновения.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, все дхармы подобны рогам зайца, лошади, осла или верблюда.</li>
            <li>Все явления, Махамати, являются невозникшими,</li>
            <li>ибо их собственная природа (<em>svabhāva</em>)</li>
            <li>лишь ложно воображена (<em>abhūta-parikalpita</em>) невеждами и обычными людьми.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Ибо то, что кажется возникновением признаков собственной природы явлений,</li>
            <li>Махамати, есть лишь сфера личного благородного постижения;</li>
            <li>это не природа двойственной сферы,</li>
            <li>воображаемой невеждами.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, Алайя-виджняна,</li>
            <li>обладающая признаками тела, объектов наслаждения и обители,</li>
            <li>разворачивается через признаки схватываемого и схватывающего (<em>grāhya-grāhaka</em>).</li>
            <li>Но невежды, чьи умы захвачены [двойственностью] двух воззрений —</li>
            <li>о возникновении, пребывании и распаде, —</li>
            <li>воображают возникновение всех явлений как «существующих» или «несуществующих».</li>
            <li>Посему, Махамати, тебе следует усердствовать в йоге.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.17 (Пять родов постижения)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, существует пять родов постижения.<a href="#citation-254" id="ref-254" class="citation-mark"><sup>254</sup></a></li>
            <li>Каковы эти пять?</li>
            <li>Род постижения колесницы шраваков;<a href="#citation-255" id="ref-255" class="citation-mark"><sup>255</sup></a></li>
            <li>Род постижения колесницы пратьекабудд;<a href="#citation-256" id="ref-256" class="citation-mark"><sup>256</sup></a></li>
            <li>Род постижения колесницы Татхагат;<a href="#citation-257" id="ref-257" class="citation-mark"><sup>257</sup></a></li>
            <li>Неопределённый род,<a href="#citation-258" id="ref-258" class="citation-mark"><sup>258</sup></a> склоняющийся к одной из трёх колесниц;</li>
            <li>Лишённый рода<a href="#citation-259" id="ref-259" class="citation-mark"><sup>259</sup></a> — пятый.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Как же, Махамати, распознать род колесницы шраваков?</li>
            <li>Тот, у кого при изложении учения о постижении</li>
            <li>собственных и общих признаков <em>скандх</em>, <em>дхату</em> и <em>аятан</em></li>
            <li>волосы встают дыбом от благоговения,</li>
            <li>и чей ум устремляется к познанию признаков,</li>
            <li>но не к постижению нераздельности в цепи зависимого возникновения, —</li>
            <li>таков, Махамати, род колесницы шраваков.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Узрев свой путь, такой человек</li>
            <li>на пятой или шестой ступени<a href="#citation-260" id="ref-260" class="citation-mark"><sup>260</sup></a></li>
            <li>избавляется от явных клеш,</li>
            <li>но не от клеш-отпечатков (<em>vāsanā-kleśa</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Находясь в состоянии непостижимого перехода (<em>acintya-cyuti</em>),</li>
            <li>он испускает истинный львиный рык:</li>
            <li>«Рождение моё исчерпано, святая жизнь прожита!»</li>
            <li>И, утвердившись лишь в понимании отсутствия «я» личности,</li>
            <li>он полагает, что достиг Нирваны.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Иные же, Махамати,</li>
            <li>ищут Нирвану, не постигая, что такие понятия, как</li>
            <li>«Высшее Я» (<em>ātman</em>), «существо» (<em>sattva</em>), «жизненная сила» (<em>jīva</em>), «взращивающий» (<em>poṣa</em>),</li>
            <li>«человек» (<em>puruṣa</em>), «личность» (<em>pudgala</em>) — лишь воображения ума.<a href="#citation-261" id="ref-261" class="citation-mark"><sup>261</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Иные же, Махамати, увидев, что все дхармы зависят от причин,</li>
            <li>полагают, будто это и есть путь к Нирване.</li>
            <li>Однако, Махамати, без видения отсутствия «я» в дхармах нет освобождения.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Таково, Махамати, [состояние] тех, кто принадлежит к роду шраваков:</li>
            <li>они принимают за освобождение то, что не является им.<a href="#citation-262" id="ref-262" class="citation-mark"><sup>262</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Посему, Махамати, тебе следует усердствовать в йоге,</li>
            <li>чтобы отвратиться от этих ложных воззрений.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что касается, Махамати, рода постижения колесницы пратьекабудд,</li>
            <li>то это тот, у кого при изложении учения о личном постижении (<em>pratyekābhisamaya</em>)</li>
            <li>наполняются слёзы и волосы встают дыбом от благоговения.</li>
            <li>Он привлекается учением об отсутствии связи с другими (<em>asaṃsarga</em>),</li>
            <li>учением о зависимой обусловленности (<em>pratītyasamutpāda</em>),</li>
            <li>и описаниями разнообразных чудесных способностей:</li>
            <li>таких как умножение тела, двойные чудеса (<em>yamaka-prātihārya</em>) и господство над формами.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Зная, что это человек рода пратьекабудд,</li>
            <li>следует вести с ним беседу, соответствующую его пути.</li>
            <li>Таков, Махамати, признак рода постижения колесницы пратьекабудд.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что касается, Махамати, рода постижения колесницы Татхагат, он трояк:</li>
            <li>Род постижения, в котором собственная природа дхарм</li>
            <li>видится как отсутствие собственной природы;<a href="#citation-263" id="ref-263" class="citation-mark"><sup>263</sup></a></li>
            <li>Род постижения личного благородного достижения;<a href="#citation-264" id="ref-264" class="citation-mark"><sup>264</sup></a></li>
            <li>Род постижения внешних земель Будд и их величия.<a href="#citation-265" id="ref-265" class="citation-mark"><sup>265</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Когда же, Махамати, при изложении любого из этих трёх [учений] —</li>
            <li>в особенности о непостижимой сфере тела, объектов наслаждения и обители,</li>
            <li>которая есть лишь воспринимаемое собственным умом (<em>svacitta-dṛśya</em>) —</li>
            <li>[человек] не страшится, не трепещет и не впадает в ужас, следует знать:</li>
            <li>это — человек рода постижения колесницы Татхагат.</li>
            <li>Таков, Махамати, признак рода постижения колесницы Татхагат.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Неопределённый же род, Махамати, —</li>
            <li>это те, кто, когда излагают любую из этих трёх колесниц,</li>
            <li>склоняются к той, к которой их влечёт.</li>
            <li>Их следует направлять именно в ту колесницу.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, эта классификация родов —</li>
            <li>лишь подготовительная ступень (<em>parikarma-bhūmi</em>).</li>
            <li>Она устанавливается ради вхождения</li>
            <li>в ступени без ментальных образов (<em>nirābhāsa-bhūmi</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Но в самой <em>Алайе</em> (<em>pratyātmālaye</em>),</li>
            <li>когда она очищена от клеш-отпечатков (<em>kleśa-vāsanā</em>),</li>
            <li>через видение отсутствия «я» в дхармах</li>
            <li>и обретение блаженного пребывания в <em>самадхи</em>,</li>
            <li>даже шравака обретёт Тело Победителя (<em>jinakāyatā</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>128. Плод «вступившего в поток»,</li>
            <li>плод «однажды возвращающегося»,</li>
            <li>плод «невозвращающегося»</li>
            <li>и само состояние архата —</li>
            <li>это всё ещё блуждание ума (<em>citta-vibhrama</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>129. О Трёх Колесницах, о Единой Колеснице</li>
            <li>и об Отсутствии Колесницы (<em>ayāna</em>)</li>
            <li>Я проповедую ради невежд и слабоумных,</li>
            <li>и ради уединения Благородных.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>130. Врата высшей истины (<em>paramārtha</em>) —</li>
            <li>это познание, свободное от двойственности (<em>vijñapti-dvaya-varjitā</em>).</li>
            <li>Если [йогин] утвердился в сфере без ментальных образов (<em>nirābhāsa</em>),</li>
            <li>откуда взяться делению на Три Колесницы?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>131. <em>Дхьяны</em>, безмерные состояния, бесформенные <em>самадхи</em></li>
            <li>и полное прекращение восприятия —</li>
            <li>ничто из этого не обнаруживается</li>
            <li>в сфере «только-ума» (<em>cittamātra</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.18 (Иччхантики)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что касается иччхантик, Махамати,</li>
            <li>то почему их освобождение считается невозможным?</li>
            <li>Это происходит по двум причинам:</li>
            <li>из-за отсечения всех корней благого (<em>sarva-kuśala-mūla-utsarga</em>),</li>
            <li>и из-за обетов в отношении существ, принятых в безначальные времена.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что есть отсечение всех корней благого?</li>
            <li>Это — отвержение собраний наставлений бодхисаттв (<em>bodhisattva-piṭaka-nikṣepa</em>)</li>
            <li>и клеветническое утверждение, будто эти сутры</li>
            <li>противоречат дисциплине (<em>vinaya</em>) и цели освобождения (<em>mokṣa</em>).</li>
            <li>Из-за такого отсечения всех корней благого</li>
            <li>[существо] не достигает нирваны (<em>na nirvāyate</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Вторые же, Махамати, —</li>
            <li>это бодхисаттва-махасаттва, который,</li>
            <li>руководствуясь искусными средствами, дал обет:</li>
            <li>«Пока все существа не уйдут в паринирвану,</li>
            <li>Я Сам не уйду в паринирвану».</li>
            <li>Потому он не уходит в паринирвану (<em>na parinirvāti</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Таков, Махамати,</li>
            <li>признак тех, кто не уходит в окончательное угасание,</li>
            <li>и именно из-за этого они пребывают в состоянии иччхантики.</li>
        </ul>
        </blockquote>
        <p>Вновь Махамати спросил:</p>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>— Кто же из них, Благословенный, никогда не уходит в окончательное угасание?</li>
        </ul>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, именно бодхисаттва-иччхантика,</li>
            <li>познав, что все дхармы изначально пребывают в паринирване (<em>ādi-parinirvṛta</em>),</li>
            <li>никогда не уходит в паринирвану.</li>
            <li>Но не тот иччхантика, что отсёк все корни благого.</li>
            <li>Ибо даже иччхантика, отсекший все корни благого, Махамати,</li>
            <li>может вновь пробудить их благодаря благословенной силе Татхагат (<em>tathāgatādhiṣṭhāna</em>).<a href="#citation-266" id="ref-266" class="citation-mark"><sup>266</sup></a></li>
            <li>Почему это так?</li>
            <li>Потому что, Махамати, Татхагаты никогда не оставляют ни одного существа.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>По этой причине, Махамати,</li>
            <li>только бодхисаттва-иччхантика никогда не уходит в паринирвану.<a href="#citation-267" id="ref-267" class="citation-mark"><sup>267</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.19 (Три свабхавы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, бодхисаттве-махасаттве следует быть искусным</li>
            <li>в познании трёх признаков собственных природ.<a href="#citation-268" id="ref-268" class="citation-mark"><sup>268</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, воображаемая природа (<em>parikalpita-svabhāva</em>)</li>
            <li>возникает из признака (<em>nimitta</em>).<a href="#citation-269" id="ref-269" class="citation-mark"><sup>269</sup></a></li>
            <li>Как же она возникает?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, в зависимой природе (<em>paratantra-svabhāva</em>)</li>
            <li>проявляются основа, признак, характеристика и внешняя форма.<a href="#citation-270" id="ref-270" class="citation-mark"><sup>270</sup></a></li>
            <li>Привязанность к этим формам и признакам — двояка.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Татхагаты, Архаты, Совершенно Пробуждённые</li>
            <li>определяют воображаемую природу по двум её признакам:</li>
            <li>по признаку привязанности к именам<a href="#citation-271" id="ref-271" class="citation-mark"><sup>271</sup></a> и</li>
            <li>по признаку привязанности к объектам через их наименования.<a href="#citation-272" id="ref-272" class="citation-mark"><sup>272</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Здесь, Махамати, привязанность к объектам —</li>
            <li>это цепляние за внутренние и внешние дхармы.<a href="#citation-273" id="ref-273" class="citation-mark"><sup>273</sup></a></li>
            <li>Привязанность к признакам —</li>
            <li>это ложное познание собственных и общих признаков этих дхарм.<a href="#citation-274" id="ref-274" class="citation-mark"><sup>274</sup></a></li>
            <li>Таковы, Махамати, два вида воображаемой природы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Зависимая природа (<em>paratantra</em>) проявляется</li>
            <li>[в виде] основы, признака, характеристики и внешней формы.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть совершённая природа (<em>pariniṣpanna-svabhāva</em>)?</li>
            <li>Это Таковость, свободная от признаков, имён, объектов и их характеристик,</li>
            <li>а также от любого различения</li>
            <li>(<em>nimitta-nāma-vastu-lakṣaṇa-vikalpa-virahita</em>),</li>
            <li>— путь благородного знания и сфера личного благородного постижения</li>
            <li>(<em>ārya-jñāna-gati-pratyātmāryajñāna-gati-gocara</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Это, Махамати, и есть совершённая природа —</li>
            <li>Сердце Зародыша Татхагат (<em>tathāgatagarbha-hṛdayam</em>).</li>
        </ul>
        </blockquote>
        <p>Затем Благословенный произнёс гатху:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>132. Признак (<em>nimitta</em>), имя (<em>nāma</em>) и умозрительное построение (<em>saṃkalpa</em>) —</li>
            <li>таковы признаки двух [первых] природ.</li>
            <li>Подлинное знание (<em>samyag-jñāna</em>) и Таковость (<em>tathatā</em>)</li>
            <li>— таковы признаки Совершённой природы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Это, Махамати, есть изложение Дхармы,</li>
            <li>именуемой «Исследованием пяти <em>дхарм</em> и [трёх] <em>свабхав</em>» —</li>
            <li>сфера личного благородного постижения,</li>
            <li>в которой тебе и другим бодхисаттвам следует усердствовать.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.20 (Два вида отсутствия «я»)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати,</li>
            <li>бодхисаттве-махасаттве следует быть искусным</li>
            <li>в исследовании двух видов отсутствия «я» (<em>nairātmya-dvaya</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что есть отсутствие «я» в личности?</li>
            <li>Это — понимание того, что совокупность <em>скандх</em>, <em>дхату</em> и <em>аятан</em>,</li>
            <li>порождённая неведением, кармой и жаждой,</li>
            <li>лишена «я» и «моего» (<em>ātma-ātmīya-rahita</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Ум, приходя в движение</li>
            <li>из-за привязанности к восприятию форм глазом и другими органами чувств,</li>
            <li>являет [нам] обитель, тело и объекты —</li>
            <li>всё то, что воображено различениями собственного ума (<em>svacitta-vikalpa-vikalpitam</em>).<a href="#citation-275" id="ref-275" class="citation-mark"><sup>275</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно реке, ростку, светильнику, ветру или облаку,</li>
            <li>[эта совокупность] распадается в каждое мгновение непрерывной череды;</li>
            <li>она непостоянна, словно обезьяна или муха;</li>
            <li>она ненасытна, словно бушующий огонь;</li>
            <li>подобно колодезному колесу (<em>araghaṭṭa</em>),</li>
            <li>она вращается в колесе сансары,</li>
            <li>несущем отпечатки безначального многообразия различений (<em>anādi-prapañca-viṣaya-vāsanā</em>);</li>
            <li>она движется, принимая разнообразные телесные формы,</li>
            <li>подобно механической кукле (<em>yantra</em>) или иллюзии (<em>māyā</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, знание, прозревающее эти признаки,</li>
            <li>именуется знанием об отсутствии «я» в личности (<em>pudgala-nairātmya-jñāna</em>).<a href="#citation-276" id="ref-276" class="citation-mark"><sup>276</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть знание об отсутствии «я» в дхармах (<em>dharmanairātmyajñāna</em>)?</li>
            <li>Это — постижение того, что <em>скандхи</em>, <em>дхату</em> и <em>аятаны</em></li>
            <li>лишены воображаемой собственной природы (<em>parikalpita-lakṣaṇa-svabhāva</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как <em>скандхи</em> лишены «я»</li>
            <li>и являются лишь совокупностью факторов,</li>
            <li>связанных нитями причины, кармы и жажды,</li>
            <li>и движутся взаимной обусловленностью, без самостоятельной активности, —</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>так же и сами <em>скандхи</em>, Махамати,</li>
            <li>лишены собственных и общих признаков (<em>sva-sāmānya-lakṣaṇa</em>),</li>
            <li>и являются лишь разнообразным проявлением ложного воображения (<em>abhūta-parikalpa</em>),</li>
            <li>которое воображают невежды, но не Благородные.<a href="#citation-277" id="ref-277" class="citation-mark"><sup>277</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, бодхисаттва-махасаттва становится искусным</li>
            <li>в отсутствии «я» в дхармах,</li>
            <li>когда созерцает все явления как свободные</li>
            <li>от ума (<em>citta</em>), интеллекта (<em>manas</em>), различающего сознания (<em>vijñāna</em>),</li>
            <li>а также от пяти <em>дхарм</em> и трёх <em>свабхав</em>.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Обретя это мастерство, Махамати, бодхисаттва</li>
            <li>вскоре достигает первой ступени —</li>
            <li>Радостной (<em>pramuditā</em>),</li>
            <li>где начинается исследование сферы без ментальных образов (<em>nirābhāsa-pravicaya</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Последовательно пройдя девять ступеней,</li>
            <li>он достигает десятой — Облака Дхармы (<em>mahādharma-megha</em>).</li>
            <li>Утвердившись на ней,</li>
            <li>он восседает в великом драгоценном чертоге (<em>mahā-ratna-vimāna</em>),</li>
            <li>подобном царю лотосов (<em>mahā-padma-rāja</em>),</li>
            <li>украшенном бесчисленными драгоценностями и жемчугом.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Он окружён сыновьями Победителей (<em>jina-putra</em>),</li>
            <li>и, подобно сыну чакравартина,</li>
            <li>получает посвящение (<em>abhiṣeka</em>)</li>
            <li>из рук всех Будд, пришедших из всех земель Будд.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Превзойдя ступень «сына Будды»,</li>
            <li>благодаря личному постижению благородной Дхармы (<em>pratyātmārya-dharma-gati</em>),</li>
            <li>он становится Татхагатой,</li>
            <li>владеющим Телом Дхармы (<em>dharmakāya-vaśavartin</em>),</li>
            <li>ибо узрел отсутствие «я» в дхармах.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Таков, Махамати,</li>
            <li>признак отсутствия «я» во всех дхармах.</li>
            <li>В этом тебе и другим бодхисаттвам следует усердствовать.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.21 (Наложение и отрицание)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Пусть Благословенный разъяснит мне</li>
            <li>признаки наложения (<em>samāropa</em>) и отрицания (<em>apavāda</em>),</li>
            <li>дабы я и другие бодхисаттвы,</li>
            <li>освободив ум от дурных воззрений,</li>
            <li>связанных с наложением и отрицанием,</li>
            <li>быстро достигли непревзойдённого совершенного пробуждения.</li>
            <li>Достигнув же пробуждения</li>
            <li>и оставив воззрения на вечность, наложение,</li>
            <li>отрицание и уничтожение,</li>
            <li>мы не станем более порицать Твоё Око Будды.</li>
        </ul>
        </blockquote>
        <p>Затем Благословенный, восприняв просьбe бодхисаттвы-махасаттвы Махамати, произнёс этот
            стих:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>133. В реальности «только-ума» (<em>cittamātra</em>)</li>
            <li>нет ни наложения, ни отрицания.</li>
            <li>Те же невежды, что не знают,</li>
            <li>что [весь мир] — лишь воспринимаемое собственным умом,</li>
            <li>являющееся как тело, объекты наслаждения и обитель,</li>
            <li>— те блуждают в наложении и отрицании.</li>
        </ul>
        </blockquote>
        <p>И далее Благословенный, разъясняя смысл этого стиха, вновь сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Существует, Махамати, четыре вида наложения несуществующего (<em>asat-samāropa</em>).</li>
            <li>Каковы эти четыре?</li>
            <li>— Наложение несуществующих признаков (<em>asal-lakṣaṇa-samāropa</em>);</li>
            <li>— Наложение несуществующих воззрений (<em>asat-dṛṣṭi-samāropa</em>);</li>
            <li>— Наложение несуществующих причин (<em>atad-dhetu-samāropa</em>);</li>
            <li>— Наложение бытия на не-бытующее (<em>asat-bhāva-samāropa</em>).</li>
            <li>Таковы, Махамати, четыре вида наложения.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же касается отрицания (<em>apavāda</em>), Махамати, — что оно собой представляет?</li>
            <li>Это — отрицание, возникающее из-за</li>
            <li>отсутствия исследования недоступности (<em>anupalabdhi-pravicaya-abhāva</em>)</li>
            <li>именно этого ложного воззрения-наложения (<em>kudṛṣṭi-samāropa</em>).</li>
            <li>Таков, Махамати, признак наложения и отрицания.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, каков признак наложения несуществующих признаков?</li>
            <li>Это — привязанность к несуществующим собственным и общим признакам</li>
            <li><em>скандх</em>, <em>дхату</em> и <em>аятан</em> в форме утверждения:</li>
            <li>«Это именно так и не иначе!»</li>
            <li>Таков, Махамати, признак наложения несуществующих признаков.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поистине, Махамати, это различение (<em>vikalpa</em>) —</li>
            <li>наложение несуществующих признаков —</li>
            <li>возникает из-за привязанности к разнообразным отпечаткам (<em>vāsanā</em>),</li>
            <li>порождённым косным безначальным многообразием различений (<em>anādi-prapañca-dauṣṭhulya</em>).</li>
            <li>Таков, Махамати, признак наложения несуществующих признаков.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же есть, Махамати, наложение несуществующих воззрений?</li>
            <li>Это — приписывание тем же <em>скандхам</em>, <em>дхату</em> и <em>аятанам</em></li>
            <li>воззрений на:</li>
            <li>«я» (<em>ātman</em>),</li>
            <li>«существо» (<em>sattva</em>),</li>
            <li>«живое существо» (<em>jīva</em>),</li>
            <li>«рождённое» (<em>jantu</em>),</li>
            <li>«питающего» (<em>poṣa</em>),</li>
            <li>«личность» (<em>puruṣa</em>),</li>
            <li>«индивидуальность» (<em>pudgala</em>).</li>
            <li>Именно это, Махамати, именуется наложением несуществующих воззрений.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть наложение несуществующих причин?</li>
            <li>Это — [воззрение], будто сознание,</li>
            <li>— не возникнув ранее,</li>
            <li>— возникает без причины,</li>
            <li>— или подобно майе возникает, не имея предшествующего состояния,</li>
            <li>— или появляется лишь из сочетания глаза, формы, света и памяти,</li>
            <li>— и, возникнув, вновь исчезает.</li>
            <li>Таков, Махамати, признак наложения несуществующих причин.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же есть, Махамати, наложение несуществующего бытия?</li>
            <li>Это — привязанность к бытию</li>
            <li>пространства (<em>ākāśa</em>),</li>
            <li>прекращения (<em>nirodha</em>),</li>
            <li>нирваны (<em>nirvāṇa</em>)</li>
            <li>и несотворённого (<em>akṛtaka</em>).</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поистине, Махамати, эти дхармы выходят за пределы бытия и небытия.</li>
            <li>Все они, Махамати,</li>
            <li>подобны рогам зайца, лошади, осла или верблюда,</li>
            <li>или видению плавающих в воздухе волос и пушинок (<em>keśoṇḍuka</em>).</li>
            <li>Они свободны от сторон существования и несуществования,</li>
            <li>и от наложения и отрицания.</li>
            <li>Лишь невежды, чьи умы</li>
            <li>не постигли, что всё — лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-mātra</em>),</li>
            <li>воображают такие различения.</li>
            <li>Но не Благородные.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Таков, Махамати,</li>
            <li>признак наложения и отрицания в отношении ложного бытия.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Посему, Махамати,</li>
            <li>тебе следует пребывать свободным от воззрений наложения и отрицания.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.22 (Тело Воплощения)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, бодхисаттвы,</li>
            <li>постигнув природу ума (<em>citta</em>), интеллекта (<em>manas</em>), различающего сознания (<em>manovijñāna</em>),</li>
            <li>пяти <em>дхарм</em>, трёх <em>свабхав</em> и двоякого отсутствия «я»,</li>
            <li>ради блага других принимают разнообразные облики.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Как воображаемая природа проявляется на основе зависимой природы,</li>
            <li>так и бодхисаттвы, основываясь на зависимой природе,</li>
            <li>проявляют разнообразные формы,</li>
            <li>подобно драгоценному камню Чинтамани.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Пребывая в собраниях во всех землях Будд,</li>
            <li>они слушают от всех Татхагат поучения,</li>
            <li>недоступные шравакам и пратьекабуддам,</li>
            <li>где все дхармы описываются как</li>
            <li>подобные <em>майе</em>, сновидению, отражению и луне в воде —</li>
            <li>свободные от рождения и распада,</li>
            <li>свободные от вечности и уничтожения.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Они обретают сотни тысяч врат <em>самадхи</em>,</li>
            <li>и даже бесчисленные, как песчинки Ганга, <em>самадхи</em>;</li>
            <li>с их помощью они перемещаются из одной земли Будды в иную.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Прославляя Будд и проповедуя Три Драгоценности</li>
            <li>во всех обителях богов и мирах рождений,</li>
            <li>они принимают облик Будды,</li>
            <li>окружённые шраваками и бодхисаттвами,</li>
            <li>и наставляют существ, указывая, что всё —</li>
            <li>лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-mātra</em>),</li>
            <li>и разъясняют отсутствие внешнего бытия и небытия,</li>
            <li>дабы отвратить их от крайностей «есть» и «нет».</li>
        </ul>
        </blockquote>
        <p>Затем Благословенный произнёс этот стих:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>134. Когда сыновья Победителей</li>
            <li>прозревают мир как «только-ум»,</li>
            <li>они обретают Тело Воплощения (<em>nairmāṇikaṃ kāyaṃ</em>),</li>
            <li>свободное от действий и формирующих факторов (<em>kriyā-saṃskāra-varjitam</em>),</li>
            <li>вместе с <em>силами</em> (<em>bala</em>), <em>сверхзнаниями</em> (<em>ābhijña</em>) и <em>властью</em> (<em>vaśita</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.23 (Семь видов шуньяты)</h4>

    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Пусть Благословенный разъяснит признаки <em>шуньяты</em>,</li>
            <li>не-возникновения, недвойственности и</li>
            <li>отсутствия собственной природы всех дхарм!</li>
            <li>Дабы, постигнув эти признаки,</li>
            <li>я и другие бодхисаттвы-махасаттвы,</li>
            <li>освободившись от различений «есть» и «нет»,</li>
            <li>быстро достигли непревзойдённого совершенного пробуждения.</li>
        </ul>
        </blockquote>
        <p>Тогда Благословенный сказал бодхисаттве-махасаттве Махамати:</p>
        <p>— Слушай же внимательно, Махамати, и хорошо удержи это в уме! Я разъясню тебе это.</p>
        <p>— Да, Благословенный! — ответил Махамати.</p>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li><em>«Шуньята</em>, <em>шуньята»</em>, Махамати, —</li>
            <li>это лишь слово, принадлежащее воображаемой природе (<em>parikalpita-svabhāva-pada</em>).</li>
            <li>Из-за привязанности к воображаемой природе</li>
            <li>люди утверждают бытие <em>шуньяты</em>, не-возникновения,</li>
            <li>недвойственности и отсутствия собственной природы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Если говорить кратко, Махамати, существует семь видов <em>шуньяты</em>:</li>
            <li><em>Шуньята признака</em> (<em>lakṣaṇa-śūnyatā</em>);</li>
            <li><em>Шуньята собственной природы явлений</em> (<em>bhāva-svabhāva-śūnyatā</em>);</li>
            <li><em>Шуньята непроявленного</em> (<em>apracarita-śūnyatā</em>);</li>
            <li><em>Шуньята проявленного</em> (<em>pracarita-śūnyatā</em>);</li>
            <li><em>Шуньята невыразимости всех дхарм</em> (<em>sarvadharma-nirabhilāpya-śūnyatā</em>);</li>
            <li><em>Великая шуньята высшей истины и благородного знания</em> (<em>paramārthāryajñāna-mahāśūnyatā</em>);</li>
            <li><em>Шуньята взаимного отсутствия</em> (<em>itaretara-śūnyatā</em>) — седьмая.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть <em>шуньята признака</em> (<em>lakṣaṇa-śūnyatā</em>)?</li>
            <li>Это — [понимание того], что все явления лишены собственных и общих признаков (<em>sva-sāmānya-lakṣaṇa-śūnyāḥ</em>).</li>
            <li>Махамати, собственные признаки не проявляются,</li>
            <li>поскольку [явления] проявляются лишь взаимной зависимостью (<em>paraspara-samūha-apekṣitatvāt</em>)</li>
            <li>и лишены аналитического разделения (<em>pravicaya-vibhāga-abhāvāt</em>).</li>
            <li>И поскольку [признаки] не устанавливаются</li>
            <li>ни в себе, ни в другом, ни в обоих,</li>
            <li>они не обретают опоры (<em>na avatiṣṭhate</em>).</li>
            <li>Потому говорится:</li>
            <li>«Все явления лишены собственных признаков».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть <em>шуньята собственной природы явлений</em> (<em>bhāva-svabhāva-śūnyatā</em>)?</li>
            <li>Махамати, все дхармы [кажутся] возникающими</li>
            <li>лишь вследствие отсутствия у них собственной природы (<em>svabhāva-abhāva-utpatti</em>).</li>
            <li>Именно поэтому и говорится: «шуньята собственной природы явлений».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть <em>шуньята непроявленного</em> (<em>apracarita-śūnyatā</em>)?</li>
            <li>Махамати, она заключается в том,</li>
            <li>что нирвана не была ранее проявлена (в потоке <em>скандх</em>).</li>
            <li>Потому говорится: «шуньята непроявленного».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть <em>шуньята проявленного</em> (<em>pracarita-śūnyatā</em>)?</li>
            <li>Это — [понимание того], что <em>скандхи</em> лишены «я» и «моего»,</li>
            <li>и приходят в движение, продолжая проявляться,</li>
            <li>лишь благодаря сочетанию причин, условий, действий и кармы.</li>
            <li>Посему говорится: «шуньята проявленного».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть <em>шуньята невыразимости всех дхарм</em> (<em>sarvadharma-nirabhilāpya-śūnyatā</em>)?</li>
            <li>Махамати, все дхармы невыразимы,</li>
            <li>поскольку воображаемая природа не может быть выражена (<em>parikalpita-svabhāva</em>) —</li>
            <li>Потому говорится: «шуньята невыразимости».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть великая <em>шуньята высшей истины и благородного знания</em> (<em>paramārthāryajñāna-mahāśūnyatā</em>)?</li>
            <li>Это — личное благородное постижение (<em>sva-pratyātmāryajñāna-adhigama</em>),</li>
            <li>лишённое всех отпечатков, оставляемых ошибочными воззрениями.</li>
            <li>Потому говорится: «великая шуньята высшей истины и благородного знания».</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть <em>шуньята взаимного отсутствия</em> (<em>itaretara-śūnyatā</em>)?</li>
            <li>Это — когда говорят:</li>
            <li>«Это шунья от того, потому что того здесь нет».</li>
            <li>Подобно тому, Махамати, как во Дворце Шригалы</li>
            <li>нет слонов, коров или овец.</li>
            <li>Я [как-то] сказал:</li>
            <li>«Он не пуст, ибо в нём находятся бхикшу» (<em>aśūnyaṃ ca bhikṣubhiḥ</em>).</li>
            <li>Говорится лишь, что он пуст от тех [животных].</li>
            <li>Но это не значит, Махамати, что</li>
            <li>— чертог перестал быть чертогом,</li>
            <li>— или бхикшу перестали быть бхикшу.</li>
            <li>И это не значит, что те слоны и коровы</li>
            <li>не существуют где-то в другом месте.</li>
            <li>Здесь [мы видим] собственные и общие признаки всех дхарм,</li>
            <li>но одно не содержится в другом (<em>itaretaraṃ tu na saṃvidyate</em>).</li>
            <li>Это именуется «шуньята взаимного отсутствия».</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Таковы, Махамати, семь видов <em>шуньяты</em>.</li>
            <li>Но эта <em>шуньята взаимного отсутствия</em> — самая низшая (<em>sarvajaghanyā</em>),</li>
            <li>и тебе следует её избегать!</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.24 (Признаки не-возникновения, недвойственности и отсутствия собственной природы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>[Дхармы] не возникают сами по себе;</li>
            <li>и также, Махамати, они не возникают из чего-то иного —</li>
            <li>разве что в состоянии взаимного схождения условий.</li>
            <li>Поэтому они именуются «невозникшими и лишёнными собственной природы».</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, все явления лишены собственной природы,</li>
            <li>ибо их совокупность не имеет истинного возникновения.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Также, Махамати, все явления лишены собственной природы</li>
            <li>из-за отсутствия преемственности (<em>prabandha</em>) в потоке мгновений:</li>
            <li>то, что видится изменчивостью (<em>anyathā-bhāva</em>),</li>
            <li>не имеет под собой единой основы.</li>
            <li>Потому говорится: «все дхармы лишены собственной природы».<a href="#citation-278" id="ref-278" class="citation-mark"><sup>278</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть признак недвойственности?</li>
            <li>Это — понимание того, что такие пары, как тень и свет,</li>
            <li>длинное и короткое, чёрное и белое,</li>
            <li>не существуют по отдельности друг от друга.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Точно так же, Махамати, <strong>сансара и нирвана — недвойственны</strong>,</li>
            <li>ибо все дхармы недвойственны.</li>
            <li>Где нирвана — там нет сансары;</li>
            <li>где сансара — там нет нирваны,</li>
            <li>поскольку у них нет общей основы бытия (<em>vilakṣaṇa-hetu-sadbhāvāt</em>).</li>
            <li>Потому говорится:</li>
            <li>«<strong>Все дхармы недвойственны, как сансара и нирвана</strong>».</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Потому, Махамати, тебе следует усердствовать в йоге</li>
            <li>для постижения признаков <strong>шуньяты</strong>,</li>
            <li><strong>не-возникновения</strong>, <strong>недвойственности</strong> и <strong>отсутствия собственной природы</strong>.<a href="#citation-279" id="ref-279" class="citation-mark"><sup>279</sup></a></li>
        </ul>
        </blockquote>
        <p>Затем Благословенный произнёс эти гатхи:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>135. Я всегда проповедую шуньяту,</li>
            <li>свободную от [крайностей] вечности и уничтожения.</li>
            <li>Сансара подобна сну и иллюзии, но карма не исчезает.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>136. Пространство (<em>ākāśa</em>), нирвана и прекращение (<em>nirodha</em>) —</li>
            <li>эти два [нирвану и прекращение]</li>
            <li>невежды воображают как несотворённые.</li>
            <li>Благородные же свободны от представлений «есть» и «нет» в отношении них.<a href="#citation-280" id="ref-280" class="citation-mark"><sup>280</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.25 (Суть и буква Учения)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем Благословенный вновь обратился к бодхисаттве-махасаттве Махамати:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поистине, Махамати, эта четверица —</li>
            <li><em>шуньята</em>, не-возникновение, недвойственность и отсутствие собственной природы —</li>
            <li>пронизывает все учения и все сутры всех Будд.</li>
            <li>В какой бы сутре ты ни встретил иное,</li>
            <li>следует усматривать именно этот смысл.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Ибо, Махамати, поучения в сутрах варьируются</li>
            <li>ради соответствия склонностям всех существ,</li>
            <li>но они не являются окончательным изложением реальности.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как мираж в пустыне влечёт оленей,</li>
            <li>заставляя их верить в существование воды, хотя воды там нет,</li>
            <li>так и поучения во всех сутрах служат лишь</li>
            <li>для удовлетворения воображения невежд,</li>
            <li>но не являются изложением непосредственного благородного знания истины.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Посему, Махамати, надо следовать за смыслом (<em>artha</em>),</li>
            <li>а не цепляться за форму изложения (<em>deśanā-abhilāpa</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.26 (Татхагатагарбха и Атман)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати обратился к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Благословенный, в Твоих поучениях в сутрах</li>
            <li>Ты описываешь Зародыш Татхагаты (<em>tathāgatagarbha</em>).</li>
            <li>Ты говоришь, что он изначально сияющий, чист по своей природе,</li>
            <li>наделён тридцатью двумя признаками</li>
            <li>и пребывает внутри тел всех живых существ.</li>
            <li>Ты сравниваешь его с бесценным сокровищем, завёрнутым в грязную ткань,</li>
            <li>и описываешь его как окутанный <em>скандхами</em>, <em>дхату</em> и <em>аятанами</em>,</li>
            <li>запятнанный грязью страсти, гнева, заблуждения и ложных воображений.</li>
            <li>Ты называешь его вечным (<em>nitya</em>), неизменным (<em>dhruva</em>),</li>
            <li>благим (<em>śiva</em>) и постоянным (<em>śāśvata</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Как же, Благословенный, Твоё учение о Зародыше Татхагаты</li>
            <li>не оказывается тождественным учению тиртхиков об Атмане?</li>
            <li>Ведь и тиртхики, Благословенный, учат об Атмане</li>
            <li>как о вечном, «деятеле» (<em>kartā</em>), лишённом качеств,</li>
            <li>всепроникающем и неразрушимом.</li>
        </ul>
        </blockquote>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, Моё учение о Зародыше Татхагаты</li>
            <li>вовсе не тождественно учению тиртхиков об Атмане!</li>
            <li>Напротив, Махамати, Татхагаты, Архаты, Совершенно Пробуждённые</li>
            <li>излагают учение о Зародыше Татхагаты,</li>
            <li>подразумевая под ним <strong>шуньяту</strong>, <strong>предел истинности</strong> (<em>bhūtakoṭi</em>),</li>
            <li><strong>нирвану</strong>, <strong>не-возникновение</strong>, <strong>беспризнаковость</strong> (<em>ānimitta</em>) и <strong>безустремлённость</strong> (<em>apraṇihita</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Дабы невежды не впадали в страх,</li>
            <li>возникающий от постижения отсутствия «я» (<em>nairātmya</em>),</li>
            <li>Татхагаты указывают на это как на вход в сферу,</li>
            <li>лишённую различений и образов.</li>
            <li>И не следует Бодхисаттвам настоящего и будущего</li>
            <li>усматривать здесь привязанность к «я».</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как гончар</li>
            <li>из одной и той же глины изготавливает разные сосуды</li>
            <li>с помощью рук, умения, палки, воды и нити —</li>
            <li>так и Татхагаты излагают то же самое отсутствие «я» в дхармах,</li>
            <li>свободное от всех признаков различения.</li>
            <li>Они делают это через разнообразные искусные средства (<em>upāya</em>):</li>
            <li>то через учение о Зародыше,</li>
            <li>то через учение об отсутствии «я»,</li>
            <li>используя, подобно гончару,</li>
            <li>разные сочетания слов и оборотов.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поэтому, Махамати, учение о Зародыше Татхагаты</li>
            <li>не имеет ничего общего с учением тиртхиков об Атмане.</li>
            <li>Татхагаты учат о Зародыше лишь для того,</li>
            <li>чтобы привлечь тиртхиков, привязанных к идее Души.</li>
            <li>[Они думают]: "Как бы эти люди,</li>
            <li>павшие в бездну ложных воззрений о несуществующем «я»,</li>
            <li>могли через врата трёх освобождений</li>
            <li>быстро достичь совершенного пробуждения?"</li>
            <li>Вот ради чего Татхагаты проповедуют о Зародыше.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Посему, Махамати, дабы отвратиться от воззрений тиртхиков,</li>
            <li>тебе следует следовать за Зародышем Татхагаты как как тем, что свободно от «я».</li>
        </ul>
        </blockquote>
        <p>Затем Благословенный произнёс этот стих:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>137. Личность (<em>pudgala</em>), преемственность (<em>saṃtati</em>), <em>скандхи</em> (<em>skandha</em>),</li>
            <li>условия (<em>pratyaya</em>), атомы (<em>aṇu</em>), Первоматерия (<em>pradhāna</em>),</li>
            <li>Владыка (<em>īśvara</em>) и деятель (<em>kartā</em>) — всё это —</li>
            <li>лишь воображаемые различения внутри «только ума» (<em>cittamātra</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.27 (27. Четыре совершенных качества йогина)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Затем бодхисаттва-махасаттва Махамати,</li>
            <li>взирая на грядущие поколения,</li>
            <li>вновь воззвал к Благословенному:</li>
        </ul>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Пусть Благословенный разъяснит [путь] йогического постижения,</li>
                <li>дабы бодхисаттвы-махасаттвы стали великими мастерами йоги
                    (<em>mahāyoga-yogin</em>)!</li>
            </ul>
        </blockquote>

        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, бодхисаттвы становятся великими мастерами йоги,</li>
            <li>обладая четырьмя качествами. Каковы эти четыре?</li>
            <li>• Глубокое осознание того, что всё — лишь воспринимаемое собственным умом;</li>
            <li>• Отбрасывание воззрений о возникновении, пребывании и распаде;</li>
            <li>• Понимание, что внешние объекты лишены бытия и небытия;</li>
            <li>• Устремлённость к личному благородному постижению истины.</li>
            <li>Обладая этими четырьмя качествами, Махамати,</li>
            <li>бодхисаттвы-махасаттвы становятся великими мастерами йоги.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Как же, Махамати, бодхисаттва-махасаттва</li>
            <li>становится искусным в ясном созерцании того,</li>
            <li>что всё — лишь воспринимаемое собственным умом?</li>
            <li>Он созерцает это так:</li>
            <li>«Три мира — это только лишь собственный ум;</li>
            <li>он лишён «я» и «моего».</li>
            <li>Он лишён личного стремления (<em>nirīha</em>),</li>
            <li>свободен от [усилий] по созиданию и разрушения (<em>āyūha-niyūha</em>).</li>
            <li>Он пропитан отпечатками,</li>
            <li>оставленными привязанностью к пагубной привычке</li>
            <li>безначального размножествления понятий (<em>prapañca-dauṣṭhulya</em>).</li>
            <li>Он проявляется через разнообразие форм трёх миров;</li>
            <li>он воображается и является как поток различений тела,</li>
            <li>объектов восприятия и мира-обители (<em>deha-bhoga-pratiṣṭhā</em>),</li>
            <li>а также [различных] состояний существования».</li>
            <li>Поистине, Махамати, так бодхисаттва</li>
            <li>становится искусным в созерцании того,</li>
            <li>что всё — лишь воспринимаемое собственным умом.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Как же, Махамати, бодхисаттва-махасаттва</li>
            <li>становится свободным от воззрений</li>
            <li>о возникновении, пребывании и распаде?</li>
            <li>Он видит, что возникновение всех явлений подобно иллюзии или сну;</li>
            <li>они не возникают [реально],</li>
            <li>так как не устанавливаются ни из себя,</li>
            <li>ни из другого, ни из обоих [вместе].</li>
            <li>Следуя [истине о том, что всё] — лишь собственный ум, и</li>
            <li>увидев деятельность сознаний (<em>vijñānānāmapravṛtti</em>)</li>
            <li>которая затухает из-за отсутствия внешних объектов,</li>
            <li>он постигает, что условия — это лишь случайное нагромождение,</li>
            <li>лишенное основы (<em>akūṭarāśitva</em>),</li>
            <li>и видит Тройственный мир как порождение понятий и условий.</li>
            <li>Не обнаруживая дхарм ни внутри, ни вовне,</li>
            <li>и видя отсутствие у них собственной природы,</li>
            <li>он отвращается от воззрений о возникновении.</li>
            <li>Проникая в природу дхарм как подобную иллюзии,</li>
            <li>он обретает принятие/убежденность</li>
            <li>в не-возникновении дхарм (<em>anutpattika-dharma-kṣānti</em>).</li>
            <li>Утвердившись на восьмой ступени [Бодхисаттвы]</li>
            <li>и постигнув поворот основы (<em>parāvṛtti</em>)</li>
            <li>через постижение пяти <em>дхарм</em>, трех <em>свабхав</em> и двоякого отсутствия «я»,</li>
            <li>он обретает тело, порожденное умом (<em>manomaya-kāya</em>).</li>
        </ul>
        </blockquote>
        <p>Махамати спросил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Благословенный, почему это тело</li>
            <li>называют порожденным умом (<em>manomaya-kāya</em>)?</li>
        </ul>
        </blockquote>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Его называют порожденным умом, Махамати,</li>
            <li>потому что оно обладает беспрепятственной и</li>
            <li>мгновенной скоростью, подобной самой мысли.</li>
            <li>Подобно тому, Махамати, как мысль</li>
            <li>беспрепятственно проносится сквозь горы, стены, реки и деревья,</li>
            <li>мгновенно вспоминая объекты,</li>
            <li>виденные и познанные прежде за сотни тысяч йоджан;</li>
            <li>и движется она как неразрывное</li>
            <li>с потоком собственного ума тело (<em>svacitta-prabandha-avicchinna-śarīra</em>),</li>
            <li>не встречая преград, — точно</li>
            <li>так же, Махамати, [действует бодхисаттва].</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Одновременно с обретением тела, порожденного умом,</li>
            <li>и пребыванием в <em>самадхи</em>, подобном иллюзии,</li>
            <li>он наделяется <em>силами</em> (<em>bala</em>), <em>властью</em> (<em>vaśitā</em>) и <em>сверхзнаниями</em> (<em>abhijñā</em>).</li>
            <li>Украшенный ими словно цветами (<em>kusumita</em>),</li>
            <li>он становится соприроден (<em>sahaja</em>) сонму Благородных</li>
            <li>и движется так же беспрепятственно, как мысль,</li>
            <li>памятуя о своих прежних обетах ради созревания живых существ.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поистине, Махамати, так бодхисаттва-махасаттва</li>
            <li>становится свободным от воззрений</li>
            <li>о возникновении, пребывании и распаде.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Как же, Махамати, бодхисаттва-махасаттва становится искусным</li>
            <li>в распознавании того, что внешние объекты</li>
            <li>лишены как бытия, так и небытия?</li>
            <li>[Это происходит], когда он ясно видит:</li>
            <li>все явления, Махамати, подобны миражу, сну или</li>
            <li>миражам «плавающих волос» перед глазами (<em>keśoṇḍuka</em>).</li>
            <li>Он прозревает, что природа всех явлений</li>
            <li>обусловлена привязанностью к отпечаткам</li>
            <li>разнообразных созревающих различений (<em>vipāka-vikalpa</em>) и</li>
            <li>пагубностью инерции безначального размножествления понятий.</li>
            <li>Прозревая это, он устремляется</li>
            <li>к сфере личного благородного постижения истины.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Обладая этими четырьмя качествами, Махамати,</li>
            <li>бодхисаттвы-махасаттвы становятся великими мастерами йоги.</li>
            <li>Посему, Махамати, тебе следует усердствовать в этой йоге.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.28 (28. Признак причинно-условной природы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь воззвал к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Пусть Благословенный разъяснит</li>
            <li>признак причинно-условной природы всех дхарм!</li>
            <li>Дабы, постигнув этот признак, я и другие бодхисаттвы-махасаттвы,</li>
            <li>освободившись от различений и воззрений о бытии и небытии,</li>
            <li>более не воображали бы ни постепенного,</li>
            <li>ни мгновенного возникновения всех явлений.<a href="#citation-281" id="ref-281" class="citation-mark"><sup>281</sup></a></li>
        </ul>
        </blockquote>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Существует два вида признака</li>
            <li>зависимого возникновения (<em>pratītyasamutpāda-lakṣaṇa</em>) всех дхарм:</li>
            <li>внешний и внутренний.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же, Махамати, есть внешнее зависимое возникновение?</li>
            <li>Подобно тому, как из кома глины,</li>
            <li>с помощью палки, гончарного круга,</li>
            <li>нити, воды и усилий человека возникает кувшин;</li>
            <li>как из глины — кувшин, из нитей — ткань,</li>
            <li>из тростника — циновка, из семени — росток,</li>
            <li>а из молока при сбивании и усилиях человека — масло.</li>
            <li>Именно так, Махамати, следует рассматривать</li>
            <li>внешнее зависимое возникновение —</li>
            <li>как цепь условий, где каждое последующее</li>
            <li>обусловлено предшествующим.<a href="#citation-282" id="ref-282" class="citation-mark"><sup>282</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Что же касается внутреннего зависимого возникновения (<em>ādhyātmikaḥ pratītyasamutpāda</em>), Махамати, —</li>
            <li>то это такие дхармы, как неведение, жажда и карма.</li>
            <li>Именно они обозначаются как «зависимое возникновение».</li>
            <li>Рождённые из них, Махамати, дхармы,</li>
            <li>называемые <em>скандхами</em>, <em>дхату</em> и <em>аятанами</em>,</li>
            <li>также обозначаются как «зависимое возникновение».</li>
            <li>Хотя всё это неотличимо, невежды воображают их [как нечто отдельное].<a href="#citation-283" id="ref-283" class="citation-mark"><sup>283</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Существует, Махамати, шесть видов причин:</li>
            <li>• Будущая причина (<em>bhaviṣyad-dhetu</em>) исполняет роль порождения внутренних и внешних дхарм.</li>
            <li>• Причина связи (<em>saṃbandha-hetu</em>) исполняет роль опоры (<em>ālambana</em>) при возникновении внутренних и внешних <em>скандх</em>, семян и прочего.</li>
            <li>• Причина признака (<em>lakṣaṇa-hetu</em>) порождает преемственность, обусловленную признаком непрерывности действия.</li>
            <li>• Действующая причина (<em>kāraṇa-hetu</em>) исполняет роль доминирующей власти, подобно царю-миродержцу.</li>
            <li>• Проявляющая причина (<em>vyañjana-hetu</em>) исполняет роль высвечивания признаков уже возникшего в различении бытия, подобно светильнику, [освещающему] формы.</li>
            <li>• Причина нейтральности (<em>upekṣā-hetu</em>) в момент прекращения [обусловленности] исполняет роль пресечения деятельности потока, [ведя] к возникновению безразличительного состояния (<em>avikalpa</em>).<a href="#citation-284" id="ref-284" class="citation-mark"><sup>284</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Все эти [причины], Махамати, ложно воображены невеждами;</li>
            <li>на самом деле [дхармы] не приходят в движение ни постепенно, ни мгновенно.</li>
            <li>Почему это так?</li>
            <li>Если бы они возникали мгновенно, Махамати,</li>
            <li>то не было бы различия между причиной и следствием,</li>
            <li>ибо отсутствует признак причины.</li>
            <li>Если же они возникают постепенно, то это также невозможно,</li>
            <li>ибо [причина] не обладает признаком [следствия].</li>
            <li>Подобно тому, Махамати, как нельзя говорить о порядке</li>
            <li>между отцом и ещё не рождённым сыном —</li>
            <li>связь последовательности здесь невозможна.</li>
            <li>[Учения] логиков о возникновении через причины, опоры и условия</li>
            <li>не объясняют постепенности рождения.</li>
            <li>Из-за привязанности к признакам воображаемой природы</li>
            <li>[дхармы] не возникают мгновенно.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поскольку тело, объекты и обитель —</li>
            <li>лишь видимое собственным умом,</li>
            <li>а внешние вещи лишены бытия и небытия,</li>
            <li>они не возникают ни постепенно, ни мгновенно.</li>
            <li>Сознание — это лишь воображение,</li>
            <li>порождённое умозрительным различением</li>
            <li>воспринимаемого собственным умом.</li>
            <li>Потому, Махамати, тебе следует оставить</li>
            <li>воззрения о постепенном и мгновенном,</li>
            <li>основанные на привязанности к действию причин и условий.</li>
        </ul>
        </blockquote>
        <p>Об этом сказано гатхами:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>138. В действительности ничто не возникает из условий и ничто не прекращается.</li>
            <li>Возникают и прекращаются лишь сами воображаемые условия (<em>pratyayā eva
                    kalpitāḥ</em>).</li><br>
            <li>139. Нельзя устранить распад и возникновение самих условий [в мире явлений];</li>
            <li>но там, где невежды строят различения — именно там [через мудрость] эти условия устраняются.</li><br>
            <li>140. Поскольку у дхарм нет реального возникновения из условий, то [очевидно]:</li>
            <li>это лишь ум, введённый в заблуждение отпечатками (<em>vāsanā</em>), является как Тройственный мир.</li>
            <li>Ничто не рождается, не существуя [прежде], и ничто не пресекается (<em>na virudhyate</em>) условиями.</li><br>
            <li>141. Когда увидят в обусловленном мире лишь сына бесплодной женщины или цветок в небе,</li>
            <li>тогда, узрев это заблуждение (<em>bhrānti</em>), [двойственность] схватываемого и схватывающего (<em>grāhya-grāha</em>) прекращается.</li><br>
            <li>142. Нет ни того, что должно возникнуть, ни возникшего; даже сами условия — ничто.</li>
            <li>Это не существует нигде и ни в чём, а всё, что говорится — лишь условное обозначение (<em>vyavahāra</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.29 (29. Четыре вида признаков различающей речи)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь воззвал к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Пусть Благословенный разъяснит изложение Дхармы (<em>dharmaparyāya</em>),</li>
            <li>именуемое «Сутью признаков различающей речи» (<em>vāgvikalpa-lakṣaṇa-hṛdaya</em>)!</li>
            <li>Дабы благодаря ясному различению этой сути я и другие бодхисаттвы</li>
            <li>постигли двойственность выражения и выражаемого смысла (<em>abhilāpa-abhilāpya-artha</em>) и,</li>
            <li>быстро достигнув непревзойдённого совершенного пробуждения,</li>
            <li>очистили бы всех существ от [пустых] слов и привязанности к их смыслам.</li>
        </ul>
        </blockquote>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Существует, Махамати, четыре вида различающей речи:</li>
            <li>• Речь признаков (<em>lakṣaṇa-vāk</em>);</li>
            <li>• Речь сновидений (<em>svapna-vāk</em>);</li>
            <li>• Речь привязанности к косным различениям (<em>dauṣṭhulya-vikalpa-abhiniveśa-vāk</em>);</li>
            <li>• Речь безначальных различений (<em>anādi-vikalpa-vāk</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Здесь, Махамати, речь признаков (<em>lakṣaṇa-vāk</em>) возникает</li>
            <li>из привязанности к формам и знакам,</li>
            <li>созданным собственным различением.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Речь сновидений (<em>svapna-vāk</em>), Махамати,</li>
            <li>возникает из припоминания объектов, испытанных прежде,</li>
            <li>даже когда сами эти объекты отсутствуют [после] пробуждения.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Речь привязанности к косным различениям (<em>dauṣṭhulya</em>)</li>
            <li>возникает из воспоминаний о вражде и деяниях,</li>
            <li>совершенных в прошлом, и привязанности к ним.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Речь безначальных различений, Махамати,</li>
            <li>возникает из собственных семян-отпечатков (<em>vāsanā</em>),</li>
            <li>[порождённых] привязанностью к косности многообразия понятий (<em>prapañca</em>),</li>
            <li>тянущегося из безначальных времён.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Таковы, Махамати, четыре вида признаков различающей речи,</li>
            <li>о которых Я говорил; это и есть ответ на твой вопрос.<a href="#citation-285" id="ref-285" class="citation-mark"><sup>285</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.30 (30. Сфера проявления различающей речи)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному с той же просьбой:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Пусть Благословенный ещё раз разъяснит</li>
            <li><strong>сферу проявления различающей речи</strong>!</li>
            <li>Где, из чего, как и почему, о Благословенный,</li>
            <li>у людей возникает это умозрительное различение</li>
            <li>в виде речевых обозначений (<em>vāg-vijñapti-vikalpa</em>)?</li>
        </ul>
        </blockquote>
        <p>Благословенный ответил:</p>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>— Махамати, речь приходит в движение благодаря сочетанию головы,</li>
            <li>груди, носа, горла, нёба, губ, языка и зубов.</li>
        </ul>
        <p>Махамати спросил:</p>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>— Но является ли речь, о Благословенный,</li>
            <li>отличной от различения (<em>vikalpa</em>) или же она не отлична от него?</li>
        </ul>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, речь не отлична от различения и не тождественна ему.</li>
            <li>Почему это так?</li>
            <li>Потому что, Махамати, различающая речь проявляется,</li>
            <li>имея [это самое] различение признаком своей причины (<em>taddhetūtpattilakṣaṇatvāt</em>).</li>
            <li>Если бы, Махамати, речь была отлична от различения,</li>
            <li>она бы не имела его своей причиной.</li>
            <li>Если бы она была тождественна ему,</li>
            <li>она не могла бы выполнять роль проявления смысла (<em>arthābhivyaktitvāt</em>).</li>
            <li>Однако она её выполняет. Потому она не иная и не та же самая.<a href="#citation-286" id="ref-286" class="citation-mark"><sup>286</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.31 (31. Обозначаемое словом и высший смысл)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Махамати вновь спросил:</p>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>— Благословенный, является ли само слово высшим смыслом (<em>paramārtha</em>),</li>
            <li>или же высший смысл — это то, что обозначается словом?</li>
        </ul>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Нет, Махамати, ни само слово не является высшим смыслом,</li>
            <li>ни то, что им обозначается. Почему это так?</li>
            <li>Потому что высший смысл — это [блаженство], войти в которое можно благодаря провозглашению [учения]; само же слово — не истина.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Высший смысл, Махамати, постигается личностным благородным знанием (<em>āryajñāna-pratyātmagati</em>);</li>
            <li>он не является сферой рассудка или различающей речи.</li>
            <li>Потому различение не может явить высший смысл.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Слово же, Махамати, возникает и мгновенно исчезает;</li>
            <li>оно мимолётно (<em>capala</em>) и рождено из сочетания взаимных условий.</li>
            <li>То же, что рождено из условий, не может явить высший смысл.</li>
            <li>Из-за отсутствия признаков «себя» и «другого»,</li>
            <li>оно не может установить признаки внешнего.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Более того, Махамати, поскольку [весь мир] —</li>
            <li>лишь следствие видимого собственным умом,</li>
            <li>и поскольку внешние вещи</li>
            <li>в их многообразных признаках лишены бытия и небытия, —</li>
            <li>постольку различающая речь не способна вычленить высший смысл.</li>
            <li>Поэтому, Махамати, тебе следует пребывать свободным</li>
            <li>от разнообразных различений, порождаемых речью.</li><br>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Все явления лишены собственной природы;</li>
            <li>даже слова о «бытии» — ложны.</li>
            <li>Не узрев смысла <em>шуньята-шуньяты</em>,</li>
            <li>невежда мчится вперёд.</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>144. Собственная природа всех явлений и речь людей — лишь воображение;</li>
            <li>и само это воображение — не существует.</li>
            <li>Нирвана подобна сну. Исследуй бытие так,</li>
            <li>чтобы не вязнуть в сансаре и не исчезать в нирване.</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>145. Подобно тому как царь или богач</li>
            <li>манит своих детей пёстрыми глиняными зверушками,</li>
            <li>давая им наиграться,</li>
            <li>а затем дарит им истинных зверей, —</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>146. так и Я, используя разнообразные признаки и отражения дхарм,</li>
            <li>наставляю своих сыновей,</li>
            <li>дабы привести их к пределу истинности (<em>bhūtakoṭi</em>),</li>
            <li>постигаемому лишь лично.<a href="#citation-287" id="ref-287" class="citation-mark"><sup>287</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.32 (32. Мир как отражение и представление: разрушение иллюзий)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь воззвал к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Пусть Благословенный разъяснит вхождение в истину высшего смысла,</li>
            <li>свободное от [идей] бытия и небытия, единства и инаковости,</li>
            <li>обоих и ни того, ни другого, вечности и непостоянства!</li>
            <li>Поведай о том, что недоступно всем тиртхикам,</li>
            <li>но постигается личным благородным знанием;</li>
            <li>о том, что свободно от воображаемых собственных и общих признаков.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Разъясни вхождение в истину высшего смысла,</li>
            <li>признаки преемственной связи между ступенями (<em>bhūmy-anusaṃdhi</em>)</li>
            <li>и постепенного очищения (<em>uttarottara-viśuddhi</em>),</li>
            <li>а также признаки вхождения в ступень Татхагаты —</li>
            <li>деятельности, совершаемой без усилий (<em>anābhoga</em>) в силу прежних обетов,</li>
            <li>подобной драгоценному камню, принимающему бесконечные формы отражений,</li>
            <li>чей поток признаков беспределен в соответствии с нуждами существ!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Разъясни признаки различения сферы того, что есть лишь</li>
            <li>воспринимаемое собственным умом во всех дхармах!</li>
            <li>Дабы я и другие бодхисаттвы, очистив воззрения</li>
            <li>от воображаемой природы и собственных признаков [дхарм],</li>
            <li>быстро достигли непревзойдённого совершенного пробуждения</li>
            <li>и наполнили всех существ совершенством всех благих качеств!</li>
        </ul>
        </blockquote>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Превосходно, Махамати! Истинно превосходно,</li>
            <li>что ты решился просить об этом смысле.</li>
            <li>Ты действуешь ради блага и счастья многих, из сострадания к миру,</li>
            <li>ради пользы и счастья богов и людей.</li>
            <li>Слушай же внимательно и запечатлей это в уме!</li>
        </ul>
        </blockquote>
        <p>— Да, Благословенный! — ответил Махамати.</p>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, из-за непонимания того, что всё — лишь воспринимаемое собственным умом,</li>
            <li>невежды привязываются к внешним формам.</li>
            <li>Из-за привязанности к отпечаткам, порождённым</li>
            <li>умозрительными построениями о бытии и небытии,</li>
            <li>единстве и инаковости, вечности и непостоянстве,</li>
            <li>они строят дальнейшие различения.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как олени в летний зной, мучимые жаждой,</li>
            <li>принимают мираж за воду и бегут к нему,</li>
            <li>не понимая из-за заблуждения собственного зрения, что воды там нет, —</li>
            <li>так и невежды, чей разум пропитан безначальным многообразием различений,</li>
            <li>а умы опалены огнём страсти, гнева и заблуждения,</li>
            <li>жаждут разнообразных форм и объектов.</li>
            <li>Пребывая в плену воззрений о рождении, распаде и пребывании,</li>
            <li>они впадают в цепляние за единство и инаковость, есть и нет.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как у несведущих людей возникает представление о городе</li>
            <li>при виде города гандхарвов — иллюзорного города, видимого вдали, —</li>
            <li>хотя там нет никакого города.</li>
            <li>Этот облик города возникает лишь из-за привязанности</li>
            <li>к безначальным отпечаткам-семенам города.</li>
            <li>Этот «город» — ни не-город, ни город.</li>
            <li>Точно так же, Махамати, те, кто привязан к безначальным отпечаткам</li>
            <li>умозрительных учений тиртхиков,</li>
            <li>цепляются за утверждения о единстве, инаковости, бытии и небытии,</li>
            <li>не осознавая, что всё — лишь воспринимаемое собственным умом.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как человек во сне видит страну и дворец,</li>
            <li>украшенные мужчинами, женщинами, слонами, конями,</li>
            <li>колесницами, пешими, городами, деревнями, коровами, буйволами,</li>
            <li>лесами, парками, разнообразными горами, реками,</li>
            <li>прудами и озёрами, а затем пробуждается.</li>
            <li>Проснувшись, он продолжает удерживать в памяти</li>
            <li>ту страну и тот дворец как нечто, что было.<a href="#citation-288" id="ref-288" class="citation-mark"><sup>288</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Как ты думаешь, Махамати, можно ли назвать мудрым человека,</li>
            <li>который [всерьёз] вспоминает и обдумывает причудливые образы из своего сна?</li>
        </ul>
        </blockquote>
        <p>— О нет, Благословенный!</p>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Точно так же, Махамати, невежды,</li>
            <li>уязвлённые дурными воззрениями тиртхиков,</li>
            <li>не понимают, что всё —</li>
            <li>лишь воспринимаемое собственным умом, подобное сну.</li>
            <li>Они опираются на взгляды о единстве и инаковости, бытии и небытии.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как на картине, написанной художником,</li>
            <li>нет впадин и выступов, но невежды воображают их там, —</li>
            <li>так же в будущем люди, вскормленные отпечатками воззрений тиртхиков,</li>
            <li>будут цепляться за идеи о единстве, различии или обоих сразу.</li>
            <li>Сами заблудшие, они станут называть нигилистами тех,</li>
            <li>кто учит о не-возникновении и отделён от сторон «есть» и «нет».</li>
            <li>Отрицая связь причин и плодов, они выкорчевывают в себе корни благого.</li>
            <li>Те, кто ищет высшего блага, должны держаться от них подальше!</li>
            <li>Павшие в бездну приписывания и отрицания, они устремляются в ад.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как люди с помутнением зрения,</li>
            <li>видя в воздухе мнимые волоски, говорят друг другу:</li>
            <li>«Смотрите, как это дивно!»</li>
            <li>Но эти волоски не являются ни сущими, ни не-сущими.</li>
            <li>Так же и тиртхики, отрицая истинную Дхарму, губят себя и других.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как колесо,</li>
            <li>возникающее от быстрого вращения горящего посоха,</li>
            <li>в котором нет никакого реального колеса,</li>
            <li>принимается невеждами за колесо, но не мудрецами.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, как пузыри на воде во время дождя</li>
            <li>кажутся невеждам прозрачными кристаллами или драгоценными камнями.</li>
            <li>Но эти пузыри ни жемчуг, ни не-жемчуг.</li>
            <li>Точно так же тиртхики будут описывать возникновение несуществующего через условия</li>
            <li>и уничтожение того, что реально не рождалось.<a href="#citation-289" id="ref-289" class="citation-mark"><sup>289</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, [в будущем] некоторые будут утверждать,</li>
            <li>опираясь на логические доводы и три средства познания (<em>pramāṇa</em>),</li>
            <li>как будто существует некая «реальная вещь» (<em>vastu</em>), постигаемая благородными,</li>
            <li>но свободная от двойственности собственной и общей природ.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Однако, Махамати, у йогинов,</li>
            <li>чей ум (<em>citta</em>), интеллект (<em>manas</em>) и различающее сознание (<em>vijñāna</em>)</li>
            <li>совершили поворот основы (<em>parāvṛtti</em>),</li>
            <li>кто оставил различения между схватываемым и схватывающим,</li>
            <li>и кто вошёл в сферу личного благородного знания ступени Татхагаты,—</li>
            <li>у них не возникает представления (<em>saṃjñā</em>) о «бытии» или «небытии».</li>
            <li>Если бы у таких йогинов всё же возникло цепляние за «бытие» и «небытие»,</li>
            <li>это было бы у них цеплянием за «я» (<em>ātman</em>),</li>
            <li>цеплянием за «питающее» (<em>poṣa</em>),</li>
            <li>цеплянием за «личность» (<em>puruṣa</em>)</li>
            <li>и цеплянием за «существо» (<em>pudgala</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Помни, Махамати:</li>
            <li>учения о бытии, собственной природе и признаках вещей —</li>
            <li>это поучения, данные через Нирманакаю (<em>nairmāṇikabuddha-deśanā</em>),</li>
            <li>а не поучения Дхармакаи (<em>dharmatābuddha-deśanā</em>).</li>
            <li>Эти наставления даны лишь для умиротворения склонностей невежд,</li>
            <li>но они не порождают блаженства <em>самадхи</em></li>
            <li>и прямого постижения истины.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно тому, Махамати, как тень дерева в воде кажется реальной,</li>
            <li>но она ни тень, ни не-тень — из-за наличия или отсутствия дерева.</li>
            <li>Подобно тому, как в зеркале видны отражения всех форм</li>
            <li>в зависимости от условий и собственного различения, —</li>
            <li>эти отражения ни объекты (<em>bimba</em>), ни не-объекты —</li>
            <li>из-за видения или невидения самих объектов.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>И всё же, Махамати, эти различения воспринимаемого собственным умом</li>
            <li>видятся невеждам в виде [реальных] форм.</li>
            <li>Так же и всё проявляется в виде отражений собственного ума</li>
            <li>под видом воззрений о единстве, инаковости, обоих и ни того, ни другого.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно эху, возникающему из сочетания голоса, реки и леса, —</li>
            <li>оно ни существует, ни не существует — из-за слышимости или неслышимости звука.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно миражу на безтравной равнине,</li>
            <li>который под лучами солнца колеблется, словно волны, —</li>
            <li>он ни есть, ни нет — в зависимости от того, жаждет ли его путник.</li>
            <li>Так и сознание невежд, пропитанное безначальными косными отпечатками</li>
            <li>и многообразием умозрительных построений,</li>
            <li>волнуется, подобно миражу,</li>
            <li>создавая иллюзии рождения, пребывания, распада,</li>
            <li>единства и инаковости, бытия и небытия.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно механической кукле (<em>yantra-puruṣa</em>) и призраку (<em>vetāla</em>),</li>
            <li>которые лишены жизни, но двигаются силой заклинаний пишачей, —</li>
            <li>невежды впадают в заблуждение, видя их движения.</li>
            <li>Так и люди, уязвлённые взглядами тиртхиков,</li>
            <li>привязываются к идеям о единстве и инаковости.</li>
            <li>Это — лишь приписывание несуществующего (<em>asadbhūta-samāropa</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Потому, Махамати, тебе следует пребывать свободным</li>
            <li>от различений о рождении, пребывании, распаде,</li>
            <li>единстве, инаковости, обоих и ни того, ни другого,</li>
            <li>бытии и небытии.</li><br>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>147. Пять <em>скандх</em>, во главе с сознанием,</li>
            <li>подобны отражению деревьев в воде.</li>
            <li>Видимое — лишь магия и сон;</li>
            <li>не строй различений на основе представлений (<em>vijñapti</em>)!</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>148. Этот Тройственный мир</li>
            <li>подобен видению волос в воздухе или миражу;</li>
            <li>он зовётся сном и магией.</li>
            <li>Лишь тот, кто созерцает его так, обретает свободу.</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>149. Как мираж в зной колеблется, обманывая разум,</li>
            <li>и олени бегут к нему за водой, хотя воды там нет, —</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>150. так и семя сознания (<em>vijñāna-bīja</em>) пульсирует в сфере видимого.</li>
            <li>Невежды цепляются за «рождение»,</li>
            <li>подобно тому как больной глазами видит мнимые пятна.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>151. В безначальной сансаре, скованной цеплянием за бытие,</li>
            <li>невежду [нужно] отвратить от заблуждений,</li>
            <li>подобно тому как один колышек выбивают другим.</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>152. Узри этот мир как механическую куклу или призрака,</li>
            <li>как вспышку молнии или облако —</li>
            <li>и через пресечение трёх непрерывностей (<em>trisaṃtati</em>) ты освободишься.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>153. В этом нет никакого представления [об объектах],</li>
            <li>как нет воды в небесных миражах.</li>
            <li>Постигая так дхармы,</li>
            <li>мудрые не выдвигают никаких утверждений.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>154. Всё представление — лишь имя, признаков же в нём нет.</li>
            <li><em>Скандхи</em> подобны пучкам волос в воздухе,</li>
            <li>в которых строится различение.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>155. Подобно волоскам в глазу, иллюзии, сну,</li>
            <li>городу гандхарвов, огненному колесу и миражу</li>
            <li>является ум людям, хотя и не существует.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>156. Вечное и невечное, единство и множественность,</li>
            <li>и то, и другое, и ни то, ни другое —</li>
            <li>всё это невежды, опутанные безначальными пороками,</li>
            <li>воображают в своём ослеплении.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>157. В зеркале, в воде, в глазу,</li>
            <li>в полированном сосуде и в драгоценном камне —</li>
            <li>всюду видится отражение (<em>bimba</em>),</li>
            <li>но этого отражения нет ни в одном из них.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>158. Так и ум — лишь видимость бытия, подобно миражу в небе;</li>
            <li>он является в многообразных формах,</li>
            <li>как [сын], увиденный во сне бесплодной женщиной.<a href="#citation-290" id="ref-290" class="citation-mark"><sup>290</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.33 (33. Учение Татхагат: свобода от крайностей и очищение от завес)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, поучение Татхагат в Дхарме</li>
            <li>свободно от тетралеммы (четвероякого рассмотрения) (<em>catuṣṭaya</em>).</li>
            <li>Оно оставляет стороны тождественности и инаковости (<em>ekatva-anyatva</em>),</li>
            <li>обоих [сразу] и ни того, ни другого;</li>
            <li>оно свободно от приписывания/наложения (<em>samāropa</em>) и</li>
            <li>отрицания (<em>apavāda</em>) [идей] бытия и небытия.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поучение Татхагат, Махамати, направляет к освобождению</li>
            <li>через путь прекращения [иллюзии] зависимого возникновения (<em>pratītyasamutpāda-nirodha</em>), поскольку оно [в своей основе] ложно (<em>asatya</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Поучение Татхагат не связано с [представлениями]</li>
            <li>о Первоматерии (<em>prakṛti</em>), Боге-Творце (<em>īśvara</em>), [внешней] причине (<em>hetu</em>), случае (<em>yadṛcchā</em>),</li>
            <li>атомах (<em>aṇu</em>), времени (<em>kāla</em>) или неизменной сущности (<em>svabhāva</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, ради очищения от двоякой завесы —</li>
            <li><em>клеш</em> (<em>kleśa-āvaraṇa</em>) и препятствий к всезнанию (<em>jñeya-āvaraṇa</em>) —</li>
            <li>[Татхагаты], подобно опытным проводникам караванов (<em>sārthavāha</em>),</li>
            <li>последовательно утверждают [йогинов] в ста восьми высказываниях,</li>
            <li>свободных от ментальных образов (<em>nirābhāsa-pada-śata</em>),</li>
            <li>а также в ясном различении ступеней (<em>bhūmi</em>) и колесниц (<em>yāna</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.34 (34. Четыре вида дхьяны)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, существует четыре вида дхьяны. Каковы эти четыре?</li>
        <li>— <em>Дхьяна, свойственная невеждам</em> (<em>bālopacārikam</em>);</li>
        <li>— <em>Дхьяна исследования смысла</em> (<em>arthapravicayam</em>);</li>
        <li>— <em>Дхьяна опоры на Таковость</em> (<em>tathatālambanam</em>);</li>
        <li>— <em>Дхьяна Татхагаты</em> (<em>tāthāgatam</em>) — четвёртая.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Что же, Махамати, есть <em>дхьяна, свойственная невеждам</em>?</li>
        <li>Это [созерцание], присущее шравакам и пратьекабуддам,</li>
        <li>когда они, привязываясь к признакам:</li>
        <li>— отсутствия «я» в личности,</li>
        <li>— общих и собственных признаков явлений,</li>
        <li>— непостоянства, страдания и нечистоты,</li>
        <li>наблюдают их в последовательности, вплоть до прекращения восприятия (<em>saṃjñā-nirodha</em>),</li>
        <li>полагая: «Признак именно таков и не иначе».</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Что есть <em>дхьяна исследования смысла</em>?</li>
        <li>Это [созерцание], когда йогин,</li>
        <li>установив отсутствие «я», «другого» и «обоих» —</li>
        <li>как утверждают внешние тиртхики, —</li>
        <li>последовательно исследует смысл:</li>
        <li>— отсутствия «я» в дхармах,</li>
        <li>— и признаков ступеней (<em>bhūmi</em>).</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Что есть <em>дхьяна опоры на Таковость</em>?</li>
        <li>Это [состояние], когда вследствие пребывания</li>
        <li>в реальности как она есть (<em>yathābhūta</em>),</li>
        <li>не возникает различение (<em>vikalpa</em>)</li>
        <li>о воображаемом двойном отсутствии «я».</li>
        <li>Я называю это «опорой на Таковость».</li>
    </ul>
    <ul class="list-none mb-12 pl-2 space-y-1 ml-2">
        <li>Что же есть <em>дхьяна Татхагаты</em>?</li>
        <li>Это вхождение в образ ступеней Татхагаты,</li>
        <li>пребывание в блаженстве трёх признаков</li>
        <li>личного благородного знания</li>
        <li>и совершение непостижимых деяний ради живых существ.</li>
        <li>Это Я называю «дхьяной Татхагаты».</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>159. Созерцание, [ведущее к] исследованию смысла;</li>
        <li>созерцание, свойственное невеждам;</li>
        <li>созерцание, [основанное на] Таковости,</li>
        <li>и <em>дхьяна Татхагаты</em> — благая.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>160. Подобно облику луны и солнца,</li>
        <li>подобно лотосу над бездной,</li>
        <li>подобно небу или огню —</li>
        <li>такие разнообразные [образы] созерцает йогин в своей практике.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>161. [Но] эти многообразные признаки (<em>nimitta</em>) ведут [лишь] на пути тиртхиков,</li>
        <li>или же они низвергают в состояние шраваков</li>
        <li>и в область пратьекабудд.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>162. Когда же, отбросив всё это, йогин пребывает в без-образности (<em>nirābhāsa</em>),</li>
        <li>тогда Будды из всех миров, сияющие как солнца,</li>
        <li>собираются вместе и касаются его головы —</li>
        <li>[это] признак (<em>nimitta</em>), согласующийся с Таковостью.<a href="#citation-291" id="ref-291" class="citation-mark"><sup>291</sup></a></li>
    </ul>
</blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.35 (35. Нирвана)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</p>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
        <li>— «Нирвана, нирвана», о Благословенный, — так говорится [повсюду].</li>
        <li>Обозначением чего именно, о Благословенный, является это слово «нирвана»?</li>
    </ul>
    <p>Благословенный ответил:</p>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>— Нирваной именуется всеми Буддами и Мною</li>
        <li>поворот основы (<em>parāvṛtti</em>), [заключающийся в] преобразовании:</li>
        <li>— отпечатков природы всех сознаний,</li>
        <li>— и отпечатков воззрений, связанных с <em>Алайей</em>, <em>манасом</em> и <em>мановиджняной</em>.<a href="#citation-291" id="ref-291" class="citation-mark"><sup>291</sup></a></li>
        <li>Это — сфера состояния нирваны, [характеризуемая]</li>
        <li><em>шуньятой</em> собственной природы всех вещей.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, Нирвана —</li>
        <li>это сфера личного благородного постижения,</li>
        <li>свободная от различений о вечности и уничтожении, о бытии и небытии.</li>
        <li>Почему она — не вечность? Потому что в ней</li>
        <li>полностью оставлены различения собственных и общих признаков [явлений];</li>
        <li>потому она — не вечность. Почему в ней нет уничтожения?</li>
        <li>Потому что все объекты (<em>sarvārtha</em>) прошлого, будущего и настоящего</li>
        <li>достигаются в личном постижении; потому это — не уничтожение.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Более того, Махамати, Великая Нирвана — это не исчезновение и не смерть.</li>
        <li>Если бы Великая Нирвана была смертью, Махамати,</li>
        <li>то вновь возникла бы преемственность рождений.</li>
        <li>Если бы она была исчезновением, она подпадала бы</li>
        <li>под признаки обусловленного [бытия].</li>
        <li>По этой причине, Махамати, Великая Нирвана — ни исчезновение, ни смерть.</li>
        <li>Йогины же достигают смерти, не ведущей к новому рождению.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, Великая Нирвана именуется Нирваной,</li>
        <li>поскольку она — ни отбрасывание, ни достижение,</li>
        <li>вне уничтожения и вечности, вне единства и множественности.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Более того, Махамати, нирвана шраваков и пратьекабудд [заключается в том],</li>
        <li>что через постижение собственных и общих признаков [дхарм]</li>
        <li>они пребывают в отделённости [от объектов] (<em>asaṃsarga</em>).</li>
        <li>Благодаря видению объектов без искажений, их различающее мышление (<em>vikalpa</em>)</li>
        <li>перестаёт двигаться [вовне]. Именно в этом состоянии у них</li>
        <li>возникает убеждение (<em>buddhi</em>) о том, что это и есть нирвана.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.36 (Две формы признака собственной природы)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, признак двойственной собственной природы проявляется двояко.</li>
        <li>Каковы эти два [проявления]?</li>
        <li>— Привязанность к собственной природе обозначений (<em>abhilāpa-svabhāva-abhiniveśa</em>);</li>
        <li>— Привязанность к собственной природе объектов (<em>vastu-svabhāva-abhiniveśa</em>).</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Махамати, привязанность к собственной природе обозначений</li>
        <li>возникает из привязанности, содержащейся в отпечатках</li>
        <li>безначального речевого многообразия (<em>anādi-kāla-vāk-prapañca-vāsanā-abhiniveśāt</em>).</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Привязанность же к собственной природе объектов, Махамати,</li>
        <li>возникает из непостижения того, что [всё это] —</li>
        <li>лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-mātrān-avabodhāt</em>).</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.37 (Благословление Татхагат)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, благодаря двоякому благословению (<em>adhiṣṭhāna</em>)</li>
        <li>бодхисаттвы склоняются к стопам Татхагат и задают им вопросы.</li>
        <li>Каково это двоякое благословение?</li>
        <li>— Благословение через достижение <em>самадхи</em>;</li>
        <li>— Благословение через посвящение</li>
        <li>телом, ликом и руками (<em>sarva-kāya-mukha-pāṇi-abhiṣeka</em>).</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Махамати, на первой ступени (<em>bhūmi</em>) бодхисаттвы, благодаря силе Будд,</li>
        <li>входят в <em>самадхи</em> под названием «Сияние Махаяны».</li>
        <li>Как только они входят в него, Татхагаты десяти сторон света</li>
        <li>являют свои лики и благословляют их явлением [своего] тела, лика и речи.</li>
        <li>Так происходит с бодхисаттвой Ваджрагарбхой и другими,</li>
        <li>наделёнными подобными качествами.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Накопив корни благого в течение сотен тысяч кальп,</li>
        <li>бодхисаттва постепенно постигает признаки</li>
        <li>благоприятного и неблагоприятного на ступенях и достигает десятой —</li>
        <li>Облака Дхармы (<em>dharmameghā</em>).</li>
        <li>Там, восседая на великом лотосовом троне в небесном чертоге</li>
        <li>в окружении других бодхисаттв, в короне, украшенной драгоценностями,</li>
        <li>сияющей подобно жёлтому аурипигменту,</li>
        <li>золоту, цветам чампака, лунным лучам и лотосу, он получает посвящение.</li>
        <li>Руки Победителей (<em>jina-karāḥ</em>), пришедших из десяти сторон света,</li>
        <li>возлагаются на его голову, подобно тому как венчают царя-чакравартина.</li>
        <li>Это именуется благословением через возложение рук.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Обладая этим двояким благословением, Махамати,</li>
        <li>бодхисаттвы взирают на лики всех Будд. Иначе Татхагаты невидимы.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Более того, Махамати, что бы ни являлось бодхисаттвам-махасаттвам</li>
        <li>в форме <em>самадхи</em>, чудесных сил или проповеди —</li>
        <li>всё это происходит благодаря двоякому благословению Будд.</li>
        <li>Если бы, Махамати, бодхисаттвам являлось подобное без благословения,</li>
        <li>то и обычным людям оно являлось бы. Почему это не так?</li>
        <li>Потому что они не утверждены благословением.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Махамати, благодаря благословению вхождения Татхагаты</li>
        <li>даже травы, кусты, деревья и горы,</li>
        <li>а также различные музыкальные инструменты,</li>
        <li>города, дворцы, дома, небесные чертоги и троны начинают провозглашать [Дхарму]!</li>
        <li>Что уж говорить о наделённых сознанием?</li>
        <li>Даже немые, слепые и глухие, Махамати, освобождаются от своих недостатков.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Таковы, Махамати, особые великие качества благословения Татхагаты.</li>
    </ul>
    </blockquote>
    <p>Махамати вновь спросил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Благословенный, почему Татхагаты, Архаты, Совершенно Пробуждённые</li>
        <li>даруют бодхисаттвам благословение во время пребывания</li>
        <li>в <em>самадхи</em> и посвящение (<em>abhiṣeka</em>) на особых ступенях?</li>
    </ul>
    </blockquote>
    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Дабы отделить их от Мары, кармы и клеш;</li>
        <li>дабы не дать им пасть на ступень созерцания шраваков;</li>
        <li>ради их личного достижения ступени Татхагаты и</li>
        <li>ради расширения их постижения уже достигнутой Дхармы.</li>
        <li>По этой причине, Махамати, Татхагаты</li>
        <li>даруют бодхисаттвам своё благословение.</li>
        <li>Без этого благословения, Махамати,</li>
        <li>бодхисаттвы могли бы упасть в воззрения</li>
        <li>тиртхиков, шраваков или Мары и</li>
        <li>не достигли бы непревзойдённого пробуждения.</li>
        <li>Именно поэтому они поддерживаются Татхагатами.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>163. Поддержка (<em>adhiṣṭhāna</em>) Владык Людей, очищенная их обетами,</li>
        <li>проявляется в посвящении (<em>abhiṣeka</em>), <em>самадхи</em> и прочем —</li>
        <li>от первой и до десятой ступени.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<hr class="my-8 border-t-4 border-gray-500">

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.38 (Спор о зависимом возникновении)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Затем Бодхисаттва Махамати вновь сказал Благословенному:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Благословенный, проповедуя о зависимом возникновении, Ты лишь обозначаешь причины, но не объясняешь [истинный] способ — пребывание в собственной природе. Тиртхики тоже описывают возникновение из причин: из Первоматерии, Бога-Творца, Духа, Времени или Атомов. Ты же лишь переименовываешь [причины] в условия. В чём же разница между Твоим выводом и их?</li>

        <li>И те, и другие говорят о возникновении бытия и небытия, и об их разрушении через условия. Твоя формула: «Из неведения возникают формирующие факторы и так далее до старости и смерти» — это изложение беспричинности (<em>ahetuvāda</em>), а не учение о причине (<em>hetuvāda</em>). Твоё изречение: «При наличии этого возникает то» — справедливо лишь для одновременно существующих [причины и следствия], но не для тех, кто полагается на последовательное возникновение.</li>

        <li>Более того, доводы тиртхиков кажутся убедительнее! У них причина независимо-сущая, но порождает следствие. У Тебя же, Благословенный, причина зависит от следствия, а следствие — от причины. Это порождает путаницу причин и условий и взаимный бесконечный регресс! Если Ты говоришь: «При наличии этого возникает то», — Ты фактически утверждаешь беспричинность мира.</li>
    </ul>
    </blockquote>
    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Махамати, Моё учение — не о беспричинности и не о путанице причин. Когда Я говорю: «При наличии этого возникает то», — Я исхожу из отсутствия схватываемого и схватывающего и из понимания того, что всё — лишь воспринимаемое собственным умом.</li>

        <li>Этот изъян [бесконечного регресса], Махамати, касается лишь тех, кто привязан к двойственности субъекта и объекта и не понимает, что всё — лишь содержания ума, но верит в бытие или небытие внешних объектов. Но он не касается Меня, излагающего учение о зависимых причинах [как о проекциях ума].<a href="#citation-293" id="ref-293" class="citation-mark"><sup>293</sup></a></li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.39 (Спор о словах и вещах)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Махамати вновь спросил:</p>
    <p>— Но разве, Благословенный, все явления не существуют благодаря реальности слов (<em>abhilāpa</em>) для их обозначения? Если бы явлений не было, слова не могли бы возникнуть. Но они возникают. Посему, Благословенный, из-за реальности слов существуют и все явления.</p>
    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Махамати, слова произносятся даже о несуществующих явлениях. Разве в мире не говорят о «рогах зайца», «шерсти черепахи» или «сыне бесплодной женщины»? Хотя они не являются ни бытием, ни небытием, о них говорят. Посему твой довод о том, что явления существуют благодаря словам, отпадает.</li>
        <li>Более того, Махамати, не во всех мирах Будд слова имеют силу. Слова, Махамати, — построены. В одних мирах Дхарма проповедуется через пристальный взгляд, в других — через жесты, в иных — через движение бровей, или через движение глаз, или через смех, или через зевоту, или через кашель, или через воспоминание о мире, или через трепет.</li>
        <li>Подобно тому, Махамати, как в мире «Немигающего Благоухания» (<em>Анимиша-Гандхасугандха</em>), в обители Татхагаты Самантабхадры, Бодхисаттвы, созерцая друг друга немигающими глазами, обретают терпение в не-возникновении дхарм и высшие <em>самадхи</em>. По этой самой причине, Махамати, существование слов не доказывает существования явлений.</li>
        <li>Посмотри, Махамати: даже в этом мире такие существа, как черви и мухи, совершают свои дела вообще без слов.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>164. О пространстве, о рогах зайца</li>
        <li>и о сыне бесплодной женщины говорят, хотя их нет;</li>
        <li>точно так же воображают явления.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>165. Глядя на совокупность причин и условий,</li>
        <li>невежды воображают [реальное] возникновение; не зная этого метода [постижения истины],</li>
        <li>они блуждают в обители Тройственного мира.<a href="#citation-294" id="ref-294" class="citation-mark"><sup>294</sup></a></li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.40 (Вечность иллюзии)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Затем Бодхисаттва-махасаттва Махамати вновь спросил:</p>
    <p>— Относительно чего, Благословенный, Ты употребляешь слово «вечный»?</p>
    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Относительно иллюзии (<em>bhrānti</em>), Махамати. Ибо эта иллюзия проявляется даже перед Благородными — из-за остаточной извращённости [восприятия].</li>
        <li>Подобно тому, Махамати, как мираж, огненный круг, мушки перед глазами, город гандхарвов, магия, сон, отражение и магическая кукла принимаются невеждами за реальность, но не мудрецами — при этом они не перестают являться.</li>

        <li>Эта иллюзия, Махамати, может являться в бесчисленных формах, но это многообразие не создаёт её невечности. Почему? Потому что она свободна от бытия и небытия.</li>
        <li>Как же она свободна от бытия и небытия? Она является сферой опыта всех невежд, подобно волнам океана и воде Ганги: эта вода видима для одних, но невидима для претов. По этой причине иллюзия — это не [реальное] бытие. Но так как эта «вода» является восприятию других существ, она — не небытие.</li>

        <li>Так и иллюзия для Благородных лишена как извращённого, так и неизвращённого видения. Поэтому, Махамати, иллюзия вечна, ибо её признаки неразличимы. Она не претерпевает разделения, даже когда воображается через множество разнообразных форм. Потому, Махамати, иллюзия — вечна.<a href="#citation-295" id="ref-295" class="citation-mark"><sup>295</sup></a></li>

        <li>Как же, Махамати, заблуждение обретает природу истины? Именно потому, Махамати, что у Благородных в отношении этого заблуждения не возникает ни понятия «искажения», ни понятия «не-искажения». Благородные не наделяют это заблуждение какими-либо знаками, кроме самого личного благородного знания. То, что невежды называют «чем-то существующим» — лишь детский лепет, а не речь Благородных.</li>

        <li>Это же самое заблуждение, будучи различаемым как искажённое или неискажённое, порождает два духовных рода (<em>gotra</em>): род Благородных и род обычных людей.</li>

        <li>Как же заблуждение, различаемое невеждами, порождает род Пути шраваков? Через привязанность к собственным и общим признакам [объектов]. Так оно ведёт к роду шраваков.</li>
        <li>Как оно порождает род Пути пратьекабудд? Через отсутствие соприкосновения с миром при сохранении привязанности к тем же признакам.</li>
        <li>Как же это же самое заблуждение, различаемое мудрыми, порождает род Пути Будды? Через осознание того, что всё — лишь воспринимаемое собственным умом, и через оставление различений о внешнем бытии и небытии. Вот в чём смысл «рода» (<em>gotra</em>).</li>

        <li>Когда же невежды воображают в этом заблуждении многообразие объектов [в форме суждения]: «Это именно так и не иначе!», оно ведёт их к роду вращающихся в сансаре. Поэтому для невежд заблуждение предстаёт как реальные объекты, хотя оно не является ни объектом, ни не-объектом.</li>

        <li>Само же это заблуждение, когда оно более не различается [двойственно] у Благородных — благодаря повороту основы от пагубных отпечатков природы сознания, <em>манаса</em> и <em>мановиджняны</em>, — именно это заблуждение именуется Таковостью (<em>tathatā</em>). Поэтому и сказано: «Таковость свободна от ума». Она лишена любых воображений и различений.</li>
    </ul>
    </blockquote>
    <p>Махамати спросил:</p>
    <p>— Благословенный, существует ли заблуждение или нет?</p>
    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Подобно магии, Махамати, заблуждение не существует из-за привязанности к признакам. Если бы заблуждение существовало из-за привязанности к признакам, то привязанность к бытию была бы неискоренима. Оно стало бы подобно [реальной] причинности или первопричинам тиртхиков.</li>
    </ul>
    </blockquote>
    <p>Махамати спросил:</p>
    <p>— Но если заблуждение подобно магии, не станет ли оно причиной для других заблуждений?</p>
    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Нет, Махамати, магия не является причиной заблуждения. Она не несёт в себе пагубного изъяна (<em>dauṣṭhulya</em>). Магия, Махамати, возникает благодаря благословению знания другого существа; она не опирается на пагубные отпечатки собственных различений. Посему она не порождает порока. Это, Махамати, всего лишь заблуждение ума и зрения у невежд, порождённое привязанностью к «чему-то существующему»; Благородные же не впадают в него.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>166. Благородный не видит ни заблуждения,</li>
        <li>ни истины, ни чего-либо между ними.</li>
        <li>Ибо само заблуждение и есть истина,</li>
        <li>поскольку между ними нет различия.<a href="#citation-296" id="ref-296" class="citation-mark"><sup>296</sup></a></li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>167. И если, отбросив всякое заблуждение,</li>
        <li>[йогин вновь] порождает некий признак (<em>nimitta</em>),</li>
        <li>— то это и станет его [новым] заблуждением,</li>
        <li>подобно нечистому помутнению глаз.<a href="#citation-297" id="ref-297" class="citation-mark"><sup>297</sup></a></li>
    </ul>
    </blockquote>


    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.41 (Дхармы подобны магии)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати: магия не есть ничто. Из-за видения сходства (<em>sādharmya</em>) между магией и всеми дхармами, они называются подобными магии.</li>
    </ul>
    </blockquote>

    <p>Махамати спросил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Но как именно, Благословенный, все дхармы подобны магии? Из-за признака привязанности к многообразной магии или из-за признака привязанности к ложности?</li>
        <li>Если, Благословенный, они подобны магии из-за признака привязанности к многообразной магии, то, увы, вещи не могут быть ей подобны! И вот почему: в формах мира мы видим отсутствие [единой] причины их многообразных признаков. Ведь нет никакой причины, Благословенный, из-за которой форма являлась бы столь многообразной, как магия [является благодаря знанию фокусника]. Посему, вещи не могут быть подобны магии лишь из-за сходства в многообразии признаков.<a href="#citation-298" id="ref-298" class="citation-mark"><sup>298</sup></a></li>
    </ul>
    </blockquote>

    <p>Благословенный ответил:</p>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-12 pl-2 space-y-1 ml-2">
        <li>— Махамати, все дхармы подобны магии не из-за сходства с её многообразными признаками, но из-за сходства с тем, что и магия, и дхармы — ложны и подобны вспышке молнии.</li>
        <li>Подобно тому, Махамати, как вспышка молнии — с мгновенным разрушением, едва явившись, сразу исчезает из взора невежд, — точно так же и все явления, кажущиеся наделёнными частными и общими признаками, порождёнными собственным различением, — из-за отсутствия исследования — принимаются [невеждами] за реальные вследствие привязанности к признакам форм.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>168. Магия — не небытие; из-за сходства с ней говорится о существовании дхарм.</li>
        <li>Поскольку они ложны и подобны быстрой вспышке молнии, поэтому они считаются «подобными магии».</li>
    </ul>
    </blockquote>

    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.42 (42. Не-возникновение и условное бытие)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Махамати вновь спросил:</p>
     <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Когда Благословенный говорит, что все дхармы не возникли и в то же время подобны магии, не впадает ли Он в противоречие? Ведь, утверждая не-возникновение, Ты одновременно называешь дхармы магией.</li>
    </ul>
    </blockquote>
        <p>Благословенный ответил:</p>
     <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Махамати, здесь нет противоречия. Ибо через постижение того, что и возникновение, и не-возникновение — лишь воспринимаемое собственным умом, и через видение не-возникновения внешнего бытия и небытия, не возникает изъян внутреннего противоречия.</li>
        <li>Я говорю: «Подобны магии и не возникли» — чтобы опровергнуть учения тиртхиков о реальном рождении дхарм из внешних причин. Невежды-тиртхики верят в рождение бытия и небытия из внешних причин, не понимая, что всё — лишь игра их собственных различений.</li>
        <li>Учение же о «бытии» (<em>bhāva</em>) Я даю ради принятия сансары [как условно реального поля практики] и ради предотвращения нигилизма (<em>uccheda</em>). Чтобы мои ученики принимали основу разнообразных кармических плодов, Я использую слово «бытие».</li>
        <li>Но Я учу, что природа дхарм подобна магии и сну, чтобы отвратить невежд от их дурных воззрений — от привязанности к причинам и условиям. Ибо те, кто не понимает, что всё — лишь воспринимаемое собственным умом, будут вводить в заблуждение себя и других, не видя дхармы в их Таковости (<em>yathābhūta</em>).</li>
        <li>Видеть же дхармы в их Таковости — значит осознавать, что они суть только лишь воспринимаемое собственным умом.</li>
    </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>169. В не-возникновении (<em>anutpāda</em>) — устранение веры в реальную причину;</li>
        <li>в [признании] бытия (<em>bhāva</em>) — принятие сансары [как условно реальной].</li>
        <li>Следует видеть [мир] подобным магии и прочему,</li>
        <li>но не строить различений относительно его признаков (<em>lakṣaṇa</em>).</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.43 (Признаки обозначения имён, слов и букв/знаков)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>
            Кроме того, Махамати, Я разъясню признаки совокупностей имени, слова и буквы/ (<em>nāma-pada-vyañjana-kāya</em>). Благодаря ясному пониманию этих совокупностей бодхисаттвы-махасаттвы, следующие за смыслом, словом и знаком, быстро обретут непревзойдённое пробуждение и пробудят к нему всех существ.</li>
        <li>Махамати, что есть совокупность имени (<em>nāma-kāya</em>)? Это когда на основе некоей сущности (<em>vastu</em>) создаётся имя; эта сущность и есть тело (<em>kāya</em>). «Тело» и «форма» (<em>śarīra</em>) здесь синонимы. Такова, Махамати, совокупность имени.</li>
        <li>Что есть совокупность слова (<em>pada-kāya</em>)? Это установленность реального существования совокупности объектов слова. «Предел» (<em>niṣṭhā</em>) и «обнаружение» (<em>upalabdhi</em>) здесь синонимы. Это наставление о совокупности слова, Махамати, — майя.</li>
        <li>Что есть совокупность знака (<em>vyañjana-kāya</em>)? Это то, посредством чего раскрываются имя и слово. «Знак» (<em>vyañjana</em>), «метка» (<em>liṅga</em>), «признак» (<em>lakṣaṇa</em>), «обнаружение» (<em>upalabdhi</em>) и «условное обозначение» (<em>prajñapti</em>) здесь синонимы.</li>

        <li>Более того, Махамати, тело/совокупность слов (<em>pada-kāya</em>) — это завершённость смысла фразы.</li>
        <li>Имя (<em>nāma</em>), Махамати, — это различие собственной природы имён — от (первой буквы алфавита) «a» (अ) до (последней) «ha» (ह).</li>
        <li>Буквы (<em>vyañjana</em>), Махамати, — это краткие, долгие и протяжные.</li>
            <li>Под телом слов, Махамати, понимаются слова, идущие по пути слов, такие как «слон», «конь», «человек», «олень», «скот», «корова», «буйвол», «коза», «баран» и прочие — они получают название <em>pada-kāya</em>.</li>
        <li>Имя и буква, Махамати, — это также четыре бесформенные <em>скандхи</em> (<em>arūpin skandha</em>) (ощущение (<em>vedanā</em>), распознавание (<em>saṃjñā</em>), формирующие факторы (<em>saṃskāra</em>), сознание (<em>vijñāna</em>)). Они называются «именем», поскольку обозначаются через имена; и они называются «буквой/знаком», поскольку проявляются через свои признаки.</li>
        <li>Таковы, Махамати, признаки обозначения имён, слов и букв/знаков. В этом тебе следует совершенствоваться.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>170. В буквах, в совокупности слов и особенно в именах</li>
        <li>вязнут скудоумные невежды —</li>
        <li>подобно тому как слоны увязают в великой трясине.</li>
    </ul>
    </blockquote>

    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.44 (Необъяснимые вопросы)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, в будущем времени появятся лже-логики с извращённым разумом, лишённые правильного умозаключения (<em>yukti</em>). Когда мудрецы спросят их о том, что свободно от признаков воззрений на единство, различие, и то и другое, ни то ни другое, — они ответят так:
        «Этот вопрос недопустим, он не относится к сути».
        </li>
        <li>Когда их спросят: «Отлично ли непостоянство от форм и прочего? Отлична ли нирвана от обусловленного? Признак — от признака? Обладающий качествами — от качеств? Элементы — от производных элементов? Видимое — от видения? Пыль — от атомов? Йогин — от знания?» — и подобные вопросы, следующие один за другим в установленном порядке, — они скажут:
        «Благословенный объявил это необъяснимым (<em>avyākṛta</em>) и велел оставлять такие вопросы без ответа (<em>sthāpanīya</em>)».
        </li>
        <li>Но эти глупцы не поймут, что Татхагаты, Архаты, Совершенно Пробуждённые не дают ответов на такие вопросы лишь ради слушателей, чьё понимание ещё слабо, ради устранения почвы для страха (<em>utrāsapadavivarjanārthaṃ</em>).</li>

        <li>Махамати, даже «необъяснимые» [вопросы] не излагаются Татхагатами ради опровержения воззрений тиртхиков. Ведь тиртхики, Махамати, говорят так:<br>
        «Существо и тело — одно»,<br>
        «Существо и тело — разные»,<br>
        — и подобные им положения составляют их учение о необъяснимом.
        </li>

        <li>У тиртхиков, Махамати, запутавшихся в причинах, есть «необъяснимое», но в Моём учении его нет. В Моём учении, Махамати, различение не возникает, когда нет связи между схватываемым и схватывающим. Как же тогда можно «оставлять без ответа» то, чего в самом учении нет?
        Лишь для тех, Махамати, кто привязан к схватываемому и схватывающему и чей ум не утверждён в осознании того, что всё есть лишь воспринимаемое собственным умом, — для них Я установил «оставление без ответа» (<em>sthāpanīya</em>).</li>

        <li>Махамати, Татхагаты, Архаты, Совершенно Пробуждённые наставляют существ в Дхарме, используя четыре вида ответов на вопросы (<em>caturvidhapadapraśnavyākaraṇena</em>). «Оставление без ответа» — это, Махамати, мера, установленная на иное время (<em>kālāntaradeśanā</em>) для тех, чьи способности ещё не созрели. Для тех же, чьи способности созрели, нет ничего, что следовало бы оставлять без ответа.<a href="#citation-299" id="ref-299" class="citation-mark"><sup>299</sup></a></li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.45 (Природа дхарм)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, все дхармы не возникают, ибо в них нет ни действия, ни деятеля. Поэтому говорится: все дхармы не являются возникшими.</li>

        <li>Почему же, Махамати, все дхармы лишены собственной природы? Потому что, когда их исследует собственный ум, они не постигаются по причине отсутствия их собственных и всеобщих признаков. Поэтому говорится: все дхармы лишены собственной природы.</li>

        <li>Почему же, Махамати, все дхармы вне составления и разложения? Потому что, Махамати, когда составляются их собственные и всеобщие признаки, они не составляются; когда разлагаются — не разлагаются. По этой причине, Махамати, все дхармы вне составления и разложения.</li>

        <li>Почему все дхармы непрекращаемы? Потому что они не обнаруживаются как нечто имеющее природу бытия.</li>

        <li>Почему же, Махамати, все дхармы называются непостоянными? Потому что их признаки возникают и исчезают.</li>
        <li>И почему же, Махамати, все дхармы называются постоянными? Потому что в их непостоянстве нет ни возникновения, ни прекращения — и потому они постоянны.<a href="#citation-300" id="ref-300" class="citation-mark"><sup>300</sup></a></li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>171. Четыре способа ответа:</li>
        <li>однозначный, встречный вопрос,</li>
        <li>аналитический и оставление без ответа —</li>
        <li>последний — чтобы отсечь взгляды тиртхиков.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>172. Санкхьяики и вайшешики утверждают:</li>
        <li>«Из бытия и из небытия нечто возникает».</li>
        <li>Именно они распространяют все эти «необъяснимые» вопросы.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>173. Когда ум пытается постичь их природу,</li>
        <li>ничего устойчивого не находится.</li>
        <li>Поэтому Я учу: они невыразимы</li>
        <li>и лишены собственной природы.</li>
    </ul>
    </blockquote>

    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.46 (Вступившие в поток)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Затем бодхисаттва-махасаттва Махамати вновь воззвал к Благословенному:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Пусть Благословенный разъяснит признаки различения пути и этапов <em>Вступивших в поток</em> (<em>srotāpanna</em>)!</li>
        <li>Дабы я и другие бодхисаттвы, став искусными в понимании этапов вхождения в поток и зная методы достижения уровней <em>Однажды возвращающегося</em> (<em>sakṛdāgāmin</em>), <em>Невозвращающегося</em> (<em>anāgāmin</em>) и <em>Архата</em>, могли [верно] проповедовать Дхарму существам.</li>
        <li>Дабы мы, полностью очистившись от двоякого отсутствия «я» (<em>nairātmya-dvaya</em>) и двоякой завесы (<em>āvaraṇa-dvaya</em>), прошли через все ступени (<em>bhūmi</em>), достигли непостижимой сферы Татхагаты и стали подобны драгоценному камню Чинтамани — опорой для жизни всех существ, в телах которых вся полнота Дхармы является и прибежищем, и наслаждением.</li>
    </ul>
    </blockquote>

    <p>Благословенный сказал:</p>
    <p>— Слушай, Махамати, внимай хорошо! Я буду говорить.</p>
    <p>— Да, Благословенный, — ответил бодхисаттва-махасаттва Махамати.</p>

    <p>Благословенный сказал:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Есть три вида плодов <em>вхождения в поток</em> (<em>srotāpanna</em>): низший, средний и высший.</li>
        <li>Низший — это тот, кому суждено ещё семь рождений,</li>
        <li>средний — тот, кто достигает нирваны через три или пять рождений,</li>
        <li>высший — тот, кто достигает нирваны в текущем рождении.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>У этих троих есть три [вида] уз (<em>saṃyojana</em>), которые бывают слабыми, средними и сильными. Что это за три узы? Это: взгляд на совокупность <em>скандх</em> как на реальное «я» (<em>satkāya-dṛṣṭi</em>), сомнение (<em>vicikitsā</em>), привязанность к нравственности/дисциплине и обетам/ритуалам (<em>śīlavrata-parāmarśa</em>).</li>
        <li>Эти три узы постепенно отпадают, ведя к плоду Архата.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Взгляд на совокупность <em>скандх</em> как на реальное «я» бывает двух видов: врождённый (<em>sahajā</em>) и воображаемый (<em>parikalpitā</em>), подобно зависимой (<em>paratantra</em>) и воображаемой (<em>parikalpita</em>) природам.</li>
        <li>Подобно тому, Махамати, как на основе зависимой природы (<em>paratantra-svabhāva</em>) развёртывается привязанность к разнообразной воображаемой природе (<em>parikalpita-svabhāva</em>), которая не является ни существующей, ни несуществующей, ни тем и другим вместе, ибо она — лишь признак ложного воображения (<em>abhūta-parikalpa</em>), — так и невежды воображают [личность], привязываясь к признакам разнообразных свойств, подобно тому как олени [бегут за] миражом.</li>
        <li>Таков, Махамати, воображённый взгляд на совокупность <em>скандх</em> как на реальное «я» у <em>Вступившего в поток</em>: он накоплен из-за неведения и давней привычки к привязанности. Он устраняется благодаря постижению отсутствия «я» в личности (<em>pudgala-nairātmya</em>).</li>
        <li>Врождённый же взгляд на совокупность <em>скандх</em> как на реальное «я» у <em>Вступившего в поток</em> устраняется через видение равенства своего и чужого тела. Поскольку [тело] обладает признаками формы четырёх <em>скандх</em>, а возникновение формы обусловлено первоэлементами и производным от них, и поскольку эти элементы взаимно обуславливают друг друга, — <em>Вступивший в поток</em> понимает, что форма [как нечто самостоятельное] не возникает. Благодаря видению крайностей бытия и небытия этот врождённый взгляд на <em>скандхи</em> как на «я» у него исчезает. Именно поэтому у того, кто отринул взгляд на совокупности <em>скандх</em> как на «я», более не возникает страсть.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Далее, Махамати, каков признак сомнения (<em>vicikitsā-lakṣaṇa</em>)? Поскольку [<em>Вступивший в поток</em>] обрёл Дхарму и его постижение стало признаком верного видения, и поскольку он прежде отринул двойственное различение взгляда на реальность личности (<em>satkāyadṛṣṭi</em>), — у него более не возникает сомнения в дхармах. И у него нет иного [учения] или учителя, [основанного на разделении] на чистое и нечистое. Таков, Махамати, признак [отсутствия] сомнения у <em>Вступившего в поток</em>.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Почему же, Махамати, <em>Вступивший в поток</em> не привязывается к нравственности, обетам и ритуалам? Потому что он ясно видит их как основу возникновения страдания.</li>
        <li>Ибо привязанность — это когда невежды через обеты, ритуалы, аскезу и самоограничение жаждут чувственных удовольствий и просят о новом рождении; [<em>Вступивший же в поток</em>] так не делает. Напротив, он направляет [свои действия] к личному постижению истины (<em>svapratyātmādhigama</em>). Они привержены основам нравственности в том виде, в каком признаки дхарм являют себя в опыте, свободном от различений (<em>nirvikalpa</em>) и изъянов (<em>anāsrava</em>).</li>
        <li>Таков, Махамати, признак устранения привязанности к нравственности, обетам и ритуалам у <em>Вступившего в поток</em>. У него, отринувшего три узы, более не возникают страсть, гнев и заблуждение.</li>
    </ul>
    </blockquote>

    <p>Махамати спросил:</p>
    <p>— Благословенный, Ты учил, что существует множество видов страсти (<em>rāga</em>). Какой же именно вид страсти исчезает у <em>Вступившего в поток</em>?</p>

    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>[Отринута] чувственная страсть к объектам, страсть к соитию с женщиной — то, что приносит мимолётное удовольствие в настоящем, но становится причиной мучительного рождения в будущем. Исчезает влечение к грубым формам телесного контакта, объятиям, поцелуям, прижиманиям, вдыханию запаха, томным взглядам.</li>
        <li>У него, Махамати, такая страсть более не возникает. Почему? Потому что он обрёл пребывание в блаженстве самадхи (<em>samādhi-sukha-vihāra</em>).</li>
        <li>Именно эта чувственная страсть исчезает, но не страсть, направленная на достижение Нирваны.</li>
    </ul>
    </blockquote>

    <p class="text-center font-bold">***</p>
</div>


<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.47 (Однажды возвращающийся)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Каков же, Махамати, признак плода <em>Однажды возвращающегося</em> (<em>sakṛdāgāmin</em>)?</li>
        <li>Это тот, у кого лишь однажды ещё возникает мысленное построение о форме, её признаках и проявлениях.</li>
        <li>Поскольку он ясно видит отсутствие опорных знаков, воззрений, объектов и признаков и ясно постигает признаки состояний сосредоточения, — он лишь единожды вернётся в этот мир, чтобы положить конец страданию и уйти в окончательную нирвану.</li>
        <li>Посему он зовётся <em>Однажды возвращающимся</em>.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.48 (48. Невозвращающийся)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Как же, Махамати, [определяется] <em>Невозвращающийся</em> (<em>anāgāmin</em>)?</li>
        <li>Это тот, у кого ум более не обращается (<em>pravṛtti</em>) к существованию и не-существованию признаков формы в прошлом, будущем и настоящем;</li>
        <li>кто освободился от скрытых влечений (<em>anuśaya</em>) и изъянов воззрений (<em>dṛṣṭi-doṣa</em>);</li>
        <li>и кто оставил тело, связанное с состоянием невозвращения (<em>anāgāmi-rūpa</em>), и узы (<em>saṃyojana</em>).</li>
        <li>Потому он зовётся <em>Невозвращающимся</em>.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.49 (Архат)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li><em>Архатом</em> же, Махамати, именуется тот,</li>
        <li>в ком отсутствует всякое различение</li>
        <li>о <em>дхьянах</em>, объектах созерцания, <em>самадхи</em>, освобождениях,</li>
        <li><em>силах</em>, <em>сверхзнаниях</em>, <em>клешах</em> и страдании.</li>
        <li>Посему он зовётся <em>Архатом</em>.</li>
    </ul>
    </blockquote>
    <p>Махамати спросил:</p>
    <p>— Благословенный, Ты говорил о трёх видах <em>Архатов</em>. Кому же именно принадлежит это имя «Архат»? Тем ли, кто достиг покоя на Едином Пути [шраваков]? Или тем, кто, дав обет пробуждения и накопив корни благого, внешне пребывает в омрачении? Или же это существа, созданные как проявления Нирманакаи?</p>

    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Махамати, имя «Архат» принадлежит шраваку, обретшему покой на Едином Пути, но не остальным.</li>
        <li>Что касается других, Махамати, то они — практикующие путь Бодхисаттвы или проявления Нирманакаи. В силу своих прежних обетов и искусных средств они лишь демонстрируют рождение в различных собраниях, дабы украсить собрания учеников Будды.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Все эти поучения о плодах, ступенях, созерцании и созерцающем — лишь искусное разделение, [нужное для тех, кто ещё] находится в мире различений. На самом же деле, поскольку нет ни достижения плода, ни <em>дхьяны</em>, ни созерцающего, ни созерцаемого, и поскольку всё — лишь воспринимаемое собственным умом, Я учу о «достижении плодов».</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Более того, Махамати, если бы у <em>Вступившего в поток</em> возникла мысль: «Вот эти узы, и я от них свободен», — он бы впал в двойственность и привязанность к «я», и его узы не были бы отсечены.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Более того, Махамати, чтобы выйти за пределы четырёх <em>дхьян</em>, безмерных состояний и бесформенных сфер, следует совершить поворот (<em>vyāvṛtti</em>) от признаков, воспринимаемых собственным умом.</li>
    </ul>

    <ul class="list-none mb-12 pl-2 space-y-1 ml-2">
        <li>Даже вхождение в <em>самадхи прекращения восприятия и чувств</em> (<em>saṃjñā-vedita-nirodha</em>), Махамати, не является превосхождением течения воспринимаемого собственным умом, ибо [само это состояние] также является только лишь умом (<em>cittamātra</em>).</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>174. [Четыре] <em>дхьяны</em>, безмерные состояния, <em>самадхи мира без форм</em></li>
        <li>и полное прекращение восприятия —</li>
        <li>ничего этого не обнаруживается в [состоянии] «только лишь ума».</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>175. Плод <em>Вступившего в поток</em>, а также <em>Однажды возвращающегося</em>,</li>
        <li>плод <em>Невозвращающегося</em> и само состояние <em>Архата</em> —</li>
        <li>всё это — заблуждение ума (<em>citta-vibhrama</em>).</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>176. Созерцающий, созерцание и объект созерцания,</li>
        <li>отсечение [<em>клеш</em>] и видение истины —</li>
        <li>всё это — лишь мысленное построение (<em>kalpanā-mātra</em>).</li>
        <li>Тот, кто пробуждается к этому — освобождается.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.50 (Два вида разума)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, разум (<em>buddhi</em>) бывает двух видов:</li>
        <li>исследующий разум (<em>pravicaya-buddhi</em>) и разум, утверждающий цепляние за признаки различений (<em>vikalpa-lakṣaṇa-grāha-abhiniveśa-pratiṣṭhāpikā buddhi</em>).</li>
        <li>Махамати, исследующий разум — это тот, при котором признаки собственной природы явлений, будучи исследуемы, не обнаруживаются [как реальные сущности] и свободны от четырёх крайностей.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Под четырьмя крайностями (<em>catuṣkoṭi</em>), Махамати, Я подразумеваю применение тетралеммы к таким парам:</li>
        <li>— единство и различие: рассматриваются единство, различие, и то и другое, ни то ни другое;</li>
        <li>— бытие и небытие: есть, нет, и то и другое, ни то ни другое;</li>
        <li>— вечность и непостоянство: вечно, невечно, и то и другое, ни то ни другое.</li>
        <li>Именно через эту тетралемму следует исследовать все дхармы.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Каков же разум, утверждающий цепляние?</li>
        <li>Это тот, который через привязанность к тезисам, причинам, признакам и примерам приписывает первоэлементам (<em>mahābhūta</em>) качества тепла, влажности, движения и твёрдости как признаки нереального воображения, совершая ложное наложение несуществующего [как существующего].</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Обладая этими двумя видами разума, бодхисаттвы, постигшие двоякое отсутствие «я» в личности и дхармах и ставшие искусными в практике исследования на ступенях [пути], достигают первой ступени (<em>bhūmi</em>).</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Там они входят в сотню <em>самадхи</em> и, через обретение особого <em>самадхи</em>, созерцают сотни будд и бодхисаттв, прозревают сотни кальп прошлого и будущего и озаряют сотни миров.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Понимая признаки высших ступеней, они, играя [в освобождение] благодаря особенности своих обетов, достигают посвящения на ступени Облака Дхармы и, обретя личную ступень Татхагаты, сияют магическими лучами ради созревания существ.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.51 (Первоэлементы)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Более того, Махамати, бодхисаттве следует стать искусным в понимании первоэлементов и производных от них форм.</li>
        <li>Как он достигает этого?</li>
        <li>Бодхисаттва обучается так: он ясно видит, что первоэлементы не возникают реально. Он зрит их как лишь имена и мысленные построения.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Осознавая, что всё — лишь различение (<em>vikalpa-mātra</em>), лишь воспринимаемое собственным умом (<em>svacittadṛśya-mātra</em>), он понимает: : три мира существования — это лишь различение-проявление ума (<em>cittadṛśya-vikalpa-mātra</em>), лишённое первоэлементов и производных от них форм.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Он видит их через чистоту метода четырёх крайностей, свободными от «я» и «моего», пребывающими в своей Таковости и невозникшими по своей природе.</li>
        <li>Как же, Махамати, из первоэлементов возникают производные формы?</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Великий элемент, основанный на мысленном построении о влажности, порождает [восприятие] элемента Воды внутри и снаружи.</li>
        <li>Великий элемент, основанный на мысленном построении об энергии (жаре), порождает элемент Огня внутри и снаружи.</li>
        <li>Великий элемент, основанный на мысленном построении о движении, порождает элемент Воздуха внутри и снаружи.</li>
        <li>Великий элемент, основанный на мысленном построении об очерченности форм, порождает элемент Земли вместе с пространством внутри и снаружи.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Из-за привязанности к ложному и истинному возникает совокупность пяти <em>скандх</em>, состоящая из первоэлементов и производных от них форм.</li>
        <li>Сознание же движется к новому рождению из-за привязанности к объектам.</li>
        <li>Тиртхики полагают, что для производных форм, основанных на элементе Земли, причиной являются великие элементы; но сами великие элементы, по их же логике, не имеют причины.</li>
        <li>По какой причине? Потому что, Махамати, возникновение связи с действием возможно лишь для того, что обладает становлением, признаком, характеристикой, восприятием, формой и способностью к действию; но не для того, что лишено признаков.</li>
        <li>Поэтому, Махамати, этот признак великих элементов и производных от них форм воображается тиртхиками, но не Мною.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.52 (Скандхи)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, Я разъясню природу <em>скандх</em> (совокупностей).</li>
        <li>Существует пять <em>скандх</em>: форма, ощущение, восприятие, формирующие факторы и сознание.</li>
        <li>Четыре из них — ощущение, восприятие, формирующие факторы и сознание — лишены формы (<em>arūpiṇo</em>).</li>
        <li>Форма же (<em>rūpa</em>) состоит из четырёх первоэлементов, чьи признаки отличны друг от друга.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Однако, Махамати, эти четыре бесформенные <em>скандхи</em> не поддаются счёту, как и пространство.</li>
        <li>Подобно тому, как пространство выходит за пределы чисел и признаков, но воображается как «пространство», — так и <em>скандхи</em> выходят за пределы счёта и признаков.</li>
        <li>Они свободны от бытия и небытия, от четырёх крайностей.</li>
        <li>Их указывают посредством счёта и исчисления — так делают невежды, но не Благородные.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Благородные же, Махамати, считают <em>скандхи</em> подобными магическим, разнообразным формам, которые не являются ни тождественными, ни отличными [от ума], подобно образам во сне или отражениям.</li>
        <li>Из-за заблуждения относительно пути благородного знания и из-за недвойственности со своей основой (<em>āśraya</em>), Махамати, возникает это различение <em>скандх</em>.<a href="#citation-301" id="ref-301" class="citation-mark"><sup>301</sup></a></li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Потому, Махамати, тебе следует отбросить это различение. Отбросив его, ты должен учить о дхармах, свободных от двойственности.</li>
        <li>Проповедуя это учение во всех собраниях Будд для пресечения воззрений тиртхиков, ты очистишь видение отсутствия «я» дхарм и войдёшь на ступень Дурангама (<em>Dūraṃgamā</em> — «Далеко идущая»).</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Войдя на эту великую ступень, бодхисаттва овладевает бесчисленными <em>самадхи</em>. Обретя тело, созданное умом (<em>manomaya-kāya</em>), он достигает <em>самадхи</em>, подобного магии (<em>māyopama-samādhi</em>).</li>
        <li>Наделённый <em>силами</em>, <em>сверхзнаниями</em> и <em>властью</em>, он становится опорой для всех существ, подобно самой земле.</li>
        <li>Подобно тому, Махамати, как великая земля поддерживает всех существ, так и бодхисаттва-махасаттва становится источником жизни для всех.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.53 (Четыре вида нирваны)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, существует четыре вида нирваны [в представлениях тиртхиков]. Каковы эти четыре?</li>
        <li>— Нирвана как отсутствие собственной природы бытия;</li>
        <li>— Нирвана как отсутствие многообразия признаков бытия;</li>
        <li>— Нирвана как осознание отсутствия собственных признаков;</li>
        <li>— Нирвана как пресечение потока собственных и общих признаков <em>скандх</em>.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Эти четыре вида нирваны, Махамати, принадлежат тиртхикам (ложным учителям), но не Моему учению.</li>
        <li>В Моём же учении, Махамати, нирваной именуется прекращение <em>мановиджняны</em>, являющейся причиной различений.</li>
    </ul>
   </blockquote>

    <p>Махамати спросил:</p>
    <p>— Разве Благословенный не устанавливал [учение о] восьми сознаниях?</p>

    <p>Благословенный ответил:</p>
    <p>— Устанавливал, Махамати.</p>

    <p>Махамати спросил:</p>
    <p>— Если так, Благословенный, то почему только <em>мановиджняна</em> прекращает свою деятельность [в Нирване], а не остальные семь сознаний?</p>

    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-12 pl-2 space-y-1 ml-2">
        <li>Семь сознаний приходят в движение, имея <em>мановиджняну</em> своей причиной и опорой.</li>
        <li><em>Мановиджняна</em> же, Махамати, движется, привязываясь к различению объектов, и через отпечатки (<em>vāsanā</em>) питает <em>Алайя-виджняну</em>.</li>
        <li>Сопровождаемая <em>манасом</em>, [<em>мановиджняна</em>] движется в виде привязанности к [схватыванию] «я» и «моего».</li>
        <li>Эта совокупность сознаний (<em>citta-kalāpa</em>), имеющая признак неразделённого тела, приходит в движение взаимно-причинным образом (<em>anyonya-hetuka</em>), имея <em>Алайя-виджняну</em> своей причиной и опорой, из-за привязанности к объектам, воспринимаемым собственным умом.</li>
        <li>Подобно волнам океана, Махамати, которые возникают и исчезают, подгоняемые ветром объектов, — так и сознания движутся.</li>
        <li>Поэтому, Махамати, когда <em>мановиджняна</em> прекращает свою деятельность, прекращают свою деятельность и семь [остальных] сознаний.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>177. Я не ухожу в Нирвану через бытие, действие или признаки.</li>
        <li>Когда сознание, являющееся причиной различений,</li>
        <li>прекращается, Я угас, Я освобождён.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>178. Опираясь на <em>манас</em> и его течение,</li>
        <li>сознание становится причиной ума,</li>
        <li>оно само находит в нём опору.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>179. Подобно тому как при иссыхании великого океана</li>
        <li>становится невозможным рождение волн —</li>
        <li>так и многообразие сознаний, будучи прекращённым,</li>
        <li>более не приходит в движение.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.54 (Признаки разделения воображаемой природы)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Кроме того, Махамати, Я разъясню признаки разделения воображаемой природы (<em>parikalpita-svabhāva</em>).</li>
        <li>Постигнув их, ты и другие бодхисаттвы освободитесь от воображения и различений.</li>
        <li>Ваше понимание пути Благородных и путей тиртхиков станет ясным;</li>
        <li>вы отбросите двойственность схватываемого и схватывающего</li>
        <li>и более не будете налагать форму воображаемой природы</li>
        <li>на многообразные признаки зависимой природы.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li><strong>Каковы же, Махамати, признаки разделения воображаемой природы? Это:</strong></li>
        <li>— Воображение речи (<em>abhilāpa-vikalpa</em>);</li>
        <li>— Воображение того, что подлежит обозначению (<em>abhidheya-vikalpa</em>);</li>
        <li>— Воображение признаков (<em>lakṣaṇa-vikalpa</em>);</li>
        <li>— Воображение смысла/объекта (<em>artha-vikalpa</em>);</li>
        <li>— Воображение собственной природы (<em>svabhāva-vikalpa</em>);</li>
        <li>— Воображение причины (<em>hetu-vikalpa</em>);</li>
        <li>— Воображение воззрений (<em>dṛṣṭi-vikalpa</em>);</li>
        <li>— Воображение логики (<em>yukti-vikalpa</em>);</li>
        <li>— Воображение возникновения (<em>utpāda-vikalpa</em>);</li>
        <li>— Воображение не-возникновения (<em>anutpāda-vikalpa</em>);</li>
        <li>— Воображение связи (<em>saṃbandha-vikalpa</em>);</li>
        <li>— Воображение оков и освобождения (<em>bandhābandha-vikalpa</em>).</li>
        <li>Таковы, Махамати, признаки разделения воображаемой природы.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li><strong>Воображение речи:</strong> привязанность к сладостным звукам и пению.</li>
        <li><strong>Воображение того, что подлежит обозначению:</strong> ложное представление о том, что существует некий объект, имеющий собственную природу и постигаемый путём благородного знания, на который опирается речь.</li>
        <li><strong>Воображение признаков:</strong> наложение на этот «мираж обозначаемого» множества качеств — жара, влажности, движения или твёрдости.</li>
        <li><strong>Воображение смысла:</strong> представление о золоте, серебре и разнообразных драгоценностях как о значимых объектах.</li>
        <li><strong>Воображение собственной природы:</strong> утверждение в духе тиртхиков: «это именно так и не иначе!»</li>
        <li><strong>Воображение причины:</strong> разделение бытия и небытия/существования и не-существования через поиск логических оснований и условий возникновения.</li>
        <li><strong>Воображение воззрений:</strong> привязанность к дурным взглядам тиртхиков о «есть» и «нет», единстве и инаковости.</li>
        <li><strong>Воображение логики:</strong> споры и поучения, основанные на признаках «я» и «моего».</li>
        <li><strong>Воображение возникновения:</strong> вера в то, что бытие и небытие/существование и не-существование рождается из реальных причин.</li>
        <li><strong>Воображение не-возникновения:</strong> утверждение, что вещи не существовали прежде, но появились из условий без собственной основы.</li>
        <li><strong>Воображение связи:</strong> вера в [физическое] сцепление вещей, подобно золотой нити [в ткани].</li>
        <li><strong>Воображение оков и свободы:</strong> привязанность к самой идее связывания и причины связывания — подобно человеку, который завязывает и развязывает узлы на верёвке.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Это и есть признаки воображаемой природы, в которую погружены невежды.</li>
        <li>Подобно тому, как воображают разнообразие в магии, хотя магия не отлична от своего разнообразия и не неотлична от него.</li>
        <li>Если бы она была отлична — разнообразие не имело бы магической причины;</li>
        <li>если бы неотлична — нельзя было бы разделить магию и её проявления.</li>
        <li>Но разделение видно.</li>
        <li>Потому, Махамати, тебе и бодхисаттвам не следует привязываться к магии через категории «есть» или «нет».</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.55 (Воображаемая, зависимая и совершенная природы)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>180. Ум связан с объектом (<em>viṣaya-saṃbandha</em>);</li>
            <li>познание (<em>jñāna</em>) проявляется в рассуждении (<em>tarke</em>);</li>
            <li>мудрость (<em>prajñā</em>) же обнаруживается в особом состоянии (<em>viśeṣa</em>),</li>
            <li>лишённом ментальных образов (<em>nirābhāsa</em>).<a href="#citation-302" id="ref-302" class="citation-mark"><sup>302</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>181. Воображаемая природа (<em>parikalpita-svabhāva</em>)</li>
            <li>не существует в зависимом (<em>paratantre na vidyate</em>).</li>
            <li>Воображаемое (<em>kalpita</em>) схватывается по заблуждению (<em>bhrāntyā</em>);</li>
            <li>зависимое (<em>paratantra</em>) не есть воображаемое.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>182. Как магия (<em>māyā</em>), возникая через проявление</li>
            <li>множества частей (<em>vividhāṅgābhinirvṛttyā</em>),</li>
            <li>не устанавливается [как реальная], так и признак (<em>nimitta</em>),</li>
            <li>сколь бы пёстрым ни казался (<em>citra</em>),</li>
            <li>будучи воображаемым (<em>kalpyamāna</em>), не устанавливается.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>183. Признак — связывание, несущее в себе порочность (<em>dauṣṭhulya</em>),<a href="#citation-303" id="ref-303" class="citation-mark"><sup>303</sup></a></li>
            <li>возникающее из ума (<em>cittasaṃbhavam</em>).</li>
            <li>Те, кто не знает (<em>ajānāna</em>) воображаемого,</li>
            <li>строят различения на основе зависимого (<em>paratantraiḥ</em> <em>vikalpyate</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>184. То, что называют воображаемым бытием (<em>kalpitaṃ bhāvaṃ</em>), —</li>
            <li>именно то и есть (<em>tadeva</em>) зависимое (<em>paratantra</em>) [в своём проявлении];</li>
            <li>именно в зависимом воображаемое,</li>
            <li>являющееся в многообразии (<em>vicitrābha</em>), различается (<em>vikalpyate</em>).<a href="#citation-304" id="ref-304" class="citation-mark"><sup>304</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>185. Есть условная истина (<em>saṃvṛti</em>) и высшая истина (<em>paramārtha</em>);</li>
            <li>третьего — обусловленного (<em>hetukam</em>) — не существует.</li>
            <li>Воображаемое названо условным (<em>saṃvṛti</em>);</li>
            <li>с его пресечением открывается сфера Благородных (<em>āryagocara</em>).<a href="#citation-305" id="ref-305" class="citation-mark"><sup>305</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>186. Как йогину является один объект (<em>vastu ekaṃ</em>),</li>
            <li>предстающий многообразным (<em>citram</em>),</li>
            <li>хотя многообразия там нет (<em>na hyasti citratā</em>), —</li>
            <li>таковы признаки воображаемого (<em>kalpitalakṣaṇam</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>187. Как те, у кого тимира (<em>taimira</em>),</li>
            <li>воображают видимость формы (<em>rūpadarśanam</em>),</li>
            <li>хотя болезнь — ни форма (<em>rūpa</em>), ни не-форма (<em>arūpa</em>), —</li>
            <li>так и невежды (<em>abudhaiḥ</em>) воспринимают зависимое (<em>paratantra</em>).<a href="#citation-306" id="ref-306" class="citation-mark"><sup>306</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>188. Как золото (<em>haima</em>) бывает чистым, как вода (<em>jala</em>) свободна от мути (<em>kaluṣa</em>),</li>
            <li>как небо (<em>gagana</em>) чисто при отсутствии облаков (<em>ghanābhāvāt</em>) —</li>
            <li>так и зависимое [является] очищенным от вымысла (<em>vikalpitam</em>).<a href="#citation-307" id="ref-307" class="citation-mark"><sup>307</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>189. Воображаемого бытия (<em>kalpito bhāvaḥ</em>) нет;</li>
            <li>зависимое (<em>paratantra</em>) существует.</li>
            <li>Тот, кто мыслит через наложение (<em>samāropa</em>) и</li>
            <li>отрицание (<em>apavāda</em>), погибает (<em>vinaśyati</em>).<a href="#citation-308" id="ref-308" class="citation-mark"><sup>308</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>190. Если бы воображаемое было полным отсутствием (<em>abhāva</em>)</li>
            <li>относительно зависимого (<em>paratantrasvabhāvataḥ</em>),</li>
            <li>то бытие (<em>bhāva</em>) существовало бы без бытия,</li>
            <li>и бытие возникало бы из небытия (<em>abhāvasaṃbhava</em>).<a href="#citation-309" id="ref-309" class="citation-mark"><sup>309</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>191. Опираясь на воображаемое (<em>parikalpita</em>),</li>
            <li>воспринимается зависимое (<em>paratantra</em>).</li>
            <li>Из связи имени (<em>nāma</em>) и признака (<em>nimitta</em>)</li>
            <li>рождается воображаемое.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>192. Воображаемое абсолютно неустановлено (<em>atyantaṃ aniṣpannam</em>) и</li>
            <li>не рождается из чего-либо внешнего.</li>
            <li>Когда это постигнуто,</li>
            <li>познаётся чистая высшая природа (<em>pāramārthika-svabhāva</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>193. Воображаемое — десяти видов,</li>
            <li>зависимое — шести видов.</li>
            <li>Но в личном постижении Таковости (<em>pratyātma-tathatā</em>)</li>
            <li>нет определений (<em>viśeṣaṇa</em>).<a href="#citation-310" id="ref-310" class="citation-mark"><sup>310</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>194. Пять <em>дхарм</em> и три <em>природы</em> — вот истина.</li>
            <li>Йогин, ясно созерцающий их, не отклоняется от Таковости.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>195. Признак (<em>nimitta</em>) — это зависимое;</li>
            <li>имя (<em>nāma</em>) — воображаемое.</li>
            <li>Но признаки воображаемого</li>
            <li>возникают из зависимости (<em>pāratantryāt</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>196. То, что рассматривается разумом (<em>buddhyā vivecyamānam</em>), —</li>
            <li>ни зависимое, ни воображаемое.</li>
            <li>Совершенная природа (<em>niṣpanna</em>) не есть бытие (<em>bhāva</em>);</li>
            <li>как же разум может её вообразить?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>197. Совершенная природа существует как бытие,</li>
            <li>свободное от бытия и небытия.</li>
            <li>Если она вне бытия и небытия, то как в ней могут быть те две природы —</li>
            <li>воображаемая и зависимая?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>198. В перспективе воображаемой природы различаются две природы:</li>
            <li>воображаемое видится как многообразие (<em>citra</em>),</li>
            <li>а чистое есть сфера Благородных (<em>āryagocara</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>199. Воображаемое, являющееся в многообразии (<em>vicitrābha</em>),</li>
            <li>различается на почве зависимого.</li>
            <li>Думать иначе — значит следовать</li>
            <li>учениям тиртхиков (<em>tīrthyavāda</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>200. Воображение называется воображаемым</li>
            <li>в силу усмотрения причинного возникновения.</li>
            <li>То, что свободно от двойственности различений (<em>vikalpa-dvaya</em>),</li>
            <li>и есть совершенная природа (<em>niṣpanna</em>).</li>
        </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
</div>

<h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.56 (Единая колесница)</h4>
<div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Затем бодхисаттва-махасаттва Махамати вновь воззвал к Благословенному:</p>
    <p>— Пусть Благословенный разъяснит признаки личного постижения Благородных (<em>pratyātmāryajñāna</em>) и Единой Колесницы (<em>ekayāna</em>)! Дабы благодаря постижению этих признаков я и другие бодхисаттвы-махасаттвы стали искусными в личном постижении Благородных и Единой Колеснице и более не зависели бы от других как от руководителей в Учении Будды.</p>

    <p>Благословенный ответил:</p>
    <p>— Слушай же внимательно, Махамати, и запечатлей это в уме!</p>

    <p>— Да, Благословенный, — ответил бодхисаттва-махасаттва Махамати.</p>

    <p>Благословенный сказал:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Бодхисаттва-махасаттва, будучи свободен от [опоры на] средства достоверного познания (<em>pramāṇa</em>), авторитетные источники (<em>āpta</em>), наставления (<em>upadeśa</em>) и мысленные построения (<em>vikalpa</em>), удалившись в уединение, исследует через собственное непосредственное постижение (<em>svapratyātmabuddhi</em>). Он становится независимым от чужих наставлений, оставляет воображаемые воззрения и прилагает усилие к вхождению, ступень за ступенью, в ступени Татхагаты.</li>
        <li>Таков признак хода личного постижения Благородных.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Каков же признак хода Единой Колесницы?</li>
        <li>Я называю это Единой Колесницей в силу пробуждения к пути Единой Колесницы.</li>
        <li>Что же это за пробуждение?</li>
        <li>Это когда ум пребывает в Таковости (<em>yathābhūta</em>) и более не возникает движение различений между схватываемым (<em>grāhya</em>) и схватывающим (<em>grāhaka</em>).</li>
        <li>Это и есть пробуждение к Единой Колеснице.<a href="#citation-311" id="ref-311" class="citation-mark"><sup>311</sup></a></li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Махамати, это пробуждение к Единой Колеснице прежде не достигалось ни тиртхиками, ни шраваками, ни пратьекабуддами, ни Брахмой — никем, кроме Меня.</li>
        <li>По этой самой причине она зовётся Единой Колесницей.</li>
    </ul>
    </blockquote>

    <p>Махамати спросил:</p>
    <p>— По какой же причине Благословенный проповедует три колесницы (<em>yānatraya</em>), а не [сразу] одну лишь Единую Колесницу?</p>

    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-12 pl-2 space-y-1 ml-2">
        <li>Махамати, Я не проповедую Единую Колесницу всем шравакам и пратьекабуддам, поскольку они по своей природе не способны к паринирване самостоятельно (<em>svayamaparinirvāṇadharmatvāt</em>).</li>
        <li>Ибо, Махамати, все шраваки и пратьекабудды обретают освобождение лишь благодаря наставлению, дисциплине и практике различения-уединения (<em>viveka</em>), данным Татхагатой, а не сами по себе.</li>
        <li>Более того, Махамати, из-за того, что шраваки и пратьекабудды ещё не искоренили завесу познаваемого (<em>jñeyāvaraṇa</em>),<a href="#citation-312" id="ref-312" class="citation-mark"><sup>312</sup></a> карму (<em>karma</em>) и отпечатки (<em>vāsanā</em>), Я не проповедую им Единую Колесницу.</li>
        <li>Из-за их непонимания отсутствия «я» дхарм (<em>dharmanairātmya</em>) и из-за того, что они ещё не достигли непостижимого превращения-перехода-падения (<em>acintyapariṇāmacyuti</em>),<a href="#citation-313" id="ref-313" class="citation-mark"><sup>313</sup></a> Я учу шраваков трём колесницам.</li>
        <li>Но когда, Махамати, все их порочные отпечатки будут искоренены благодаря постижению отсутствия «я» дхарм, тогда они, в силу отсутствия опьянения самадхи (<em>samādhimada</em>),<a href="#citation-314" id="ref-314" class="citation-mark"><sup>314</sup></a> порождённого порочными отпечатками, пробудятся в сфере без изъянов (<em>anāsravadhātu</em>).</li>
        <li>Вновь наполнив [свои] накопления в этой сверхмирской сфере без изъянов, они обретут состояние следования непостижимому Телу Дхармы (<em>acintyadharmakāya</em>).<a href="#citation-315" id="ref-315" class="citation-mark"><sup>315</sup></a></li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>201. Я проповедую Колесницу богов (<em>devayāna</em>),</li>
            <li>Колесницу Брахмы (<em>brahmayāna</em>),</li>
            <li>путь шраваков (<em>śrāvakīya</em>), путь пратьекабудд (<em>pratyeka</em>) и</li>
            <li>путь Татхагат (<em>tāthāgata</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>202. Но пока движется ум (<em>citta</em>), предела колесницам нет.</li>
            <li>Когда же ум совершает поворот основы (<em>parāvṛtti</em>),</li>
            <li>нет ни колесниц, ни тех, кто на них едет.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>203. Установления колесниц вовсе не существует —</li>
            <li>Единую колесницу Я провозглашаю.</li>
            <li>Лишь ради привлечения невежд</li>
            <li>Я говорю о различии колесниц.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>204. Также существуют три вида освобождения</li>
            <li>и отсутствие «я» дхарм (<em>dharmanairātmya</em>).</li>
            <li>Однако [шраваки] лишены того освобождения,</li>
            <li>которое именуется мудростью равенства (<em>samatājñāna</em>)</li>
            <li>и свободой от клеш.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>205. Подобно тому, как бревно в океане уносится волнами,</li>
            <li>так и глупый шравака увлекается признаками (<em>lakṣaṇa</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>206. Связанные привычными тенденциями и клешами (<em>vāsanākleśa</em>),</li>
            <li>но свободные от активных проявлений [клеш],</li>
            <li>опьянённые <em>самадхи</em> (<em>samādhimada</em>),</li>
            <li>они пребывают в <em>сфере без притока</em> (<em>anāsrava-dhātu</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>207. Они не достигают окончательного предела,</li>
            <li>но и не возвращаются вновь.</li>
            <li>Достигнув <em>тела самадхи</em> (<em>samādhikāya</em>),</li>
            <li>они не пробуждаются вплоть до [конца] кальпы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>208. Подобно тому, как пьяный трезвеет,</li>
            <li>когда проходит действие хмеля,</li>
            <li>так и они обретут моё Тело,</li>
            <li>именуемое Буддадхармой  (<em>buddhadharma</em>).</li>
        </ul>
    </blockquote>

    <p class="text-center font-bold">***</p>
    <p class="text-center italic">Так завершается вторая глава «Ланкаватары», называемая «Собрание всех дхарм в тридцати шести тысячах строк».</p>
</div>






    <h4 class="text-center text-gray-800 font-bold text-xl my-4">ПРИМЕЧАНИЯ</h4>
    <hr class="my-8 border-t-4 border-gray-500">
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p></p>
        <div>
        <p class="my-2" id="citation-1"><sup>1</sup> <strong>Ващита</strong> (<em>vaśitā</em>) —
            духовная власть, обретаемая бодхисаттвой на высоких ступенях пути (<em>бхуми</em>).
            Она означает непринуждённое господство над собственным умом, дхармами, кармой и
            процессом перерождений. В отличие от обычного «самообладания», ограниченного
            эмоциональным контролем, <em>ващита</em> — это способность свободно проявляться в
            сансаре без загрязнений, действовать без усилий (<em>анабхисамскара</em>) и
            спонтанно откликаться на нужды существ. Она проистекает из прямого постижения
            недвойственной природы реальности (<em>адвая-джняна</em>) и преобразования ума (<em>āśraya-parāvṛtti</em>).
            Традиционно выделяют десять видов <em>ващиты</em>: власть над жизнью
            (<em>āyur-vaśitā</em>),
            власть над умом (<em>citta-vaśitā</em>), власть над необходимыми средствами (<em>pariṣkāra-vaśitā</em>),
            власть над дхармами (<em>dharma-vaśitā</em>), власть над чудесными силами (<em>ṛddhi-vaśitā</em>),
            власть над рождением (<em>janma-vaśitā</em>), власть над устремлением (<em>adhimukti-vaśitā</em>),
            власть над обетами (<em>praṇidhāna-vaśitā</em>), власть над кармой
            (<em>karma-vaśitā</em>), власть над мудростью (<em>jñāna-vaśitā</em>). Бодхисаттва,
            обладающий совершенной <em>ващитой</em>, может по своей воле принимать рождение в
            любом мире, сохранять память о прошлых жизнях, проявлять любые формы и применять
            любые искусные средства (<em>упая</em>) ради освобождения существ. В контексте
            <strong><em>Ланкаватара-сутры</em></strong> <em>ващита</em> тесно связана с владением
            <em>самадхи</em>
            (<em>samādhi-vaśitā</em>), постижением того, что всё есть проявление ума (<em>svacitta-dṛśya-gocara-parijñāna</em>)
            и игровой деятельностью (<em>vikrīḍita</em>) — ибо именно <em>ващита</em> делает
            возможной «игру» просветлённого бодхисаттвы в мире форм.<a href="#ref-1"
                                                                       class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-2"><sup>2</sup> <strong>Бала</strong> (<em>bala</em>) —
            духовная сила или непоколебимость, обретаемая бодхисаттвой благодаря прямому
            постижению природы ума. В отличие от обычной «силы воли», <em>бала</em> — это
            устойчивость, проистекающая из реализации <em>шуньяты</em>. Она делает бодхисаттву
            неуязвимым для заблуждений, страхов и власти кармы. Эта сила не является результатом
            эгоистического усилия — она возникает спонтанно из недвойственного знания (<em>адвая-джняна</em>)
            как его естественное качество. <em>Бала</em> позволяет бодхисаттве непрерывно
            действовать ради блага существ, не отклоняясь от пути даже в самых трудных
            обстоятельствах, подобно горе, неподверженной бурям («Как скала единая, не
            колеблется ветром» — <strong><em>Дхаммапада</em></strong>, ст. 81). В махаянской традиции
            различают пять сил (<em>pañca balāni:</em> вера, усердие, памятование, самадхи,
            мудрость) и десять сил Будды (<em>daśa tathāgata-balāni</em>): знание возможного и
            невозможного, знание созревания кармы, знание различных склонностей существ, знание
            различных элементов (<em>дхату</em>), знание высших и низших способностей, знание
            путей, ведущих везде, знание происхождения загрязнений и их очищения, знание
            воспоминаний о прошлых жизнях, знание смерти и рождения существ, знание истощения
            <em>асрав</em> (омрачений). Бодхисаттвы на высоких ступенях пути, особенно начиная с
            восьмой бхуми (<em>Ачала</em>, «Неподвижная»), обретают зачатки этих сил. На этой
            ступени они достигают <em>анивартаны</em> (невозвратности), их деяния становятся
            <em>анабхога</em> (безусильными), а знание — <em>анабхисамскара-джняна</em>
            (недеятельным). Именно здесь <em>бала</em> расцветает как <em>акампья</em> —
            абсолютная несотрясаемость. В контексте <strong><em>Ланкаватара-сутры</em></strong>
            <em>бала</em> неотделима от <em>ващиты</em> (власти), <em>абхиджни</em>
            (сверхзнаний) и <em>викриды</em> (игровой деятельности) — ибо все они являются
            гранями единого просветлённого ума, свободно играющего в мире форм ради спасения
            существ.<a href="#ref-2" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-3"><sup>3</sup> <strong>Абхиджня</strong> (<em>abhijñā</em>)
            — высшие знания или сверхспособности, возникающие как естественные функции освобождённого
            сознания. Традиционно выделяют шесть <em>абхиджня:</em> <strong>Ṛddhi</strong> —
            чудесные силы (полёт, хождение по воде, множественные эманации и т.д.), <strong>Divya-śrotra</strong>
            — божественный слух (восприятие звуков всех миров),
            <strong>Para-citta-jñāna</strong> — знание мыслей других существ, <strong>Pūrva-nivāsānusmṛti</strong>
            — память о прошлых жизнях, <strong>Divya-cakṣus</strong> — божественное око (видение
            смерти и перерождения существ в соответствии с их кармой),
            <strong>Āsrava-kṣaya-jñāna</strong>
            — знание об истощении загрязнений (<em>āsrava</em>). В отличие от магических
            навыков, приобретаемых через <em>мантры</em> или ритуалы, <em>абхиджни</em> — это
            спонтанные проявления ума, освободившегося от двойственности субъекта и объекта. В
            ранних текстах первые пять <em>абхиджня</em> доступны даже не-буддистам через
            достижение глубоких <em>дхьян</em>, но шестая <em>абхиджня</em> — знак истинного
            освобождения, недоступный тем, кто не преодолел āsrava (омрачения-загрязнения) или
            kleśa (эгоистические эмоциональные реакции). В <strong><em>Ланкаватара-сутре</em></strong>
            <em>абхиджни</em> радикально переосмыслены в духе учения <em>Читтаматры</em>
            («Только-ум»). Здесь истинная <em>абхиджня</em> — это <em>париджняна</em> (полное
            постижение) того, что весь воспринимаемый мир есть лишь проявление собственного ума
            (<em>svacitta-dṛśya-gocara</em>). Остальные способности являются частными аспектами
            этого фундаментального знания: если бодхисаттва постиг иллюзорность границ между
            умами, он естественным образом видит мысли других; если он знает, что его ум творит
            все миры, он может проявлять чудесные силы без усилий. Таким образом,
            <em>абхиджни</em> не являются целью практики, а служат искусными средствами
            (<em>упая</em>)
            для освобождения существ. У <em>махасаттв</em> они неотделимы от <em>балы</em>
            (непоколебимой силы), <em>ващиты</em> (духовной власти) и <em>викриды</em> (игровых
            проявлений), поскольку все эти качества проистекают из единой основы —
            недвойственного знания (<em>адвая-джняна</em>). Привязанность к <em>абхиджням</em>
            или гордость ими считается серьёзным препятствием на пути. Истинный бодхисаттва
            использует их исключительно ради блага существ, оставаясь внутренне свободным от
            всех проявлений. В <strong><em>Вималакирти-нирдеша-сутре</em></strong> есть замечательный
            эпизод, где Вималакирти критикует монахов, гордящихся своими <em>абхиджнями</em>,
            показывая, что истинная способность — это постижение <em>шуньяты</em>, а не
            магические силы. В <strong><em>Алмазной сутре</em></strong> также сказано: «Те, кто видит
            Меня в форме, Те, кто следует за Моим голосом, Идут ложным путём — Они не узрят
            Татхагату». Это напоминание, что <em>абхиджни</em> относятся к миру форм
            (<em>рупа-дхату</em>)
            и не являются конечной реализацией.<a href="#ref-3"
                                                  class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-4"><sup>4</sup> <strong>Викрида</strong>
            (<em>vikrīḍita</em>, тиб. <em>rol pa</em>) — «свободная игра» или «игровая
            деятельность» просветлённого ума. Термин происходит от санскритского корня
            √<strong>krīḍ</strong>
            («играть») с усилительной приставкой <strong>vi-</strong>, означающей «разворачивать
            игру во всём её многообразии». Это спонтанная, непринуждённая активность бодхисаттвы
            или Будды, совершаемая: <strong>без усилия</strong> (<em>anabhisaṃskāra</em>) — без
            волевого напряжения и искусственности, <strong>без привязанности к
                результату</strong>, <strong>без разделения на субъект и объект
                действия</strong>, <strong>без накопления кармических следов</strong>. В отличие
            от обычной деятельности, порождённой желанием, страхом или долгом, <em>викрида</em>
            подобна игре ребёнка: она полна энергии и жизни, но свободна от цели и расчёта.
            Однако это не легкомыслие, а высшая форма активности — деятельность, полностью
            освобождённая от эго-центричности. В <strong><em>Ланкаватара-сутре</em></strong>
            <em>викрида</em> — естественное выражение постижения <em>читтаматры</em>
            («только-ум»): бодхисаттва знает, что весь мир есть проявление ума, и потому в его
            действиях нет ни напряжения, ни следа. Он «играет» в сансаре, как актёр на сцене,
            зная иллюзорность декораций, но при этом искренне служа освобождению существ. <em>Викрида</em>
            неотделима от: <em>балы</em> (непоколебимой силы), <em>ващиты</em> (духовной
            власти), <em>абхиджни</em> (сверхзнаний). Все они — грани единой свободы,
            проявляющейся в мире форм <strong>исключительно ради блага существ</strong>.
            Истинная <em>викрида</em> возможна только при полном постижении <em>шуньяты</em> и
            недвойственности (<em>адвая</em>). Без этой реализации попытка «играть» превращается
            в обычную кармическую деятельность или, хуже того, в духовную гордыню. Как говорится
            в <strong><em>Ваджраччхедика-сутре</em></strong>: «Воистину, Субхути, нельзя называть
            бодхисаттвой того, кто держится понятия <em>атман, саттва, джива</em> или
            <em>пудгала</em>».
            Только <strong>когда нет играющего</strong>, игра становится совершенной. В <strong>индуизме</strong>:
            <em>лила</em> (<em>līlā</em>) — божественная игра Брахмана в творении мира;
            предполагается реальный играющий (Атман). В <strong>буддизме</strong>:
            <em>викрида</em> — игра без играющего (<em>найратмья</em>). В <strong>дзэн</strong>:
            <em>мусин</em> (<em>mushin</em>) — «не-ум», спонтанное действие. В <strong>тибетском
                буддизме</strong>: <em>ролпа</em> (<em>rol pa</em>) — игровое проявление
            <em>ригпа</em>
            (изначального осознавания). В <strong>тантре</strong>: <em>викрида</em> проявляется
            как игровая деятельность божеств мандалы. Из <strong><em>Аватамсака-сутры</em></strong>:
            «Подобно луне, отражающейся в тысяче озёр, — Бодхисаттва проявляется в мириадах
            форм. Но сама луна остаётся в небе, не тронутая водой». Это и есть <em>викрида</em>:
            <strong>полная вовлечённость без привязанности, деятельность без деятеля</strong>.<a
                href="#ref-4" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-5"><sup>5</sup> <strong>Абхишека</strong>
            (<em>abhiṣeka</em>) — буквально «орошение» или «освящение» (от корня
            √<strong>sic</strong> — «лить» с приставкой <strong>abhi-</strong> — «направленное
            действие»). В индийской традиции абхишека изначально — ритуал коронации царя
            (раджасуя), при котором его омывали священной водой из четырёх сосудов,
            символизирующих четыре стороны света. Этот обряд, упоминаемый уже в Ригведе, означал
            передачу кшатра-шакти — власти правителя. В <strong><em>Ланкаватара-сутре</em></strong>
            абхишека радикально переосмыслена: это не внешний ритуал, а внутреннее признание
            зрелости бодхисаттвы, достигшего глубокого постижения того, что весь мир есть
            проявление ума (<em>cittamātra</em>). Выражение «посвящённые руками всех Будд» (<em>sarvabuddha-pāṇi-abhiṣekābhiṣikta</em>
            — букв. «те, кто посвящён посвящением от рук [благословения] всех Будд») означает,
            что вся совокупность просветлённой мудрости подтверждает реализацию бодхисаттвы.
            «Рука Будды» здесь — метафора сострадания (<em>karuṇā</em>) и благословляющей силы (<em>adhiṣṭhāna</em>),
            через которую происходит прямая передача ума к уму. <em>Абхишека</em>
            на десятой <em>бхуми</em> (<em>Дхармамегха</em> — «Облако Дхармы») предшествует <em>āśraya-parāvṛtti</em>
            (повороту основы сознания) — полной трансформации алайя-виджняны в
            <em>ādarśa-jñāna</em> (Зерцалоподобную мудрость), которая завершится при достижении
            буддовости. Как сказано в традиции, опирающейся на
            <strong><em>Дашабхумика-сутру</em></strong>: в этот миг Будды из десяти направлений касаются
            головы бодхисаттвы, подобно тому, как царя помазывают при коронации, и возникает
            великое сияние (<em>mahā-prabhāsa</em>), знаменующее его невозвратность
            (<em>anivartanā</em>)
            и готовность стать Буддой. «Подобно тому, как царевич, достигший совершеннолетия,
            помазывается водой четырёх океанов и становится чакравартином, так и бодхисаттва,
            достигший совершенства в мудрости и сострадании, касается головой лотосовых стоп
            всех Будд и получает великую абхишеку. С этого момента он уже не обычное существо
            (<em>pṛthagjana</em>), но и ещё не полностью Будда — он <em>вирья-ратна</em>
            (драгоценность усилия), готовая засиять». В сутрическом контексте (включая
            <strong><em>Ланкаватару</em></strong>)
            <em>абхишека</em> — следствие реализации; бодхисаттва «посвящён», потому что его ум
            уже неотличим от ума всех Будд. Это описательный термин, а не предписание. В
            тантрическом контексте <em>абхишека</em> — причина или катализатор реализации,
            формальный ритуал, необходимый для практики. Указывают четыре типа <em>абхишеки</em>
            в тантре: <em>калаша</em> (сосуд), <em>гухья</em> (тайная), <em>праджня-джняна</em>
            (мудрость-знание), <em>чатуртха</em> (четвёртая). Важно не смешивать эти два уровня:
            в <strong><em>Ланкаватаре</em></strong> абхишека остаётся прямым выражением внутренней
            свободы, а не предварительным условием практики. В контексте
            <strong><em>Ланкаватары</em></strong> <em>абхишека</em> знаменует глубокое очищение
            <em>алайя-виджняны</em>
            от <em>васан</em> (кармических отпечатков). Если ритуальная вода очищает тело, то
            лучи мудрости (<em>raśmi</em>) Будд ослабляют тончайшие препятствия к всеведению
            (<em>jñeyāvaraṇa</em>). Здесь абхишека — это граница: бодхисаттва достигает высшей
            ступени пути и становится <em>ювараджей</em> (наследным принцем Дхармы), чья
            деятельность во благо существ становится тождественной деятельности самих Будд.<a
                href="#ref-5" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-6"><sup>6</sup> <strong>Париджняна</strong>
            (<em>parijñāna</em>, тиб. <em>yongs su shes pa</em>) — исчерпывающее,
            непосредственное постижение, в котором объект раскрывается со всех сторон, полностью
            и без остатка. Термин образован от корня √<strong>jñā</strong> («знать») с
            приставкой <strong>pari-</strong>, означающей «вокруг» (всестороннее охватывание),
            «полностью» (завершённость) и «за пределы» (превосхождение обычного знания). <em>Париджняна</em>
            — не интеллектуальное знание (<em>jñāna</em>), не результат обучения
            (<em>śruta-jñāna</em>)
            или логического размышления (<em>cintā-jñāna</em>). Она является вершиной
            взращённого созерцательного опыта (<em>bhāvanā-jñāna</em>) и плодом прямого постижения. Это
            не мимолётное озарение, не экстатическое переживание единства и не трансовое
            состояние, в котором может отсутствовать мудрость. Это необратимое изменение способа
            познания. В контексте <strong><em>Ланкаватара-сутры</em></strong> центральным является
            <em>париджняна</em>
            <em>svacitta-dṛśya-gocara</em> — полное и прямое постижение того, что весь
            воспринимаемый мир есть сфера проявления ума (<em>читтаматра</em>), ум
            окончательно перестаёт принимать внешний мир как независимый объект,
            субъектно-объектная двойственность растворяется. В момент <em>париджняны</em>
            познание и освобождение неразделимы: постижение шуньяты освобождает от
            привязанностей, поскольку объект теряет свою «внешнюю» власть над воспринимающим.
            <em>Париджняна</em> предшествует окончательному <em>повороту основы</em> (<em>āśraya-parāvṛtti</em>),
            способствует устранению <em>познавательных препятствий к всеведению
                (jñeyāvaraṇa)</em> и является внутренним фундаментом для духовного посвящения
            (<em>абхишеки</em>). Без <em>париджняны</em> даже глубокие состояния сосредоточения
            остаются ограниченными двойственным восприятием. С <em>париджняной</em> само бытие
            постигается как Татхата (Таковость) в её недвойственной природе, а любая
            деятельность бодхисаттвы превращается в <em>викриду</em> (свободную игру) и
            <em>упаю</em> (искусное средство) для блага существ.<a href="#ref-6"
                                                                   class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-7"><sup>7</sup> <strong>Svacitta-dṛśya-gocara</strong>
            (санскр. <em>sva-citta-dṛśya-gocara</em>, тиб. <em>rang sems kyi snang yul</em>) —
            «сфера видимого собственным умом», или, образно, «пастбище восприятий собственного
            ума». Слово <em>gocara</em> буквально означает «место, где пасутся коровы»
            (<em>go</em> — корова, <em>cara</em> — движение). В классической индийской
            эпистемологии оно обозначает сферу действия чувств: зрение «пасётся» в мире форм,
            слух — в мире звуков. В <strong><em>Ланкаватара-сутре</em></strong> этот образ получает
            глубокое переосмысление: ум сам создаёт своё пастбище. Обыденное сознание «пасётся»
            в мире, который является проекцией его собственных кармических отпечатков
            (<em>васан</em>). Здесь <em>citta</em> — не индивидуальное «я» или «сердце», а
            фундаментальный поток сознания (<em>алайя-виджняна</em>), проецирующий всё
            воспринимаемое как <em>ābhāsa</em> — «кажимость» или «отражение» (подобно луне в
            воде). То, что принимается за «внешний мир», на деле является динамикой самого ума,
            разворачивающейся в его собственной сфере (<em>gocara</em>). Учение не утверждает
            реальность «я», творящего мир. Напротив, оно постулирует, что и воспринимающий
            субъект (<em>грахака</em>), и воспринимаемый объект (<em>грахья</em>) равно лишены
            самосущности (<em>шунья</em>). Это безличный процесс возникновения иллюзии
            разделения. Мир, воспринимаемый как нечто внешнее и отдельное, — это
            <em>парикальпита</em>
            (воображаемое). Сам поток <em>svacitta-dṛśya-gocara</em>, процесс взаимозависимого
            возникновения явлений в уме, — это <em>паратантра</em> (зависимое). Постижение этого
            потока, свободного от наслоений двойственности «я и другие», — это
            <em>паринишпанна</em> (совершенное), или <em>Татхата</em> (Таковость). Постижение
            «сферы собственного ума» достигается через вопрос: «Где находится объект — внутри
            или снаружи?» Невозможность определить местоположение объекта (он не может быть ни
            внутри, ни снаружи) приводит к прямому переживанию: разделения не существует. В этот
            момент исчезает мнимая пропасть между познающим и познаваемым. Реализация <em>svacitta-dṛśya-gocara</em>
            устраняет цепляние за личность (<em>атма-граха</em>) и за независимость вещей (<em>дхарма-граха</em>).
            Бодхисаттва, постигший это, обретает недвойственную свободу (<em>адвая-гати</em>).
            Он действует в мире как актёр на сцене: будучи полностью вовлечённым, он остаётся
            свободным, так как знает — и сцена, и действие, и зрители суть безличный процесс
            проявления ума, игра без играющего.<a href="#ref-7"
                                                  class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-8"><sup>8</sup> <strong>Рупа</strong> (<em>rūpa</em>, тиб.
            <em>gzugs</em>) — в данном контексте это не «материальная форма» (одна из пяти <em>скандх</em>),
            а гибкий способ проявления бодхисаттвы, соответствующий кармическому восприятию и
            характеру существ. Для обычного существа <em>рупа</em> — кармическая тюрьма: оно
            цепляется за тело как за «своё», страшится его утраты и страдает от иллюзии
            плотности. Но для бодхисаттвы, постигшего <em>svacitta-dṛśya-gocara</em>,
            <em>рупа</em> становится инструментом освобождения — <em>майя-рупа</em> («телом,
            подобным иллюзии»): <em>шуньевым</em> по природе, но действенным. Это не намеренное
            преображение. Ум бодхисаттвы, свободный от двойственности, естественно откликается
            на нужды существ, и форма возникает сама — как звук небесных барабанов (<em>divya-dundubhi</em>)
            или свет драгоценности, исполняющей желания (<em>cintāmaṇi</em>). Такое проявление —
            <em>анабхисамскара</em>: безусильное, непринуждённое, лишённое эгоцентрического
            намерения. Благодаря знанию чужих умов (<em>para-citta-jñāna</em>) и пониманию
            различных склонностей существ (<em>nānā-sattva-citta-carita</em>), бодхисаттва
            принимает форму не как маску, а как часть триады искусных средств (<em>upāya</em>):
            <em>рупа</em> — подходящее тело, <em>найя</em> — подходящий метод наставления, <em>винайя</em>
            — способ усмирения клеш. В системе трёх Тел Будды (<em>tri-kāya</em>) такие
            проявления предвосхищают Нирманакаю — Тело Проявлений. Ключевое различие в отношении
            к форме выражается через уровни реализации: Обычное существо заперто в форме;
            Бодхисаттва играет с формой (викрида); Будда являет все формы — но ни одна не
            является его сутью. Постигнув, что и «он», и «другое существо» — проявления ума,
            свободного от разделения, бодхисаттва свободно проявляется во всех мирах, оставаясь
            внутренне недвижимым. Он подобен луне, которая отражается в тысячах водоёмов, но,
            оставаясь в небе, не затронута движением воды.<a href="#ref-8"
                                                             class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-9"><sup>9</sup> <strong>Найя</strong> (<em>naya</em>, тиб.
            <em>tshul</em>), происходящая от санскритского корня √<strong>nī</strong> («вести»),
            — персонализированный метод наставления или искусный подход, подбираемый
            бодхисаттвой в строгом соответствии со склонностями, способностями и кармическим
            состоянием конкретного существа. В отличие от догматического подхода, <em>найя</em>
            является живым процессом ведения к истине, где форма учения диктуется состоянием
            слушателя. Для одного бодхисаттва может использовать прямое указание на
            <em>шуньяту</em> — резкое и беспощадное, как удар меча, отсекающий корень
            привязанности; для другого он выберет иносказание или притчу, мягко раскрывающую
            сердце через сострадание. В иных случаях высшей <em>найей</em> становится
            благородное молчание, подобное ответу Вималакирти на вопрос о недвойственности,
            когда само отсутствие слов указывает на реальность, лежащую за пределами понятий.
            Такая гибкость становится возможной только на фундаменте <em>париджняны
                svacitta-dṛśya-gocara</em>, благодаря которой бодхисаттва непосредственно видит
            структуру чужого ума. Через <em>para-citta-jñāna</em> (знание мыслей других) он
            понимает, как ум другого существа строит свой мир, какие именно <em>васаны</em> и
            <em>клеши</em> формируют его иллюзию, и, исходя из этого видения, подбирает тот
            особый путь, который способен разрушить это конкретное заблуждение. В этом ключе
            сама доктрина трёх колесниц, описанная в <strong><em>Лотосовой сутре</em></strong>, объявляется не
            конечной
            истиной, а <em>найей</em> — временным средством, приспособленным к разной глубине
            понимания существ, подобно тому как отец в притче о горящем доме обещает детям
            разные повозки, чтобы спасти их от огня и в итоге привести к единому высшему
            Пробуждению. В неразрывной триаде <em>рупа—найя—винайя</em> именно <em>найя</em>
            занимает центральное положение, выступая мостом между проявленной формой и целью — освобождением от <em>клеш</em>. Если <em>рупа</em> (подходящий облик) устанавливает
            канал доверия, то <em>найя</em> передаёт смысл Дхармы в доступных категориях, а <em>винайя</em>
            закрепляет этот процесс, устраняя аффекты и приводя ум к покою. Вместе эти аспекты
            воплощают <em>упая-каушалью</em> (искусность в средствах), лишённую эгоцентрических
            намерений и проистекающую из глубокого постижения недвойственной природы ума.
            Действуя как искусный врач, бодхисаттва не применяет одно лекарство ко всем
            болезням, но определяет состояние каждого существа и назначает именно ту
            <em>найю</em>, которая принесёт исцеление в данное время и при данных
            обстоятельствах.<a href="#ref-9" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-10"><sup>10</sup> <strong>Винайя</strong> (<em>vinaya</em>),
            происходящая от санскритского корня √<strong>nī</strong> («вести») с приставкой
            <strong>vi-</strong> («прочь», «врозь»), буквально означает «ведение прочь от
            заблуждений», «усмирение» или «направление в правильное русло». В контексте глубоких
            реализаций бодхисаттвы этот термин радикально отличается от формального монашеского
            устава (<em>Vinaya-piṭaka</em>); здесь он обозначает живое, обращённое к конкретному
            существу воспитательное действие, направленное на устранение его клеш. Если
            <em>рупа</em> устанавливает доверительную связь через подходящий облик, а
            <em>найя</em> раскрывает смысл учения в доступной форме, то <em>винайя</em>
            закрепляет результат, непосредственно воздействуя на омрачения, которые блокируют
            путь к освобождению. Такое воспитательное действие может принимать самые разные
            формы: от строгого слова, сокрушающего самодовольство, до мягкого упрёка или
            временного отстранения от практики, если она выполняется из эгоистических
            побуждений. <em>Винайя</em> не является актом наказания, исходящим из гнева или
            осуждения; это лекарство сострадания, которое порой может выглядеть как суровая
            мера, но в действительности служит единственной цели — пробуждению ясности ума.
            Бодхисаттва применяет <em>винайю</em> искусно, поскольку его действия опираются на
            постижение <em>svacitta-dṛśya-gocara</em>: он видит тончайшие кармические наслоения
            (<em>васаны</em>), питающие эго другого существа, и точно знает, какая именно мера
            не вызовет бесполезного сопротивления, но разрушит сам корень заблуждения. В триаде
            <em>рупа—найя—винайя</em> именно <em>винайя</em> выступает завершающим актом
            преобразования сознания, превращая понимание в устойчивое состояние покоя. Она
            воплощает принцип, согласно которому истинное милосердие иногда требует жёсткости, а
            истинное наставление — решительного пресечения ложных путей. Таким образом,
            <em>винайя</em>
            становится проявлением искусности в средствах, где бодхисаттва действует не по букве
            правила, а исходя из глубокого видения того, что именно в данный миг необходимо
            существу для исцеления его ума.<a href="#ref-10"
                                              class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-11"><sup>11</sup> <strong>Пять дхарм</strong> (<em>pañcadharma</em>) — одна из центральных классификационных схем <strong><em>Ланкаватары</em></strong>: Имя (<em>nāma</em>), Признак (<em>nimitta</em>), Различение (<em>vikalpa</em>), Правильное знание (<em>samyagjñāna</em>) и Таковость (<em>tathatā</em>).<br>
Первые три относятся к сфере обусловленного различения. Признак — непосредственно воспринимаемый облик вещи. Имя — слово, накладываемое на признак. Различение — умственное построение, соединяющее имена и признаки в «явления» и «я». Эти три соответствуют воображаемой (<em>parikalpita</em>) и зависимой (<em>paratantra</em>) природам.<br>
Правильное знание и Таковость указывают за пределы этой схемы. Правильное знание видит имена и признаки без наложения различений. Таковость — сама природа реальности, открывающаяся в этом видении. Они соответствуют совершенной природе (<em>pariniṣpanna</em>). Подробное разъяснение этих пяти дхарм даётся в подглаве 6.2.<a href="#ref-11" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-12"><sup>12</sup> <strong>Три свабхавы</strong> (<em>tri-svabhāva</em>)
            — три уровня, на которых ум воспринимает реальность. <em>Парикальпита</em> (<em>parikalpita</em>)
            — воображаемая природа. Ум принимает свои проекции за независимую реальность: «я» и
            «мир» кажутся отдельными, самосущими. Это — корень всех заблуждений.
            <em>Паратантра</em> (<em>paratantra</em>) — зависимая природа. Ум видит, что всё
            возникает взаимозависимо: мысли, образы, чувства — всё это поток причин и условий.
            Но пока ещё не свободен от привычки делить опыт на «внутреннее» и «внешнее». <em>Паринишпанна</em>
            (<em>pariniṣpanna</em>) — совершенная природа. Прямое постижение того, что <em>паратантра</em>
            изначально чиста: нет ни «я», ни «мира», только недвойственная таковость
            (<em>татхата</em>).
            Это — реализация <em>шуньяты</em> без отрицания явления. Эти три природы — не три
            разных вещи, а три способа видеть одно и то же. <em>Паринишпанна</em> — это та же
            <em>паратантра</em>, но очищенная от <em>парикальпиты</em>. Обычное существо видит
            <em>парикальпиту</em>, йогин — <em>паратантру</em>, просветлённый —
            <em>паринишпанну</em>. Бодхисаттва использует это различие, чтобы точно направлять
            других.<a href="#ref-12" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-13"><sup>13</sup> <strong>Восемь виджнян</strong> (<em>aṣṭau
                vijñānāni</em>) — восемь видов сознания, описываемых в учении <em>йогачары</em>
            и центральных для <strong><em>Ланкаватара-сутры</em></strong>. 1–5. Пять чувственных
            сознаний: зрительное, слуховое, обонятельное, вкусовое, осязательное. 6. Ментальное
            сознание (<em>мано-виджняна</em>) — различает объекты, строит мысли, работает с
            памятью и логикой. 7. <em>Манас</em> (<em>kliṣṭa-manas</em>) — омрачённое
            эго-сознание. Оно постоянно цепляется за алайю, принимая её за «я», и порождает
            четыре коренных клеши: самомнение (<em>ātma-māna</em>), ложное воззрение о «я» (<em>ātma-dṛṣṭi</em>),
            привязанность к себе (<em>ātma-sneha</em>) и неведение о себе (<em>ātma-avidyā</em>).
            8. <em>Алайя-виджняна</em> (<em>ālaya-vijñāna</em>) — сознание-хранилище. В нём
            хранятся все кармические отпечатки (<em>bīja</em>, «семена»), которые созревают как
            <em>васаны</em> (привычные склонности) и проявляются в виде опыта. Это — основа всех
            остальных сознаний: они возникают из <em>алайи</em> и питают её новыми отпечатками.
            Обычный человек не замечает ничего, кроме первых шести. Бодхисаттва, углубляясь в
            медитацию, распознаёт тонкую работу <em>манаса</em> (седьмого) и <em>алайи</em>
            (восьмого). При <em>āśraya-parāvṛtti</em> (повороте основы) <em>алайя-виджняна</em>
            преображается в <em>ādarśa-jñāna</em> (Зерцалоподобную Мудрость), а манас — в <em>samatā-jñāna</em>
            (Мудрость Равностности). Остальные шесть сознаний также преображаются в
            соответствующие Мудрости. Восемь виджнян преображаются в пять Мудростей
            (<em>pañca-jñāna</em>):
            Зерцалоподобную, Равностности, Различающую, Совершающую деяния и Дхармадхату — свободные
            от кармических наслоений. Именно постижение восьми виджнян позволяет бодхисаттве
            видеть механизм возникновения иллюзии «я» и конструирования мира умом. Это —
            практическая основа для <em>āśraya-parāvṛtti</em> и освобождения.<a href="#ref-13"
                                                                                class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-14"><sup>14</sup> <strong>Пудгала-найратмья</strong> (<em>pudgala-nairātmya</em>)
            — отсутствие «я» в личности. Обычное сознание принимает поток пяти <em>скандх</em> —
            <em>рупа</em> (форма), <em>ведана</em> (чувства), <em>санджня</em> (различение),
            <em>самскара</em> (ментальные формирующие факторы) и <em>виджняна</em> (сознание) —
            за постоянное «я», обладающее опытом. Учение о <em>пудгала-найратмье</em>
            показывает, что такого независимого, неизменного «я» нет. Личность — лишь временный
            набор условий, лишённый собственной сущности. Это первая ступень освобождения:
            устранение цепляния за «я». В <strong><em>Ланкаватара-сутре</em></strong> она неразрывна со
            второй — <em>дхарма-найратмьей</em>, ибо пока есть вера в «я», будет и вера в «вещи»
            как нечто реальное.<a href="#ref-14" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-15"><sup>15</sup> <strong>Дхарма-найратмья</strong> (<em>dharma-nairātmya</em>)
            — отсутствие самости в явлениях. Если <em>пудгала-найратмья</em> отрицает «я», то
            <em>дхарма-найратмья</em> отрицает независимую реальность самих составляющих опыта —
            форм, звуков, мыслей, чувств и даже элементов пути. Ни одно явление (<em>дхарма</em>)
            не обладает независимой, устойчивой природой. Все они возникают зависимо, длятся
            мгновение и исчезают. Это более тонкое постижение, чем отсутствие личности. Оно
            разрушает последнее убежище эго — веру в то, что хотя «я» и нет, зато «мир» реален.
            В <strong><em>Ланкаватара-сутре</em></strong> полная реализация возможна только тогда, когда
            ум видит: ни «я», ни «вещи» не имеют собственной сущности — оба шунья.<a
                href="#ref-15" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-16"><sup>16</sup> <strong>Адвая-гати</strong>
            (<em>advaya-gati</em>)
            — недвойственная стезя, путь, свободный от противопоставлений. Здесь нет разделения
            на «я» и «мир», «сансару» и «нирвану», «чистое» и «нечистое», «субъект» и «объект»,
            «бытие» и «небытие». Такой путь не ведёт от чего-то к чему-то — он есть прямое
            пребывание в природе ума, как она есть. <em>Адвая-гати</em> — не теория и не
            состояние, а способ бытия, в котором вся деятельность бодхисаттвы — будь то учение,
            молчание или чудо — происходит без следа двойственности. Это завершение пути,
            описанного <em>через пять дхарм, три свабхавы, восемь виджнян</em> и <em>два вида
                отсутствия «я»</em>.<a href="#ref-16"
                                       class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-17"><sup>17</sup> Дворец Царя Нагов символизирует
            Алайя-виджняну — глубину сознания, где Дхарма пребывает в недоступной тишине. Семь
            дней — символ завершённого постижения, пребывания в недвойственном самадхи. Выход из
            него — спонтанное проявление сострадания: Дхармакая, оставаясь неизменной, являет
            Нирманакаю ради блага живых существ.<a href="#ref-17"
                                                   class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-18"><sup>18</sup> Встреча Будды с Индрой, Брахмой и
            дочерьми царей нагов в <strong><em>Ланкаватаре</em></strong> — это не просто сцена внешнего
            почитания, а символическое указание на внутренние уровни сознания. Индра
            олицетворяет чувственный мир (<em>kāma-dhātu</em>), Брахма — мир форм
            (<em>rūpa-dhātu</em>),
            а дочери <em>нагов</em> — глубинные слои «океана ума» (<em>citta-samudra</em>), где
            пребывают кармические семена (<em>bīja</em>) и <em>васаны</em>. Ни одно из этих
            существ не является источником Дхармы. Их присутствие лишь указывает на то, что
            учение Будды охватывает все уровни сознания — от грубых до тончайших. Однако сама
            Дхарма не принадлежит ни чувственному, ни рассудочному, ни даже глубинному
            подсознательному уровню. Когда Будда покидает дворец Царя Нагов, истина переходит из
            невыразимой тишины недвойственности в сферу выражаемого. Боги и наги здесь лишь
            подтверждают, что путь к освобождению теперь доступен для восприятия на всех уровнях
            бытия. Суть этой встречи в том, что пробуждение превосходит любые состояния сознания
            — будь то чувственные наслаждения Индры или тончайшие блаженства Брахмы. Источник
            Дхармы лежит за пределами этой структуры, в «несотворённом» (<em>asaṃskṛta</em>),
            которое Будда выносит из глубины океана для блага всех существ.<a href="#ref-18"
                                                                              class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-19"><sup>19</sup> Улыбка Будды (<em>smita</em>) — знак
            узнавания и преемственности. Взглянув на гору Малайя, Будда видит, что это место,
            где Дхарма всегда провозглашалась. Его улыбка — подтверждение, что он вступает в ту
            же стезю, что и все Татхагаты прошлого.<a href="#ref-19"
                                                      class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-20"><sup>20</sup> «<strong>Благородная мудрость</strong>» (<em>svapratyātmārya-jñāna</em>)
            — знание, постигаемое непосредственно в личном опыте, без опоры на слова, логику или
            авторитет. Оно возникает только в результате глубокого преобразования ума и
            недоступно тому, кто полагается на представления/идеи. <em>svapratyātma</em>
            подразумевает «своё собственное» знание, не заимствованное, не выведенное, а
            раскрытое изнутри.<a href="#ref-20" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-21"><sup>21</sup> <strong>Тарка</strong> (<em>tarka</em>) —
            логическое рассуждение, основанное на двойственности «субъект–объект». В <strong>Ланкаватара-сутре</strong>
            оно считается препятствием, поскольку не может привести к недвойственному
            постижению.<a href="#ref-21" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-22"><sup>22</sup> «<strong>Проявили […] Дхарму</strong>»
            (<em>tadbhāvito dharmo</em>) — глагол <em>deśitaḥ</em> («излагалась») определяется
            причастием <em>tadbhāvitaḥ</em> — «сделанная таковой», «доведённая до подлинного
            бытия». Это означает: Дхарма не просто рассказывалась, а возникла из самой природы
            просветления Татхагат и была проявлена как живое событие. В
            <strong><em>Ланкаватара-сутре</em></strong>
            учение всегда есть выражение реализации, а не передача информации.<a href="#ref-22"
                                                                                 class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-23"><sup>23</sup> В <strong><em>Ланкаватаре</em></strong> фигуры
            Раваны и города Ланки имеют символический характер. Равана, царь ракшасов,
            представляет ум огромной силы и проницательности, способный как к глубокому
            заблуждению, так и к пониманию. Ланка на вершине горы Малайя — образ
            труднодоступного внутреннего пространства, «крепости сознания», где возможно
            преобразование. Происхождение Раваны в индийской традиции подчёркивает эту
            двойственность. Его отец, мудрец Вишрава, был сыном Пуластьи и внуком Брахмы, что
            помещает Равану в линию «рожденных из ума» божественных прародителей и объясняет его
            выдающийся интеллект и знание Вед. Его мать, Кайкеши, происходила из рода ракшасов и
            стремилась родить наследника, способного вернуть им былую силу и власть. Из этого
            союза возникает фигура, сочетающая мудрость брахмана с мощью ракшаса. История
            возвышения Раваны далее усиливает этот образ. Он не унаследовал власть:
            первоначально Ланкой правил его брат Кубера. Добившись силы благодаря суровым
            аскезам перед Брахмой и получив обещание неуязвимости от богов и асуров, Равана
            сверг Куберу и овладел Ланкой и всем его богатством. Его эпитет «Десятиглавый» (<em>Daśagriva</em>)
            символически указывает на знание четырёх Вед и шести шастр, а также на способность
            управлять всеми направлениями опыта. В шиваитской традиции он известен как великий
            бхакта Шивы и автор почитаемого гимна <strong><em>Шива-тандава-стотра</em></strong>.
            Использование Раваны как центрального собеседника в буддийской сутре — не
            случайность. Эта фигура воплощает вершину мирского могущества, магической силы и
            интеллектуальной эрудиции. То, что именно Равана приглашает Будду и склоняется перед
            ним, подчёркивает ключевой мотив <strong><em>Ланкаватара-сутры</em></strong>: даже высшая
            форма мирского знания и силы уступает прямому пониманию природы сознания. Дхарма
            превосходит и побеждает как грубые страсти, так и утончённое рассудочное знание.<a
                href="#ref-23" class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-24"><sup>24</sup> <strong>Сила благословения
                Татхагат</strong> (<em>tathāgatādhiṣṭhāna</em>) — не ответ на молитву, а милость
            Будд, без которой невозможно даже услышать Дхарму. Без неё Равана, несмотря на своё
            могущество, остался бы глух к учению.<a href="#ref-24"
                                                    class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-25"><sup>25</sup> <strong>Алайя-виджняна</strong> (<em>ālayavijñāna</em>)
            — «сознание-сокровищница», восьмое сознание в учении йогачары. В нём, как в океане,
            под действием «ветра» чувственного восприятия и <em>клеш</em> возникают «волны» —
            мысли, эмоции и кажущийся внешний мир. В этом образе внешний океан и внутренний —
            одно: всё видимое есть проявление ума. <em>Алайя</em> — как океан; семь сознаний —
            как волны. Ветер неведения движет их. Когда ветер стихает и волны успокаиваются —
            сам океан преобразуется: <em>алайя-виджняна</em>, освобождаясь от <em>васан</em>,
            раскрывается как <em>ādarśa-jñāna</em> (Зерцалоподобная Мудрость).<a href="#ref-25"
                                                                                 class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-26"><sup>26</sup> <strong>Колесница Пушпака</strong> —
            «Цветочная вимана» — самодвижущаяся воздушная колесница, первоначально
            принадлежавшая Кубере, хранителю севера и сокровищ земли. Согласно «Рамаяне», её
            захватил Равана, изгнав Куберу из Ланки. В буддийских текстах Пушпака символизирует
            высокое положение, но не просветление.<a href="#ref-26"
                                                     class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-27"><sup>27</sup> <strong>Вина</strong> (<em>vīṇā</em>) —
            один из древнейших и наиболее почитаемых музыкальных инструментов Индии. Это
            струнный щипковый инструмент с длинной шейкой и двумя резонаторами (обычно
            тыквенными или деревянными), натянутыми между ними струнами — чаще всего семью, хотя
            число могло варьироваться. В ведической и буддийской традициях <em>вина</em> — не
            просто инструмент, а символ гармонии между мудростью и состраданием. Её звук
            считался способным успокоить ум, рассеять помехи и подготовить слушателя к
            восприятию Дхармы. В индуизме <em>вина</em> — атрибут <em>Сарасвати</em>, богини
            знания, речи и искусства. В буддийских текстах (особенно махаянских) она часто
            звучит при встрече с Буддой — как знак того, что пространство очищено, а собрание
            готово слушать. Когда Равана берёт вину, он не просто играет — он совершает
            подношение через звук, превращая музыку в путь, ведущий к внутреннему постижению.
            Именно на фоне её мелодии он начинает петь <em>гатхи</em> — слияние слова и звука
            как единое выражение Дхармы.<a href="#ref-27"
                                           class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-28"><sup>28</sup> <strong>Индранела</strong>
            (<em>indranīla</em>) — драгоценный камень цвета неба, обычно лазурит или синий
            сапфир. В индийской традиции считается камнем Индры, царя богов.<a href="#ref-28"
                                                                               class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-29"><sup>29</sup> <strong>Вайдурья</strong>
            (<em>vaiḍūrya</em>) — драгоценный камень, упоминаемый в индийских и буддийских
            текстах как один из главных самоцветов. Его точная природа варьируется в зависимости
            от эпохи и региона: В древнеиндийских источниках (включая ранние буддийские сутры)
            <em>vaiḍūrya</em> обычно означает лазурит — глубокий сине-голубой камень с
            золотистыми прожилками, добывавшийся в Афганистане и высоко ценившийся за его
            небесный цвет. В поздних текстах (особенно в тибетской и китайской традициях) под
            <em>vaiḍūrya</em> часто подразумевают изумруд или зелёный берилл. В некоторых
            контекстах — прозрачный горный хрусталь или даже опал, если речь идёт о сиянии, а не
            цвете. В <strong><em>Ланкаватаре</em></strong> и других махаянских сутрах <em>вайдурья</em>
            символизирует чистоту, прозрачность ума и способность отражать истину без искажений.
            Этимология неясна. Согласно одной версии, название происходит от города Видура
            (Южная Индия), где добывали этот камень. Возможна также связь с греческим
            <em>beryllos</em>
            (берилл), хотя направление заимствования остаётся предметом дискуссий.<a
                href="#ref-29" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-30"><sup>30</sup> <strong>Приянга</strong>
            (<em>Priyaṅgu</em>, предположительно <em>Aglaia elaeagnoidea</em> или <em>Callicarpa
                macrophylla</em>) — тропическое растение, распространённое в Индии и
            Юго-Восточной Азии. Известно своими мелкими, густыми соцветиями белых или
            бледно-жёлтых цветов, которые источают нежный, сладковатый аромат. В санскритской
            поэзии и буддийских текстах цветы <em>приянги</em> — символ нежности, чистоты и
            благоухания добродетели. Их белый цвет часто сравнивают с лунным светом, снегом на
            вершинах Гималаев или чистой шёлковой тканью. Упоминание «ткани цвета
            <em>приянги</em>» — не просто описание оттенка, а аллегория свежести, мягкости и
            духовной чистоты. Когда Равана обвивает вину такой тканью, он не только соблюдает
            ритуальную эстетику — он подготавливает пространство для восприятия Дхармы через
            образ безупречности.<a href="#ref-30" class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-31"><sup>31</sup> <strong>Музыкальное подношение
                Раваны</strong> — это не просто пение под аккомпанемент вины, это сложный
            ритуальный акт, свидетельствующий о владении <em>сангита-шастрой</em> — наукой о
            звуке. Перечисление терминов — <em>шадджа, ришабха, гандхара, мадхьяма, дхаивата,
                нишада</em> — указывает на семь основных звуков (<em>свар</em>), которые в
            индийской традиции соотносятся с <em>чакрами</em>, планетами и уровнями космоса.
            Особое внимание привлекает <em>кайшика</em> — термин, обозначающий тончайший
            микротоновый оттенок (<em>шрути</em>). В классических трактатах, таких как <strong><em>Натьяшастра</em></strong>,
            <em>кайшика</em> не является самостоятельной нотой, а указывает на утончённую
            градацию звука. Её упоминание вместо стандартной пятой ступени (<em>панчамы</em>)
            подчёркивает исключительность исполняемого лада — вероятно, редкой ритуальной
            системы, предназначенной для воздействия на тонкие уровни сознания. Эта музыка
            опирается на строгую теоретическую основу: <em>грамы</em> и <em>мурччханы</em>. <em>Грама</em>
            — базовая ладовая система; в древности их было три (<em>Ṣaḍja-grāma</em> — основная,
            <em>Madhyama-grāma</em> — вторичная, <em>Gāndhāra-grāma</em> — утрачена к
            средневековью), каждая из которых соотносилась с одним из трёх миров.
            <em>Мурччхана</em> — способ получения новых ладов путём смещения тоники, аналогичный
            античным модусам. Владение четырнадцатью <em>мурччханами</em> (по семь для каждой из
            двух сохранившихся <em>грам</em>) символически означало власть над четырнадцатью
            мирами вселенной. Сам инструмент описан как микрокосм: гриф из <em>индранелы</em>
            (синего сапфира), накладки из <em>вайдурьи</em> (берилла или лазурита), ткань цвета
            <em>приянги</em> — всё это не украшение, а символическая структура. Струны вины
            уподобляются энергетическим каналам (<em>нади</em>), её корпус — телу Вселенной.
            Таким образом, Равана предстаёт не как мифологический демонический тиран, а как
            великий аскет и мастер <strong><em>Гандхарва-веды</em></strong> — ведической науки о
            ритуальном звуке. Согласно канону, особенно <strong><em>Самаведе</em></strong>, безупречное
            исполнение такой музыки очищает пространство и «настраивает» ум слушателя. Равана
            выступает как ритуальный исполнитель, подготавливающий пространство для проповеди
            Будды через гармонию звука, формы и намерения.<a href="#ref-31"
                                                             class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-32"><sup>32</sup> <strong>Устойчивое ошибочное
                воззрение</strong> (<em>dṛṣṭi</em>) — рассудочное убеждение, принимаемое за
            окончательную истину. Оно является не просто мнением или временной точкой зрения, а
            глубоко укоренившейся ментальной зацикленностью, возникающей из пристрастия к
            построению систем понятий (<em>vikalpa</em>). Такие воззрения формируют ложные
            представления о существовании «я», о сущностях, о мире и о способе их существования
            — будь то вера в вечность, уничтожение, тождество или различие, бытие или небытие. В
            канонических текстах, особенно в <strong><em>Брахмаджала-сутте</em></strong> (<em>Brahmajāla
                Sutta, Дигха-никая 1</em>), перечисляется 62 вида подобных воззрений, образующих
            «сеть» (<em>jāla</em>), в которую попадает ум, пытаясь уловить реальность через
            двойственные категории. Все они опираются на основополагающее разделение субъекта и
            объекта, порождают цепляние за «я» (<em>ātma-graha</em>) и «моё» и тем самым
            порождают, поддерживают и усиливают страдание и круг перерождений. Истинная Дхарма,
            согласно как ранним, так и махаянским источникам, не является ни философской
            позицией, ни даже «правильным» мнением. Она не утверждает ни бытия, ни небытия, не
            принимает и не отвергает сущностных утверждений и не может быть полностью выражена
            словами, логикой или понятиями. Освобождение — это постижение природы реальности в
            непосредственном опыте (<em>pratyātma-vedya</em>), за пределами всех конструкций
            ума.<a href="#ref-32" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-33"><sup>33</sup> <strong>Путь, постигаемый непосредственно
                (лично)</strong> (<em>pratyātma-vedya-gati</em>) — это путь, который невозможно
            усвоить через слушание (<em>śruta</em>), чтение, логическое умозаключение
            (<em>anumāna</em>)
            или опору на авторитет (<em>āgama</em>). Он принадлежит исключительно сфере личного,
            недвойственного опыта, свободного от посредничества слов, символов, понятий и
            рассудочного анализа. В <strong><em>Ланкаватаре</em></strong> подчёркивается: Дхарма — не
            система учений, это реальность, подлежащая внутреннему видению. Поэтому Будда говорит:
            «Я не проповедую Дхарму» — ибо подлинная Дхарма не есть нечто, что можно передать.
            Она — то, что должно быть увидено каждым самостоятельно. Этот термин противопоставляется
            постижению через внешние источники — всему, что опирается на Учителя, тексты,
            рассуждение, традицию, символы, ритуалы или веру. Даже «правильные взгляды», если
            они остаются на уровне понятий, не ведут к освобождению, поскольку продолжают быть
            <em>dṛṣṭi</em> — устойчивыми ложными воззрениями, пусть и внешне корректными.
            Непосредственное постижение в <strong><em>Ланкаватаре</em></strong> — это не вспышка эмоции,
            не мистический экстаз и не интеллектуальная интуиция. Это — ясное видение природы
            ума, сопровождаемое прекращением всех воззрений (<em>dṛṣṭi-nirodha</em>) и
            отсечением умственных построений (<em>vikalpa-kṣaya</em>). Освобождение не происходит
            благодаря рождению новой идеи или нового переживания, оно случается через распад всей
            структуры схватывания, в которой ум конструирует субъект, объект и их отношения.
            Именно поэтому даже Равана — владыка ракшасов — способен услышать Дхарму Татхагаты.
            Его «демоническая природа» не является препятствием: ум, готовый отпустить ложные
            воззрения, способен к непосредственному постижению, независимо от кармического
            прошлого или статуса. В <strong><em>Ланкаватаре</em></strong> важна не нравственная оценка
            персонажей, имеет значение их готовность в данный момент перестать цепляться за фиксации ума.
            Таким образом, встреча Раваны с Буддой — указание на
            внутреннюю возможность: когда ум выходит за пределы <em>vikalpa</em> и
            <em>dṛṣṭi</em>, становится возможно прямое постижение Дхармы.<a href="#ref-33"
                                                                            class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-34"><sup>34</sup> <strong>Нирмана</strong>
            (<em>nirmāṇa</em>) — «созидание-проявление», «чудесное воплощение». В махаянской
            доктрине это не просто «проявление», а активный акт сострадательного творения,
            посредством которого Будда создаёт формы — тела, голоса, миры, учения, даже
            множества «двойников» — в соответствии с потребностями существ. Отсюда Нирманакая —
            Тело Проявления, возникающее из деятельности Будды, а не из кармы. Важно различать
            <em>nirmāṇa</em> и <em>nirmita</em>. Первое — процесс, способность, акт проявления; второе —
            результат: «созданное», «проявленная форма», «чудесное творение». В
            <strong><em>Ланкаватаре</em></strong>
            эта разница подчёркнута формулой <em>nirmāṇa-nirmitapradarśanakaṃ</em> —
            «показывающий <em>nirmāṇa</em> и <em>nirmita</em>», то есть и сам акт проявления, и его
            проявленные формы. Грамматически: <em>nirmāṇa</em> — отглагольное существительное от
            √<strong>mā</strong> («создавать»), обозначающее действие; <em>nirmita</em> —
            причастие прошедшего времени, означающее «сотворённое». Распространённая ошибка —
            смешивать их, переводя <em>nirmāṇa</em> как «проявленный объект». Но объект — это
            <em>nirmita</em>; <em>nirmāṇa</em> же — живая сила сострадания, выражающаяся в
            форме. Именно поэтому Будда может быть одновременно недвойственным (в Дхармакае) и
            множественным (в Нирманакае): Его сострадание не остаётся в покое, а творит формы,
            чтобы достичь каждого, кто готов услышать.<a href="#ref-34"
                                                         class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-35"><sup>35</sup> <strong>«Ты пребываешь в радости, когда
                Дхарму постигают лично»</strong> — Радость Будды возникает, когда ум слушателя
            выходит за пределы всех внешних опор: Учителя, канона, ритуала, даже «правильного
            воззрения». Подлинная Дхарма — это то, что постигается непосредственно (<em>pratyātma-vedya</em>),
            а не передаётся как учение. Будда — лишь указующий палец (в примере с Луной); он
            теряет смысл, как только взгляд обращён на Луну. Поэтому
            <strong><em>Ланкаватара</em></strong> говорит: «За сорок пять лет проповеди Будда не произнёс
            ни единого слова». Ибо истинная Дхарма раскрывается сама, когда ум
            отпускает все ложные воззрения (<em>dṛṣṭi</em>) и прекращает умственное
            конструирование (<em>vikalpa</em>).<a href="#ref-35"
                                                  class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-36"><sup>36</sup> <strong>Якши, владеющие множеством
                обликов</strong> — здесь символ подвижного,
            многоликого сознания, способного быстро менять свои состояния. В
            <strong><em>Ланкаватаре</em></strong> их «слушание» Дхармы означает, что истина доступна даже
            такому уму, который кажется нестабильным, противоречивым или слишком изменчивым для
            практики. Главное — готовность открыться. Это продолжает
            тему Раваны: даже демонический, многоглавый, страстный ум может стать сосудом для
            Дхармы.<a href="#ref-36" class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-37"><sup>37</sup> <strong>То́така</strong> (<em>toṭaka</em>)
            — санскритский стихотворный размер, состоящий из четырёх строк по 12 слогов. Часто
            использовался в гимнах и философских стихах. Сам Ади Шанкара писал гимны в этом
            размере. В <strong><em>Ланкаватаре</em></strong> указание на <em>то́така</em> подчёркивает:
            речь Раваны — ритуально-поэтическое подношение, достойное Будды.<a
                href="#ref-37" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-38"><sup>38</sup> <strong>Попугаи и майны</strong> —
            символы двух типов восприятия. Попугай олицетворяет повторение без понимания: он
            может точно воспроизвести речь, но не постигает её смысла. Майна — птица, известная
            своей чуткостью к звуку, — символ внимательного, внутреннего слушания. Их совместное
            упоминание подчёркивает, что истинное постижение требует не повторения слов, а
            живого отклика ума.<a href="#ref-38" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-39"><sup>39</sup> <strong>Кумбхакарна</strong> в
            <strong><em>Рамаяне</em></strong> —
            брат Раваны, гигант, погружённый в многолетний сон, пробуждающийся лишь для еды или
            битвы. Он олицетворяет инертное, спящее сознание, скованное неведением. Однако даже
            он, пробуждаясь, способен к ясности и мудрости — он критикует Равану за беззаконие,
            хотя и остаётся верен долгу. Его упоминание здесь — знак того, что даже самое
            тяжёлое, дремлющее сознание способно пробудиться к Махаяне, если возникает контакт с
            Дхармой.<a href="#ref-39" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-40"><sup>40</sup> <strong>Апсары</strong> — небесные девы,
            символы чувственного наслаждения; рощи <strong>ашоки</strong> — «деревья без
            страдания» (<em>a-śoka</em>), чьё имя обещает утешение. Равана приносит в подношение
            всё, что связано с утешением, удовольствием и эстетикой сансары. Его обращение —
            готовность отпустить все формы привязанности, включая самые изящные.<a
                href="#ref-40" class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-41"><sup>41</sup> <strong>Явил Дхарму</strong> (<em>vibhāvayāmāsa</em>)
            — не означает словесного изложения. Глагол <em>vibhāvayati</em> (каузатив от <em>bhāvayati</em>)
            в йогачаринской традиции обозначает акт внутреннего проявления или «вызывания к бытию».
            Здесь Будда, приняв подношения, не произносит ещё ни слова, но своим присутствием
            раскрывает поле Дхармы, делая её внутреннюю суть ощутимой для бодхисаттв и иных
            присутствующих. Это — преддверие проповеди: истина, которая постигается только лично
            (<em>pratyātma-gati</em>), сначала проявляется в безмолвном пространстве между Учителем
            и учениками, и лишь затем облекается в форму ответов на вопросы Раваны.<a href="#ref-41"
                                                                                      class="text-blue-500 hover:underline">↩</a>
        </p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-42"><sup>42</sup> В <strong><em>Ланкаватаре</em></strong> Махамати —
            главный вопрошающий, носитель высшей йогачаринской мудрости. Его имя означает «Великий
            Ум» (<em>Mahā-mati</em>), и он символизирует ум, способный вместить недвойственное
            знание. Махамати задаёт вопросы, которые становятся основой для изложения глубокой
            Дхармы. В каждую эпоху у каждого Будды есть такой вопрошающий о <em>pratyātma-gati</em>
            — Дхарме, постигаемой лично, вне слов.<a href="#ref-42"
                                                     class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-43"><sup>43</sup> <strong>Сон</strong> (<em>svapna</em>) —
            опыт, обладающий реальностью лишь внутри сновидения, демонстрирует отсутствие различия
            между субъектом и объектом: и то, и другое порождены одним умом. <strong>Мираж</strong>
            (<em>mṛgatṛṣṇ</em>ā) — видимость воды в пустыне, лишённая плотности и сущности,
            символизирует влечение ума к объектам, которые не существуют вне желания. <strong>Город
                гандхарвов</strong> (<em>gandharva-nagara</em>) — небесный град, возникающий в
            воздухе, показывает, как привычные отпечатки сознания (<em>васаны</em>) создают иллюзию
            устойчивого и внешнего мира. <strong>Помутнение зрения</strong> (<em>timira</em>) —
            зрительная иллюзия (например, видение двух лун при катаракте), указывает на то, что даже
            «ясное» восприятие может быть искажено природой самого ума. <strong>Сын
                бесплодной</strong> (<em>vandhyā-putra</em>) — образ, подчёркивающий абсолютное
            отсутствие объекта; подобно тому как у бесплодной женщины нет ребёнка, так и у всех
            явлений отсутствует самосущая природа. <strong>Огненное колесо</strong>
            (<em>alāta-cakra</em>) — иллюзия непрерывного круга огня, возникающая от быстрого
            вращения горящей палочки, демонстрирует иллюзию непрерывности: мир состоит из мгновенных
            вспышек сознания, создающих видимость плотного, длящегося бытия.<a href="#ref-43"
                                                                               class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-44"><sup>44</sup> Видение Раваны — прямое раскрытие природы
            ума. Горы, драгоценности, множественные образы Будды и Раваны представляют собой
            проекции потока сознания, лишённого субъектно-объектной двойственности. Эта демонстрация
            лишает воспринимаемый мир внешней опоры. Сомнения Раваны — «сон? мираж? город
            гандхарвов?» — перечисляют классические примеры обманчивого восприятия, принятые в
            индийской философии для иллюстрации природы иллюзии. Такое понимание вызывает у Раваны
            внезапное прозрение (<em>avabodha</em>). Царь ракшасов осознаёт мир как порождение
            собственного ума. Происходит его преображение: Равана перестаёт воспринимать себя только
            как правителя и становится готовым принять Дхарму. Истинная природа реальности
            открывается ему в недвойственном состоянии (<em>advaya</em>), когда <em>викальпа</em>
            (конструирующая активность ума) прекращается.<a href="#ref-44"
                                                            class="text-blue-500 hover:underline">↩</a>
        </p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-45"><sup>45</sup> <strong>«Пробудился
                непосредственно»</strong> — термин указывает на
            момент прямого прозрения (<em>avabodha</em>), когда ум Раваны внезапно постигает природу
            реальности. В это мгновение он оставляет привычку воспринимать мир как внешнюю среду и
            обретает прямое видение: всё видимое представляет собой проявление сознания, лишённого
            субъектно-объектной двойственности.</p>
        <p>Данный акт является глубоким сдвигом в восприятии — <em>париджняной
                svacitta-dṛśya-gocara</em> (исчерпывающим постижением того, что мир есть сфера
            проявления ума). После такого сдвига видение реальности изменяется фундаментально, хотя
            полная стабилизация требует дальнейшей практики.</p>
        <p>Подобное пробуждение описывается как личное постижение (<em>pratyātma-vedya</em>) —
            уникальный опыт, который пребывает вне сферы передачи словами, но преображает природу
            познающего. Это переход от интеллектуального анализа к непосредственному пребыванию в
            реальности «как она есть» (<em>yathābhūta</em>).</p>
        <p>Именно это прозрение делает Равану готовым услышать глубокую Дхарму о пути, постигаемом
            лично (<em>pratyātma-gati</em>), которую Будда затем излагает.<a href="#ref-45"
                                                                             class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-46"><sup>46</sup> <strong>«Когда его основа
                преобразилась»</strong>
            (<em>parāvṛttāśraye</em>) — термин, указывающий на момент прямого прозрения, когда
            структура восприятия радикально изменяется.</p>
        <p><em>Āśraya</em> («опора») — базовое сознание (<em>ālayavijñāna</em>), в котором
            накапливаются кармические отпечатки (<em>васаны</em>) и из которого возникает иллюзия
            разделения на «я» и «мир».</p>
        <p><em>Parāvṛtti</em> («поворот») — в полном смысле это необратимая трансформация <em>алайя-виджняны</em>
            в <em>ādarśa-jñāna</em> (Зерцалоподобную мудрость), происходящая при достижении
            буддовости.</p>
        <p>Однако в данном контексте термин <em>parāvṛttāśraya</em> описывает начальное переживание
            этого поворота — момент, когда Равана впервые постиг (<em>adhigama</em>), что весь
            видимый мир есть лишь <em>svacitta-dṛśya-mātra</em> (проявление собственного ума). Это
            не окончательная <em>паравритти</em>, но решающий прорыв: ум временно освобождается от
            грубой двойственности и напрямую видит свою истинную природу.</p>
        <p>Будда хвалит Равану словами «<em>sādhu, sādhu</em>» («отлично, отлично») и говорит: «<em>evaṃ
                śikṣitavyaṃ yoginā</em>» («так должен учиться йогин»), что указывает: Равана испытал
            правильное постижение, открывающее путь к полной реализации, но ещё продолжает обучение.
        </p>
        <p>После этого прозрения Равана становится готовым вместилищем Дхармы, способным воспринять
            глубокое учение о <em>pratyātma-gati</em> (пути, постигаемом лично).<a href="#ref-46"
                                                                                   class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-47"><sup>47</sup> <strong>«Всё видимое — лишь проявление
                собственного сознания»</strong>
            (<em>svacitta-dṛśya-mātra</em>) — указание на то, что воспринимаемый объект не имеет
            внешней опоры: он возникает вместе с актом восприятия, как волна в океане ума.</p>
        <p><em>Svacitta</em> — «собственное сознание» — сознание как таковое, лишённое разделения на
            «я» и «не-я».</p>
        <p><em>Mātra</em> — «лишь» — отсекает веру в реальность внешних сущностей.</p>
        <p>Таким образом, <em>svacitta-dṛśya-mātra</em> — это отрицание двойственности. Постижение
            этого видения открывает путь к <em>āśraya-parāvṛtti</em> — полному повороту основы
            сознания, который завершится при достижении буддовости. После такого поворота <em>алайя-виджняна</em>
            раскроется как Зерцалоподобная мудрость (<em>ādarśa-jñāna</em>), полностью свободная от
            цепляния за «я» и «мир» как реальные сущности.<a href="#ref-47"
                                                             class="citation-back">↩</a></p>
        <p class="my-2" id="citation-48"><sup>48</sup> <strong>«Утвердился в сфере безмолвия, где
                прекратилось движение
                умопостроений»</strong> (<em>avikalpa-pracāra-sthita</em>) — указывает на состояние,
            в котором ум перестаёт порождать понятийные конструкции.</p>
        <p><em>Pracāra</em> — «движение», «циркуляция» — описывает обычное состояние сознания,
            непрерывно проецирующее субъект, объект и их отношения.</p>
        <p><em>Avikalpa</em> — «отсутствие различающей деятельности ума» — это не переживается как оцепенение или пустое безмыслие, это ясное осознавание, свободное от сетки определений: «я / не-я», «бытие / небытие», «истина / ложь».</p>
        <p>Утверждение в этом состоянии означает, что Равана более не анализирует, не сравнивает, не
            интерпретирует — он пребывает в том, что есть. Именно здесь, в тишине, где затухает сам
            механизм различения, становится возможным непосредственное восприятие учения Татхагаты —
            вне слов и понятий, как прямое узнавание собственной природы Будды
            (<em>tathāgatagarbha</em>). Это состояние — необходимое условие перехода от
            интеллектуального понимания к непосредственному постижению.<a href="#ref-48"
                                                                          class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-49"><sup>49</sup> <strong>«Побуждаемый корнями благого,
                взращёнными в
                прошлом»</strong> (<em>pūrvakuśalamūlasaṃcodita</em>)
            — указывает на внутреннюю зрелость, необходимую для подлинного постижения.</p>
        <p>Корни благого (<em>kuśala-mūla</em>) — технический термин, обозначающий устойчивые
            качества ума: прежде всего отсутствие жадности (<em>alobha</em>), гнева (<em>adveṣa</em>)
            и заблуждения (<em>amoha</em>). В случае Раваны это его прошлые аскезы, преданность и
            изучение наук, которые подготовили почву для преображения.</p>
        <p>Побуждение (<em>saṃcodita</em>) — внутренний импульс, возникающий, когда внешнее условие
            (встреча с Буддой) встречается с внутренней готовностью.</p>
        <p>Эта фраза поясняет, почему Равана — владыка ракшасов — способен непосредственно войти в
            состояние <em>avikalpa</em>. Его пробуждение — естественный расцвет того, что было
            посеяно в прошлом.<a href="#ref-49" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-50"><sup>50</sup> <strong>«Сведущий во всех шастрах»</strong>
            (<em>sarva-śāstra-vidagdha</em>) — указывает на глубокое овладение каноническими
            науками: философией, логикой, грамматикой, метрикой, искусством и дхармой.</p>
        <p><em>Vidagdha</em> — «закалённый» — означает разум, прошедший через строгую дисциплину
            учения и очищенный от грубого невежества.</p>
        <p>В <em>йогачаре</em> именно такой ум способен постичь <em>читтаматру</em> и встать на путь
            к <em>āśraya-parāvṛtti</em>: лишь тот, кто в совершенстве познал пределы понятийного
            мышления, может его отпустить.</p>
        <p>Поэтому Равана, несмотря на свою природу ракшаса, непосредственно распознаёт в явлении
            Будды то, что превосходит все шастры, — и переходит от анализа к непосредственному
            постижению.<a href="#ref-50" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-51"><sup>51</sup> <strong>«Видящий вещи такими, каковы они
                есть»</strong> (<em>yathātathya-darśana</em>)
            — прямое видение реальности, свободное от искажений желания, страха и понятийного
            мышления.</p>
        <p><em>Yathātathya</em> — «согласно их истинной природе» — означает восприятие вещей такими,
            каковы они есть: лишёнными самосущности (<em>niḥsvabhāva</em>), пустыми (<em>śūnya</em>)
            по природе. Это синоним <em>татхаты</em> — «таковости».</p>
        <p><em>Darśana</em> — «видение» — не зрение глазами, а непосредственное прозрение умом, в
            котором объекты распознаются как проекции собственного сознания (<em>svacitta-dṛśya-mātra</em>).
        </p>
        <p>Такое видение становится возможным только после прекращения <em>викальп</em> — умственных
            конструкций. Оно знаменует момент, когда постижение Раваны переходит от понятийного к
            непосредственному, делая его готовым к дальнейшему продвижению на пути.<a href="#ref-51"
                                                                                      class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-52"><sup>52</sup> <strong>«Не нуждающийся в чужом
                руководстве»</strong>
            (<em>aparapraṇeya</em>) — термин, обозначающий способность самостоятельно постигать
            Дхарму через прямой опыт. Это состояние йогина, который опирается на непосредственное
            видение реальности (<em>pratyātma-vedya</em>), а не на слепое доверие к авторитетам или
            логические построения.</p>
        <p>После прозрения Равана различает истину и заблуждение исходя из внутреннего опыта. Это делает его способным воспринять глубокое учение Будды как подтверждение собственного постижения.<a href="#ref-52" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-53"><sup>53</sup> <strong>«Искусный в исследовании
                собственного разума»</strong> (<em>svabuddhi-vicālana-kuśala</em>)
            — указывает на способность йогина непосредственно наблюдать природу своего интеллекта.
        </p>
        <p><em>Svabuddhi</em> — «собственный разум» — здесь означает сам механизм познания.</p>
        <p><em>Vicālana</em> — «исследование» — активное всматривание в работу ума с целью
            распознать скрытые проекции <em>викальпы</em>.</p>
        <p><em>Kuśala</em> — «искусный» — подчёркивает, что Равана владеет самонаблюдением как
            мастерством.</p>
        <p>Именно это позволяет ему увидеть, как ум конструирует иллюзию субъекта и объекта, — и тем
            самым открывает путь к <em>āśraya-parāvṛtti</em>: повороту, при котором <em>алайя-виджняна</em> полностью освобождается от омрачений и раскрывается как <em>ādarśa-jñāna</em>
            (Зерцалоподобная мудрость).<a href="#ref-53" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-54"><sup>54</sup> <strong>«Свободный от рассудочных
                воззрений»</strong> (<em>tarka-dṛṣṭi-vyapeta</em>)
            — указывает на выход за пределы формальной логики как средства постижения истины.</p>
        <p><em>Tarka</em> — «рассуждение» — метод умозаключения, полезный на начальных этапах пути,
            но неспособный проникнуть в недвойственную природу реальности, ибо всегда опирается на
            разделение.</p>
        <p><em>Dṛṣṭi</em> — «воззрение» — здесь означает привязанность к рассудочным воззрениям
            (<em>tarka-dṛṣṭi</em>) как к окончательной истине.</p>
        <p><em>Vyapeta</em> — «ушедший за пределы» — означает, что Равана более не пытается
            «вывести» Дхарму логически. Его видение (<em>darśana</em>) стало непосредственным: он
            созерцает реальность, не опираясь на рассудочные построения, что является признаком
            перехода от теоретического знания к йогическому опыту.<a href="#ref-54"
                                                                     class="citation-back">↩</a></p>
        <p class="my-2" id="citation-55"><sup>55</sup> <strong>«Принимающий вселенскую
                форму»</strong> (<em>mahā-viśvarūpa-dhārin</em>)
            — эпитет, указывающий на способность йогина проявлять бесчисленные формы без
            привязанности к какой-либо из них.</p>
        <p><em>Viśvarūpa</em> — «вселенская форма» — означает способность проявляться во всех
            формах, постигнув их как проявления собственного ума.</p>
        <p><em>Dhārin</em> — «удерживающий» — подчёркивает, что он владеет искусством проявления
            форм, ибо постиг их природу как <em>svacitta-dṛśya-mātra</em> — «лишь проявление
            собственного сознания».<a href="#ref-55" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-56"><sup>56</sup> <strong>«Умелый в искусных
                средствах»</strong> (<em>upāyakauśalya</em>)
            — указывает на способность йогина являть Дхарму в любой форме, где есть существо,
            готовое её воспринять.</p>
        <p><em>Upāya</em> — «искусное средство» — непосредственное выражение сострадания,
            возникающее без намерения, когда ум свободен от разделения на «учителя» и «ученика».</p>
        <p><em>Kauśalya</em> — «умение» — мастерство, рождённое из прямого видения реальности.</p>
        <p>Такое умение проистекает из постижения недвойственности: когда ум перестаёт цепляться за
            «я» и «мир», он способен откликаться на нужду любого существа — через слово, молчание,
            образ или даже отсутствие формы.<a href="#ref-56" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-57"><sup>57</sup> <strong>«Искусный в последовательном
                постижении отличительных признаков
                всех ступеней»</strong> (<em>sarva-bhūmy-uttarottara-sva-lakṣaṇādhigama-kuśala</em>)
            — указывает на глубокое знание внутренней структуры пути.</p>
        <p><em>Bhūmi</em> — «земли, степени, ступени» — десять ступеней бодхисаттвы, каждая из
            которых имеет свою природу и функцию.</p>
        <p><em>Uttarottara</em> — «последовательный, один выше другого» — означает понимание того,
            как каждое состояние естественно рождает следующее.</p>
        <p><em>Svalakṣaṇa</em> — «собственные признаки» — указывает на способность непосредственно
            распознавать каждую ступень по её внутреннему качеству, а не по внешним проявлениям.</p>
        <p>Такое мастерство (<em>kuśala</em>) свидетельствует о зрелости Раваны как йогина,
            подготовленного прошлыми аскезами и накоплением корней благого. Оно позволяет ему не
            останавливаться на промежуточных состояниях, а стремиться к сфере личного постижения
            Татхагаты (<em>pratyātma-gati</em>).<a href="#ref-57" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-58"><sup>58</sup> <strong>«Радующийся различению природы
                ума, разума и сознания»</strong>
            (<em>cittamanomanovijñāna-svabhāva-viveka-rata</em>) — указывает на глубокое понимание
            структуры ума, лежащей в основе учения <em>йогачары</em>.</p>
        <p><em>Citta</em> — базовый ум, вместилище всех отпечатков (<em>васан</em>), тождественный
            <em>алайя-виджняне</em>.</p>
        <p><em>Manas</em> (<em>kliṣṭa-manas</em>) — омрачённое эго-сознание, цепляющееся за <em>алайя-виджняну</em>
            как за «я», порождая двойственность.</p>
        <p><em>Manovijñāna</em> — ментальное сознание, интерпретирующее данные чувств и порождающее
            понятийные построения (<em>викальпы</em>).</p>
        <p><em>Viveka</em> — «различение» — это не аналитическое разделение, это ясное видение их
            природы: все три — взаимозависимые аспекты единого потока сознания, лишённые
            самосущности.</p>
        <p><em>Rata</em> — «радующийся» — означает, что для Раваны это различение стало безусильным
            естественным состоянием. В этом — подлинная радость йогина: увидеть механизмы ума и
            более не быть ими обманутым.<a href="#ref-58" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-59"><sup>59</sup> <strong>«Прекративший тройственную
                непрерывность видимого»</strong>
            (<em>trisaṃtati-vyavacchinna-darśana</em>) — разрыв с механизмами, порождающими иллюзию
            сансарического опыта.</p>
        <p><em>Trisaṃtati</em> — «три потока преемственности»: поток причин (кармические отпечатки,
            <em>васаны</em>), поток объектов (кажущаяся устойчивость внешнего мира), поток сознания
            (непрерывная цепь моментов различения). Эти три потока создают видимость времени, «я» и
            мира.</p>
        <p><em>Vyavacchinna</em> — «отсечённый» — означает, что Равана более не поддерживает эту
            преемственность своим цеплянием. Он не «останавливает» процессы, но перестаёт придавать
            им реальность.</p>
        <p>Его <em>darśana</em> — «видение» — теперь свободно от веры в непрерывность. Он видит
            явления такими, каковы они есть: мгновенными, лишёнными сущности, не связанными
            причинной цепью.</p>
        <p>Этот разрыв преображает его видение: сознание становится готовым к восприятию Дхармы,
            пребывающей вне всякой преемственности.<a href="#ref-59" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-60"><sup>60</sup> <strong>«Свободный от причинных воззрений
                тиртхиков»</strong> (<em>sarva-kāraṇa-tīrthya-vyapeta</em>)
            — указывает на отказ от поиска внешних причин мира.</p>
        <p>Тиртхики объясняют существование через первопричины, лежащие вне сознания: Бога-творца,
            первоматерию, атомы или время.</p>
        <p>С точки зрения <strong>Ланкаватары</strong>, такие воззрения — заблуждение, ибо мир не
            имеет внешней опоры: всё видимое есть лишь проявления ума (<em>citta-mātra</em>), не
            существующие независимо от сознания.</p>
        <p><em>Vyapeta</em> — «ушедший за пределы» — означает, что Равана более не цепляется за идеи
            первопричин. Он не отвергает их логически, но просто видит их ненужность. И в этом
            заключён переход от философствования к йогическому видению: вопросы о «начале» теряют
            смысл, когда ум покоится в том, что есть.<a href="#ref-60" class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-61"><sup>61</sup> <strong>«Вошедший во внутреннюю сферу
                Татхагатагарбхи»</strong> (<em>tathāgatagarbha-adhyātma-samāpanna</em>)
            — указывает на прямое постижение природы ума, в которой уже присутствует полнота качеств
            Будды.</p>
        <p><em>Tathāgatagarbha</em> — «зародыш Татхагаты» — чистая природа сознания, не затронутая
            омрачениями, хотя и скрытая ими.</p>
        <p><em>Adhyātma</em> — «внутреннее» — означает, что Равана обнаружил источник Дхармы в
            глубинной основе собственного ума.</p>
        <p><em>Buddhabhūmi</em> — «ступени Будды» — уровни, на которых эта природа проявляется без
            помех. Постижение их внутренней природы знаменует, что Равана осознал: разделение между
            «обычным существом» и «Буддой» — иллюзия, порождённая омрачениями.</p>
        <p>Это завершает подготовку Раваны: его ум настроен на ту же глубину постижения, что и ум
            Татхагаты, что делает его способным воспринять учение о <em>pratyātma-gati</em> — пути,
            постигаемом лично.<a href="#ref-61" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-62"><sup>62</sup> <strong>«Утвердившийся в мудрости
                Будды»</strong> (<em>sthita-buddha-buddhi</em>)
            — состояние, в котором разум йогина устойчиво пребывает в постижении природы мудрости
            Будды.</p>
        <p><em>Buddhi</em> — здесь высшая познавательная способность, свободная от сомнений,
            колебаний и понятийных искажений.</p>
        <p><em>Sthita</em> — «утвердившийся» — означает, что прозрение Раваны перестало быть
            мимолётным и стало его естественным состоянием.</p>
        <p>Это постижение того, что его собственный ум — по природе уже мудрость Будды (<em>tathāgatagarbha</em>),
            лишь временно скрытая омрачениями (вспоминаем Уттаратантру Майтреи).</p>
        <p>Так завершается подготовку Раваны: его разум устойчиво направлен на постижение той же
            таковости (<em>tathatā</em>), что полностью реализована Учителем, — и потому он готов
            воспринять Дхарму в её полной глубине.<a href="#ref-62" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-63"><sup>63</sup> <strong>«Звук, постигаемый лишь
                внутренне»</strong> (<em>adhyātma-vedya-śabda</em>)
            — указывает, что наставление не было внешним явлением, воспринимаемым ушами, а возникло
            непосредственно в сознании Раваны.</p>
        <p><em>Gagana</em> — «небо» — в буддийской символике означает природу ума, лишённую помех,
            подобно чистому пространству. Звук, «раздающийся из неба», — выражение мудрости,
            возникающей из самой чистоты сознания.</p>
        <p><em>Adhyātma-vedya</em> — «постигаемое внутренне» — означает, что Равана воспринял это
            наставление как прямое узнавание истины.</p>
        <p>Этот момент знаменует переход к <em>pratyātma-vedya</em> — личному постижению,
            недоступному передаче. Голос из пространства — проявление Дхармы, ставшее возможным
            потому, что ум Раваны более не цепляется за внешние объекты и понятия. Это — звук
            тишины, слышимый только тогда, когда умолкает <em>викальпа</em>.<a href="#ref-63"
                                                                               class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-64"><sup>64</sup> <strong>«Воззрение полного
                прекращения»</strong>
            (<em>uccheda-dṛṣṭi</em>) — одна из двух фундаментальных крайностей, отвергаемых Буддой;
            другая — «воззрение вечности» (<em>śāśvata-dṛṣṭi</em>).</p>
        <p><em>Uccheda</em> — «полное прекращение» — это нигилистическое воззрение, согласно
            которому после разрушения формы ничто не остаётся: ни сознания, ни кармы, ни возможности
            пробуждения.</p>
        <p>Эта ошибка возникает, когда йогин, постигая <em>śūnyatā</em>, отрицает не только
            самосущность явлений, но и само условное проявление ума. Он принимает <em>śūnyatā</em>
            за ничто, а не за отсутствие воображаемого «я» и «внешнего».</p>
        <p>Такое воззрение становится новой опорой (<em>āśraya</em>) для цепляния — уже не за
            «бытие» (<em>bhāva</em>), а за «небытие» (<em>abhāva</em>). Оно не ведёт к освобождению,
            но удерживает ум в сансаре под видом отречения.</p>
        <p>Истинное видение — срединный путь (<em>madhyamā-pratipad</em>): дхармы по природе не
            имеют сущности (<em>niḥsvabhāva</em>), но не лишены условного проявления (<em>saṃvṛti-satya</em>).
            Именно это видит Равана — и потому избегает обеих крайностей.<a href="#ref-64"
                                                                            class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-65"><sup>65</sup> <strong>«Оставив ум (citta), разум (manas)
                и различающее сознание
                (manovijñāna)»</strong> — указание на необходимость выйти за пределы трёх уровней
            сансарического сознания.</p>
        <p><em>Citta</em> (ум) — здесь означает <em>алайя-виджняну</em>, хранилище кармических
            отпечатков (<em>васан</em>), из которого возникает иллюзия непрерывности.</p>
        <p><em>Manas</em> (<em>манас</em>) — седьмое сознание (<em>kliṣṭa-manas</em>), цепляющееся
            за <em>алайю</em> как за «я» и порождающее двойственность.</p>
        <p><em>Manovijñāna</em> (<em>мановиджняна</em>) — шестое сознание, функция которого —
            понятийное различение (<em>vikalpa</em>): оно проецирует разделение на «субъект» и
            «объект», «внутреннее» и «внешнее».</p>
        <p>«Оставить» их — значит перестать принимать их проявления за реальность.<a href="#ref-65"
                                                                                     class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-66"><sup>66</sup> <strong>«Созерцание, падшее в сферу
                шраваков, пратьекабудд и
                тиртхиков»</strong> — указание на состояния, в которых сохраняется тонкая
            привязанность к опорам.</p>
        <p><em>Patita</em> — «упавшее» — означает, что созерцание, несмотря на глубину,
            останавливается на промежуточном уровне и не достигает недвойственности.</p>
        <p>Шраваки и пратьекабудды стремятся к освобождению через отрицание «я», но продолжают
            принимать дхармы как реальные или стремятся к личному покою (<em>nirvāṇa</em>), а не к
            буддовости ради всех существ. Их путь — личное упокоение, а не сострадательное
            пробуждение.</p>
        <p>Тиртхики ищут истину во внешних началах — Боге, душе, материи — и потому их созерцание
            опирается на двойственность с самого начала.</p>
        <p><em>Gocara</em> — «сфера» или «область деятельности» — здесь означает умственный
            горизонт, в котором ум пасётся. Будда предостерегает, что даже глубокое самадхи
            становится «падшим», если оно не выходит за пределы всех опор.</p>
        <p>Путь махайогина — без пристанища: он не ищет покоя для себя, но остаётся в мире ради
            блага всех существ, не цепляясь ни за освобождение, ни за созерцание — это <em>apratiṣṭhita-nirvāṇa</em>
            (нирвана без опоры).<a href="#ref-66" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-67"><sup>67</sup> <strong>«Не следует быть поглощённым
                историями и преданиями»</strong> (<em>ākhyāyiketihāsa-rata</em>)
            — предостережение против привязанности к описательному эпическому знанию.</p>
        <p><em>Ākhyāyika</em> — повествования, легенды, дидактические рассказы; <em>itihāsa</em> —
            эпические сказания, представляемые как «так оно и было». Такие тексты, даже если они
            мудры, укореняют ум во времени, пространстве и личной истории — сфере <em>vikalpa</em>,
            где всё расчленено на «героя», «событие» и «смысл».</p>
        <p><em>Rata</em> — «поглощённый» — указывает на наслаждение самим процессом слушания,
            которое отвлекает от непосредственного видения.</p>
        <p>Для Раваны — существа, чья фигура уже вплетена в мифы, — это наставление особенно важно:
            истинное пробуждение требует отказа от отождествления с любой историей, включая
            собственную.</p>
        <p>Путь йогина — не в том, чтобы знать больше историй, а в том, чтобы пребывать там, где
            истории исчезают: в недвойственности (<em>advaya</em>), за пределами прошлого,
            настоящего и будущего.<a href="#ref-67" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-68"><sup>68</sup> <strong>«Не следует держаться воззрения о
                самобытной природе»</strong>
            (<em>svabhāva-dṛṣṭi</em>) — указание на корневое заблуждение, лежащее в основе всей
            сансары.</p>
        <p><em>Svabhāva</em> — «собственное бытие» — есть убеждённость в том, что явления существуют
            сами по себе, независимо от условий и сознания.</p>
        <p>С точки зрения <strong><em>Ланкаватары</em></strong>, такое воззрение — иллюзия, порождённая
            понятийным различением (<em>vikalpa</em>): ум принимает временные проявления за
            устойчивые сущности.</p>
        <p>Если дхармы обладали бы <em>svabhāva</em>, они не могли бы возникать, меняться или
            исчезать — и потому не могли бы быть проявлениями сознания.</p>
        <p>Отказ от <em>svabhāva-dṛṣṭi</em> — фундамент постижения, которое постепенно углубляется
            на пути бодхисаттвы: ум перестаёт цепляться за формы и видит их такими, каковы они есть
            — лишёнными самосущности (<em>niḥsvabhāva</em>), но проявляющимися условно (<em>saṃvṛti-satya</em>).<a
                href="#ref-68" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-69"><sup>69</sup> <strong>«Не следует подпадать под
                опьянение властью и
                господством»</strong> (<em>rājādhipatya-mada</em>) — предостережение против цепляния
            за социальный статус как за реальность.</p>
        <p><em>Mada</em> — «опьянение» — это высокомерие, возникающее, когда ум принимает внешние
            знаки власти за подтверждение собственной значимости.</p>
        <p>Для Раваны, владыки Ланки и повелителя ракшасов, это искушение особенно велико: его
            могущество — видимое, осязаемое, воспетое в преданиях.</p>
        <p>Но с точки зрения <strong><em>Ланкаватары</em></strong>, всякая власть — условна (<em>pratītya-samutpanna</em>),
            ибо основана на двойственности: «я — правитель», «они — подданные». Такое разделение
            укрепляет <em>manas</em>, цепляющийся за «я», и разрушает состояние <em>avikalpa</em> —
            недвойственного пребывания.</p>
        <p>Истинное господство — в независимости от всех форм признания, включая царский титул.
            Отказ от <em>mada</em> — условие того, чтобы власть не порабощала того, кто ею обладает.<a
                href="#ref-69" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-70"><sup>70</sup> <strong>«Не следует ограничиваться
                медитацией шести дхьян»</strong>
            (<em>ṣaḍdhyānādidhyāyin</em>) — указание на то, что даже глубокие состояния
            сосредоточения не являются освобождением, если в них сохраняется разделение на
            «созерцающего» и «созерцаемое».</p>
        <p>Шесть <em>дхьян</em> — ступени умственного успокоения, общие для многих традиций, включая
            учения тиртхиков. Они приносят покой, ясность и блаженство, но не устраняют корень
            двойственности.</p>
        <p>Практикующий может принять эти состояния за <em>nirvāṇa</em>, не замечая, что «я,
            пребывающий в <em>дхьяне</em>» — всё ещё иллюзия, поддерживаемая <em>manas</em>.</p>
        <p>Такое цепляние препятствует освобождению: пока сохраняется «субъект опыта», ум остаётся в
            тонкой двойственности.</p>
        <p>Путь махайогина в том, чтобы распознавать природу ума во всех состояниях — до, во время и
            после <em>дхьяны</em>.</p>
        <p>Истинная йога Махаяны — прекращение самого различения, которое создаёт и «<em>дхьяну</em>»,
            и «обычное состояние».<a href="#ref-70" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-71"><sup>71</sup> <strong>«Искусный в тончайшем повороте
                сознания»</strong> (<em>sūkṣma-abhivijñāna-parāvṛtti-kuśala</em>)
            — качество бодхисаттвы, способного распознавать и устранять тончайшие движения
            двойственности в самом акте познания.</p>
        <p><em>Sūkṣma</em> — «тонкий» — означает, что речь идёт о первичном импульсе двойственности,
            возникающем до всякой концепции, раньше грубых мыслей и эмоций.</p>
        <p><em>Abhivijñāna</em> — «различающее знание» — обозначает акт осознавания в его самом
            начале, до разделения на «познающего» и «познаваемое».</p>
        <p><em>Parāvṛtti</em> — «поворот» — это разворот ума от проекции внешнего мира к
            распознаванию своей собственной природы.</p>
        <p><em>Kuśala</em> — «искусный» — указывает на мастерство бодхисаттв в этой практике: они
            способны уловить момент возникновения двойственности и повернуть ум к его истинной
            природе до того, как <em>викальпа</em> (построение понятий) затвердеет в воззрение.</p>
        <p>Эта искусность отличается от полной <em>āśraya-parāvṛtti</em> (поворота основы), которая
            происходит при буддовости, когда восемь виджнян окончательно трансформируются в
            мудрости. Здесь речь о практике, ведущей к этой цели: бодхисаттва тренируется
            распознавать и устранять тончайшую двойственность, подготавливая ум к окончательному
            повороту.</p>
        <p>Тот, кто овладел этой искусностью, видит корень всех ошибочных воззрений (<em>dṛṣṭi</em>):
            они рождаются из нераспознанного <em>manas</em>, цепляющегося за «я». Великий йогин
            потому не вступает в споры — его видение само рассеивает заблуждения, подобно тому, как
            свет рассеивает тьму.<a href="#ref-71" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-72"><sup>72</sup> <strong>«Цепляются за «я» и признаки
                видимого»</strong> (<em>ātmagrāha-dṛśya-lakṣaṇa-abhiniviṣṭa</em>)
            — принимают «я» и видимые объекты как действительно существующие и самодостаточные.<a
                href="#ref-72" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-73"><sup>73</sup> <strong>«Следуют за элементами, их
                качествами и субстанциями»</strong>
            (<em>bhūta-guṇa-dravya-anucārin</em>) — верят в материальные субстанции и качества
            как в нечто объективно существующее.<a href="#ref-73" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-74"><sup>74</sup> <strong>«Укоренены в воззрениях,
                порождённых неведением»</strong> (<em>avidyā-pratyaya-dṛṣṭi-abhiniveśa</em>)
            — мировоззрение основано на неведении и поддерживает дальнейшие заблуждения.<a
                href="#ref-74" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-75"><sup>75</sup> <strong>«Рассеяны представлением, что
                пустота «возникает»»</strong>
            (<em>śūnyatā-utpāda-vikṣipta</em>) — запутались в понимании возникновения из пустоты:
            ошибочно полагают, что <em>śūnyatā</em> — это субстанция, которая возникает и исчезает,
            а не отсутствие самосущности всех явлений.<a href="#ref-75" class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-76"><sup>76</sup> <strong>«Погружены в различения»</strong>
            (<em>vikalpābhiniviṣṭa</em>)
            — их мышление создаёт искусственные понятия и они принимают свои умственные построения
            за реальность.<a href="#ref-76" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-77"><sup>77</sup> <strong>«Упали в двойственность
                обозначаемого и признака»</strong>
            (<em>lakṣya-lakṣaṇa-patita</em>) — они разделяют реальность на «объект» и «его признаки»
            и принимают оба за действительно существующие, не понимая их умственной природы.<a
                href="#ref-77" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-78"><sup>78</sup> <strong>«Ведёт к обретению вселенской
                формы»</strong> (<em>viśvarūpa-gati-prāpaka</em>)
            — способность постигать все формы как проявления ума, лишённые самосущности и
            независимого существования.<a href="#ref-78" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-79"><sup>79</sup> <strong>«Пробуждает непосредственное
                постижение собственного
                пути»</strong> (<em>svapratyātmagati-bodhaka</em>) — прямое знание пути, а не
            принятые на веру учения или логические построения.<a href="#ref-79"
                                                                 class="citation-back">↩</a></p>
        <p class="my-2" id="citation-80"><sup>80</sup> <strong>«Ведёт к обретению высших ступеней
                (bhūmi)»</strong> (<em>viśeṣa-bhava-upapatti</em>)
            — здесь освоение всё более глубоких уровней реализации, соответствующих стадиям
            бодхисаттв (bhūmi).<a href="#ref-80" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-81"><sup>81</sup> <strong>«Прекращает волны различных
                виджнян»</strong> (<em>vividhavijñāna-taraṅga-vyāvartaka</em>)
            — устраняет волны различных <em>виджнян</em>, приводя сознание к естественной
            неподвижности, в которой прекращаются колебания восприятия, памяти, различения и
            кармических отпечатков.<a href="#ref-81" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-82"><sup>82</sup> <strong>«Кто открывает внутреннюю область
                личного постижения»</strong> (<em>pratyātma-gati-gocara-udbhāvaka</em>) — Будда
            не передаёт учение как внешний
            объект. Он раскрывает то, что уже присутствует в самом йогине.</p>
        <p><em>Pratyātma</em> — «личное», «непосредственное» — это постижение недоступно через
            логику, авторитет или заимствование.</p>
        <p><em>Gati</em> — «путь» — здесь это не движение от точки к точке, подразумевается способ
            пребывания ума в недвойственном постижении.</p>
        <p><em>Gocara</em> — «область» — поле опыта, в котором нет разделения на познающего и
            познаваемое.</p>
        <p><em>Udbhāvaka</em> — «раскрывающий» — подчёркивает, что Будда не создаёт эту сферу, Он
            устраняет завесы, мешающие её видению.</p>
        <p>Таким образом, истинная Дхарма распознаётся, а не сообщается.<a href="#ref-82"
                                                                           class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-83"><sup>83</sup> <strong>«Чьё знание свободно от
                сотворённого и чудесных
                проявлений»</strong> (<em>nairmita-nairmāṇika-vyapeta adhigama-buddhiḥ</em>) —
            указывает, что подлинное постижение не связано с созданием форм, состояний или эффектов.
        </p>
        <p><em>Nirmita</em> — «сотворённое» — всё, что искусственно сконструировано умом: понятия,
            явления, даже священные образы, принимаемые за предмет постижения.</p>
        <p><em>Nairmāṇika</em> — «чудесные проявления» — относится к магическим проявлениям, которые
            в индийской традиции часто считались признаком духовной силы.</p>
        <p><em>Vyapeta</em> — «свободный от» — подчёркивает, что знание Татхагаты не опирается ни на
            создание, ни на проявление.</p>
        <p>Это — <em>adhigama-buddhi</em>: непосредственное постижение, возникающее без опоры на
            произведённое или проявленное.</p>
        <p>Это знание достигает совершенства при <em>āśraya-parāvṛtti</em> (повороте основы сознания
            при буддовости): когда ум окончательно освобождается от привязанности к «сотворённому»,
            становится видимым то, что изначально присутствует, но не нуждается в оформлении.</p>
        <p>Пробуждение потому не принадлежит сфере чудес, даже священных и почитаемых. Это — прямое
            внутреннее знание, не требующее подтверждения через явление, действие или форму.<a
                href="#ref-83" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-84"><sup>84</sup> Термин <strong>«йогин»</strong> в
            <strong><em>Ланкаватаре</em></strong> применяется
            только к тому, кто достиг постижения (<em>adhigama</em>).</p>
        <p>Мудрость, о которой идёт речь, не передаётся заранее и не усваивается через обучение
            (<em>śruta-jñāna</em>) или размышление (<em>cintā-jñāna</em>).</p>
        <p>Она раскрывается единственно в момент непосредственного постижения, при вхождении во
            врата самадхи (<em>samādhi-mukha</em>), когда умолкает умственное различение (<em>vikalpa</em>)
            и становится доступной внутренняя область личного постижения
            (<em>pratyātma-gati</em>).<a href="#ref-84" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-85"><sup>85</sup> <strong>«Свободный от признаков
                действия»</strong> (<em>kriyā-lakṣaṇa-vinivṛtta</em>)
            означает, что Татхагата не обладает характеристиками деятеля (<em>kartṛ</em>): у него
            нет намерения, усилия, цели или идеи «я действую».</p>
        <p>Его проявление — не действие в обыденном смысле (<em>kriyā</em>), это спонтанное
            раскрытие мудрости (<em>anābhoga</em> — безусильность), не порождающее кармических
            отпечатков.<a href="#ref-85" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-86"><sup>86</sup> <strong>«Не колеблется в нерождённости
                дхарм»</strong> (<em>anutpattika-dharma-kṣānti</em>)
            — означает отсутствие внутреннего смятения, когда раскрывается: ни одна дхарма никогда
            не возникала как самостоятельная сущность.</p>
        <p><em>Kṣānti</em> здесь — не психологическая устойчивость и не усилие по удержанию
            состояния. Это — естественная невозмутимость, в которой нет страха, ожидания или
            сомнения относительно бытия дхарм.</p>
        <p>В этом распознавании нет различия между видящим и видимым и нерождённость
            (<em>anutpāda</em>) здесь — это само прекращение двойственности. Достижение <em>anutpattika-dharma-kṣānti</em>
            — признак 8-й бхуми (<em>Ачала</em>, «Недвижимая») или выше, где бодхисаттва становится
            <em>anivartanīya</em> (необратимым). Будда видит, что Равана достиг этого постижения,
            что делает его готовым к глубокой Дхарме.<a href="#ref-86" class="citation-back">↩</a>
        </p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-87"><sup>87</sup> <strong>«Взор мудрости»</strong>
            (<em>buddhi-cakṣus</em>) — видение
            без разделения на субъект и объект, в отличие от плотского ока/обычного зрения
            (<em>māṃsa-cakṣus</em>).<a href="#ref-87" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-88"><sup>88</sup> <strong>«Великий смех»</strong>
            (<em>mahāhāsa</em>) — спонтанное
            выражение недвойственной радости, в которой нет страх перед шуньятой.<a
                href="#ref-88" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-89"><sup>89</sup> <strong>«Лучи из пор тела»</strong> —
            символ всепроникающего
            присутствия мудрости, не ограниченной физической формой.<a href="#ref-89"
                                                                       class="citation-back">↩</a></p>
        <p class="my-2" id="citation-90"><sup>90</sup> <strong>«Собственное внутреннее
                благородное знание»</strong> (<em>sva-pratyātma-ārya-jñāna</em>)
            — знание, недоступное через слова, раскрывающееся только в непосредственном опыте (<em>pratyātma-vedya</em>).<a
                href="#ref-90" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-91"><sup>91</sup> <strong>«Размышлял»</strong>
            (<em>anuvicintayamāna</em>) — прямое восприятие йогического пути Раваны без посредничества
            понятий.<a href="#ref-91" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-92"><sup>92</sup> <strong>«Смятение ума»</strong>
            (<em>citta-vibhrama</em>) — состояние недоумения,
            переживание потрясения основ веры, когда внешнее проявление Будды
            (смех) противоречит представлению о Нём как о бесстрастном.<a href="#ref-92"
                                                                          class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-93"><sup>93</sup> <strong>«Цепляются за буквальный
                смысл»</strong>
            (<em>yathāruta-artha-abhiniviṣṭa</em>) —
            принимают звуки слов за истину, не видя, что слова — лишь
            указатели.<a href="#ref-93" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-94"><sup>94</sup> <em>Traikālya</em> — «трёх времён» (прошлое, настоящее, будущее); указывает, что ложные воззрения (<em>dṛṣṭi</em>) одинаковы во все эпохи, и ответ Будды актуален всегда. <em>Svaparobhayārtha</em> — «ради блага себя, других и обоих»: три мотива действия в буддийской этике — <em>svārtha</em> (ради себя), <em>parārtha</em> (ради других) и <em>ubhayārtha</em> (ради обоих). Последний — недвойственный мотив бoдхисаттвы, где разделение между «я» и «другой» преодолено, и благо себя и других нераздельно, как вода и волны единого океана.<a href="#ref-94" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-95"><sup>95</sup> <strong>«Два вопроса»</strong> —
            «Существуют ли дхармы?» и «Не существуют ли
            дхармы?» — корень всех философских заблуждений. Их отвержение —
            вход в недвойственность.<a href="#ref-95" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-96"><sup>96</sup> <strong>«Преобразивший опору различающего
                мышления»</strong>
            (<em>parāvṛtta-vikalpāśraya</em>) — состояние поворота основы
            (<em>āśraya-parāvṛtti</em>), в котором исчезает действие <em>vikalpa</em>.<a
                href="#ref-96" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-97"><sup>97</sup> <strong>«Проницательная мудрость
                различения»</strong>
            (<em>pravicaya-buddhi</em>) —
            мудрость, распознающая, что за двойственностью нет никакой сущности,
            есть только игра ума. Она ведёт к прямому видению таковости.<a href="#ref-97"
                                                                           class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-98"><sup>98</sup> <strong>«Ступени Ачала, Садхумати,
                Дхармамегха»</strong> —
            8-я, 9-я и 10-я земли/степени/ступени/бхуми бодхисаттвы, где проявляются соответственно:
            непоколебимость в недвойственности,
            совершенное мастерство в проповеди,
            излияние мудрости, как дождя, на всех существ.<a href="#ref-98"
                                                             class="citation-back">↩</a></p>
        <p class="my-2" id="citation-99"><sup>99</sup> <strong>Маха-ратна-падма-вимана</strong>
            (<em>mahā-ratna-padma-vimāna</em>) —
            «великий драгоценный чертог на лотосе» (<em>вимана</em> — также «дворец»
            или «небесная колесница»). Это высшая форма проявления пробуждённого ума.
            Описание <strong>мандалы</strong>, структуры, характерной для тантрической визуализации,
            но здесь представленной в <strong>сутрическом контексте</strong>.<a href="#ref-99"
                                                                                class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-100"><sup>100</sup> <strong>«Множество [своих] тел, явленных
                силой твоего собственного ума»</strong> —
            эта фраза имеет множество параллелей с другими текстами Махаяны:
            <em>Праджняпарамитой</em> (<strong><em>Хридая-сутра</em></strong>),
            <strong><em>Аватамсака-сутрой</em></strong>, а также с более поздними текстами тантры
            (структура мандалы, визуализация идама и его окружения).
            Если парадокс «ни единства, ни множественности» в <strong><em>Хридае</em></strong> и
            «один содержит всё, всё содержит одно, один в одном, всё во всём» в
            <strong><em>Аватамсаке</em></strong> выражается
            текстуально, то в <strong><em>Ланкаватаре</em></strong> это выражено образно-визуально:
            Равана видит это напрямую
            — множество тел, но нет "одного я"; один ум, но нет "единой субстанции". Этот парадокс
            разрешается только в прямом постижении шуньяты. Лотосы символизируют изначальную чистоту
            ума, не затронутую «грязью» измышлений (<em>vikalpa</em>): как лотос растёт из ила, но
            не загрязнён им, так и ум проявляется в сансаре, но по природе (<em>prakṛti</em>) сияюще
            чист.<a href="#ref-100" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-101"><sup>101</sup> <strong>«Узришь лики, взирающие друг на
                друга»</strong>
            (<em>anyonyavakramukhanirīkṣaṇa</em>) — если описывать в стиле тантры, то можно сказать,
            что Равана видит себя как центральное божество мандалы, окружённое множественными
            проявлениями самого себя. Это зримый символ недвойственности, где "я" растворяется в
            бесконечном взаимном созерцании; единое сознание проявляется как бесчисленные формы,
            каждая из которых одновременно субъект и объект созерцания. Предположу, что
            <strong><em>Ланкаватара</em></strong>
            — мост между сутрической философией и тантрической практикой визуализации.<a
                href="#ref-101" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-102"><sup>102</sup> Эта сфера опыта непостижима уму, который
            связан понятиями: её раскрывает тот, кто пребывает на ступени, вызывающей изумление
            свободой от кармической цепи «причина-следствие» благодаря спонтанному выражению
            сострадания, которое не имеет намерения, усилия или следа, через разнообразие форм.<a
                href="#ref-102" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-103"><sup>103</sup> <strong>«Многообразие форм ступени
                Татхагаты»</strong> — ступень Татхагаты (<em>tathāgata-bhūmi</em>) представляет
            собой состояние полного пробуждения, в котором проявление и шуньята нераздельны. Его
            сострадание естественно выражается в бесчисленных проявлениях ради блага всех существ.
            «Ступень» скорее всего, употреблена по аналогии со ступенями бодхисаттв, хотя то и
            принципиально иное бытие.<a href="#ref-103" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-104"><sup>104</sup> Брахма, Индра и Упендра (Вишну)
            символизируют три столпа сансары: творение, власть и сохранение космического порядка.
            Просветление Татхагаты превосходит их все — оно лежит вне самой структуры сансары, даже
            в её божественной форме.<a href="#ref-104" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-105"><sup>105</sup> <strong>Подъём на высоту семи
                пальм</strong> (<em>sapta tāla</em>) — возможно, символ полного превосхождения мира
            желаний (<em>kāmadhātu</em>). Подношение Раваны не ограничено ни одной сферой сансары:
            оно исходит из состояния, свободного от привязанности ко всем уровням условного
            существования.<a href="#ref-105" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-106"><sup>106</sup> <strong>Сцена подношения Раваны</strong>
            выражает его утверждённость на высших бхуми. Подъём с первой вершины, взлёт на высоту
            семи пальм и восседание на второй лотосовой вершине описывают выход за пределы мира
            желаний (<em>kāmadhātu</em>) и вхождение в сферу чистой земли (<em>buddha-kṣetra</em>),
            возникающей из преображённого ума. Подношения проявляются как естественное выражение
            ума, в котором устранено различие между дарящим, даром и получающим. Сам вопрос Раваны
            рождается из прозрения, и потому получает отклик Татхагаты в форме улыбки и
            дозволения.<a href="#ref-106" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-107"><sup>107</sup> <strong>«Пара дхарм»</strong> (<em>dharmadvayam</em>)
            — два аспекта условного опыта: дхарма («благое») и адхарма («неблагое»), которые оба
            подлежат оставлению.<a href="#ref-107" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-108"><sup>108</sup> Цитата отсылает к <strong><em>Ваджраччхедика-сутре</em></strong>:
            «Дхармы должны быть оставлены, тем более не-дхармы». Равана углубляет парадокс: если
            дхармы лишены самосущности, то что именно оставлять?<a href="#ref-108"
                                                                   class="citation-back">↩</a></p>
        <p class="my-2" id="citation-109"><sup>109</sup> <em>vikalpa-lakṣaṇa</em><a href="#ref-109"
                                                                                    class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-110"><sup>110</sup> <em>vikalpa-svabhāva-abhāva</em><a
                href="#ref-110" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-111"><sup>111</sup> <em>abhautika-bhautikā</em><a
                href="#ref-111" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-112"><sup>112</sup> <em>ālaya-vijñāna-aparijñānāt</em><a
                href="#ref-112" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-113"><sup>113</sup> <em>aviśeṣa-lakṣaṇā</em><a href="#ref-113"
                                                                                    class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-114"><sup>114</sup> <strong>«Видение волосков»</strong> (<em>keśoṇḍuka</em>)
            — классическая метафора иллюзорного восприятия: как человек с больными глазами видит в
            чистом пространстве несуществующие пятна, так и ум, не познавший <em>Алайя-виджняну</em>,
            принимает свои проекции за реальность.<a href="#ref-114" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-115"><sup>115</sup> <em>aśuddha-kṣaya-jñāna-viṣayiṇām</em><a
                href="#ref-115" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-116"><sup>116</sup> Суть вопроса: если все явления — продукт
            различающего мышления (<em>vikalpa</em>), лишённого собственной природы, то «оставление»
            не может быть актом отбрасывания объектов. Оно возможно только как узнавание того, что
            сам механизм различения изначально пуст (<em>śūnya</em>). Это не является достижением
            нового состояния, это прекращение веры в то, что дхармы существуют как объекты,
            подлежащие оставлению.<a href="#ref-116" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-117"><sup>117</sup> <strong>«Сфера различений невежд»</strong>
            (<em>bāla-vikalpa-gocara</em>) — здесь различение между дхармой и адхармой условно
            функционирует; кувшины, пламя, ветви воспринимаются как реально различные.<a
                href="#ref-117" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-118"><sup>118</sup> <strong>«Постижение благородного
                знания»</strong> (<em>Ārya-jñāna-adhigama</em>) — здесь различия не видны (<em>na
                darśana</em>), распознаётся единая природа всех явлений.<a href="#ref-118"
                                                                           class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-119"><sup>119</sup> Метафоры огня и семени показывают, что
            единая природа (огонь, семя) — это <strong><em>парамартха-сатья</em></strong>
            (абсолютная истина); а многообразие проявлений (пламя, ветви) — это <strong><em>самврити-сатья</em></strong>
            (условная истина), возникающее в зависимости от условий (<em>indhanavaśāt</em> — «в силу
            топлива»).<a href="#ref-119" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-120"><sup>120</sup> <em>pratyātma-gati-lakṣaṇa</em><a
                href="#ref-120" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-121"><sup>121</sup> <em>prativikalpa-pravṛtti</em><a
                href="#ref-121" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-122"><sup>122</sup> <strong>«Причины, качества и
                субстанции»</strong> (<em>kāraṇa-guṇa-dravya</em>) — категории философии <em>вайшешики</em>
            и <em>ньяи</em>, согласно которым явления реально существуют как субстанции
            (<em>dravya</em>), обладающие качествами (<em>guṇa</em>) и порождаемые причинами (<em>kāraṇa</em>).
            <strong><em>Ланкаватара</em></strong> отвергает это овеществление: дхармы — не
            субстанции, а проекции ума (<em>svacitta-dṛśya</em>), лишённые собственного тела (<em>alabdha-śarīra</em>).<a
                href="#ref-122" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-123"><sup>123</sup>
            <em>svacitta-dṛśya-dharmatā-abhiniveśāt</em><a href="#ref-123"
                                                           class="citation-back">↩</a></p>
        <p class="my-2" id="citation-124"><sup>124</sup> <strong>«Уже отброшены»</strong> —
            оставление не есть действие, а результат видения (<em>vidarśana</em>). Как только
            распознано, что кувшин — лишь проекция (<em>svacitta-dṛśya</em>), он теряет статус
            «реального объекта» и тем самым «отброшен». Итак, если всё — <em>vikalpa</em>, и <em>vikalpa</em>
            пуст, как оставить? Оставить нужно не сами <em>vikalpa</em> (различения), а веру (<em>abhiniveśa</em>)
            в то, что они — внешняя реальность (<em>dharmatā</em>) через видение (<em>vidarśana</em>),
            что они — <em>svacitta-dṛśya</em> (лишь видимое умом). Как только узнано — они уже
            отброшены (<em>prahīṇa bhavanti</em>).<a href="#ref-124" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-125"><sup>125</sup> <em>alabdha-ātmaka</em><a href="#ref-125" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-126"><sup>126</sup> <em>lakṣaṇa-vikalpa-apracāra</em><a href="#ref-126" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-127"><sup>127</sup> <em>ahetuka</em><a href="#ref-127" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-128"><sup>128</sup> <strong>«Не-возникновение»</strong> (<em>Apravṛtti</em>) — или «отсутствие проявления». Термин указывает на статус объектов, которые, подобно «рогам зайца», никогда не возникали и не имеют причин для проявления. Их не-возникновение видится парадоксально (<em>bhūta-abhūtataḥ</em>): как существующее (<em>bhūta</em>) — поскольку мы говорим о нём, мыслим его; как несуществующее (<em>abhūta</em>) — поскольку его нет реально. Этот парадокс указывает на абсурдность попыток схватить (<em>grahaṇa</em>) такие "объекты" сознанием (<em>vijñāna</em>) или мыслить их через признаки (<em>lakṣaṇa</em>). Подобно рогам зайца, все проявления различающего мышления (<em>vikalpa-bhāva</em>) лишены сущности и не могут быть схвачены.<a href="#ref-128" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-129"><sup>129</sup> <em>na lakṣaṇataḥ kalpyāḥ</em><a href="#ref-129" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-130"><sup>130</sup> <em>saṃvyavahārārtham</em><a href="#ref-130" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-131"><sup>131</sup> <em>agrahaṇataḥ vijñānena</em><a href="#ref-131" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-132"><sup>132</sup> <em>vikalpa-bhāva</em><a href="#ref-132" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-133"><sup>133</sup> <strong><em>Visarjita</em></strong> — буквально «отпущенный» или «разрешённый». В контексте: прежние Будды ответили на этот вопрос (как делает сейчас Будда Шакьямуни), но сам вопрос порождён различением (<em>vikalpa</em>), и потому ответ не может быть окончательным в рамках различающего мышления. Истинное "разрешение" — выйти за пределы самого вопроса.<a href="#ref-133" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-134"><sup>134</sup> <strong>«Мыслительное разрастание»</strong> (<em>prapañca</em>) — самовоспроизводящийся поток ума, который, опираясь на различение (<em>vikalpa</em>), делит неделимое на противоположности — «я» и «не-я», «внутри» и «вне», «благо» и «неблаго» — и поддерживает это разделение через речь, имена и признаки. Этот поток создаёт видимость связного постигаемого мира, но при внимательном рассмотрении обнаруживает внутренние противоречия: одному и тому же объекту приписываются взаимоисключающие свойства — существующий и преходящий, единый и составной, реальный и иллюзорный. Так <em>prapañca</em> сама себя разрушает, обнажая свою безосновательность.<a href="#ref-134" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-135"><sup>135</sup> <strong>«Не полагают и не полагаемы»</strong> (<em>na kalpante na kalpyante</em>) — <em>kalpana</em> (от корня √<strong>kḷp</strong>) означает умственное действие установления чего-либо как реально существующего: например, «я» как субъект, «мир» как объект, «дхармы» как сущности. Татхагаты не осуществляют такого действия — они не принимают проекции ума за реальность, и их самих нельзя принять за объект подобного полагания, поскольку они лишены природы, доступной для различающего мышления (<em>vikalpa</em>).<a href="#ref-135" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-136"><sup>136</sup> Смотри примечание 7 в <strong><em>Ваджрачхедике</em></strong>.<a href="#ref-136" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-137"><sup>137</sup> <strong>«Вышедший за пределы различения и его отсутствия»</strong> (<em>vikalpāvikalpāgatena</em>) — имеется в виду, что освобождение не есть ни пребывание в различающем мышлении (<em>vikalpa</em>), ни фиксация/"замораживание ума" на его отсутствии (<em>avikalpa</em>). Истинное положение — вне обеих крайностей, ибо даже «отсутствие различения» становятся оковами, если ум цепляется за него как за достижение.<a href="#ref-137" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-138"><sup>138</sup> <strong>«Фигуры на стене»</strong> (<em>bhittikhacitavigraha</em>) — метафора полной неподвижности сансары: всё «движение» — лишь иллюзия, порождённая умом, который придаёт жизнь мёртвым изображениям.<a href="#ref-138" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-139"><sup>139</sup> <strong>«Магическое изваяние»</strong> (<em>nirmitapratima</em>) — указание на автоматизм сансары: мир действует, как одушевлённая кукла, но в нём нет ни деятеля, ни живой души (<em>атмана</em>).<a href="#ref-139" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-140"><sup>140</sup> <strong><em>sva-vikalpa-grahaṇa</em></strong>. Здесь <em>grahaṇa</em> — «схватывание, захватывание» от корня √<strong>grah</strong> — «хватать, брать, захватывать». Ум «хватает» различения, принимает их за реальные объекты, держится за них и пленяется ими.<a href="#ref-140" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-141"><sup>141</sup> <strong>«Питают различения»</strong> (<em>vikalpayanti puṣṇanti</em>) — ум не только создаёт различения, но и поддерживает их вниманием и верой, делая их «реальными». Оставление — прекращение этого питания.<a href="#ref-141" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-142"><sup>142</sup> <strong>«Покой»</strong> — обозначение единонаправленности (<em>ekāgratā</em>) — не концентрация на объекте, а возвращение ума к источнику, где различения затихают, и раскрывается Татхагатагарбха.<a href="#ref-142" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        </div>

        <p class="my-2" id="citation-143"><sup>143</sup> <strong>«Цветок в небе»</strong> (<em>khapuṣpa</em>) — традиционный буддийский образ невозможного, иллюзорного, не имеющего основы в реальности. Используется для обозначения явлений, лишённых собственной природы.<a href="#ref-143" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-144"><sup>144</sup> <strong>«Майя»</strong> (<em>māyā</em>) — иллюзия, мираж; в буддийском контексте — метафора нереальности, обманчивости обычного восприятия явлений, которые кажутся существующими, но лишены устойчивой сущности.<a href="#ref-144" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-145"><sup>145</sup> <strong>«Лишены [природы] ума и сознания»</strong> (<em>cittavijñānavarjitāḥ</em>) — указание на то, что дхармы не являются ни объектами ума (<em>citta</em>), ни содержанием различающего сознания (<em>vijñāna</em>); они не подлежат двойственному постижению.<a href="#ref-145" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-146"><sup>146</sup> <strong>Употребление слова «всегда»</strong> (<em>sadā</em>) критически важно для метафизики <strong><em>Ланкаватары</em></strong>. Оно указывает на то, что призрачность и отсутствие собственной сущности — это не временное состояние мира и не субъективная ошибка отдельного человека. Это фундаментальный закон: не существует и никогда не существовало «объективного» или «реального» мира, который предшествовал бы этому «сну». Мир является проекцией сознания изначально и в каждый момент своего существования. Признание того, что природа сна присуща миру всегда, позволяет Будде проявлять Сострадание: Он входит в этот сон как активный участник, ни на мгновение не забывая о его иллюзорности.<a href="#ref-146" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-147"><sup>147</sup> Этот стих раскрывает парадокс Дхармакаи. Её природа подобна майе и сновидению, она лишена любых устойчивых признаков, потому не поддаётся описанию через утвердительные суждения. Всякое приписывание Дхармакае каких-либо характеристик ограничивает её безмерность, превращая недвойственное в объект различения. Подлинное восхваление (<em>stava</em>) Татхагаты не может быть словесным, оно необходимо становится йогическим созерцанием, вхождением в недвойственное постижение шуньяты.<br><br>
            Утверждение «не-возникновение есть истинное возникновение» (<em>anutpādaḥ sa saṃbhavaḥ</em>) выражает ключевые положения: а) дхармы лишены собственной сущности (<em>niḥsvabhāva</em>) — они не существуют независимо, а проявляются в зависимости от движения ума; б) с точки зрения высшей истины (<em>paramārtha</em>), — всё видимое (<em>dṛśya</em>) есть то, что проявляется умом-как-таковым (<em>svacitta</em>); принятие этого за реальное рождение — признак омрачения (<em>kleśa</em>); в) истинное «присутствие» дхармы — это постижение её изначального не-рождения. Так реальность видится тому, чей ум свободен от цепляния. Постижение <em>шуньяты</em> и есть высшее постижение подлинной природы.<a href="#ref-147" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-148"><sup>148</sup> <em>Pratyātmagatigocaram</em> — область личного непосредственного постижения и здесь Будда обещает не просто «рассказать факты», а указать направление, в котором Махамати должен направить свой ум, чтобы <em>увидеть</em> реальность самостоятельно.<a href="#ref-148" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-149"><sup>149</sup> <strong>«Различающее рассуждение»</strong> (<em>tarka</em>) и <strong>«заблуждение»</strong> (<em>bhrānti</em>): Махамати начинает с фундаментального вопроса о механике мысли. <em>Тарка</em> понимается как линейное логическое мышление, зуд классифицирующего ума, умствование, что само по себе является формой «заблуждения» (<em>бхранти</em>), так как делит реальность на субъект и объект.<a href="#ref-149" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-150"><sup>150</sup> <strong>«Отсутствие [ментальных] образов»</strong> (<em>nirābhāsa</em>): Высшая стадия медитации, когда ум не проецирует картинки, формы и понятия, «зеркало» ума перестает отражать что-либо, кроме своей собственной природы. Это состояние «без-отражения». Махамати спрашивает о технологии достижения состояния, где нет проекции форм.<a href="#ref-150" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-151"><sup>151</sup> <strong>«Тройственное бытие»</strong> (<em>tribhava</em>): Мир желаний (<em>кама</em>), мир форм (<em>рупа</em>) и мир без форм (<em>арупа</em>). Махамати интересуется тем, кто способен «разрушить» эту структуру сансары.<a href="#ref-151" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-152"><sup>152</sup> <strong>«Отвращение от видимого»</strong> (<em>dṛśyān nivartate</em>): Ключевой термин йогачары. Это процесс, когда сознание перестает течь «наружу» к объектам и возвращается к своей чистой основе, это поворот (<em>парāвритти</em>) потока сознания от объектов к основе. Махамати просит описать механизм этого «обратного хода».<a href="#ref-152" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-153"><sup>153</sup> <strong>«Роды и без рода»</strong> (<em>gotra-agotra</em>): Этот вопрос Махамати рассматривается как запрос о духовной предрасположенности. <em>Готра</em> — это «семья» или «генетический код» пробуждения. Махамати спрашивает, почему одни существа обладают потенциалом Будды, а другие (<em>аготра</em>) кажутся лишенными его.<a href="#ref-153" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-154"><sup>154</sup> <strong>«Мгновенность распада»</strong> (<em>kṣaṇa-bhaṅga</em>) — «мгновенный распад»; доктрина, которую <strong><em>Ланкаватара-сутра</em></strong> критикует как недостаточно глубокую. В то время как школы хинаяны (в частности, <em>вайбхашика</em>) используют идею моментального разрушения дхарм для отрицания постоянства «Я», <strong><em>Ланкаватара</em></strong> видит в этом скрытый реализм: чтобы нечто «разрушилось», оно должно сначала «возникнуть». С позиции недвойственности Будда указывает, что дхармы не «мгновенны», они изначально не рождены (<em>анутапада</em>). Если объект — лишь проекция ума (<em>svacitta-dṛśya</em>), то у него нет даже мгновения реального бытия, чтобы претерпеть распад. Таким образом, идея мгновенности отвергается ради более радикального постижения: мир не «быстро меняется», он никогда не возникал вне различающего ума.<a href="#ref-154" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-155"><sup>155</sup> <strong>Нирихика</strong> (<em>nirīhika</em>) — «безусильность» или «отсутствие воления». Термин указывает на то, что мир функционирует без внешнего творца-управителя (<em>īśvara</em>) и без внутреннего субъекта-деятеля (<em>kartṛ</em>). Космос в <strong><em>Ланкаватаре</em></strong> описывается как процесс, лишенный волевого импульса; он разворачивается спонтанно (<em>sahaja</em>), подобно магической иллюзии или отражению. Постижение мира как <em>nirīhika</em> означает осознание того, что за потоком явлений не стоит никакая основополагающая воля. Для бодхисаттвы это становится основой безусильного действия (<em>анабхисамскара</em>): когда устраняется иллюзия «деятеля», поступки перестают порождать кармическую связь, превращаясь в свободную игру мудрости.<a href="#ref-155" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-156"><sup>156</sup> <strong>«Изложение без букв»</strong> (<em>nirakṣara</em>): Прямая отсылка к знаменитому утверждению <strong><em>Ланкаватары</em></strong> о том, что истинная Дхарма не может быть передана буквами (<em>акшара</em>). Махамати просит разрешить парадокс: как Будда учит, если истина безмолвна?<a href="#ref-156" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-157"><sup>157</sup> <strong>«Два вида отсутствия "Я"»</strong> (<em>nairātmyaṃ dvidhā</em>): Махамати имеет в виду отсутствие «Я» в личности (<em>пудгала-найратмья</em>) и отсутствие «Я» дхарм (<em>дхарма-найратмья</em>).<a href="#ref-157" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-158"><sup>158</sup> <strong>«Очищение познаваемого»</strong> (<em>jñeya-viśuddhi</em>) — этот вопрос касается устранение <em>джнея-авараны</em> (<em>jñeya-āvaraṇa</em>), или «завесы познаваемого». В отличие от «завесы клеш» (<em>клеша-аварана</em>), порождающей личное страдание, завеса познаваемого — это тончайшее интеллектуальное препятствие, мешающее всеведению Будды. Она заключается в самой привычке ума разделять реальность на «познающего» и «познаваемое», наделяя объекты ложной плотностью и внешней независимостью. Фраза <em>jñeyaṃ viśudhyati</em> означает, что когда ум перестает проецировать двойственность, «объект» познания очищается от наслоений понятийной ложности. В этот момент мир перестает восприниматься как совокупность внешних явлений и раскрывается в своей истинной природе как <em>татхата</em> (таковость), что делает возможным достижение недвойственного всеведения.<a href="#ref-158" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-159"><sup>159</sup> <strong>«Лишь именование»</strong>
            (<em>prajñapti-mātra</em>) — технический термин, указывающий на условный статус всех
            явлений. Согласно <strong><em>Ланкаватаре</em></strong>, весь проявленный мир возникает, когда ум,
            движимый привычками различения, наделяет именами (<em>nāma</em>) фрагменты потока опыта. Эти имена создают видимость устойчивых, независимых объектов, хотя на самом деле за ними нет никакой, имеющей некую сущность, основы. Постичь, что всё есть «лишь именование», значит увидеть, что мы взаимодействуем не с реальными явлениями, а с проекциями собственного ума, зафиксированными в языке. Это осознание ослабляет цепляние к формам, так как йогин распознаёт, что за именами скрывается таковость (<em>tathatā</em>) — недвойственная, не имеющая границ, признаков или определений. Иными словами: мир — это игра имён, лишённая автора.<a href="#ref-159" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-160"><sup>160</sup> <strong>«Иччхантика»</strong>
            (<em>icchantika</em>) — термин, обозначающий существ, кажущихся лишёнными потенциала
            пробуждения. В <strong><em>Ланкаватаре</em></strong> этот статус рассматривается диалектически:<br>
            <em>Иччхантики по омрачению</em> — те, чьи корни благого (<em>kuśala-mūla</em>) истощены вследствие тяжких проступков против Дхармы. Их ум настолько омрачён, что они не проявляют стремления к освобождению. В относительном смысле их называют «лишёнными семени Будды» (<em>bodhīccha</em>).<br>
            <em>Иччхантики по состраданию</em> — великие бодхисаттвы, давшие обет не входить в окончательную нирвану, пока не освободится последнее существо. Поскольку круговорот бесконечен, они добровольно остаются вне угасания — не из-за кармы, а из безмерного сострадания.<br>
            Однако на абсолютном уровне никто не лишён природы Будды. Учение о «безнадёжности» — искусное средство (<em>upāya</em>), применяемое Татхагатой, чтобы пробудить страх перед омрачениями у тех, кто погружён в пороки. В свете учения о <em>Татхагатагарбхе</em> — изначальной чистоте ума — состояние <em>иччхантики</em> не является вечным. Оно длится лишь до тех пор, пока действуют механизмы различения (<em>vikalpa</em>), скрывающие подлинную природу сознания. Таким образом, стать <em>иччхантикой</em> — значит оказаться в крайности: либо в самозамкнутости омрачения, либо в самоотдаче сострадания. Но даже в этой крайности природа Будды остаётся нетронутой, подобно золоту, покрытому грязью.<a href="#ref-160" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-161"><sup>161</sup> <strong>«Знаки и признаки в уходах и рождениях»</strong> — это вопрос о механизме кармической преемственности. Под «знаком» (<em>liṅga</em>) понимается скрытая потенция — семя в <em>Алайя-виджняне</em>, определяющее направление следующего перерождения. Под «признаком» (<em>lakṣaṇa</em>) — внешние проявления: форма тела, речь, поведение, в которых отражаются прошлые склонности и закладываются условия будущего. В свете йогачары, однако, нет никакого «существа», переходящего из жизни в жизнь. Есть лишь поток отпечатков (<em>vāsanā-prabandha</em>), который, подобно магниту, притягивается к соответствующим условиям. Постичь эти «знаки» — значит увидеть, как ум связывает мгновения опыта в иллюзию непрерывного «я», хотя на самом деле между смертью и рождением нет ни субъекта, ни преемника — только движение различения (<em>vikalpa</em>), лишённое опоры.<a href="#ref-161" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-162"><sup>162</sup> <strong>Риши Диргхатапас</strong>
            (<em>Dīrghatapas/Dīrghatamas</em>) — мудрец, упоминаемый в <strong><em>Ригведе;</em></strong> его имя
            буквально означает «долгий мрак». В контексте <strong><em>Ланкаватары</em></strong> его упоминание
            поднимает вопрос: откуда берётся знание? Диргхатапас символизирует предел прозрения в рамках небуддийских путей: он, будучи слепым, «видел» истину внутренним взором и провозглашал, что «Истина едина, но мудрецы называют её разными именами». Однако Будда указывает, что даже такие озарения являются лишь проявлением собственного ума (<em>svacitta-dṛśya</em>). Даже величайший мистический опыт, если он не сопровождается поворотом основы (<em>āśraya-parāvṛtti</em>), остаётся внутри круга различения (<em>vikalpa</em>). Тот, кто принимает своё видение за окончательную истину, не выходит за пределы воображаемой природы (<em>parikalpita-svabhāva</em>).<a href="#ref-162" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-163"><sup>163</sup> <strong>Формы миров</strong> — лотос, лев, Шриватса — указывают на бесконечное разнообразие земель Будд (<em>buddhakṣetra</em>), возникающих как проявление чистого ума. Форма мира не предопределена внешней необходимостью. Она зависит от благословенной силы (<em>adhiṣṭhāna</em>) Татхагаты, пребывающего в том мире, и кармы существ, его населяющих. Лотос символизирует мир, рождённый из чистоты и потенциала пробуждения. Лев — мир, где проявляется неодолимая мощь Дхармы. Шриватса — бесконечный узел, выражающий неразрывную взаимозависимость всех дхарм.<a href="#ref-163" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-164"><sup>164</sup> <strong>Будды Мудрости Таковости</strong> (<em>tathatā-jñāna-buddha</em>) соответствуют Дхармакае. Это — сама таковость реальности, лишённая признаков и различений. Здесь нет ни личности, ни познающего — только недвойственное постижение, доступное лишь в сфере личного прозрения (<em>pratyātmagati</em>), когда исчезает разделение на «я» и «мир».<br>
            <strong>Будды созревания заслуг</strong> (<em>vipākaja-buddha</em>) соответствуют Самбхогакае — Телу Блаженства. Это — величественное проявление Татхагаты в чистых мирах, возникшее как плод (<em>vipāka</em>) бесконечного накопления мудрости и заслуг. Эта форма доступна восприятию бодхисаттв, пребывающих в глубоком самадхи.<br>
            <strong>Будды воплощения</strong> (<em>nirmāṇika-buddha</em>) соответствуют Нирманакае — Телу Проявлений. Это — исторические Будды (как Шакьямуни) или нирманы, которые Татхагата являет в мирах желаний. Они принимают облик, речь и действия, соответствующие уму существ, чтобы вести их к пробуждению.<a href="#ref-164" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-165"><sup>165</sup> <strong>Сиддханта</strong>
            (<em>siddhānta</em>) в <strong><em>Ланкаватаре</em></strong> имеет два аспекта: личное постижение
            (<em>pratyātma-siddhānta</em>) — недвойственное, невыразимое, свободное от признаков и рассудочного мышления; изложение Учения (<em>deśanā-siddhānta</em>) — словесное указание, приспособленное к слушателям. Тиртхики также выдвигают свои «сиддханты» (атомы, время и т.д.), но Будда подчёркивает: истинная <em>сиддханта</em> — там, где все воззрения прекращаются. Держаться за неё как за мнение — значит утратить её.<a href="#ref-165" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-166"><sup>166</sup> <strong>«Лес из мужчин и женщин»</strong> — здесь, вероятно, символ двойственности восприятия. В адах такой лес — ловушка для страстных: иллюзорные образы желанных тел на деревьях из листьев-лезвий ведут к мучениям. В чистых землях — знак чудесного рождения, лишённого биологической кармы. Махамати указывает в вопросе, что одна и та же форма становится адом или раем в зависимости от состояния сознания. Ни привлекательность, ни ужас не принадлежат объекту — они суть проявление собственного ума (<em>svacitta-dṛśya</em>).<a href="#ref-166" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-167"><sup>167</sup> В этом эпизоде Будда применяет особый педагогический приём — священную иронию. Махамати, выступая от лица интеллектуала, стремится охватить Дхарму рассудочным знанием: его вопросы охватывают всё — от природы Нирваны до количества атомов в горчичном зерне. Это — попытка ума построить полную систему различений, где каждому явлению дано имя, мера и место.<br>
            Ответ Будды двоякий:<br>
            <em>Доведение до абсурда (шлоки 71—80):</em> Он зеркально отражает эту страсть к детализации, предлагая вопросы ещё более мелочные и бессмысленные — сколько атомов в брови? Сколько пал весит гора Меру? Тем самым Он показывает: накопление информации не есть постижение. Ум может бесконечно дробить явления, но так и не коснётся их недвойственной природы.<br>
            <em>Смешение уровней (шлоки 81—90):</em> Будда намеренно ставит в один ряд вопросы о Таковости и о «вкусности еды», о Пустоте и о половом влечении. Это — шоковая терапия для рассудка: разрушается иерархия «духовного» и «мирского», ибо для омрачённого ума любое различение — преграда, даже то, что касается Будды.<a href="#ref-167" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-168"><sup>168</sup> <strong>Bhramarā</strong> (букв.
            «пчелы») — в контексте <strong><em>Ланкаватара-сутры</em></strong> данный термин используется
            метафорически. Он указывает на «блуждающие умы» или живых существ, чье сознание из-за беспокойства и привязанностей постоянно «перелетает» от одного чувственного объекта к другому, подобно пчелам на лугу. Корень слова <strong>bhram</strong> («блуждать», «вращаться», «ошибаться») подчеркивает сансарическую природу такого сознания, вовлеченного в круговорот перерождений и ложных различений.<a href="#ref-168" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-169"><sup>169</sup> <strong><em>svapratyātmāryajñāna</em></strong> — «самопостигаемая мудрость благородных».<a href="#ref-169" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-170"><sup>170</sup> Этот список не утверждает и не отрицает понятия. Будда показывает, что каждое из них, взятое как объект цепляния, становится преградой. Только когда ум не зацепляется ни за X, ни за не-X, раскрывается недвойственная реальность.<a href="#ref-170" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-171"><sup>171</sup> <strong>«Прекращение потока»</strong> (<em>prabandha-nirodha</em>) — прекращение непрерывной цепи сцепленных состояний, в которой один акт различения мгновенно порождает следующий под влиянием кармических отпечатков. Этот поток — инерция сансарического мышления, при которой ум функционирует как автоматический «проектор», воспроизводящий прошлые галлюцинации. При <em>prabandha-nirodha</em> прекращается не сам ум, а его автоматизм — то есть признак деятельности (<em>karma-lakṣaṇa</em>), а не признак рождения (<em>jāti-lakṣaṇa</em>).<a href="#ref-171" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-172"><sup>172</sup> <strong>«Прекращение признаков»</strong> (<em>lakṣaṇa-nirodha</em>) — прекращение привязанности к признакам (<em>lakṣaṇa</em>), через которые ум строит видимость внешнего мира. Обычное сознание воспринимает готовые объекты, «построенные» умом, а не поток различений. Эти признаки — умозрительные метки, придающие зыбким проекциям ума иллюзию плотности и самостоятельности. Освобождаясь от цепляния за признаки, ум перестаёт наделять опыт характеристиками формы, цвета или ценности. Если <em>prabandha-nirodha</em> — это остановка инерции временного потока, то <em>lakṣaṇa-nirodha</em> — растворение воображаемой плотности мира. Это состояние напрямую ведёт к Без-образности (<em>nirābhāsa</em>) — высшей мудрости, в которой сознание отражает Таковость (<em>tathatā</em>) без наслоения различений (<em>vikalpa</em>).<a href="#ref-172" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-173"><sup>173</sup> <strong>«Возникновение потока»</strong> (<em>prabandha-utpāda</em>) — непрерывное воспроизводство двойственных состояний сознания, порождающее иллюзию временной непрерывности. Это динамический процесс, в котором различающий ум (<em>mano-vijñāna</em>) беспрестанно проецирует кармические отпечатки (<em>vāsanā</em>), под воздействием «ветров» внешних объектов, превращая семена <em>Алайи-виджняны</em> в волны восприятия. Так возникает самоподдерживающаяся инерция, создающая ложное чувство длительности «я» и «мира». Для бодхисаттвы этот поток — танец различений, подлежащий осознанию и прекращению через йогу.<a href="#ref-173" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-174"><sup>174</sup> <strong>«Возникновение
                признака»</strong> (<em>lakṣaṇa-utpāda</em>) — акт умозрительного выделения,
            посредством которого ум наделяет недвойственный поток опыта конкретными свойствами —
            формой, цветом, плотностью — и закрепляет их через имена. Это — первичный механизм
            иллюзии, превращающий Таковость (<em>tathatā</em>) в мир разделённых и «плотных»
            объектов, доступных для схватывания (<em>grahaṇa</em>) как «внешних». В
            <strong><em>Ланкаватаре</em></strong> это считается основой омрачения (<em>āvaraṇa</em>): если <em>prabandha-utpāda</em> создаёт иллюзию времени, то <em>lakṣaṇa-utpāda</em> — иллюзию пространственной плотности. Этот процесс подлежит прямому постижению.<a href="#ref-174" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-175"><sup>175</sup> <strong>«Пребывание потока»</strong> (<em>prabandha-sthiti</em>) — динамическая устойчивость различающего сознания (<em>mano-vijñāna</em>), обеспечивающая непрерывность иллюзорного опыта. Это — инерция сансары, благодаря которой поток кармических проекций самоподдерживающе длится, создавая для омрачённого ума иллюзию временной непрерывности «я» и мира.<a href="#ref-175" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-176"><sup>176</sup> <strong>«Пребывание признака»</strong> (<em>lakṣaṇa-sthiti</em>) — фаза умозрительного закрепления, в которой ум наделяет мгновенные проекции статусом длительного и плотного существования. Это — умственный клей, превращающий поток «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>) в устойчивый мир объектов, что делает их доступными для схватывания (<em>grahaṇa</em>) и порождает страдание.<a href="#ref-176" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-177"><sup>177</sup> <strong>«Признак деятельности»</strong>, <strong>«признак развёртывания»</strong> (<em>pravṛtti-lakṣaṇa</em>) — характеристика активного развёртывания сознания в режиме различения. В отличие от <em>karma-lakṣaṇa</em> — накопления кармических отпечатков (<em>vāsanā</em>), <em>pravṛtti-lakṣaṇa</em> описывает сам процесс проявления различений (<em>vikalpa</em>) из скрытых семян. Это — деятельный аспект ума, который может быть прекращён (<em>nirodha</em>) без уничтожения <em>jāti-lakṣaṇa</em> — признака возникновения.<a href="#ref-177" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-178"><sup>178</sup> <strong>«Признак действия»</strong> (<em>karma-lakṣaṇa</em>) — аспект сознания, посредством которого деятельность различения превращается в новые кармические отпечатки. Это механизм накопления, создающий условия для будущих циклов развёртывания. Именно этот признак прекращается при <em>prabandha-nirodha</em> (прекращение потока), а не <em>jāti-lakṣaṇa</em> (признак рождения).<a href="#ref-178" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-179"><sup>179</sup> <strong>«Признак рождения»</strong> или <strong>«возникновения»</strong> (<em>jāti-lakṣaṇa</em>) — аспект сознания, отвечающий за проявление нового цикла опыта — как тела, так и мира, воспринимаемого умом. Этот признак завершает механизм сансарического воспроизводства, описывая, как кармические отпечатки проявляются в виде «видимого собственным умом» (<em>svacitta-dṛśya</em>). Постижение его иллюзорности и изначальной нерождённости (<em>anutpāda</em>) всех явлений устраняет этот признак при повороте основы (<em>āśraya-parāvṛtti</em>).<a href="#ref-179" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-180"><sup>180</sup> <strong>«Сознание проявления»</strong> (<em>khyāti-vijñāna</em>) — аспект сознания, мгновенно и одновременно проецирующий весь феноменальный мир. Подобно зеркалу, оно являет образы тела, объектов и вместилища из скрытых отпечатков <em>Алайи-виджняны</em>. Это — первая кажимость (<em>ābhāsa</em>), предшествующая всякому рассуждению, и создающая сцену сансарического опыта.<a href="#ref-180" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-181"><sup>181</sup> <strong>«Сознание различения объектов»</strong> (<em>vastu-prativikalpa-vijñāna</em>) — рассудочный аспект ума, который анализирует, классифицирует и наделяет именами образы, проявленные сознанием проявления (<em>khyāti-vijñāna</em>). Оно работает последовательно, превращая единый поток «видимого собственным умом» (<em>svacitta-dṛśya</em>) в мир разделённых и плотных объектов. Это сознание является главным инструментом умозрительного различения (<em>vikalpa</em>), поддерживающий иллюзию внешней плотности.<a href="#ref-181" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-182"><sup>182</sup> <strong>«Непостижимое преобразование
                отпечатков»</strong> (<em>acintya-vāsanā-pariṇāma</em>) — процесс, посредством
            которого скрытые склонности (<em>vāsanā</em>), накопленные в <em>Алайя-виджняне</em>,
            созревают (<em>pariṇāma</em>) и проявляются как мир, тело и обстоятельства. Он
            называется «непостижимым» (<em>acintya</em>), потому что не поддаётся рассудочному
            мышлению (<em>tarka</em>), протекает вне осознанного контроля, и не может быть
            воспринят как объект. В <strong><em>Ланкаватаре</em></strong> этот термин указывает, что весь проявленный мир не является внешней реальностью, это динамика самого ума, движимая безначальными привычками различения. Бодхисаттва, пребывая в йоге видимого собственным умом (<em>svacitta-dṛśya-yoga</em>), не видит «проекции», а распознаёт единый поток, в котором нет разделения на внутреннее и внешнее.<a href="#ref-182" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-183"><sup>183</sup> <strong>«Различение объектов»</strong> (<em>viṣaya-vikalpa</em>) — умозрительное разделение, посредством которого ум наделяет свои проекции статусом внешних и независимых предметов; умственное искажение, создающее иллюзию объективного мира, противопоставленного субъекту, и служащее опорой для возникновения привязанностей и омрачений. Прекращение <em>viṣaya-vikalpa</em> является необходимым условием для возвращения ума в состояние недвойственного покоя.<a href="#ref-183" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-184"><sup>184</sup> <strong>«Отпечатки безначального понятийного многообразия»</strong> (<em>anādi-prapañca-vāsanā</em>) — накопленная в сознании вязкая инерция, заставляющая ум проецировать «воспринимаемое собственным умом» в виде сложной сети имён и различений. Эта словесная раздутость (<em>prapañca</em>) создаёт ложную множественность там, где существует лишь единая Таковость (<em>tathatā</em>). Освобождение от этих отпечатков означает переход от рассудочного знания к прямому постижению «только-ума» (<em>cittamātra</em>).<a href="#ref-184" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-185"><sup>185</sup> <strong>«Ложное воображение»</strong> (<em>abhūta-parikalpa</em>) — фундаментальный механизм ума, создающий иллюзию разделения на субъект и объект. Это процесс воображения того, чего нет, который превращает недвойственную Таковость (<em>tathatā</em>) в мир множественных форм. Постижение этого процесса как лишённого собственной природы позволяет йогину остановить словесную раздутость (<em>prapañca</em>) и вернуться к прямому постижению «видимого собственным умом» (<em>svacitta-dṛśya</em>).<a href="#ref-185" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-186"><sup>186</sup> <em>lakṣaṇa-nirodha</em><a href="#ref-186" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-187"><sup>187</sup> <em>prabandha-nirodha</em><a href="#ref-187" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-188"><sup>188</sup> <strong>«Отпечатки пагубной косности безначального понятийного разрастания»</strong> (<em>anādi-prapañca-dauṣṭhulya-vāsanā</em>) — пагубная косность/порочность/тяжесть/вязкость/предрасположенность сознания, обусловленная безначальной привычкой к раздроблению «воспринимаемого собственным умом» через язык и умозрительные различения. Эта дурная предрасположенность заставляет ум воспринимать мир как вязкую сеть внешних и плотных объектов, блокируя доступ к лёгкости и ясности недвойственной мудрости.<a href="#ref-188" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-189"><sup>189</sup> <strong>«Воспринимаемое собственным умом»</strong> (<em>svacitta-dṛśya</em>) — положение, согласно которому весь проявленный мир является не чем-то «внешним», а проекцией самого ума. Постижение всего опыта как <em>svacitta-dṛśya</em> устраняет иллюзию разделённости между наблюдаемым и наблюдателем, позволяя йогину увидеть в каждом объекте лишь прозрачную игру ума, свободную от ложной плотности и независимого бытия.<a href="#ref-189" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-190"><sup>190</sup> <strong>«Сознание проявлений»</strong>, <strong>«активные сознания»</strong> (<em>pravṛtti-vijñāna</em>) — совокупность семи активных уровней сознания: пяти чувственных, ментального и сознания-<em>манас</em>, которые развёртываются из <em>Алайи-виджняны</em> под воздействием объектов, воспринимаемых как внешние. Это динамический аспект ума, ответственный за понятийное различение и создание иллюзии двойственности.<a href="#ref-190" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-191"><sup>191</sup> <em>jāti-lakṣaṇa</em><a href="#ref-191" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-192"><sup>192</sup> <strong>«Признак собственного рождения»</strong> (<em>svajāti-lakṣaṇa</em>) — характеристика, согласно которой каждое явление кажется возникающим в силу собственной природы. Если <em>jāti-lakṣaṇa</em> (признак рождения) описывает сам факт проявления мира из ума, то <em>svajāti-lakṣaṇa</em> указывает, как ум наделяет каждую проекцию иллюзией уникальности и независимости. Когда этот термин применяется к <em>Алайе-виджняне</em>, её <em>svajāti-lakṣaṇa</em> не прекращается на уровне относительной истины, пока не произойдёт <em>поворот основы</em> (<em>āśraya-parāvṛtti</em>). До этого <em>поворота</em> <em>Алайя</em> функционирует как относительно устойчивый поток на уровне условной истины (<em>saṃvṛti-satya</em>), обеспечивающий непрерывность кармических отпечатков и проявление активных сознаний. Однако её кажущаяся устойчивость — это не абсолютная реальность (<em>paramārtha</em>), а лишь тончайший уровень различений «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>), который подлежит преображению при <em>parāvṛtti</em> (повороте основы).<a href="#ref-192" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-193"><sup>193</sup> <em>karma-lakṣaṇa</em><a href="#ref-193" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-194"><sup>194</sup> <strong>«Первоматерия, Дух, Ишвара, Время, Атомы»</strong> — перечисление основных метафизических понятий небуддийских школ: <em>pradhāna</em> — санкхья, <em>puruṣa</em> — санкхья, <em>Īśvara</em> — шиваизм/веданта, <em>kāla</em> — адживика, <em>aṇu</em> — вайшешика.<a href="#ref-194" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-195"><sup>195</sup> В <strong><em>Ланкаватаре</em></strong> термин
            <em>svabhāva</em> используется двояко: первые шесть видов описывают ложные природы, приписываемые явлениям различающим умом; седьмая (<em>niṣpatti-svabhāva</em>) — истинную природу, Таковость (<em>tathatā</em>), раскрывающуюся при отсечении всех ложных проекций.<a href="#ref-195" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-196"><sup>196</sup> <em>samudaya-svabhāva</em> — «природа совокупного возникновения»; заблуждение, будто явления реально возникают как сумма своих частей или условий.<a href="#ref-196" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-197"><sup>197</sup> <em>bhāva-svabhāva</em> — «природа бытия»; ложная вера в то, что объекты обладают независимым существованием.<a href="#ref-197" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-198"><sup>198</sup> <em>lakṣaṇa-svabhāva</em> — «природа признаков»; убеждённость в том, что характеристики объектов (цвет, форма) принадлежат самим объектам, а не являются проекциями различающего ума.<a href="#ref-198" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-199"><sup>199</sup> <em>mahābhūta-svabhāva</em> — «природа первоэлементов»; вера в реальность четырёх <em>махабхути</em> (земли, воды, огня, ветра) как материального фундамента мира.<a href="#ref-199" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-200"><sup>200</sup> <em>hetu-svabhāva / pratyaya-svabhāva</em> — «природа причин и условий»; представление о том, что причинно-следственные связи — это реальные внешние законы, а не ментальные привычки упорядочивания опыта.<a href="#ref-200" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-201"><sup>201</sup> <em>niṣpatti-svabhāva</em> — «природа завершённости», «истинная природа»; Таковость (<em>tathatā</em>), раскрывающаяся как изначально присутствующая реальность, когда прекращаются все ложные проекции (<em>parikalpita-svabhāva</em>).<a href="#ref-201" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-202"><sup>202</sup> <strong>Гочары</strong> (<em>gocara</em>) — сферы опыта. Эти термины описывают сферы, в которых обитает сознание, в зависимости от уровня его чистоты.<a href="#ref-202" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-203"><sup>203</sup> <em>citta-gocara</em> — «сфера ума»; обыденный уровень восприятия, где <em>Алайя-виджняна</em> проецирует мир и сама же в нём запутывается.<a href="#ref-203" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-204"><sup>204</sup> <em>jñāna-gocara</em> — «сфера знания»; состояние, где знание сливается с объектом, и исчезает разделение на познающего и познаваемое.<a href="#ref-204" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-205"><sup>205</sup> <em>prajñā-gocara</em> — «сфера мудрости»; уровень бодхисаттвы, который использует праджню для исследования шуньяты и переосмысления признаков.<a href="#ref-205" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-206"><sup>206</sup> <em>dṛṣṭi-dvaya-gocara</em> — «сфера двойственных взглядов»; ограниченное пространство ума, зажатого между крайностями «есть» и «нет».<a href="#ref-206" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-207"><sup>207</sup> <em>dṛṣṭi-dvayātikrānta-gocara</em> — «сфера, превзошедшая двойственность»; пространство свободы, где любые умозрительные оппозиции теряют смысл и опору.<a href="#ref-207" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-208"><sup>208</sup> <em>suta-bhūmi-anukramaṇa-gocara</em> — «сфера последовательного прохождения ступеней»; путь постепенного очищения сознания через слушание Учения и прохождение по ступеням (<em>бхуми</em>) бодхисаттвы.<a href="#ref-208" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-209"><sup>209</sup> <em>tathāgatasya pratyātmagati-gocara</em> — «сфера личного постижения Татхагаты»; высшая истина, невыразимая словами и недоступная рассудку; прямой внутренний опыт (<em>pratyātma</em>), возникающий в результате поворота основы (<em>āśraya-parāvṛtti</em>), когда <em>Алайя-виджняна</em> преображается в Великую Зерцалоподобную Мудрость (<em>mahā-ādarśa-jñāna</em>).<a href="#ref-209" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-210"><sup>210</sup> <strong>«Учение об уничтожении»</strong>
            (<em>ucchedavāda</em>) — в данном контексте Будда относит к нигилизму взгляды тех,
            кто верит в реальный распад <em>скандх</em> и <em>дхату</em>. Согласно
            <strong><em>Ланкаватаре</em></strong>, признание реального (а не условного) исчезновения явлений
            ведет к нигилизму, ибо разрывает преемственность кармы. Истинный Путь основывается на постижении того, что явления никогда не рождались (<em>anutpāda</em>) как независимые сущности, а лишь казались существующими в проекциях собственного ума (<em>svacitta-dṛśya</em>). Только понимание мира как <em>майи</em> позволяет сохранить логику преемственности (<em>saṃtati</em>), не впадая при этом в веру в вечные сущности (<em>śāśvata-vāda</em>).<a href="#ref-210" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-211"><sup>211</sup> <strong>«Отсутствие видения начала»</strong> (<em>Ādyadarśanābhāvāt</em>) — неспособность увидеть, что явления безначальны (<em>anādi</em>). Те, кто ищут «первопричину» — будь то Бог, время или атомы, — совершают умственное заблуждение. Они пытаются найти начало там, где есть лишь безначальный, самоподдерживающийся поток проекций, лишённый как начала, так и конца.<a href="#ref-211" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-212"><sup>212</sup> <strong>«Непрерывный поток»</strong>
            (<em>nairantarya-pravṛtti</em>) — иллюзия связного и длящегося потока опыта. В
            <strong><em>Ланкаватаре</em></strong> подчёркивается, что у явлений мира нет собственной внутренней
            преемственности. Их кажущаяся непрерывность — лишь результат стремительного воспроизводства различающим умом (<em>mano-vijñāna</em>) сходных кармических отпечатков (<em>vāsanā</em>). Постижение отсутствия этой непрерывности позволяет йогину прервать поток сансарического опыта и обнаружить нерождённую природу (<em>anutpāda-svabhāva</em>) «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>).<a href="#ref-212" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-213"><sup>213</sup> <strong>«Тройное сочетание»</strong> (<em>trisaṃgati</em>) — техническое обозначение <em>sparśa</em>, встречи объекта, органа чувств и сознания. Оппоненты полагают, что до этой встречи сознание «нет», а после неё — «возникает». Будда показывает несостоятельность этой логики: то, чего нет в причинах, не может появиться в результате. Ошибка состоит в принятии сочетания факторов за реальную причину опыта. Если элементы лишены собственной природы (<em>svabhāva</em>), их сумма не способна породить реально существующее сознание. Для бодхисаттвы «встреча факторов» — это не механическая сборка мира из частей, а недвойственный процесс внутри «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>), подобный майе — кажущийся, но лишённый какой-либо сущностной основы.<a href="#ref-213" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-214"><sup>214</sup> <em>prajñāpāramitā-vihāra</em>.<a href="#ref-214" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-215"><sup>215</sup> <em>anābhoga-caryā</em>.<a href="#ref-215" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-216"><sup>216</sup> <em>svacitta-dṛśya-gocara</em>.<a href="#ref-216" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-217"><sup>217</sup> <em>udadhi-taraṃga-ālayavijñāna-gocara</em>.<a href="#ref-217" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-218"><sup>218</sup> <em>svacitta-dṛśya</em>.<a href="#ref-218" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-219"><sup>219</sup> <strong>«Безначальное понятийное многообразие»</strong> (<em>anādi-prapañca-dauṣṭhulya</em>) — «безначальная косность/инерционность концептуальных/ментальных наслоений/структур/привычек». Это основополагающее обыкновение ума, заставляющее его бесконечно множить иллюзорные категории/идеи и «захватывать» их как реальные. Данная «пагубная инерционность» делает сознание тяжёлым и невосприимчивым к истине, удерживая его в колее привычного различения субъекта и объекта.<a href="#ref-219" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-220"><sup>220</sup> <em>vijñāna-prakṛti-svabhāva</em>.<a href="#ref-220" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-221"><sup>221</sup> <em>vicitra-rūpa-lakṣaṇa-kautūhala</em> — жадное влечение, неутолимое любопытство к многообразию форм и признаков, психологический «зуд» сознания, которое не может оставаться в покое и постоянно ищет, за какой бы объект «зацепиться».<a href="#ref-221" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-222"><sup>222</sup> <em>pravṛtti-vijñāna-taraṃga</em>.<a href="#ref-222" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-223"><sup>223</sup> <strong>«Тело, объекты и мир-вместилище»</strong> (<em>deha-bhoga-pratiṣṭhāna</em>) — триединая структура проявления <em>Алайя-виджняны</em>. Согласно <strong><em>Ланкаватаре</em></strong>, наше физическое присутствие, предметы восприятия и окружающая среда не являются внешними, они представляют собой целостную проекцию ума. Осознание того, что эта триада лишена независимого бытия, позволяет бодхисаттве выйти из-под власти кармической обусловленности и увидеть мир как игру собственного ума.<a href="#ref-223" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-224"><sup>224</sup> <strong>«Признак без-образности»</strong> (<em>nirābhāsa-lakṣaṇa</em>) — состояние сознания, полностью очищенное от проекций идей, образов и представлений. Это переход от «восприятия признаков» (<em>lakṣaṇa-grāha</em>) к прямому постижению (<em>pratyātmāryajñāna</em>), где ум перестаёт строить мир как совокупность внешних объектов. Достижение этого «признака» означает, что завеса интеллектуальных наслоений спала, и сознание пребывает в недвойственной чистоте, не разделяя опыт на зеркало и отражение.<a href="#ref-224" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-225"><sup>225</sup> <strong>«Признак опоры на обеты и благословение всех Будд»</strong> (<em>sarvabuddha-svapraṇidhāna-adhiṣṭhāna-lakṣaṇa</em>) — духовный фактор, обеспечивающий продвижение бодхисаттвы помимо его собственных рассудочных усилий. Этот признак означает, что поток сознания бодхисаттвы входит в согласие с мудростью всех Будд, чья поддержка (<em>adhiṣṭhāna</em>) позволяет ему миновать ловушки цепляния за блаженство самадхи (<em>samādhi-sukha-ābhiniveśa</em>) и не застрять на промежуточных ступенях, достигнув окончательного поворота основы (<em>āśraya-parāvṛtti</em>).<a href="#ref-225" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-226"><sup>226</sup> <strong>«Признак личного благородного постижения»</strong> (<em>pratyātmāryajñāna-gati-lakṣaṇa</em>) — высшая характеристика реализации, при которой Истина постигается напрямую, вне всяких представлений и рассудочных построений. Мнимая граница между познающим и познаваемым растворяется и тогда Таковость (<em>tathatā</em>) неотделима от самого постижения.<a href="#ref-226" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-227"><sup>227</sup> <strong>«Хромой осёл»</strong> (<em>khañjagardabha</em>) — метафора рассудочного знания, опирающегося на умозрительные различения. Будда указывает, что бодхисаттва должен иметь мужество оставить привычную опору на логику и рассудок, как только они выполнили свою подготовительную роль. Дальнейшее продвижение в «сферу личного постижения» (<em>pratyātmagati-gocara</em>) возможно только после отказа от этого «хромого» средства передвижения в пользу спонтанной и недвойственной мудрости.<a href="#ref-227" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-228"><sup>228</sup> <strong>«Тело в самадхи, подобном майе»</strong> (<em>māyopama-samādhi-kāya</em>) — проявление бодхисаттвы, чьё присутствие в мире форм уже не обусловлено кармой, но является прямым продолжением его медитативного опыта. Это — тело-призрак, которое функционирует среди явлений как магический мираж. Оно действенно и сострадательно, но абсолютно лишено собственной природы. Обретение такого «тела» знаменует победу над иллюзией плотности мира и переход к безусильной деятельности (<em>anābhoga</em>) во благо всех существ.<a href="#ref-228" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-229"><sup>229</sup> <strong>«Исследование основы благородной мудрости»</strong> (<em>āryajñāna-vastu-pravicaya</em>) — созерцательное исследование мнимой основы (<em>vastu</em>) воспринимаемых объектов посредством благородной мудрости. В отличие от рассудочного анализа (<em>tarka-pravicaya</em>), это прямое постижение (<em>pratyakṣa-avabodha</em>) отсутствия собственной природы (<em>niḥsvabhāva</em>) всех явлений как проекций ума (<em>svacitta-dṛśya</em>). Устраняя иллюзию внешней плотности (<em>bāhya-ghanatva-vikalpa</em>), йогин лишает ум опоры для цепляния (<em>upādāna-āśraya</em>) и входит в недвойственное пространство Таковости (<em>tathatā</em>).<a href="#ref-229" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-230"><sup>230</sup> <em>parikalpita-svabhāva</em> — воображаемая природа; первая из трёх свабхав (<em>svabhāva-traya</em>). Это ложная природа, приписываемая явлениям различающим умом (<em>vikalpa</em>), который наделяет проекции ума иллюзией независимого бытия. Постижение её отсутствия (<em>abhāva</em>) — ключ к освобождению.<a href="#ref-230" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-231"><sup>231</sup> <em>pudgala-dharma-nairātmya</em> — двоякое отсутствие "я": в личности (<em>pudgala</em>) и в явлениях (<em>dharma</em>). Постижение первого освобождает от <em>клеш</em> (<em>kleśa-āvaraṇa</em>), второго — от завесы познаваемого (<em>jñeya-āvaraṇa</em>), открывая путь к всеведению (<em>sarvajñatā</em>).<a href="#ref-231" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-232"><sup>232</sup> <strong>«Небытие»</strong>,
            <strong>«отсутствие» или «отрицание существования»</strong> (<em>nāstitva</em>) — В
            <strong><em>Ланкаватаре</em></strong> это понятие рассматривается как умственная ловушка — вторая
            из «двух крайностей» (<em>anta-dvaya</em>). Вера в «небытие» — это обратная сторона веры в «бытие». Чтобы нечто «отсутствовало», оно должно было сначала «быть». Но поскольку все явления изначально не рождены (<em>anutpāda</em>) и являются лишь «воспринимаемым собственным умом» (<em>svacitta-dṛśya</em>), то и говорить об их «небытии» так же некорректно, как и об их «бытии». Взгляд «небытия» (<em>nāsti-dṛṣṭi</em>) особенно опасен, так как он может привести к отрицанию закона кармы, плода и самого Пути.<a href="#ref-232" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-233"><sup>233</sup> <strong>«Истощение причины различающего
                рассудка»</strong>, <strong>«исчерпание оснований для рассудочного вывода»</strong> (<em>vikalpa-buddhi-hetu-kṣaya</em>) — различающий рассудок (<em>vikalpa-buddhi</em>), не обнаруживая устойчивой причины (<em>hetu</em>) явлений, заключает: «раз причины нет — явление не существует». Это <em>kṣaya</em> — полное «исчерпание» реальности в умозрительном отрицании. Будда указывает, что само это отрицание — плод того же различающего ума: нигилист видит лишь отсутствие вещей, не постигая Таковость (<em>tathatā</em>). Его рассудок занят уничтожением объектов вместо того, чтобы остановиться самому.<a href="#ref-233" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-234"><sup>234</sup> <strong>Логическая ошибка нигилистов.</strong> Они говорят: «Рогов у зайца нет (это факт), значит и мир такой же несуществующий». Будда критикует их за то, что они строят свое отрицание мира на сравнении с несуществующим объектом. Но если объект (рога зайца) абсолютно невозможен, он не может служить даже примером для отрицания. Чтобы сказать «чего-то нет», нужно сначала иметь идею о том, что это «есть». Но сами "рога зайца" — это идея, заимствованная у "рогов коровы". Таким образом, отрицание паразитирует на утверждении «есть», и обе крайности остаются в ловушке различающего ума (<em>vikalpa</em>).<a href="#ref-234" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-235"><sup>235</sup> <strong>Логическая ошибка реалистов.</strong> Они говорят: «Ладно, рогов зайца нет, но рога коровы-то мы видим! Значит, мир реален». Они разделяют реальность на «абсолютно отсутствующее» и «реально присутствующее». Будда же утверждает, что и то, и другое — лишь <em>vikalpa</em> (различение). Рога коровы так же «пусты» от собственной природы, как и рога зайца. Разница лишь в устойчивости проекции.<a href="#ref-235" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-236"><sup>236</sup> <strong>«Обусловленность через взаимную зависимость»</strong> или <strong>«относительность причинности»</strong> (<em>anyonyāpekṣa-hetutva</em>) — одна идея «взирает» (<em>apekṣā</em>) на другую, чтобы обрести смысл; ключевой логический принцип, вскрывающий ловушку, в которой представления существуют лишь парами, взаимно определяя друг друга. Будда указывает, что «небытие» (<em>nāstitva</em>) всегда тайно опирается на «бытие» (<em>astitva</em>). Когда мы говорим «у зайца нет рогов», мы неявно подтверждаем, что концепция «рога» имеет смысл (заимствованный у коровы). Отрицая одну сторону, ум всё равно остаётся в плену у другой. Если при анализе «бытие» объекта (рога коровы) оказывается лишь проекцией ума, то и «небытие» (отсутствие рогов у зайца) теряет всякую почву. Нельзя построить истинное знание, опираясь на отрицание иллюзии, ибо само это отрицание — такая же умозрительная конструкция, как и утверждение. Истинная мудрость (<em>jñāna</em>) не выбирает между «есть» и «нет». Она распознаёт, что обе эти категории — лишь словесная раздутость (<em>prapañca</em>), и оставляет саму эту двойственность. Этот термин объясняет, почему Будда отвергает как реализм, так и нигилизм.<a href="#ref-236" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-237"><sup>237</sup> <strong>«Исследование вплоть до мельчайших атомов»</strong> (<em>āparamāṇu-pravicayāt</em>) — аналитический метод разрушения кажущейся плотности объектов. Он заключается в мысленном дроблении объекта на составляющие части до тех пор, пока сама идея его независимого существования не исчезнет. Обнаруживая, что при предельном разборе никакой собственной природы (<em>svabhāva</em>) не находится, бодхисаттва убеждается, что мир не имеет внешней опоры и является лишь динамической проекцией ума. Это праджня-анализ (<em>prajñā-pravicaya</em>): вера в плотность объекта доводится до самоопровержения через обнаружение отсутствия предельной частицы. Так различающий ум (<em>vikalpa</em>) лишается опоры и прекращается сам.<a href="#ref-237" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-238"><sup>238</sup> В этом вопросе Махамати проверяет Будду, пытаясь обосновать «небытие» (<em>nāstitva</em>) через факт «прекращения» (<em>apravṛtti</em>) работы ума. Это — утончённая ловушка: попытка утвердить небытие (<em>nāstitva</em>) как логический вывод из факта прекращения деятельности различения. Махамати ищет логическое обоснование для отсутствия объектов через наблюдение за прекращением самого процесса различения, не осознавая, что Таковость (<em>tathatā</em>) не нуждается в подобных соотнесениях и лежит выше любой логики «наличия» или «отсутствия».<a href="#ref-238" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-239"><sup>239</sup> <strong>«Порочность причины»</strong> (<em>viṣama-hetu</em>) — умственное заблуждение, при котором для доказательства истины используются ложные или относительные основания. Будда указывает, что нельзя утвердить «небытие» объектов, опираясь на «бытие» других, так как при тщательном анализе любая опора лишена собственной природы. Эта порочность основания делает рассудочное доказательство невозможным: истина открывается лишь тогда, когда ум оставляет саму привычку утверждать одно через соотнесение с другим.<a href="#ref-239" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-240"><sup>240</sup> В этом фрагменте Будда последовательно устраняет опоры умозрительного различения:<br>
            • Ни тождество, ни различие (<em>anyānanya-vivarjita</em>): субъект и объект различения не утверждаются ни как одно, ни как два. Тем самым снимается возможность как утверждения бытия, так и отрицания через противопоставление.<br>
            • Порочность причины (<em>viṣama-hetu</em>): отрицание одного через другое логически недопустимо, поскольку сам объект сравнения при анализе лишён устойчивой основы (<em>vastu</em>).<br>
            • Снятие различия формы и пространства (<em>ākāśameva rūpam</em>): форма не существует отдельно от пространства и не «располагается» в нём; оба — условные обозначения, возникающие в различении.<br>
            • Исчерпание признака при анализе (<em>aṇutva-lakṣaṇe nāvatiṣṭhante</em>): при аналитическом разложении объект не обнаруживает предельной частицы и утрачивает сам признак формы, переставая быть опорой мышления.<a href="#ref-240" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-241"><sup>241</sup> <em>svacitta-dṛśya-vikalpa-anugama-manasā</em><a href="#ref-241" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-242"><sup>242</sup> <em>svacitta-dṛśya-yoga</em><a href="#ref-242" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-243"><sup>243</sup> <strong>Нишьянда-будда</strong> (<em>niṣyanda-buddha</em>) — «Будда излияния»: аспект Пробуждённого, проявляющийся как спонтанное, естественное излучение (<em>niṣyanda</em>) Таковости (<em>tathatā</em>) в форму. В <strong><em>Ланкаватаре</em></strong> этот термин описывает Будду, который является «истечением» Таковости (<em>tathatā</em>) в сферу форм. Это тот образ Будды, который наставляет бодхисаттв на высоких ступенях пути, служа живым мостом между невыразимой Таковостью и миром умозрительных различений (<em>vikalpa</em>).<a href="#ref-243" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-244"><sup>244</sup> <strong>«Признаки привязанности к воображаемой природе явлений»</strong>, <strong>«признак упорной привязанности к воображаемой собственной природе явлений»</strong> (<em>bhāva-vikalpa-svabhāva-abhiniveśa-lakṣaṇa</em>) — термин описывает трёхступенчатую ловушку: различающий ум (<em>vikalpa</em>) разделяет опыт на отдельные явления (<em>bhāva</em>), наделяет их ложной собственной природой (<em>svabhāva</em>), и упорно цепляется (<em>abhiniveśa</em>) за эти проекции как за реальность. Для бодхисаттвы распознать этот признак — значит увидеть, что вся «плотность» мира держится лишь на инерции различающего ума, принимающего свои проекции за независимые сущности.<a href="#ref-244" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-245"><sup>245</sup> <em>Нила-пита-ушна-драва-чала-катхина</em> (<em>nīla-pīta-uṣṇa-drava-cala-kaṭhina</em>) — перечисление чувственных признаков, которые шраваки принимают за реальные свойства великих элементов (<em>mahābhūta</em>): <em>nīla, pīta</em> — цветовые аспекты формы (<em>rūpa</em>), <em>uṣṇa</em> — жар (огонь), <em>drava</em> — текучесть (вода), <em>cala</em> — движение (ветер), <em>kaṭhina</em> — твёрдость (земля). Хотя эти признаки введены в учении как условные обозначения для анализа опыта, шраваки, удерживаясь в рамках отсутствия «я» личности, не проникают в отсутствия «я» дхарм  и поэтому овеществляют элементы, наделяя их собственной природой. Это и есть привязанность к воображаемой природе (<em>parikalpita-svabhāva-abhiniveśa</em>) — принятие аналитических построений за реальные сущности.<a href="#ref-245" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-246"><sup>246</sup> <em>anitya-bhāva-vilakṣaṇa-hetutvāt</em> — «по причине [желания найти] иное по отношению к непостоянному бытию». Тиртхики строят свою «<strong>Вечность</strong>» на отталкивании от изменчивости мира. Но если ваша вечность зависит от непостоянства (как его противоположность), она не абсолютна.<a href="#ref-246" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-247"><sup>247</sup> <em>na svakṛta-hetu-lakṣaṇa-prabhāvitā</em> — буквально: «[состояние], не явленное/не порождённое через признаки своих собственных причин».<a href="#ref-247" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-248"><sup>248</sup> <em>vāg-vikalpa-mātra</em> — «словесная раздутость», когда ум плодит определения, не имея под ними живого опыта.<a href="#ref-248" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-249"><sup>249</sup> <em>pratyātmāryādhigama-lakṣaṇa</em><a href="#ref-249" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-250"><sup>250</sup> <em>kṛtaka-bhāva-abhāva-varjita.</em> Тиртхики видят мир как «сотворённый» и потому разрушимый, а свою вечность — как нечто «несотворённое». Будда же «свободен» (<em>varjita</em>) от самой этой пары. Его состояние не является ни «сотворённым», ни «несотворённым», так как оно лежит за пределами логики возникновения. Это радикальное «ни то, ни другое», которое оставляет логиков в тупике.<a href="#ref-250" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-251"><sup>251</sup> <strong>«Рассудочное умозаключение на основе
                внешнего»</strong> (<em>bāhya-bhāva-anitya-anumāna</em>). Тиртхики смотрят на внешний
            мир (<em>bāhya-bhāva</em>), видят, что он распадается (<em>anitya</em>), и логически
            делают вывод: «значит, должно быть что-то вечное». Будда называет это «гаданием по
            признакам». Ошибка здесь в том, что они принимают «внешний мир» за реальную точку отсчёта
            . Для <strong><em>Ланкаватары</em></strong> внешний мир — это галлюцинация ума, поэтому строить на
            его «непостоянстве» выводы о Вечности — всё равно что изучать законы оптики по отражению в кривом зеркале.<a href="#ref-251" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-252"><sup>252</sup> <em>svacitta-dṛśya-gocara</em><a href="#ref-252" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-253"><sup>253</sup> <em>bāhya-citta-dṛśya-gocara</em> —
            буквально "сфера видимого вне ума", то есть они принимают объекты за независимо существующие (<em>bāhya</em>), не понимая, что эти объекты — проекции самого ума (<em>citta-dṛśya</em>).<a href="#ref-253" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-254"><sup>254</sup> <em>pañcābhisamaya-gotrāṇi</em><a href="#ref-254" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-255"><sup>255</sup> <em>śrāvakayānābhisamaya-gotra</em><a href="#ref-255" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-256"><sup>256</sup> <em>pratyekabuddhayānābhisamaya-gotra</em><a href="#ref-256" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-257"><sup>257</sup> <em>tathāgatayānābhisamaya-gotra</em><a href="#ref-257" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-258"><sup>258</sup> <em>aniyata-ekatara-gotra</em><a href="#ref-258" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-259"><sup>259</sup> <em>agotra</em><a href="#ref-259" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-260"><sup>260</sup> <em>ṣaṭ-pañcamyāṃ bhūmau</em> — «на пятой или шестой ступени». Хотя шраваки не проходят «ступени» (<em>bhūmi</em>) бодхисаттв, здесь Будда использует терминологию <em>бхуми</em> условно, указывая, что даже на уровне духовного развития, сопоставимом с пятой-шестой ступенью бодхисаттвы, шравак, не постигший <em>dharma-nairātmya</em>, остаётся связан отпечатками клеш (<em>kleśa-vāsanā</em>).<a href="#ref-260" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-261"><sup>261</sup> <em>ātma-sattva-jīva-poṣa-puruṣa-pudgala-sattva-avabodhāt</em> — Данный перечень представляет собой своего рода «каталог заблуждений» относительно природы личности, последовательно разоблачающий все основные способы, которыми индийская мысль пыталась наделить индивидуальное существование некой реальностью. Включение в один ряд <em>Атмана</em>, <em>Пуруши</em>, <em>Дживы</em> и <em>Пудгалы</em> призвано показать, что при всем различии терминов за ними стоит одна и та же ошибка познания — попытка найти неизменного «хозяина» внутри изменчивого потока опыта.<br><br>Исторически этот список направлен против главных философских оппонентов Будды того времени. Отрицая <em>Атмана</em>, сутра бьет по брахманистскому учению о вечной душе; отвергая <em>Пурушу</em>, она разрушает двойственность школы Санкхья, видевшей в нем чистого, отделенного от материи свидетеля; отрицание <em>Дживы</em> направлено против джайнов с их представлением о живой сущности как носителя жизненной силы. Особое значение имеет включение в список <em>Пудгалы</em> — «личности», которую пытались утвердить некоторые ранние буддийские школы (<em>пудгалавадины</em>) как реального носителя кармического груза. <strong><em>Ланкаватара</em></strong> определяет <em>пудгалу</em> как еще одну форму «словесной раздутости», скрывающую отсутствие «Я». Все эти категории рассматриваются не как реальные сущности, а как номинальные обозначения, не имеющие под собой объективной основы. Постижение их ложности (<em>avabodhāt</em>) освобождает ум от точки привязанности — «схватывающего» субъекта. Только когда ум распознает, что ни один из этих терминов не описывает реального «Я», он перестает проецировать «владельца» опыта и совершает окончательный поворот основы, раскрываясь как недвойственная мудрость, где нет места ни душе, ни индивиду.<a href="#ref-261" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-262"><sup>262</sup> <em>aniryāṇa-niryāṇa-buddhiḥ</em> — «разум, различающий "выход" и "не-выход"». Будда критикует интеллектуальную установку, при которой освобождение воспринимается как реальный переход из «плена» сансары в «свободу» нирваны. Такая позиция остается двойственной и опирающейся на понятия. Для бодхисаттвы истинное освобождение заключается в распознавании того, что и «плен», и «выход» — лишь проекции ума, не имеющие собственной основы. Оставить этот «разум выхода» — значит постичь исконное тождество сансары и нирваны (<em>saṃsāra-nirvāṇa-samatā</em>) — поскольку ничто никогда не было связано и не нуждается в освобождении.<a href="#ref-262" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-263"><sup>263</sup> <em>svabhāva-niḥsvabhāva-dharma-abhisamaya-gotra.</em> Этот род постижения основан на основополагающем парадоксе махаяны: единственная подлинная «природа» (<em>svabhāva</em>) любого явления заключается в том, что у него полностью отсутствует какая-либо неизменная, независимая сущность (<em>niḥsvabhāva</em>). Бодхисаттва, принадлежащий к этому «роду», не просто верит в шуньяту, он видит мир как совершенно пластичный поток причин и условий. Это прозрение лишает сознание ложных опор в «плотных» объектах, подготавливая его к пониманию реальности как <em>воспринимаемой собственным умом</em>.<a href="#ref-263" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-264"><sup>264</sup> <em>adhigama-sva-pratyātmārya-abhisamaya-gotra.</em> Слово <em>adhigama</em> (достижение/прибытие) указывает на то, что истина не заимствуется извне (из книг или слов), а открывается как глубоко личный, недвойственный опыт (<em>sva-pratyātma</em>). Принадлежность к этой готре означает, что мудрость бодхисаттвы больше не нуждается во внешних доказательствах, так как <em>таковость</em> сияет в нем как его собственная проживаемая данность.<a href="#ref-264" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-265"><sup>265</sup> <em>bāhya-buddhakṣetra-udārya-abhisamaya-gotra.</em> Хотя йогачара учит, что всё есть ум, «внешние» (<em>bāhya</em>) земли Будд рассматриваются здесь как бесконечные горизонты проявления сострадания. Постигая их «величия» (<em>udārya</em>), бодхисаттва выходит за пределы личного спасения и обретает способность беспрепятственно проявляться в любых мирах ради блага других существ. Это вхождение в сферу искусных средств (<em>упая</em>), где «внешняя» реальность распознается как столь же прозрачная и податливая мудрости, как и сам ум.<a href="#ref-265" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-266"><sup>266</sup> <strong>«Благословение Татхагат»</strong>, <strong>«сила удержания»</strong> (<em>tathāgatādhiṣṭhāna</em>) — проявление изначального единства бодхисаттвы и Татхагат: их природа одна — Таковость (<em>tathatā</em>). Будды «не оставляют» ни одного существа, их <em>adhiṣṭhāna</em> действует как естественное движение сострадания.<a href="#ref-266" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-267"><sup>267</sup> Бодхисаттва реализует «непребывающую нирвану» (<em>apratiṣṭhita-nirvāṇa</em>), которая не является ни сансарой, ни статичным покоем.<a href="#ref-267" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-268"><sup>268</sup> <strong>«Три признака собственных природ»</strong> (<em>svabhāva-lakṣaṇa-traya</em>) — воображаемая природа (<em>parikalpita</em>) (мир двойственности и имен), зависимая природа (<em>paratantra</em>) (поток причин и условий) и совершенная природа (<em>pariniṣpanna</em>) (Таковость). При этом важно понимать, что <em>parikalpita</em> — единственная полностью иллюзорная природа; <em>paratantra</em> — условно реальна (поток причин существует, но лишён собственной природы); <em>pariniṣpanna</em> — абсолютно реальна, ибо есть сама Таковость.<a href="#ref-268" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-269"><sup>269</sup> <strong>Нимитта</strong> (<em>nimitta</em>) — метка качества-характеристики, которую наш ум накладывает на поток опыта. В системе пяти <em>дхарм нимитта</em> — первая: за ней следуют <em>имя</em> (<em>nāma</em>), <em>различение</em> (<em>vikalpa</em>), <em>правильное знание</em> (<em>samyag-jñāna</em>) и Таковость (<em>tathatā</em>). Первые три принадлежат сфере ложного воображения; последние два — сфере освобождения. Если «имя» (<em>nāma</em>) — это ярлык в языке, то «признак» — это то, что мы «видим» как плотную характеристику вещи: её цвет, форму, твердость или протяженность. Ум выхватывает из безбрежного океана <em>Алайи</em> отдельные качества и «замораживает» их, создавая иллюзию устойчивого объекта. Без признака ум не мог бы «схватить» реальность. Мы привязываемся не к вещам, а к их признакам (приятное, постоянное, «мое»). Именно <em>нимитта</em> делает возможной двойственность «субъекта» и «объекта», создавая поле для работы различающего сознания (<em>викальпы</em>). Практика бодхисаттвы направлена на <em>анимитту</em> — «беспризнаковость».<a href="#ref-269" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-270"><sup>270</sup> <strong>«Основа, признак, характеристика и внешняя форма»</strong> (<em>vastu-nimitta-lakṣaṇa-ākāra</em>) — В <strong><em>Ланкаватаре</em></strong> эта цепочка раскрывает механику ложного воображения (<em>abhūta-parikalpa</em>). Будда показывает, как ум строит иллюзию, последовательно наделяя её деталями: <em>Васту</em> (<em>vastu</em>) — «Основа» или «точка фиксации», первичное выделение в океане <em>Алайи</em>. Ум «выхватывает» некое ментальное пятно, принимая его за независимую «вещь». <em>Нимитта</em> (<em>nimitta</em>) — «Признак» или «образ». На выбранную основу ум накладывает общую метку (например, «зримое» или «твёрдое»). Это — первый импульс выделения объекта из фона. <em>Лакшана</em> (<em>lakṣaṇa</em>) — «Характеристика» или «специфический признак». Здесь объект обретает детальные качества: цвет, размер, плотность. Это этап «раскрашивания» ментального образа, придающий ему уникальность. <em>Акара</em> (<em>ākāra</em>) — «Внешняя форма» или «вид». Финальная стадия, на которой объект предстаёт перед сознанием как завершённая, оформленная и «внешняя» фигура. Именно здесь возникает окончательная вера в то, что мир существует «снаружи».<a href="#ref-270" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-271"><sup>271</sup> <strong>«Признак привязанности к именам»</strong> (<em>nāma-abhiniveśa-lakṣaṇa</em>) — он описывает лингвистический плен сознания. Слово «имя» (<em>nāma</em>) здесь означает не только названия предметов, но и все понятия, которыми мы пользуемся. Ум обладает безначальной привычкой (<em>vāsanā</em>) наделять слова статусом реальности, значимости. Как только мы даем явлению имя, мы мгновенно приписываем этому слову плотную, неизменную суть. Термин <em>абхинивеша</em> (упорствование, вязкая привязанность) указывает на то, что сознание «прикипает» к именам и начинаем взаимодействовать с миром «ярлыков». Но имена — это лишь условные соглашения (<em>saṃketa</em>), не имеющие под собой никакой основы (<em>vastu</em>).<a href="#ref-271" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-272"><sup>272</sup> <strong>«Признак привязанности к объектам через их наименования»</strong> (<em>nāma-vastu-nimitta-abhiniveśa-lakṣaṇa</em>) — финальный этап цепи ложного воображения: ум склеивает имя (<em>nāma</em>, например, «кувшин») с чувственными признаками (<em>nimitta</em> — форма, цвет, твёрдость) и рождает иллюзию самостоятельного объекта (<em>vastu</em>). Эта «склейка» создаёт веру в существование внешнего мира, обладающего собственной сутью, тогда как на деле за именами и формами — лишь поток опыта, лишённый основы. Распознав этот механизм, бодхисаттва видит мир как прозрачную игру ума — «словесную конструкцию», в которой нет ни «вещей», ни «схватывающего».<a href="#ref-272" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-273"><sup>273</sup> <strong>«Внутренние и внешние дхармы»</strong> (<em>adhyātma-bāhya-dharma</em>) — привязанность к объектам не ограничивается внешним миром Ум «овеществляет» даже психические состояния — мысли, ощущения, самоощущение — наделяя их ложной плотностью и превращая в объекты обладания.<a href="#ref-273" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-274"><sup>274</sup> <strong>«Ложное понимание собственных и общих признаков»</strong> (<em>sva-sāmānya-lakṣaṇa-parijñāna-avabodha</em>) — Будда указывает на два типа признаков, за которые цепляется ум:<br>— собственные признаки (<em>sva-lakṣaṇa</em>) — качества, кажущиеся «уникальными»: твёрдость земли, текучесть воды, черты лица. Они принимаются как внутренние свойства вещей, наделяя их некой сущностью (<em>svabhāva</em>);<br>— общие признаки (<em>sāmānya-lakṣaṇa</em>) — универсальные категории: «все кувшины», «все люди», «всё непостоянное». Это уровень абстрактного, обобщающего мышления, где ум группирует опыт по схемам, категориям, группам.<br>Здесь <em>parijñāna</em> и <em>avabodha</em> используются иронически — это не истинное постижение, а самоуверенное «знание» различающего ума, принимающего свои классификации за реальность.<a href="#ref-274" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-275"><sup>275</sup> Процесс построения «плотной реальности» разворачивается в строгой последовательности. Всё начинается с внутреннего «зуда» неведения (<em>ajñāna</em>) — основополагающей слепоты познания, неспособности распознать в текущем опыте его истинную, пустотную природу (<em>шуньяту</em>). Это неведение направляется кармой — накопленной инерцией прошлых привычек — и подпитывается жаждой (<em>tṛṣṇā</em>). Жажда заставляет сознание «выбрасываться» вовне в поисках опоры, превращая покой океана <em>Алайи</em> в движение активных сознаний. Когда органы чувств встречаются с потоком данных, происходит мгновенное «слипание» (<em>abhiniveśa</em>). Ум не просто отражает форму, он «хватается» за неё (<em>grahaṇa</em>), наделяя её статусом независимого объекта. В этот момент возникает разделение на «воспринимающего» и «воспринимаемое». Именно процесс захвата признака «овеществляет» пустотный опыт, придавая ему видимую плотность и внешнее положение. В ответ на акт захвата сознание-хранилище (<em>Алайя-виджняна</em>) мгновенно развёртывает целостную галлюцинацию:<br>— Обитель (<em>bhājana</em>) — пространство/ мир-вместилище (сцена действия);<br>— Тело (<em>deha</em>) — совокупность процессов (актёр);<br>— Объекты/ предметы наслаждения (<em>bhoga</em>) — объекты восприятия (реквизит).<br><br>Важнейшее утверждение <strong><em>Ланкаватары</em></strong> состоит в том, что тело не находится в мире, а мир не находится вне тела. Оба — равноправные проекции одного ума (<em>svacitta-dṛśya</em>). Это единое явление, которое ошибочно разделяется на «внутреннее» и «внешнее».<br><br>Итогом становится «воображение различениями собственного ума». Использование двойного корня «викальп» в оригинале указывает на взаимообращающийся, самоподдерживающийся характер иллюзии. Ум не просто выдумывает мир; он структурирует его через бесконечные разделения (субъект/объект, приятное/болезненное, я/другой). Эти различения (<em>vikalpa</em>) наслаиваются друг на друга, создавая вязкую сеть понятий, в которой ум запутывается, как в паутине, принимая плоды собственного воображения за независимую и твердую реальность.<a href="#ref-275" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-276"><sup>276</sup> Постижение отсутствия «я» в личности (<em>pudgala-nairātmya</em>) раскрывается через ряд точных метафор, обнажающих кажущуюся устойчивость существования. Иллюзия «дления» личности во времени объясняется через образы реки, ростка, светильника, ветра и облака. Подобно реке, которая кажется неизменной, хотя в каждый миг в ней течет новая вода, или ростку, который видится единым процессом, являясь лишь непрерывной сменой состояний, — так и совокупность <em>скандх</em> есть лишь мгновенная преемственность (<em>kṣaṇa-paramparā</em>). Как пламя светильника создаёт видимость одного огня через череду сгорающих частиц масла, или как ветер и облако постоянно меняют форму, не имея какого-либо центра, так и личность распадается и пересобирается в каждое мгновение.<br><br>Ум, подобно обезьяне, не может остановиться ни на секунду, вечно прыгая по веткам объектов, а суетливость сознания, инстинктивно ищущего, к чему бы «прилипнуть» в поисках удовольствия, уподоблена мухе. Сами же стремления ненасытны, словно бушующий огонь: чем больше «дров» в виде впечатлений в него бросаем, тем сильнее разгорается жажда, поддерживая горение этой иллюзии.<br><br>Цикличность и автоматизм нашего существования уподоблены колодезному колесу (<em>araghaṭṭa</em>) с прикрепленными к нему кувшинами. Как колесо принудительно вращается, то опуская кувшины в мутную глубину, то поднимая их к поверхности, так и личность вращается в круговороте сансары. Это движение не управляется волей «Я», оно движимо лишь тяжестью накопленных отпечатков безначального многообразия (<em>anādi-prapañca -vāsanā</em>).<br><br>В конечном итоге Будда лишает личность самой «живости», уподобляя её механической кукле (янтра) или магической иллюзии. Внутри этого аппарата нет души; «кукла» движется лишь потому, что натянуты нити кармы и дуют ветры прошлых привычек. Это «оживленный труп». Знание, прозревающее эти признаки, именуется знанием об отсутствии «я» в личности. Оно превращает «хозяина жизни» в прозрачный, закономерный и никем не управляемый поток элементов, окончательно лишая его ложной плотности и власти эго.<a href="#ref-276" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-277"><sup>277</sup> Будда здесь совершает двойное отрицание, ведущее к полному растворению иллюзии плотности <em>скандх</em>. Первый уровень — <em>pudgala-nairātmya</em>: <em>скандхи</em> лишены «я» — нет хозяина потока, есть лишь совокупность факторов, движимых причиной, кармой и жаждой. Второй уровень — <em>dharma-nairātmya:</em> сами <em>скандхи</em> лишены собственных (<em>sva-lakṣaṇa</em>) и общих признаков (<em>sāmānya-lakṣaṇa</em>). Их «твёрдость», «форма», «непостоянство» — проекции различающего ума. Термин — <em>abhūta-parikalpa</em> («ложное воображение несуществующего») указывает, что <em>скандхи</em> хотя и пусты, но воображаются как плотные.<a href="#ref-277" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-278"><sup>278</sup> Отрицание возникновения в данном фрагменте строится на разрушении идеи причинности: дхармы не возникают «сами по себе» (<em>svataḥ</em>), так как это предполагало бы наличие изначальной сущности, и не возникают «извне» (<em>parataḥ</em>), так как в высшем смысле нет объектов, отделенных от ума. Упоминание «состояния взаимного схождения условий» (<em>saṃghātāvasthā</em>) указывает на то, что любая «вещь» — это лишь временное сочетание факторов (<em>скандх</em> и элементов). Поскольку эти условия сами лишены основы, их совокупность не порождает новой реальности. Довод об отсутствии «непрерывной цепи» (<em>prabandha-abhāva</em>) подчеркивает теорию мгновенности (<em>kṣaṇika-vāda</em>): поток опыта состоит из отдельных вспышек, между которыми нет связующего «клея». Таким образом, «изменчивость» явлений — это иллюзия познания, возникающая при наложении идеи длительности на «выделяемые» моменты ума.<a href="#ref-278" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-279"><sup>279</sup> Принцип недвойственности здесь раскрывается через относительность понятий: «свет» и «тень» не являются отдельными сущностями — они возникают как парные проекции различения. Будда применяет это и к паре «сансара и нирвана». Их недвойственность/тождественность не означает, что они идентичны или смешаны — ни одна из них не обладает самостоятельным бытием. В опыте они исключают друг друга: нельзя одновременно пребывать в заблуждении и в ясном видении. Но на глубинном уровне они — два способа восприятия потока, лишённого сущности. Разделение между миром страданий и освобождением существует только в языке и различении ума. За пределами этих «ярлыков» нет ни единства, ни частей, есть лишь недвойственное видение, свободное от всех умопостроений.<a href="#ref-279" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-280"><sup>280</sup> Здесь звучит предостережение от двух крайностей: нигилизма («ничто не имеет значения») и догматизма («Нирвана — вечная реальность»). Хотя и утверждается, что сансара подобна сну — но пока ум не пробуждён, инерция кармы продолжает формировать его события. С другой стороны Нирвана — не «вечное прибежище», не объект, который «есть», и не пустота, которой «нет». Для Благородных — это свобода от необходимости приписывать реальности ярлыки «существует» или «не существует». Называть её «несотворённой» (<em>akṛtaka</em>) — лишь педагогический приём, а не описание сущности.<a href="#ref-280" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-281"><sup>281</sup> Вопрос Махамати касается ловушки причинно-условной модели. В индийской философии дебаты велись вокруг того, возникают ли вещи последовательно (<em>anukrama</em>) или одновременно (<em>yugapad</em>). Однако с позиции «только-ума» оба эти представления ошибочны, так как предполагают, что «нечто» реально переходит из состояния небытия в состояние бытия. Махамати просит разъяснить «признак причинно-условной природы» именно для того, чтобы распознать в ней плод ложного воображения. Постижение <em>hetu-pratyaya</em> ведёт к осознанию того, что ни один объект не имеет собственной природы (<em>niḥsvabhāva</em>), а значит, ничто никогда не возникало — ни мгновенно, ни постепенно.<a href="#ref-281" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-282"><sup>282</sup> Внешнее зависимое возникновение (<em>bāhya-pratītyasamutpāda</em>) рассматривается здесь через призму условий (<em>pratyaya</em>): материального основания (глины) и сопутствующих факторов (гончарного круга, усилий человека и т.д.). Перечисляя эти примеры, Будда подводит Махамати к пониманию того, что ни один внешний объект не появляется из ниоткуда и не существует сам по себе. Фраза «каждое последующее обусловлено предшествующим» (<em>pūrvottarottara</em>) обнажает механизм формирования понятия времени: наш ум связывает разрозненные моменты опыта в линейную цепь, создавая иллюзию стабильного процесса возникновения кувшина или ростка, тогда как на самом деле это лишь поток мгновений, лишённых собственной природы.<a href="#ref-282" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-283"><sup>283</sup> Внутреннее зависимое возникновение (<em>ādhyātmika-pratītyasamutpāda</em>) описывает умозрительную обусловленность опыта. Будда указывает, что такие базовые элементы нашего существования, как тело, органы чувств и объекты восприятия (<em>скандхи, дхату, аятаны</em>), не являются самодостаточными сущностями. Они — лишь результат работы неведения, жажды и кармы. Ключевое утверждение о том, что эти процессы «неотличимы» (<em>aviśiṣṭāḥ</em>), разрушает иллюзию двойственности субъект-объект. С точки зрения «только-ума», внутренние омрачения и внешние формы — это единый поток воспринимаемого собственным умом. Только незрелый ум (<em>bāla</em>) воображает между ними качественную разницу, разделяя единый поток различений на «внутреннее Я» и «внешний мир».<a href="#ref-283" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-284"><sup>284</sup> То, что мы принимаем за «объективные законы мира», является набором функций различающего ума (<em>vikalpa</em>). Первые пять причин описывают механизм умозрительного построения и поддержания иллюзии сансары: от скрытого потенциала семян (<em>bhaviṣyad</em>) до их высвечивания в восприятии (<em>vyañjana</em>). Шестая причина — нейтральности (<em>upekṣā-hetu</em>) описывает момент затухания умопостроений. Когда ум перестаёт вовлекаться в процесс различения, инерция потока (<em>prabandha</em>) пресекается, что ведёт к реализации состояния <em>avikalpa</em> — непосредственного видения, не разделённого на субъект и объект.<a href="#ref-284" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-285"><sup>285</sup> Учение о четырёх видах речи в <strong><em>Ланкаватаре</em></strong> вскрывает механизмы, посредством которых язык подменяет реальность.<br><br>
            • Речь признаков фиксирует мир как набор устойчивых объектов.<br>
            • Речь сновидений показывает, что язык может оперировать объектами, которых нет «здесь и сейчас», создавая воображаемые миры.<br>
            • Речь косных различений (<em>dauṣṭhulya</em>) обнажает эмоциональную определённость языка: мы говорим, исходя из прошлых конфликтов и эмоций.<br>
            • Речь безначальных различений — это самый глубокий уровень, обусловленный <em>прапанчей</em> (умозрительным множащимся многословием), накопленным в <em>Алая-виджняне</em>.<br><br>
            Бодхисаттва должен осознать, что между «выражением» (<em>abhilāpa</em>) и «выражаемым» (<em>abhilāpya</em>) нет реальной связи; это разделение — лишь работа различающего ума, создающая иллюзию объективной реальности.<a href="#ref-285" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-286"><sup>286</sup> Здесь разбирается механизм речи, вычленяя грубый физический механизм артикуляции (<em>samavāya</em>) и тонкий процесс умственного различения (<em>vikalpa</em>). Ответ на вопрос о тождестве речи и мысли опирается на принцип зависимого возникновения: речь не является чем-то самостоятельным (она обусловлена мыслью), но и не растворяется в мысли полностью, так как обладает определённой функцией «проявления смысла» (<em>arthābhivyaktitvāt</em>) во внешнем мире. Привязанность к словам возникает именно тогда, когда ум принимает выражение (<em>abhilāpa</em>) за само выражаемое (<em>abhilāpya</em>), порождая иллюзию объективной реальности.<a href="#ref-286" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-287"><sup>287</sup> Здесь проводится граница между познанием посредством умозрительного построения сети различений (<em>vikalpa</em>) и благородным постижением (<em>āryajñāna</em>). Высший смысл (<em>paramārtha</em>) определяется как недвойственный опыт, принципиально невыразимый в словах. Будда подчёркивает, что любая словесное построение «мимолётно» (<em>capala</em>) и обусловлено, тогда как истина самодостоверна. Пример царя и глиняных игрушек объясняет назначение учения: все термины — включая «шуньята», «признаки» и «дхармы» — искусные средства (<em>упайя</em>), имеющие лишь воспитательную ценность и не являются «истинными зверями», они подготавливают ум к восприятию «предела истинности» (<em>bhūtakoṭi</em>), который лежит за пределами любого описания.<a href="#ref-287" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-288"><sup>288</sup> В данном фрагменте Будда использует три уровня разрушения иллюзии реальности. Метафора миража показывает, как <em>клеши</em> (страсть и гнев) заставляют нас бежать за несуществующим. Метафора города гандхарвов объясняет механизм проекции: мы видим мир лишь потому, что наш ум полон «семян-категорий/понятий/представлений». Наконец, метафора сна обнажает природу памяти и рождения образов-понятий: даже когда объект исчезает, мы продолжаем приписывать ему реальность. Главный посыл здесь — <em>svacittadṛśyamātrānavabodha</em> (непонимание того, что всё есть лишь воспринимаемое собственным умом). Именно это неведение превращает пустое пространство в тюрьму двойственности: «бытия» и «небытия», «единства» и «различия».<a href="#ref-288" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-289"><sup>289</sup> Этот ряд примеров (картина, волоски, огненное колесо, пузыри) служит для описания «бытия» явлений в системе Йогачары. Они не являются ни абсолютно реальными (<em>sat</em>), ни абсолютно отсутствующими (<em>asat</em>). Как пузырь кажется жемчугом лишь в силу ошибки зрения, так и мир кажется состоящим из внешних объектов лишь в силу «отпечатков» (<em>vāsanā</em>). Привязанность к двойственности «есть/нет» ведёт к потере понимания Срединного пути, превращая практикующего либо в фаталиста, либо в материалиста. Подлинное видение — это понимание всего происходящего как динамического потока восприятия (<em>svacittadṛśya</em>), лишённого какой-либо неизменной сущности, подобно огненному колесу, возникающему от вращения горящей палочки в темноте.<a href="#ref-289" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-290"><sup>290</sup> Использование цепочки метафор (мираж, волоски, огненное колесо, отражение, механическая кукла, призрак, сын бесплодной женщины) указывает и на иллюзорность мира, и на метод освобождения. Ключевым является принцип «клин клином вышибают»: хотя употребляемые слова и понятия сами по себе не являются истиной, они служат инструментами для удаления грубых заблуждений. Когда цепляние за «бытие» и «небытие» устранено, инструмент должен быть оставлен, что ведёт к состоянию, в котором мудрец «не берёт на себя никаких утверждений» (<em>na kiṃcit pratijānate</em>), оставив все воззрения на бытие и небытие.<a href="#ref-290" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-291"><sup>291</sup> <strong>Четыре вида <em>дхьяны:</em></strong><br>
  <strong>I. <em>Дхьяна, свойственная невеждам</em></strong> (<em>bālopacārika-dhyāna</em>)<br>
  Термин <em>bāla</em> («дитя», «незрелый», часто переводимый как «невежда»)  в контексте <strong><em>Ланкаватары</em></strong> означает существо, лишённое правильного воззрения на природу ума, не пришедшее к недвойственности; <em>upacāra</em> — «практика, соответствующая уровню», или точнее: «созерцание, соответствующее начальному уровню, свойственное тем, кто ещё не вышел за пределы двойственного восприятия». Несмотря на название, эту <em>дхьяну</em> практикуют шраваки и пратьекабудды, достигшие значительных плодов. Их «невежество/незрелость» заключается в ограничении воззрением Малой колесницы: они достигают лишь бессамостности личности (<em>pudgala-nairātmya</em>), но их <em>дхьяна</em> не достигает постижения отсутствия «я» в дхармах (<em>dharmanairātmya</em>), они всё ещё остаются в плену реальности признаков (<em>lakṣaṇa</em>).<br>
  Что касается объекта созерцания, то санскритский составной термин задаёт полный перечень: (а) отсутствие «я» в личности (<em>pudgalanairātmya</em>); (б) собственные и общие характеристики явлений (<em>sva-sāmānya-lakṣaṇa</em>); (в) нечистота тела, включая конкретную практику медитации на скелете (<em>aśubhā-bhāvanā</em>, ср. <em>saṃkalā</em> — «совокупность форм»); (г) непостоянство, страдание, нечистота (<em>anitya, duḥkha, aśubha</em>). Практика ведётся последовательно (<em>pūrvottarottara</em>), вплоть до прекращения восприятия (<em>saṃjñā-nirodha</em>, <em>ниродха-самапатти</em>). Характерная черта такой <em>дхьяны</em> — привязанность (<em>abhiniveśa</em>) к признакам: «признак именно таков и не иначе»; ум всё ещё цепляется за форму, даже если форма — «нечистота», превращая созерцание страдания или нечистоты в новую догму.<br>
  Цзунми в «Предисловии» помещает эту <em>дхьяну</em> на третью ступень своей пятичленной классификации — «дхьяна Малой колесницы». Он её оценивает как не ошибочную, но неполную — она не достигает постижения всего воспринимаемого как <em>cittamātra</em>.<br>
  <strong>II. <em>Дхьяна исследования смысла</em></strong> (<em>arthapravicaya-dhyāna</em>)<br>
  <em>Artha</em> — «смысл, объект познания, цель»; <em>pravicaya</em> — «тщательное исследование, аналитическое разложение».<br>
  Процесс исследования разворачивается в два этапа: (1) сначала практик закрепляет отсутствие «я» в личности (<em>pudgala-nairātmya</em>), анализируя собственные и общие признаки индивидуальности (<em>sva-sāmānyalakṣaṇa</em>), чтобы окончательно убедиться в отсутствии «хозяина» внутри <em>скандх</em>; (2) затем он обращается к критике внешних доктрин (тиртхиков) (<em>bāhyatīrthakarasvaparobhayābhāvaṃ kṛtvā</em>), установив отсутствие «я», «другого» и «обоих». После этого двойного превосхождения — хинаянского воззрения и крайностей тиртхиков — практик переходит к последовательному исследованию отсутствия «я» в дхармах (<em>dharmanairātmya</em>) и признаков ступеней бодхисаттвы (<em>bhūmi-lakṣaṇa</em>, <em>daśabhūmi</em>). Китайский перевод Гунабхадры также упоминает эту двуступенчатую структуру: «у внешних [тиртхиков] — отсутствие "я", "другого" и "обоих"».<br>

  <strong>III. <em>Дхьяна опоры на Таковость</em></strong> (<em>tathatālambana-dhyāna</em>)<br>
  <em>parikalpita-nairātmya-dvaya-vikalpa-yathābhūtāvasthānād apravṛtter vikalpasya</em>: «вследствие пребывания в реальности как она есть (<em>yathābhūta-avasthāna</em>) — не возникает (<em>apravṛtti</em>) различение о воображаемом двойном отсутствии "я"». Речь идёт не о волевом акте подавления, а о том, что различение само не возникает — как волны не рождаются на зеркальной поверхности озера. Китайский перевод Гунабхадры: «в месте реальности как она есть не возникает различение» — подтверждает именно такое прочтение.<br>
  Даже идея различение «я»/«не-я» остаётся препятствием, если удерживается как устойчивое понятие. Третья дхьяна превосходит не только «я», но и понятие «анатман» как объект цепляния. Это — позиция поздней Йогачары: даже <em>шуньята</em> не должна становиться новым «я».<br>
  <em>Ālambana</em> — «объект опоры» — здесь применён к Таковости (<em>tathatā</em>), которая по определению не является обычным объектом. Таковость — не предмет медитации, она — единственное оставшееся «содержание» опыта после исчезновения всех наслоений понятий.<br>

  <strong>IV. <em>Дхьяна Татхагаты</em></strong> (<em>tāthāgata-dhyāna</em>)<br>
  <em>Три составляющих</em> (по санскр. <em>tāthāgatabhūmyākārapraveśaṃ pratyātmāryajñānalakṣaṇatrayasukhavihāra-acintyasattvakṛtyakaraṇatayā</em>): (а) вхождение в образ ступеней Татхагаты (<em>tāthāgata-bhūmi-ākāra</em>); (б) пребывание в блаженстве трёх признаков личного благородного знания (<em>pratyātmāryajñāna-lakṣaṇa-traya</em>) — в комментаторской традиции соотносятся с тремя вратами освобождения (<em>śūnyatā, animitta, apraṇihita</em>) или тремя телами Будды (<em>trikāya</em>); (в) непостижимые деяния ради живых существ (<em>acintya-sattva-kṛtya</em>) — спонтанная деятельность будды, не обусловленная намерением (<em>anābhoga</em>).<br>
  Цзунми в «Предисловии» отождествляет эту <em>дхьяну</em> с «дхьяной высшей колесницы» и сутью чаньской передачи Бодхидхармы: непосредственное постижение природы ума как изначально чистого. Шэньхуэй цитирует <strong><em>Вималакирти-сутру</em></strong>: «Наблюдая Татхагату: прежде он не приходил, в будущем не уйдёт, ныне не пребывает нигде — именно это и есть <em>дхьяна Татхагаты</em>» — сближая её с пониманием непребывания (<em>anupalambha / wu-zhu</em>), центральной для хуэйнэновской линии.<br>

  В гатхе 160 в термине <em>padma-pātāla</em> <em>pātāla</em> — «подземные миры, преисподняя, бездна». Китайский перевод Гунабхадры передаёт это слово как «глубокий и опасный» (указывая на бездну), а само сочетание означает «лотос над бездной» — намеренный парадоксальный образ: символ просветления, укоренённый в самой глубине сансары. Образы этой гатхи (луна, солнце, лотос над бездной, огонь в небе) — медитативные опорные знаки созерцания первых трёх дхьян.<br>
  В гатхе 161 в выражении «нимитты как ловушка» <em>nimitta</em> — «опорный медитативный знак, видение». Привязанность к <em>нимиттам</em> — общий изъян практик тиртхиков и шраваков. Глагол <em>nipātayanti</em> — «низвергают» — указывает, что даже <em>самадхи</em> шраваков, построенное на <em>нимиттах</em>, рассматривается в <strong><em>Ланкаватаре</em></strong> как падение относительно высшей реализации.<br>
  В гатхе 162 выражение <em>nimittaṃ tathatānugam</em> допускает два прочтения: (1) «Признак, следующий за Таковостью» (<em>anu + gam</em>) — прикосновение Будд вторично по отношению к Таковости, следует после неё — точнее. (2) «Признак, согласующийся с Таковостью» (<em>anugata</em>) — прикосновение как внешнее выражение внутренней реализации. Оба смысла, по всей видимости, совмещены намеренно. Китайский перевод Гунабхадры акцентирует второй: «рука Будды касается его головы, запечатлевая образ реальности-как-она-есть» — прикосновение как «печать» (<em>mudrā</em>), удостоверяющая реализацию.<br>

  <em>Первоисточники для данной сноски</em>: Vaidya P.L. (ed.). <em>Saddharmalaṅkāvatārasūtram</em>. Buddhist Sanskrit Texts 3. Darbhanga: Mithila Institute, 1963. — Гунабхадра, пер. <em>Ланкаватара-сутры</em> (四卷本), ок. 443 г. Тайсё 670, T16. — Бодхируци, пер. (十卷本). Тайсё 671. — Шикшананда, пер. (七卷本). Тайсё 672.<br>
  <em>Комментаторская традиция</em>: Цзунми. «Предисловие к своду всех источников о дхьяне». Тайсё 2015, T48. — Шэньхуэй. Записи (Дуньхуанский вариант). В: Ху Ши (сост.). <em>Собрание сочинений Хэцзэ Шэньхуэя</em>. Шанхай, 1930. — Нань Хуайцзинь. <em>«Ланкаватара-сутра: смысл для современности»</em>. Тайбэй: Лаогу вэньхуа, 1993.
  <a href="#ref-291" class="citation-back">↩</a>
</p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-291"><sup>291</sup> <em>sarva-vijñāna-svabhāva-vāsanā-ālaya-manas-manovijñāna-dṛṣṭi-vāsanā-parāvṛtti</em> — единый составной термин, раскрывающий два уровня преобразования: (1) отпечатки, формирующие иллюзию «собственной природы» у всех восьми сознаний; (2) отпечатки ложных воззрений, специфически связанные с тремя внутренними сознаниями (<em>Алайя, манас, мановиджняна</em>). Это отражает двойственную природу завесы: <em>kleśāvaraṇa</em> (эмоции) и <em>jñeyāvaraṇa</em> (неведение о природе дхарм).<a href="#ref-291" class="citation-back">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-293"><sup>293</sup> Этот отрывок — один из наиболее философски насыщенных фрагментов <em>Ланкаватары</em>. Махамати выдвигает серию возражений против буддийского учения о зависимом возникновении (<em>pratītyasamutpāda</em>), воспроизводя реальную критику буддизма со стороны брахманистских школ, зафиксированную в полемических текстах (особенно в <em>Ньяя-сутрах</em> Гаутамы с комментарием Ватсьяяны; <em>Юкти-дипике</em> на <em>Санкхья-карике</em>, где критикуется буддийская доктрина мгновенности и причинности). Центральный пункт критики: буддизм, отрицая фундаментальную реальность (<em>dravya</em>), не может объяснить устойчивость причинно-следственных связей. Санкхья постулирует <em>Пракрити</em> как вечную, несотворённую первопричину (<em>pradhāna, mūla-prakṛti</em>), которая сама не возникла, но порождает все видоизменения (<em>vikāra</em>). Ньяя-вайшешика постулирует <em>Ишвару</em> как независимую действующую причину (<em>nimitta-kāraṇa</em>) и атомы (<em>paramāṇu</em>) как вечную материальную причину (<em>upādāna-kāraṇa</em>). Обе школы обвиняют буддизм в том, что отказ от абсолютной первопричины ведёт к <em>anavasthā-doṣa</em> (изъяну бесконечного регресса).<br>Ответ виджнянавады, сформулированный в <em>Ланкаватаре</em>, станет классическим для позднейшей традиции (Дигнага, Дхармакирти, Шантаракшита): причинность не является непреложным свойством мира, а тем, как ум связывает структуру опыта. Вопрос «что является абсолютной причиной мира» некорректен, поскольку «мир» (как независимая от сознания реальность) не существует. Существует лишь поток сознания (<em>vijñāna-santāna</em>), в котором одно содержание закономерно следует за другим — и эту закономерность мы, в силу привычки (<em>vāsanā</em>), ошибочно проецируем вовне как «объективную причинность».<br><strong>I. Структура возражения Махамати</strong><br><strong>Первое обвинение: терминологическая подмена.</strong> Махамати утверждает, что Будда лишь переименовывает «причины» (<em>kāraṇa</em>) в «условия» (<em>pratyaya</em>), но по сути описывает то же самое, что и тиртхики: возникновение одного из другого. Разница — лишь в словах (<em>pratyaya-paryāya-antara</em> — «иной способ обозначения условий»), но не в самом учении.<br><strong>Второе обвинение: скрытая беспричинность (<em>ahetuvāda</em>).</strong> Формула «из неведения — формирующие факторы, из формирующих факторов — сознание…» (двенадцатичленная цепь зависимого возникновения) на самом деле является учением о беспричинности. Логика такова: если причина <strong>А</strong> сама обусловлена условием <strong>Б</strong>, условие <strong>Б</strong> — условием <strong>В</strong> и так до бесконечности, то абсолютной первопричины нет. Бесконечный регресс (<em>anavasthā</em>) равнозначен отсутствию причины вообще. Это классическое возражение школ, утверждающих реальное существование независимых сущностей: без независимой, несотворённой первопричины (как <em>Пракрити</em> в санкхье или <em>Ишвара</em> в ньяе) любое учение о причинности вырождается в беспричинность.<br><strong>Третье обвинение: проблема одновременности и последовательности.</strong> Махамати указывает на классическую проблему: формула «при наличии этого возникает то» (<em>asmin sati idam bhavati</em>) логична только если причина и следствие существуют одновременно (<em>yugapat</em>). Но тогда нет порождения — они уже сосуществуют. Если же они последовательны (<em>krama-vṛtti</em>), то когда причина ещё есть, следствия ещё нет; а когда следствие возникло, причина уже прекратилась. Как же несуществующая причина может породить существующее следствие? Эта дилемма была центральной в индийской дискуссии о причинности (ср. спор <em>satkāryavāda</em> против <em>asatkāryavāda</em> в санкхье и ньяе).<br><strong>Четвёртое обвинение: взаимная зависимость определений.</strong> У Будды «причина зависит от следствия, а следствие — от причины» (<em>kāraṇam api kāryāpekṣaṃ kāryam api kāraṇāpekṣam</em>). То есть то, что мы называем причиной, определяется через то, что оно производит (следствие); а следствие — через то, что его произвело (причину). Это взаимная опора понятий (<em>anyonya-āśraya</em>), а не подлинная причинность. Возникает «путаница причин и условий» (<em>hetupratyaya-saṃkara</em>) и «взаимный бесконечный регресс» (<em>anyonya-anavasthā</em>). У тиртхиков этой проблемы нет: причина (<em>Пракрити</em>, <em>Ишвара</em>) абсолютна, независима и сама не возникла (<em>a-pratītya-samutpanna</em>), но порождает всё остальное.<br><strong>II. Ответ Будды: виджнянавадинское переосмысление</strong><br>Будда не отрицает возражений Махамати по существу. Вместо этого он указывает, что все эти проблемы возникают только при реалистическом понимании причинности — то есть если верить в подлинное существование внешних объектов, выступающих причинами и следствиями.<br><strong>Ключ ответа: отсутствие противопоставляющей двойственности схватывающего и схватываемого.</strong><br>«Моё учение — не о беспричинности… Когда Я говорю: «при наличии этого возникает то», Я исхожу из отсутствия схватываемого и схватывающего (<em>grāhya-grāhaka-abhāva</em>) и из понимания того, что всё — лишь воспринимаемое собственным умом (<em>svacittadṛśyamātra</em>)». Здесь — суть виджнянавадинского переосмысления причинности. Зависимое возникновение в <em>Ланкаватаре</em> не является описанием объективного процесса во внешнем мире, это описание того, как в потоке сознания одно содержание (<em>vijñapti</em>) обусловливает появление другого. Нет подлинных «причин» и «следствий» как внешних вещей — есть только последовательность содержаний ума, каждое из которых возникает в зависимости от предыдущего.<br><strong>Разрешение проблемы одновременности/последовательности.</strong><br>Если причина и следствие — не внешние вещи, а содержания одного потока сознания, вопрос об их «одновременности» или «последовательности» во внешнем времени отпадает. В потоке сознания один мгновенный момент (<em>kṣaṇa</em>) обусловливает следующий не через подлинное «порождение» (как огонь порождает дым), а через преемственность ряда (<em>santāna</em>). Формула «при наличии этого возникает то» описывает не подлинное возникновение одного из другого, а закономерную последовательность в потоке опыта.<br><strong>Разрешение проблемы бесконечного регресса.</strong><br>Обвинение в <em>ahetuvāda</em> (беспричинности) справедливо, если искать абсолютную первопричину во внешнем мире. Но виджнянавада не утверждает подлинности внешнего мира: «этот изъян касается лишь тех, кто привязан к двойственности субъекта и объекта и не понимает, что [так называемый] внешний [мир] лишён бытия и небытия (<em>bāhya-sva-viṣaya-bhāva-abhāva</em>)».<br><em>bhāva-abhāva</em> — пара «бытие-и-небытие». Виджнянавада отвергает не только вечность («внешний мир существует субстанциально»), но и уничтожение («внешнего мира абсолютно нет»). Внешний мир — не реален и не нереален; он — проекция сознания (<em>vijñapti-mātra</em>). Поэтому вопрос о его «первопричине» некорректен.<br><strong>Источники</strong><br>Современные исследования: Kalupahana David J. Causality: The Central Philosophy of Buddhism. Honolulu: University of Hawaii Press, 1975 (глава 9: «Criticisms and Replies»). — Westerhoff Jan. Nāgārjuna's Madhyamaka: A Philosophical Introduction. Oxford: OUP, 2009, ch. 3 (анализ буддийской критики субстанциалистской причинности). — Siderits Mark. Buddhism as Philosophy. Indianapolis: Hackett, 2007, ch. 5 (виджнянавадинская теория причинности).<a href="#ref-293" class="citation-back">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-294"><sup>294</sup> Этот отрывок продолжает критику наивного реализма, начатую в подглаве 2.38. Там опровергалась объективная причинность (явления не порождают друг друга вне сознания); здесь — что слова не указывают на независимо существующие объекты. Обе критики направлены против веры в реальность внешнего мира.<br><br>
<strong>I</strong>. Возражение Махамати воспроизводит позицию языкового реализма, характерную для брахманистской традиции: существование слова доказывает существование обозначаемого объекта. Логика аргумента такова: если бы объектов не было, не было бы и слов для их обозначения; но слова есть — следовательно, объекты реальны. Эта позиция опиралась на представление о сакральности ведийского языка и фундаментальной связи между именем и именуемым (<em>nāma-nāmin-sambandha</em>). То есть полагали, что слово не просто условный знак, но выражение сущности явления.<br>
Буддийская позиция (как в <strong><em>Ланкаватаре</em></strong>, так и в других текстах традиции) утверждает условность языка: слова — это договорные обозначения (<em>saṃketa</em>), установленные по соглашению, а не отражение реальной структуры мира. Нет необходимой связи между словом и объектом — связь устанавливается привычкой и договорённостью. Следовательно, из наличия слова нельзя вывести существование объекта.<br><br>
<strong>II</strong>. Рога зайца, шерсть черепахи, сын бесплодной женщины (<em>śaśa-viṣāṇa</em>, <em>kūrma-roma</em>, <em>vandhyā-putra</em>) — классические буддийские примеры того, чего в природе нет и быть не может. О них можно говорить, но самих предметов не существует. Это прямо опровергает утверждение: «раз есть слово — значит, есть и то, что оно обозначает».<br>
Формула «ни бытие, ни небытие» (<em>na bhāvā nābhāvāḥ</em>) показывает, как следует понимать подобные вещи: рога зайца не существуют в реальности, но при этом не являются полной пустотой — они возникают в уме как воображаемые образы.<br><br>
<strong>III</strong>. Слова — лишь один из многих способов передачи Дхармы. Будда перечисляет иные: взгляд, жесты, движение бровей, мигание глаз, смех, зевота, кашель, воспоминание, трепет. Никакой неразрывной связи между словом и реальностью нет. Истина может быть передана любым путём — а подчас и вовсе без слов.<br>
В мире Будды Самантабхадры, который называют «Немигающий Благоухающий» (<em>Анимиша-Гандхасугандха</em>), бодхисаттвы обретают высшую реализацию — терпение в не-возникновении дхарм — просто взирая друг на друга немигающими глазами. Здесь название мира и способ передачи Дхармы совпадают: мир — Немигающий, и созерцание — немигающее. Это указание на то, что истина передаётся напрямую — от ума к уму, без посредства речи.<br>
Такое постижение невыразимо словами — они лишь указывают путь, но не передают опыт. Для продвинутых практиков слова не нужны. Именно этот отрывок <strong><em>Ланкаватары</em></strong> лёг в основу позднейшей дзэнской формулы: «передача вне слов и письмен».<br>
И даже в нашем мире всё это видно наглядно: черви и мухи совершают свои дела, не имея языка в нашем понимании. Это напоминание о том, что слова — надстройка над более глубокими процессами — в буддизме их называют кармическими отпечатками (<em>vāsanā</em>). Даже сложное, целенаправленное поведение возможно без речи.<br><br>
<strong>IV</strong>. Если предшествующий отрывок указывал, что явления не порождают друг друга в реальности — то, что мы принимаем за «внешнюю причинность», есть лишь закономерная смена образов в потоке сознания, то данная часть текста добавляет: слова тоже не связаны с какими-то внешними объектами — они соотносятся лишь с тем, что возникает в уме.<br>
Оба отрывка разоблачают одну и ту же иллюзию — веру в то, что наши понятия и слова отражают независимую реальность. Причинность и язык — способы, которыми ум упорядочивает опыт.<a href="#ref-294" class="citation-back">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-295"><sup>295</sup> Парадокс «вечности иллюзии» (<em>bhrānti</em>) разрешается через различение уровней реальности в виджнянаваде. <em>Bhrānti</em> не существует как объективный факт (<em>na bhāva</em>), но в то же время и не есть абсолютное ничто (<em>na abhāva</em>) — она вечна как постоянная структура опыта, пока действует неведение. Например, вода Ганги видна людям как вода, претам — как гной, богам — как нектар; ни одно восприятие не «правильное», все — проекции кармы. Даже Благородные продолжают видеть иллюзорные формы (мираж, отражение), но не принимают их за реальность; иллюзия сохраняет способность являться, но утрачивает для них силу заблуждения.<a href="#ref-295" class="citation-back">↩</a></p>
<p class="my-2" id="citation-296"><sup>296</sup> Здесь формулируется недвойственность иллюзии и истины: Благородный не постулирует ни заблуждение, ни истину как отдельные сущности — само заблуждение, когда оно постигнуто без привязанности, есть истина (классическая махаянская формула: сансара = нирвана).<a href="#ref-296" class="citation-back">↩</a></p>
<p class="my-2" id="citation-297"><sup>297</sup> Если йогин, «устранив заблуждение», цепляется за идею «я достиг чистоты» или за опорный знак (<em>nimitta</em>) своего достижения — это порождает новое, более тонкое заблуждение. Метафора <em>timira</em> (глазная болезнь, катаракта) указывает: подобно тому, как попытка очистить глаз от одного загрязнения может внести новое, так и привязанность к «устранению» создаёт новое искажение восприятия.<a href="#ref-297" class="citation-back">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-298"><sup>298</sup> Махамати выдвигает логическое возражение против уподобления дхарм магии. Магия многообразна (<em>vicitra</em>) благодаря единой внешней причине — знанию фокусника. Но формы мира (<em>rūpa</em>) многообразны без единой причины — они возникают из бесчисленных условий (<em>hetupratyaya</em>). Следовательно, простое сходство в многообразии не делает дхармы подобными магии.<a href="#ref-298" class="citation-back">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-299"><sup>299</sup> <strong>I. Четырнадцать необъяснимых вопросов (<em>avyākṛta</em>)</strong><br>
В палийском каноне Будда оставляет без ответа четырнадцать вопросов (<em>catuddasavyākatavatthūni</em>), сгруппированных по принципу тетралеммы (<em>catuṣkoṭi</em> — утверждение, отрицание, оба, ни то ни другое):<br>
О мире: вечен ли он? не вечен? и вечен, и не вечен? ни вечен, ни не вечен?<br>
О пространственных границах мира: конечен ли? бесконечен? и то, и другое? ни то, ни другое?<br>
О Татхагате после смерти: существует ли? не существует? и то, и другое? ни то, ни другое?<br>
О душе и теле: душа (<em>jīva</em>) и тело (<em>śarīra</em>) — одно или разное?<br>
Будда последовательно отказывается отвечать на них, поясняя, что такие вопросы «не ведут к благу, не ведут к нирване».</p>
<p class="my-2"><strong>II. Палийская традиция объясняет молчание Будды прагматически:</strong> эти вопросы отвлекают от практики. Классическая метафора — человек, раненный отравленной стрелой, который вместо извлечения стрелы требует узнать, кто её выпустил и из какого дерева она сделана.<br>
<em>Ланкаватара</em> добавляет виджнянавадинское объяснение:<br>
• Чтобы уберечь слушателей от страха (<em>utrāsa-pada-vivarjana</em>): слабые умом (<em>buddhi-vaikalya</em>) испугались бы доктрины отсутствия «я», если бы Будда прямо сказал: «Атмана нет».<br>
• Чтобы опровергнуть тиртхиков: их вопросы основаны на ложной предпосылке — вере в реальность атмана или внешнего мира. Ответить — значит принять эту предпосылку.<br>
• Для продвинутых практиков нет «необъяснимых вопросов». Те, кто постиг «только-ум» (<em>svacittadṛśyamātra</em>), понимают: вопрос «вечен ли мир?» бессмыслен, поскольку нет «мира» вне сознания. Это подразумевает устранение ложной предпосылки самого вопроса.</p>
<p class="my-2"><strong>III. Четыре способа ответа (<em>catur-vidha-vyākaraṇa</em>):</strong><br>
• Прямой ответ (<em>ekāṃśa-vyākaraṇa</em>): «Все обусловленные дхармы непостоянны» — универсальное утверждение.<br>
• Аналитический ответ (<em>vibhajja-vyākaraṇa</em>): «Убийство плохо? — Да, если намеренное; нет, если случайное» — требует различения контекста.<br>
• Встречный вопрос (<em>paṭipucchā-vyākaraṇa</em>): «Много ли песчинок в Ганге?» — «А что ты понимаешь под "много"?» — выявляет неясность в самом вопросе.<br>
• Оставление без ответа (<em>sthāpanīya-vyākaraṇa</em>): Вопрос отклоняется, поскольку основан на ложной предпосылке или не способствует освобождению. <em>sthāpanīya</em> — временная педагогическая мера (<em>kālāntara-deśana</em>, «учение для другого времени») для незрелых (<em>aparipakvendriya</em>). Для зрелых (<em>paripakvendriya</em>) нет ничего «необъяснимого» — они видят природу вопросов.<a href="#ref-299" class="citation-back">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-300"><sup>300</sup> Настоящий отрывок представляет собой единую логическую цепь, где каждое последующее утверждение вытекает из предыдущего как необходимое следствие. Структура аргументации строится на последовательном разрушении овеществления — приписывания независимого существования дхармам.<br><br>
<strong>1. Отсутствие деятеля → невозникновение (<em>akārakatvāt → anutpannāḥ</em>)</strong><br>
Первое звено отвергает классическую индийскую модель причинности, предполагающую тройку «деятель — действие — результат». Если нет самостоятельного субъекта (<em>kāraka</em>), невозможно и само действие (<em>kriyā</em>), следовательно, и возникновение дхарм как независимых сущностей. Дхармы не возникают ни из бытия (как у санкхьи), ни из небытия (как у вайшешики), ибо обе модели предполагают наличие деятеля.<br><br>
<strong>2. Невозникновение → отсутствие собственной природы (<em>anutpannāḥ → niḥsvabhāvāḥ</em>)</strong><br>
То, что никогда не возникало, не может обладать неизменной сущностью (<em>svabhāva</em>). Собственная природа предполагает способность возникнуть, устоять и прекратиться. Если возникновения нет, неизменная сущность невозможна изначально. Ум, исследующий дхармы, не обнаруживает их признаков как действительно существующих.<br><br>
<strong>3. Отсутствие природы → вне составления и разложения (<em>niḥsvabhāvāḥ → anāyūhāniryūhāḥ</em>)</strong><br>
<em>Āyūha</em> (составление, сочленение) и <em>niryūha</em> (разложение, расчленение) — умственные построения, предполагающие наличие составляемого предмета. Если дхармы лишены неизменной сущности, ум не может их составить через признаки (<em>lakṣaṇa</em>), равно как не может и разложить то, что не было составлено. Признаки, будучи сочиняемы умом, не сочиняются; будучи разлагаемы — не разлагаются.<br><br>
<strong>4. Вне составления → непрекращаемость (<em>anāyūhāniryūhāḥ → aniruddhāḥ</em>)</strong><br>
Здесь происходит резкий логический поворот. Если дхармы нельзя составить (<em>āyūha</em>), их нельзя и разрушить (<em>niryūha</em>). Если нет процесса возникновения через составление, нет и процесса прекращения. То, что никогда не возникало, не может прекратиться. Следовательно, дхармы <em>aniruddhāḥ</em> — неподверженные прекращению, непреодолимые, неистребимые.<br><br>
<strong>5. Непрекращаемость → парадокс непостоянства и постоянства (<em>aniruddhāḥ → anityāḥ/nityāḥ</em>)</strong><br>
Финальное звено разрешает кажущееся противоречие. На уровне признаков (<em>lakṣaṇa</em>) дхармы непостоянны, ибо признаки возникают и прекращают. На уровне таковости (<em>tathatā</em>) дхармы постоянны, ибо в их непостоянстве нет действительного возникновения и прекращения — оно само лишено неизменной сущности. Постоянство достигается через непостоянство, когда ум перестаёт овеществлять оба понятия.<br><br>
<strong>Общий смысл</strong><br>
Вся цепь направлена на разрушение двойственности «существование — несуществование» (<em>bhāvābhāva</em>). Последовательное отрицание умственных построений приводит к <em>tathatā</em> — таковости, единственному, что остаётся, когда исчерпаны все бытийные определения. Это ключевое положение йогачары и мадхьямаки, подготавливающее почву для понимания <em>cittamātra</em> (только-ум): поскольку внешние дхармы не возникают, всё есть лишь воспринимаемое собственным умом.<a href="#ref-300" class="citation-back">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-301"><sup>301</sup> Фраза допускает два основных толкования в буддийской традиции.<br><br>
1. В классической йогачаре (как она интерпретировалась в китайской и тибетской традициях) <em>āśraya</em> («опора») указывает на <em>алая-виджняну</em> — сознание-сокровищницу. Заблуждение состоит в том, что <em>манас</em> не распознаёт: <em>скандхи</em> — разновидности <em>алайи</em>, а не внешние объекты. Из-за непонимания хода благородного знания <em>скандхи</em> овеществляются как самостоятельные сущности, хотя они — лишь «волны» на «океане» <em>алайи</em>. Различение <em>скандх</em> подобно принятию отражений на экране за реальных персонажей, хотя они — лишь свет самого экрана.<br><br>
2. Альтернативная интерпретация (близкая к дзэнскому прочтению Д.&nbsp;Т.&nbsp;Судзуки) связывает <em>āśraya</em> непосредственно с Таковостью (<em>tathatā</em>). Благородное знание видит <em>скандхи</em> как недвойственные с абсолютной реальностью. Обычный ум же, заблуждаясь о природе этого знания, сначала отождествляет <em>скандхи</em> с «я», затем — пытаясь отвергнуть это — продолжает мыслить их как нечто отдельное (чтобы было что отвергать). <em>Āśrayānanyatva</em> указывает: <em>скандхи</em> неотличны от самой реальности (<em>tathatā</em>), а не от какой-либо отдельной основы. Оба толкования сходятся: различение <em>скандх</em> исчезает, когда ум перестаёт проецировать разделение между «основой» и «проявлениями».<a href="#ref-301" class="citation-back">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-302"><sup>302</sup> Шлока выстраивает восходящую трёхчастную схему: <em>citta</em> (ум как таковой) — <em>jñāna</em> (рассудочное знание) — <em>prajñā</em> (мудрость). Это различение перекликается с классификацией из <strong><em>Махаянасамграхи</em></strong> Асанги, где разграничиваются сознание, порождающее видимость внешних объектов, знание, движущееся в понятиях и умозаключениях, и знание вне образов (<em>nirvikalpajñāna</em>). Термин <em>nirābhāsa</em> — «лишённый образа (<em>ābhāsa</em>)» — технически указывает именно на последнее: ту фазу познания, в которой снято разделение на познающего и познаваемое. В <strong><em>Дхармадхармататавибхаге</em></strong> («Различение явлений и их природы»), приписываемой Майтрее/Асанге, то же состояние описывается как преодоление двойственности схватываемого и схватывающего (<em>grāhya-grāhaka-dvaya</em>). Слово <em>viśeṣa</em> («особое состояние») подчёркивает, что речь идёт о качественно иной ступени опыта, достигаемой в созерцании, — переживаемой как полнота целостного, нераздвоенного восприятия.<a href="#ref-302" class="citation-back">↩</a></p>

<p class="my-2" id="citation-303"><sup>303</sup> Термин <em>dauṣṭhulya</em> — один из специфических понятий йогачары, трудно передаваемых на русский язык. В <strong><em>Йогачарабхуми</em></strong> и <strong><em>Махаянасамграхе</em></strong> он обозначает особую отягощённость, неподатливую инертность/негибкость/оцепенелость ума и тела, препятствующую как созерцательной практике (<em>bhāvanā</em>), так и прямому восприятию природы вещей (<em>dharmatā</em>). Это не просто загрязнённость в общем смысле (<em>kleśa</em> или <em>āvaraṇa</em>), а именно практическая помеха: <em>dauṣṭhulya</em> делает ум неспособным к усилию освобождения. Противоположность ему — <em>karmanyatā</em>, «рабочая пригодность» ума и тела, взращиваемая через <em>samādhi</em>. В данном контексте признак (<em>nimitta</em>) назван «несущим <em>dauṣṭhulya</em>», поскольку именно через цепляние за признаки ум приобретает эту инертную привязанность к выстроенным им же образам.<a href="#ref-303" class="citation-back">↩</a></p>

<p class="my-2" id="citation-304"><sup>304</sup> Гатхи 181-184 посвящены учению о трёх природах (<em>trisvabhāva</em>): воображаемой (<em>parikalpita</em>), зависимой (<em>paratantra</em>) и совершенной (<em>pariniṣpanna</em>). Утверждение, что воображаемая природа не имеет самостоятельного бытия внутри зависимой, но обнаруживается через неё в акте заблуждения (<em>bhrānti</em>) сходным образом формулирует Васубандху в <strong><em>Тридцати строфах</em></strong> (<em>Triṃśikā</em>): зависимая природа служит основанием (<em>āśraya</em>), на котором воображаемая природа надстраивается через наложение (<em>samāropa</em>), тогда как совершенная природа — это та же зависимая, взятая без наложений, в её подлинном виде.<br>Что касается парадоксального выражения: «воображаемое есть зависимое» — вне зависимой природы воображаемое не имеет никакой точки опоры. Его «материалом» всегда служит зависимое, ошибочно принятое за нечто независимо существующее. Иными словами, воображаемое не существует отдельно от зависимого — оно есть зависимое, воспринятое через заблуждение.<a href="#ref-304" class="citation-back">↩</a></p>

<p class="my-2" id="citation-305"><sup>305</sup> Отождествление воображаемого (<em>parikalpita</em>) с условной истиной (<em>saṃvṛti</em>) — особенность учения <strong><em>Ланкаватары</em></strong>. В мадхьямике — у Нагарджуны и Чандракирти — <em>saṃvṛti</em> охватывает весь мир явлений, включая зависимое возникновение (<em>pratītyasamutpāda</em>), которое не считается заблуждением.<br>В йогачаре же, и особенно в <strong><em>Ланкаватаре</em></strong>, воображаемое выделяется как то, что не имеет опоры в вещах: это лишь наложение (<em>samāropa</em>), лишённое реальной основы. Именно его здесь называют <em>saṃvṛti</em>.<br>Поэтому «пресечение» (<em>cheda</em>) — не устранение мира явлений, а прекращение именно <em>parikalpita</em>, ошибочного наложения на зависимую природу.<br>Сфера Благородных (<em>āryagocara</em>) открывается, когда зависимое видится без ментальных образов (<em>nirābhāsa</em>) — то есть в своей совершенной природе (<em>pariniṣpanna</em>).<br>Схожий образ сферы Благородных встречается в <strong><em>Сандхинирмоканасутре</em></strong>, где <em>āryagocara</em> связывается с <em>самадхи</em>, свободным от ментальных образов.<a href="#ref-305" class="citation-back">↩</a></p>

<p class="my-2" id="citation-306"><sup>306</sup> Оба примера — йогин, видящий один объект по-разному, и больной <em>тимирой</em> — показывают, что многообразие (<em>citra</em>) не принадлежит объекту, оно возникает в уме. Зависимая природа, воспринимаемая невеждами, подобна видению при <em>тимире</em> и не является нереальной, она искажена наложением воображаемого.<a href="#ref-306" class="citation-back">↩</a></p>

<p class="my-2" id="citation-307"><sup>307</sup> Три уподобления — золото, вода, небо — образуют нарастающий ряд от частного к безграничному. В буддийской литературе небо (<em>gagana, ākāśa</em>) устойчиво служит образом <em>dharmadhātu</em> или <em>tathātā</em>: оно изначально чисто, а облака — лишь случайные наслоения. Тот же образ развёрнут в <strong><em>Ратнаготравибхаге</em></strong> применительно к природе будды (<em>tathāgatagarbha</em>): она подобна небу, омрачения — облакам. В данном контексте «зависимое, очищенное от вымысла» указывает на переход от <em>paratantra</em> к <em>pariniṣpanna</em>: одна и та же ткань опыта, взятая без наложений <em>паракальпиты</em>, оказывается совершенной природой.<a href="#ref-307" class="citation-back">↩</a></p>

<p class="my-2" id="citation-308"><sup>308</sup> <em>Samāropa</em> — приписывать зависимому то, чего у него нет (например, независимую неизменную сущность). <em>Apavāda</em> — отрицать то, что есть (например, само зависимое). Гатха отвергает обе крайности: воображаемого нет, но зависимое существует. Это — срединный путь, выраженный в терминах трёх природ.<a href="#ref-308" class="citation-back">↩</a></p>

<p class="my-2" id="citation-309"><sup>309</sup> Здесь мы видим довод от нелепого следствия. Шлока применяет классическую форму <em>prasaṅga</em> — сведения к нежелательному выводу. Логика такова: если воображаемое и зависимое абсолютно разделены и первая есть чистое небытие по отношению ко второй, возникают два невозможных следствия — бытие не может существовать само без себя, а возникновение из полного ничто невозможно по самой природе причинности. Первое нарушает закон самотождественности бытия, второе — принцип причинно-следственной связи (<em>hetupratyayatā</em>). Тем самым отвергается представление о полной раздельности природ: воображаемое не есть абсолютное ничто, оно надстраивается над зависимым как его искажённое восприятие. Схожую логику применяет Васубандху в <strong><em>Двадцати строфах</em> </strong>(<strong><em>Viṃśatikā</em></strong>), отвергая вывод, что отрицание внешней реальности объектов равнозначно признанию абсолютного ничто.<br>
    Если суммировать сказанное простыми словами, то <em>paratantra</em> — это поток опыта, который «есть». Он подобен экрану или чистой воде; <em>parikalpita</em> — это то, как мы этот поток интерпретируем (делим на «я» и «мир»). Это «муть» в воде или <em>timira</em> в глазу; <em>pariniṣpanna</em> — это то же <em>paratantra</em>, когда оно очищено от «мути» <em>parikalpita</em>.<br>
Ошибка (<em>samāropa</em>) — это наделять мир признаками, которых в нём нет; ошибка (<em>apavāda</em>) — это отрицать сам поток жизни; а мудрость (<em>prajñā</em>) — это видеть поток таким, как он есть, в состоянии <em>nirābhāsa</em> (без ментальных образов), когда «золото» чисто от любых навязанных ему форм.<a href="#ref-309" class="citation-back">↩</a></p>

<p class="my-2" id="citation-310"><sup>310</sup> Число видов воображаемой природы варьируется в традиции. В подглаве 2.54 дана классификация из 12 типов <em>vikalpa</em>. Здесь речь идёт о сжатой схеме из 10 видов, используемой в контексте трёх природ (<em>tri-svabhāva</em>). Шестивидовая классификация <em>зависимого</em>, по всей видимости, соответствует шести сознаниям (<em>vijñāna</em>): зрительному, слуховому, обонятельному, вкусовому, осязательному и умственному.<a href="#ref-310" class="citation-back">↩</a></p>
<hr class="my-8 border-t-4 border-gray-500">
<p class="my-2" id="citation-311"><sup>311</sup> В <strong><em>Ланкаватаре</em></strong> <em>ekayāna</em> («Единая Колесница») не сводится к идее объединения трёх колесниц (как в <strong><em>Саддхармапундарике</em></strong>), а указывает на путь личного постижения (<em>pratyātmāryajñāna</em>), недоступный ни шравакам, ни тиртхикам.<a href="#ref-311" class="citation-back">↩</a></p>

<p class="my-2" id="citation-312"><sup>312</sup> Завеса познаваемого (<em>jñeyāvaraṇa</em>) — одно из двух главных препятствий в йогачаре. Шраваки устраняют завесу омрачений (<em>kleśāvaraṇa</em>) и достигают личной нирваны, но <em>jñeyāvaraṇa</em> — более тонкое препятствие, мешающее всеведению (<em>sarvajñatā</em>). Поэтому их освобождение не является окончательным с точки зрения Махаяны.<a href="#ref-312" class="citation-back">↩</a></p>

<p class="my-2" id="citation-313"><sup>313</sup> «Превращение-падение» (<em>pariṇāmacyuti</em>) — технический термин йогачары, обозначающий процесс, при котором шравака, вошедший в нирвану без остатка, призывается к продолжению пути.<a href="#ref-313" class="citation-back">↩</a></p>

<p class="my-2" id="citation-314"><sup>314</sup> «Опьянение самадхи» (<em>samādhimada</em>) — привязанность к блаженству медитативного поглощения как самоцели. Это тонкое препятствие, удерживающее шраваков от вступления на путь бодхисаттвы даже после устранения грубых омрачений.<a href="#ref-314" class="citation-back">↩</a></p>

<p class="my-2" id="citation-315"><sup>315</sup> <em>Vaśavartitā</em> — «следование», «нахождение во власти». Речь идёт об обретении состояния, в котором бывшие шраваки становятся проводниками деятельности Дхармакаи в мире.<a href="#ref-315" class="citation-back">↩</a></p>
